INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12847, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降水", "is_correct": true, "explanation": "正确：“冬天北方的降水多是雪”，“降水”作主语，与“雪”的语义相符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”不是雪，与后半句“多是雪”的语义矛盾，句子不通。"}, {"text": "收入", "is_correct": false, "explanation": "语义：“收入”与“雪”毫无关联，句子不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“声音”不与“多是雪”搭配，句子不通。"}], "explanations": {"降水": "正确：“冬天北方的降水多是雪”，“降水”作主语，与“雪”的语义相符。", "温度": "语义：“温度”不是雪，与后半句“多是雪”的语义矛盾，句子不通。", "收入": "语义：“收入”与“雪”毫无关联，句子不通。", "声音": "搭配：“声音”不与“多是雪”搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "降水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的降水很高，同学们都很羡慕他。", "explanation": "这里应该用〈身高〉。“降水”指雨雪，不能用来说人的高矮。"}, {"text": "今天的降水很甜，大家都爱吃。", "explanation": "这里应该用〈糖〉。“降水”指雨雪，不能用“甜”来形容，应说“糖很甜”。"}, {"text": "院子里的降水开了。", "explanation": "这里应该用〈花〉。“降水”不是植物，不能说“开”，“开”只用于花等植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里冬天下降水很少。", "corrected_sentence": "这里冬天降水很少。", "error_description": "“降水”的“降”已含落下义，前面再加动词“下”语义重复，应去掉“下”，说“这里冬天降水很少”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里降水的很少，树都干了。", "corrected_sentence": "这里降水很少，树都干了。", "error_description": "错误形式：“降水的很少”。“降水很少”是主谓结构，“的”不应插在“降水”与谓语之间；正确形式为“降水很少”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
