INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12848, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指特定地方所具有的、区别于其他地方的特性或特征。", "primary_collocate": null, "pronunciation": "dì fāng xìng", "ipa": "ti⁵¹ fɑŋ⁵⁵ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "而传统知识体系所提供的，是一种以地方性智慧为基础的韧性策略——它强调与自然节律的协同，而非对抗；主张节制与循环，而非无限开发。", "target_word": "地方性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种方言有很强的地方性。", "target_word": "地方性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道菜的地方性很明显。", "target_word": "地方性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地方性强的节日，外地人不太熟悉。", "target_word": "地方性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种疾病有明显的地方性，只出现在山区。", "target_word": "地方性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画地方性很强。", "target_word": "地方性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些民歌地方性很强，每个地方的唱法都不一样。", "target_word": "地方性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护节日的地方性。", "target_word": "地方性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座老城的地方性正在慢慢变弱。", "target_word": "地方性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇的房子有很强的地方性。", "target_word": "地方性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "地方性知识", "label": "复合"}], "register": "书面", "sense_fingerprint": "某地区别于别处的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '666c4209-724f-4fd6-b02e-7caaa973cf90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12848, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地方性", "is_correct": true, "explanation": "正确：“以地方性智慧为基础”指某地特有的智慧，与句子的传统知识语境相符。"}, {"text": "工业", "is_correct": false, "explanation": "语义：“工业智慧”与“强调与自然节律的协同”的主旨相反。"}, {"text": "赌博", "is_correct": false, "explanation": "语义：“赌博智慧”与“韧性策略”“节制与循环”的语境完全不符。"}, {"text": "体育", "is_correct": false, "explanation": "搭配：“智慧”一般不与“体育”搭配，且句子所说的是传统知识。"}], "explanations": {"地方性": "正确：“以地方性智慧为基础”指某地特有的智慧，与句子的传统知识语境相符。", "工业": "语义：“工业智慧”与“强调与自然节律的协同”的主旨相反。", "赌博": "语义：“赌博智慧”与“韧性策略”“节制与循环”的语境完全不符。", "体育": "搭配：“智慧”一般不与“体育”搭配，且句子所说的是传统知识。"}, "sentence_index": 0, "correct_answer": "地方性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在这个地方性住了三年。", "explanation": "这里应该用〈住所〉。“地方性”指地区的抽象特性，不指可以居住的具体场所。"}, {"text": "这个地方性的人口很多。", "explanation": "这里应该用〈地区〉。“地方性”是抽象特性，不能用来说人口多少。"}, {"text": "这是当地的地方性，我们买了很多。", "explanation": "这里应该用〈特产〉。“地方性”是抽象特征，不是可以买的具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12848, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地方性", "is_correct": true, "explanation": "正确：“地方性很强”指民歌带有本地特点，与“每个地方的唱法都不一样”相符。"}, {"text": "时速", "is_correct": false, "explanation": "语义：民歌没有“时速”，与唱法因地而异的语境不符。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”说高低，不说“很强”，也与唱法无关。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人的重量，不能用来说民歌。"}], "explanations": {"地方性": "正确：“地方性很强”指民歌带有本地特点，与“每个地方的唱法都不一样”相符。", "时速": "语义：民歌没有“时速”，与唱法因地而异的语境不符。", "价格": "搭配：“价格”说高低，不说“很强”，也与唱法无关。", "体重": "语义：“体重”指人的重量，不能用来说民歌。"}, "sentence_index": 6, "correct_answer": "地方性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的地方性很开朗，大家都喜欢他。", "explanation": "这里应该用〈性格〉。“地方性”指地区的特点，形容人的开朗要用“性格”。"}, {"text": "这座山的地方性很陡峭，我们爬了很久。", "explanation": "这里应该用〈山坡〉。“地方性”是抽象特征，不能用来形容地形的陡峭。"}, {"text": "他用这种地方性工作，效率很高。", "explanation": "这里应该用〈方式〉。“地方性”指地区特征，不能表示做事的方法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种菜有很强地方性。", "corrected_sentence": "这种菜有很强的地方性。", "error_description": "错误形式：“很强地方性”。修饰语“很强”与中心语“地方性”之间要用“的”；正确形式为“很强的地方性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12848, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节日的地方性强很。", "corrected_sentence": "这个节日的地方性很强。", "error_description": "语序错误：“很”应放在形容词“强”之前。正确形式为“这个节日的地方性很强”，不能说“强很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
