INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12849, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物有规律地重复出现的节奏或规律。", "primary_collocate": null, "pronunciation": "jié lǜ", "ipa": "tɕje³⁵ ly⁵¹", "syllable_count": 2, "sentences": [{"text": "而传统知识体系所提供的，是一种以地方性智慧为基础的韧性策略——它强调与自然节律的协同，而非对抗；主张节制与循环，而非无限开发。", "target_word": "节律", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "人的睡眠有自己的节律。", "target_word": "节律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "心跳的节律突然变快了。", "target_word": "节律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作太忙会打乱生活节律。", "target_word": "节律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "季节变化有一定的节律。", "target_word": "节律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海浪拍岸的节律让人安静。", "target_word": "节律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按照身体的节律安排休息。", "target_word": "节律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物的生长也有节律。", "target_word": "节律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜班工作会改变人的节律。", "target_word": "节律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "潮水涨落有固定的节律。", "target_word": "节律", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生物节律", "label": "复合"}, {"form": "节律性", "label": "复合"}], "register": "书面", "sense_fingerprint": "事物有规律地重复出现的节奏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '666c4209-724f-4fd6-b02e-7caaa973cf90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12849, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "节律", "is_correct": true, "explanation": "正确：「节律」指事物有规律地重复出现的节奏。"}, {"text": "纪律", "is_correct": false, "explanation": "jì（第四声）与 jié（第二声）韵母和声调都不同（i 与 ie），意思是纪律。"}, {"text": "戒律", "is_correct": false, "explanation": "jiè（第四声）与 jié（第二声）声调不同，意思是戒律。"}, {"text": "节录", "is_correct": false, "explanation": "lù（第四声）与 lǜ（第四声）韵母不同（u 与 ü），意思是摘录。"}], "explanations": {"节律": "正确：「节律」指事物有规律地重复出现的节奏。", "纪律": "jì（第四声）与 jié（第二声）韵母和声调都不同（i 与 ie），意思是纪律。", "戒律": "jiè（第四声）与 jié（第二声）声调不同，意思是戒律。", "节录": "lù（第四声）与 lǜ（第四声）韵母不同（u 与 ü），意思是摘录。"}, "sentence_index": null, "correct_answer": "节律"}, "level_3": {"options": [{"text": "节律", "is_correct": true, "explanation": "正确：「与自然节律的协同」指与自然的规律性节奏相配合，与「而非对抗」相符。"}, {"text": "对抗", "is_correct": false, "explanation": "语义：「对抗」与后句「而非对抗」意思相反，填入后与语境矛盾。"}, {"text": "冲突", "is_correct": false, "explanation": "语义：「冲突」与「协同」意思相反，「与自然冲突的协同」说不通。"}, {"text": "竞争", "is_correct": false, "explanation": "搭配：「协同」指配合一致，不能与「竞争」组成「与自然竞争的协同」这样的搭配。"}], "explanations": {"节律": "正确：「与自然节律的协同」指与自然的规律性节奏相配合，与「而非对抗」相符。", "对抗": "语义：「对抗」与后句「而非对抗」意思相反，填入后与语境矛盾。", "冲突": "语义：「冲突」与「协同」意思相反，「与自然冲突的协同」说不通。", "竞争": "搭配：「协同」指配合一致，不能与「竞争」组成「与自然竞争的协同」这样的搭配。"}, "sentence_index": 0, "correct_answer": "节律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个比赛的节律很严格，每个选手都要遵守。", "explanation": "这里应该用〈规则〉。规则是人为制定的要求；「节律」指事物有规律地重复出现的节奏，不指需要遵守的规定。"}, {"text": "这首歌的节律很好听，我一下就记住了。", "explanation": "这里应该用〈旋律〉。旋律指歌曲的曲调；「节律」指事物有规律地重复出现的节奏，不指好听的曲调。"}, {"text": "孩子在学校里很守节律。", "explanation": "这里应该用〈纪律〉。「守纪律」指遵守规矩；「节律」指规律性的节奏，不能说「守节律」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12849, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节律", "is_correct": true, "explanation": "正确：「身体的节律」指身体有规律的生理节奏，可以作为安排休息的依据。"}, {"text": "价格", "is_correct": false, "explanation": "语义：身体没有价格，「按照身体的价格安排休息」意思不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」指外观特征，「身体的颜色」不能作为安排休息的依据。"}, {"text": "音量", "is_correct": false, "explanation": "语义：「音量」指声音大小，「身体的音量」与安排休息无关。"}], "explanations": {"节律": "正确：「身体的节律」指身体有规律的生理节奏，可以作为安排休息的依据。", "价格": "语义：身体没有价格，「按照身体的价格安排休息」意思不通。", "颜色": "语义：「颜色」指外观特征，「身体的颜色」不能作为安排休息的依据。", "音量": "语义：「音量」指声音大小，「身体的音量」与安排休息无关。"}, "sentence_index": 6, "correct_answer": "节律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的性格很有节律，朋友都喜欢他。", "explanation": "这里应该用〈稳定〉或〈开朗〉之类描写性格的词；「节律」指事物有规律地重复，不用来形容性格。"}, {"text": "今年的节律很热闹，大家都来看。", "explanation": "这里应该用〈节日〉。节日指节庆的日子；「节律」指有规律地重复出现的节奏，不指节庆。"}, {"text": "他的节律很高，比我高一头。", "explanation": "这里应该用〈个子〉或〈身高〉。「节律」不能用来描述人的身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12849, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种鸟的鸣叫有一只节律。", "corrected_sentence": "这种鸟的鸣叫有一种节律。", "error_description": "量词错误：「节律」是抽象事物，「只」用于动物等个体，不能用来计量「节律」，应说「一种节律」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12849, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她按照身体地节律调整作息。", "corrected_sentence": "她按照身体的节律调整作息。", "error_description": "「地」用错：修饰名词「节律」应用「的」，「地」用于修饰动词，不能说「身体地节律」，应说「身体的节律」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12850, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "反对与“主张”构成反义：一个是公开支持某种看法，一个是公开表示不同意。"}, {"text": "接受", "is_correct": false, "explanation": "接受表示收下或认可，与“公开提出并支持看法”不构成对立关系。"}, {"text": "参加", "is_correct": false, "explanation": "参加指加入某项活动，与“主张”之间没有反义关系。"}, {"text": "承认", "is_correct": false, "explanation": "承认表示认可事实，与公开提出看法不是反义关系。"}], "correct_answer": "反对", "explanations": {"反对": "反对与“主张”构成反义：一个是公开支持某种看法，一个是公开表示不同意。", "接受": "接受表示收下或认可，与“公开提出并支持看法”不构成对立关系。", "参加": "参加指加入某项活动，与“主张”之间没有反义关系。", "承认": "承认表示认可事实，与公开提出看法不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12850, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "反对与“主张”构成反义，指不同意并公开表示反对。"}, {"text": "忘记", "is_correct": false, "explanation": "忘记与“主张”没有反义关系，指不再记得。"}, {"text": "研究", "is_correct": false, "explanation": "研究指探讨问题，与“主张”之间没有对立关系。"}, {"text": "回答", "is_correct": false, "explanation": "回答指对问题作出应答，与“主张”不构成反义。"}], "correct_answer": "反对", "explanations": {"反对": "反对与“主张”构成反义，指不同意并公开表示反对。", "忘记": "忘记与“主张”没有反义关系，指不再记得。", "研究": "研究指探讨问题，与“主张”之间没有对立关系。", "回答": "回答指对问题作出应答，与“主张”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12850, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对某种行为或事情持有自己的看法，并公开表示出来。", "primary_collocate": null, "pronunciation": "zhǔ zhāng", "ipa": "ʈʂu˨˩˦ ʈʂɑŋ˥˥", "syllable_count": 2, "sentences": [{"text": "小李主张明天早点出发，大家都同意了。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生主张病人多休息，少吃油腻的东西。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长主张学生每天运动一个小时。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人主张保护环境，少用塑料袋。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直主张大家要诚实，不能说谎。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师主张我们多读书，多写作文。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她公开主张男女应该有同样的机会。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司主张用新办法解决问题。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们主张通过谈判解决问题，不主张打仗。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府主张发展公共交通，减少汽车污染。", "target_word": "主张", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主张了", "label": "体标"}, {"form": "主张过", "label": "体标"}, {"form": "主張", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：对事情持有看法并公开提出、表示支持（主张早点出发、主张保护环境）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f895ac-25cd-46d5-9ed8-238277971775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12850, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主张", "is_correct": true, "explanation": "正确答案。主张 zhǔzhāng，意思是对某种做法持有看法并公开表示支持。"}, {"text": "助长", "is_correct": false, "explanation": "zhùzhǎng 与 zhǔzhāng 两个音节声调都不同，意思是促进（多指不好的倾向）。"}, {"text": "主掌", "is_correct": false, "explanation": "zhǔzhǎng 与 zhǔzhāng 第二个音节声调不同（掌 zhǎng 与 张 zhāng），意思是掌管。"}, {"text": "竹杖", "is_correct": false, "explanation": "zhúzhàng 与 zhǔzhāng 两个音节声调都不同，意思是竹子做的手杖。"}], "explanations": {"主张": "正确答案。主张 zhǔzhāng，意思是对某种做法持有看法并公开表示支持。", "助长": "zhùzhǎng 与 zhǔzhāng 两个音节声调都不同，意思是促进（多指不好的倾向）。", "主掌": "zhǔzhǎng 与 zhǔzhāng 第二个音节声调不同（掌 zhǎng 与 张 zhāng），意思是掌管。", "竹杖": "zhúzhàng 与 zhǔzhāng 两个音节声调都不同，意思是竹子做的手杖。"}, "sentence_index": null, "correct_answer": "主张"}, "level_3": {"options": [{"text": "主张", "is_correct": true, "explanation": "主张：提出看法并主动支持，能带“明天早点出发”这样的行动内容。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”搭配任务、工作，不能搭配“出发”这一行动。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或卫生，不能搭配“明天早点出发”。"}, {"text": "抱怨", "is_correct": false, "explanation": "搭配：“抱怨”表示不满，不是提出并支持看法，与“明天早点出发”的提议不符。"}], "explanations": {"主张": "主张：提出看法并主动支持，能带“明天早点出发”这样的行动内容。", "完成": "搭配：“完成”搭配任务、工作，不能搭配“出发”这一行动。", "打扫": "搭配：“打扫”的对象是场所或卫生，不能搭配“明天早点出发”。", "抱怨": "搭配：“抱怨”表示不满，不是提出并支持看法，与“明天早点出发”的提议不符。"}, "sentence_index": 0, "correct_answer": "主张"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于主张了自己做错的事。", "explanation": "这里应该用〈承认〉。主张是公开提出并支持某种看法，不用于承认自己做过的错事。"}, {"text": "我主张他会迟到。", "explanation": "这里应该用〈担心〉。主张表示公开支持某种看法，不用于表达对事情的忧虑。"}, {"text": "他一直在城里主张，不想搬走。", "explanation": "这里应该用〈住〉。主张表示公开提出并支持某种看法，不表示居住在某地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12850, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "主张", "is_correct": true, "explanation": "正确答案。主张 zhǔzhāng，意思是提出并支持某种看法。"}, {"text": "助长", "is_correct": false, "explanation": "zhùzhǎng 与 zhǔzhāng 两个音节声调都不同，意思是促进（多指不好的倾向）。"}, {"text": "拄杖", "is_correct": false, "explanation": "zhǔzhàng 与 zhǔzhāng 第二个音节声调不同（杖 zhàng 与 张 zhāng），意思是拄着拐杖。"}, {"text": "逐章", "is_correct": false, "explanation": "zhúzhāng 与 zhǔzhāng 第一个音节声调不同，意思是一章一章地。"}], "explanations": {"主张": "正确答案。主张 zhǔzhāng，意思是提出并支持某种看法。", "助长": "zhùzhǎng 与 zhǔzhāng 两个音节声调都不同，意思是促进（多指不好的倾向）。", "拄杖": "zhǔzhàng 与 zhǔzhāng 第二个音节声调不同（杖 zhàng 与 张 zhāng），意思是拄着拐杖。", "逐章": "zhúzhāng 与 zhǔzhāng 第一个音节声调不同，意思是一章一章地。"}, "sentence_index": null, "correct_answer": "主张"}, "level_3": {"options": [{"text": "主张", "is_correct": true, "explanation": "主张：提出并支持看法，与“公开”搭配，符合句意。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”与“公开”意思相反，句子说的是公开表态。"}, {"text": "偷", "is_correct": false, "explanation": "搭配：“偷”是暗中拿走的行为，不能与“公开”及“男女应该有同样的机会”搭配。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”指不再记得，与“公开表态”的句意不相符。"}], "explanations": {"主张": "主张：提出并支持看法，与“公开”搭配，符合句意。", "隐瞒": "语义：“隐瞒”与“公开”意思相反，句子说的是公开表态。", "偷": "搭配：“偷”是暗中拿走的行为，不能与“公开”及“男女应该有同样的机会”搭配。", "忘记": "语义：“忘记”指不再记得，与“公开表态”的句意不相符。"}, "sentence_index": 6, "correct_answer": "主张"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于主张了大家。", "explanation": "这里应该用〈说服〉。主张是提出并支持看法，不能直接带人作宾语表示使人信服。"}, {"text": "老师主张了他的错误。", "explanation": "这里应该用〈批评〉。主张是提出并支持看法，不用于指出别人的错误。"}, {"text": "他向我主张了一份礼物。", "explanation": "这里应该用〈送〉。主张表示提出并支持看法，不能用于赠送东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直主张了多种树，少砍树。", "corrected_sentence": "他一直主张多种树，少砍树。", "error_description": "错误在“主张”后多加了“了”。“了”表示动作已完成，而“一直”表示持续的态度，两者意思相冲突；正确形式是“他一直主张多种树”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的主张多坐公交车，少开私家车。", "corrected_sentence": "我们主张多坐公交车，少开私家车。", "error_description": "错误在“我们”后多加了“的”，使“主张”变成名词，后面应接“是”才通顺；“主张”作动词时直接带动词短语，正确形式是“我们主张多坐公交车，少开私家车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12851, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放纵", "is_correct": true, "explanation": "放纵与“节制”构成反义：一个是约束自己，一个是毫无节制地任由自己。"}, {"text": "研究", "is_correct": false, "explanation": "研究指探讨问题，与“节制”没有反义关系。"}, {"text": "建设", "is_correct": false, "explanation": "建设指建造、发展，与约束自己的意思无对立关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察指仔细看，与“节制”不构成反义。"}], "correct_answer": "放纵", "explanations": {"放纵": "放纵与“节制”构成反义：一个是约束自己，一个是毫无节制地任由自己。", "研究": "研究指探讨问题，与“节制”没有反义关系。", "建设": "建设指建造、发展，与约束自己的意思无对立关系。", "观察": "观察指仔细看，与“节制”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12851, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放纵", "is_correct": true, "explanation": "放纵与“节制”构成反义：一个是约束自己，一个是毫无节制。"}, {"text": "参观", "is_correct": false, "explanation": "参观指到某处看一看，与“节制”没有反义关系。"}, {"text": "检查", "is_correct": false, "explanation": "检查指仔细查看，与“节制”不构成反义。"}, {"text": "迎接", "is_correct": false, "explanation": "迎接指到门口或路上接人，与约束自己无对立关系。"}], "correct_answer": "放纵", "explanations": {"放纵": "放纵与“节制”构成反义：一个是约束自己，一个是毫无节制。", "参观": "参观指到某处看一看，与“节制”没有反义关系。", "检查": "检查指仔细查看，与“节制”不构成反义。", "迎接": "迎接指到门口或路上接人，与约束自己无对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12851, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指控制自己的欲望或行为，不过度放纵。", "primary_collocate": null, "pronunciation": "jié zhì", "ipa": "tɕje˧˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他下决心节制饮食，每天只吃一碗饭。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会节制自己，从来不乱花钱。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生要求他节制饮酒，每周不能超过一次。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃甜食要节制，不然容易变胖。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青少年玩手机需要节制。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不懂节制，一顿饭吃了三碗米饭。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她节制了饮食，三个月瘦了五公斤。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生气的时候，你要学会节制自己的脾气。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花钱要节制，别买不需要的东西。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷节制了抽烟，身体好多了。", "target_word": "节制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "节制了", "label": "体标"}, {"form": "节制过", "label": "体标"}, {"form": "節制", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：约束自己的欲望或行为，不过度（节制饮食、节制脾气）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f895ac-25cd-46d5-9ed8-238277971775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12851, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "节制", "is_correct": true, "explanation": "正确答案。节制 jié zhì，意思是控制自己的欲望或行为，不过度放纵。"}, {"text": "戒指", "is_correct": false, "explanation": "jiè zhǐ 与 jié zhì 两个音节声调都不同，意思是戒指（首饰）。"}, {"text": "解职", "is_correct": false, "explanation": "jiě zhí 与 jié zhì 两个音节声调都不同，意思是免去职务（书面用语）。"}, {"text": "介质", "is_correct": false, "explanation": "jiè zhì 与 jié zhì 第一个音节声调不同，意思是媒介、传递作用的物质。"}], "explanations": {"节制": "正确答案。节制 jié zhì，意思是控制自己的欲望或行为，不过度放纵。", "戒指": "jiè zhǐ 与 jié zhì 两个音节声调都不同，意思是戒指（首饰）。", "解职": "jiě zhí 与 jié zhì 两个音节声调都不同，意思是免去职务（书面用语）。", "介质": "jiè zhì 与 jié zhì 第一个音节声调不同，意思是媒介、传递作用的物质。"}, "sentence_index": null, "correct_answer": "节制"}, "level_3": {"options": [{"text": "节制", "is_correct": true, "explanation": "节制：约束、控制饮食，与“每天只吃一碗饭”的自我约束相合。"}, {"text": "开发", "is_correct": false, "explanation": "搭配：“开发”指开拓利用资源或土地，不能与“饮食”搭配。"}, {"text": "扩张", "is_correct": false, "explanation": "搭配：“扩张”多指范围或势力扩大，不能与“饮食”搭配。"}, {"text": "放纵", "is_correct": false, "explanation": "语义：“放纵”指毫无节制地任由自己，与“每天只吃一碗饭”的句意相反。"}], "explanations": {"节制": "节制：约束、控制饮食，与“每天只吃一碗饭”的自我约束相合。", "开发": "搭配：“开发”指开拓利用资源或土地，不能与“饮食”搭配。", "扩张": "搭配：“扩张”多指范围或势力扩大，不能与“饮食”搭配。", "放纵": "语义：“放纵”指毫无节制地任由自己，与“每天只吃一碗饭”的句意相反。"}, "sentence_index": 0, "correct_answer": "节制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她学习很节制，每天都很努力。", "explanation": "这里应该用〈勤奋〉。节制指约束欲望或行为，不用于形容努力学习的态度。"}, {"text": "他很怕冷，冬天总是节制很多衣服。", "explanation": "这里应该用〈穿〉。节制指约束欲望或行为，不用于穿衣。"}, {"text": "他节制了汽车的速度。", "explanation": "这里应该用〈控制〉。节制指约束人的欲望或行为，机器的速度应说“控制”或“限制”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12851, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节制", "is_correct": true, "explanation": "节制：控制饮食，与“三个月瘦了五公斤”的结果相合。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加饮食”会使人变胖，与“三个月瘦了五公斤”矛盾。"}, {"text": "补充", "is_correct": false, "explanation": "语义：“补充饮食”意味着多吃，与句末的减重结果相矛盾。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”搭配计划、申请，不能与“饮食”搭配。"}], "explanations": {"节制": "节制：控制饮食，与“三个月瘦了五公斤”的结果相合。", "增加": "语义：“增加饮食”会使人变胖，与“三个月瘦了五公斤”矛盾。", "补充": "语义：“补充饮食”意味着多吃，与句末的减重结果相矛盾。", "批准": "搭配：“批准”搭配计划、申请，不能与“饮食”搭配。"}, "sentence_index": 6, "correct_answer": "节制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店主热情地节制每一位顾客。", "explanation": "这里应该用〈欢迎〉。节制指约束欲望或行为，不用于接待、欢迎客人。"}, {"text": "他节制了朋友的好意。", "explanation": "这里应该用〈拒绝〉。节制是约束自己的欲望或行为，对别人的好意应说“拒绝”。"}, {"text": "他节制了这个计划，最后没做成。", "explanation": "这里应该用〈放弃〉。节制针对欲望或行为的过度，不用于放弃计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12851, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚上别吃太多，要节制了一点。", "corrected_sentence": "晚上别吃太多，要节制一点。", "error_description": "错误在“节制”后多加了“了”。“要……一点”表示应当做到的要求，动作尚未完成，动词后不能带表示完成的“了”，应说“要节制一点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12851, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是个懂得节制地人。", "corrected_sentence": "他是个懂得节制的人。", "error_description": "“节制”后修饰名词“人”时应用“的”，误用了副词标记“地”；正确形式为“懂得节制的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
