INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12853, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究人类的起源、发展、社会结构、文化习俗及生物特征的学科。", "primary_collocate": null, "pronunciation": "rén lèi xué", "ipa": "ʐən˧˥ lei˥˩ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "人类学研究表明，不同地区的人对时间的理解很不一样。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学学习人类学，毕业后想去山区工作。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类学研究人类的起源和不同民族的习俗。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对人类学很感兴趣，常常看相关的书。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在人类学的课上讲了很多故事。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类学告诉我们，不同的地方有不同的习俗。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她选了人类学作为自己的专业。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了人类学以后，我更懂得尊重别人的文化。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类学和历史学都需要了解过去。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本人类学的书写了很多古老的部落。", "target_word": "人类学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人类学家", "label": "复合"}, {"form": "文化人类学", "label": "复合"}, {"form": "人類學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：研究人类起源、社会、文化与生物特征的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f895ac-25cd-46d5-9ed8-238277971775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12853, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人类学", "is_correct": true, "explanation": "人类学：研究人类社会与文化的学科，与“研究表明”搭配，句意通顺。"}, {"text": "仪器", "is_correct": false, "explanation": "语义：“仪器”不是研究者，“仪器研究表明”句意不通。"}, {"text": "漂亮", "is_correct": false, "explanation": "语法：“漂亮”是形容词，不能作“研究表明”的主语。"}, {"text": "便宜", "is_correct": false, "explanation": "语法：“便宜”是形容词，“便宜研究表明”不成话。"}], "explanations": {"人类学": "人类学：研究人类社会与文化的学科，与“研究表明”搭配，句意通顺。", "仪器": "语义：“仪器”不是研究者，“仪器研究表明”句意不通。", "漂亮": "语法：“漂亮”是形容词，不能作“研究表明”的主语。", "便宜": "语法：“便宜”是形容词，“便宜研究表明”不成话。"}, "sentence_index": 0, "correct_answer": "人类学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人类学研究的是怎样计算房屋的承重。", "explanation": "这里应该用〈建筑学〉。人类学研究人类社会与文化，房屋承重的计算属于建筑学。"}, {"text": "这门人类学专门帮病人解决心理问题。", "explanation": "这里应该用〈心理学〉。人类学研究人类社会与文化，解决心理问题属于心理学。"}, {"text": "人类学研究的是数字的运算规则。", "explanation": "这里应该用〈数学〉。人类学研究人类社会与文化，数字的运算规则属于数学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12853, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人类学", "is_correct": true, "explanation": "人类学：一门学科，可以作“选”的对象，符合“作为自己的专业”。"}, {"text": "感情", "is_correct": false, "explanation": "语义：“感情”不是可以选来作专业的学科，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不是专业，与“选了……作为自己的专业”矛盾。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“专业”指学业方向，不能与“玩具”搭配。"}], "explanations": {"人类学": "人类学：一门学科，可以作“选”的对象，符合“作为自己的专业”。", "感情": "语义：“感情”不是可以选来作专业的学科，句意不通。", "天气": "语义：“天气”是自然现象，不是专业，与“选了……作为自己的专业”矛盾。", "玩具": "搭配：“专业”指学业方向，不能与“玩具”搭配。"}, "sentence_index": 6, "correct_answer": "人类学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人类学研究的是股票的涨跌规律。", "explanation": "这里应该用〈金融学〉。人类学研究人类社会与文化，股票的涨跌规律属于金融学。"}, {"text": "人类学研究的是三角形面积的计算方法。", "explanation": "这里应该用〈数学〉。人类学研究人类社会与文化，三角形面积的计算属于数学。"}, {"text": "人类学研究的是星星的运动。", "explanation": "这里应该用〈天文学〉。人类学研究人类社会与文化，星体运动属于天文学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12853, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她打算学一本人类学。", "corrected_sentence": "她打算学一门人类学。", "error_description": "量词错误：人类学作学科时应用量词“门”，应说“一门人类学”，不说“一本人类学”。“本”用于书籍，不能用于学科。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12853, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一本人类学的的书。", "corrected_sentence": "他买了一本人类学的书。", "error_description": "“的”重复：修饰语“人类学”后只用一个“的”，应说“一本人类学的书”，多加一个“的”不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
