INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12854, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通过观察自然迹象察觉环境变化的能力", "primary_collocate": null, "pronunciation": "gǎn zhī", "ipa": "kan˨˩ ʈʂɻ̩˥˥", "syllable_count": 2, "sentences": [{"text": "人类学研究表明，许多本土社群对水文变化的感知能力远超现代仪器所能捕捉的范畴，他们通过植物生长状态、土壤湿度、风向变化等细微线索，预判干旱趋势并调整耕作安排。", "target_word": "感知", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老农对天气的感知很准。", "target_word": "感知", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "鸟对地震的感知很敏锐。", "target_word": "感知", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "蚂蚁对下雨的感知比人早。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔民对海水变化的感知很强。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们对季节变化的感知来自多年的经验。", "target_word": "感知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧民对风向的感知，比机器还准。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "动物对环境变化的感知，常常比人快。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在山里的人，对天气的感知特别好。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民对土地干湿的感知，来自每天的观察。", "target_word": "感知", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "感知力", "label": "复合词"}, {"form": "感知能力", "label": "复合词"}], "register": "书面", "sense_fingerprint": "通过自然迹象察觉环境变化的能力（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba03f51-3fa7-4f07-875e-36a08896edd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感知", "is_correct": true, "explanation": "感知：指对环境变化的察觉能力，与句中的语境相符。"}, {"text": "财力", "is_correct": false, "explanation": "搭配：“对水文变化的”后面的能力指察觉变化的本领，不能接“财力”。"}, {"text": "语言", "is_correct": false, "explanation": "语义：这里讲的是察觉水文变化，不是语言能力。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重与察觉水文变化无关，句子的意思不通。"}], "explanations": {"感知": "感知：指对环境变化的察觉能力，与句中的语境相符。", "财力": "搭配：“对水文变化的”后面的能力指察觉变化的本领，不能接“财力”。", "语言": "语义：这里讲的是察觉水文变化，不是语言能力。", "体重": "语义：体重与察觉水文变化无关，句子的意思不通。"}, "sentence_index": 0, "correct_answer": "感知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把感知装进了箱子里。", "explanation": "这里应该用〈物品〉。装进箱子的是物品，“感知”是察觉环境变化的能力，不是可以装箱的东西。"}, {"text": "这个感知很好吃。", "explanation": "这里应该用〈食物〉。“好吃”用于食物，“感知”是察觉环境变化的能力，不能用来形容味道。"}, {"text": "爱迪生感知了电灯。", "explanation": "这里应该用〈发明〉。发明电灯要用“发明”，“感知”指察觉环境变化，不能表示创造事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '605e84e4-620d-4b13-9a06-fab69e3270a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感知", "is_correct": true, "explanation": "感知：指牧民对风向的察觉能力，句子成立。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：风向没有颜色，不能拿来与机器比较准确与否。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“风向”不能与“体积”搭配，无法说风向的大小。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”与察觉风向无关，不能说比机器还准。"}], "explanations": {"感知": "感知：指牧民对风向的察觉能力，句子成立。", "颜色": "语义：风向没有颜色，不能拿来与机器比较准确与否。", "体积": "搭配：“风向”不能与“体积”搭配，无法说风向的大小。", "价格": "语义：“价格”与察觉风向无关，不能说比机器还准。"}, "sentence_index": 6, "correct_answer": "感知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给朋友感知了一份生日礼物。", "explanation": "这里应该用〈送〉。送礼物要用“送”，“感知”不能表示把东西交给别人。"}, {"text": "我感知了一块手表，把它戴在手上。", "explanation": "这里应该用〈买〉。买手表要用“买”，“感知”是察觉变化的能力，不能表示购买。"}, {"text": "老师在黑板上感知了一道数学题。", "explanation": "这里应该用〈写〉。在黑板上写题要用“写”，“感知”不能表示书写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '605e84e4-620d-4b13-9a06-fab69e3270a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大象对地震地感知很灵敏。", "corrected_sentence": "大象对地震的感知很灵敏。", "error_description": "“地”用错了。“感知”是名词，修饰它的“对地震”后面要用“的”，不能用“地”。应为“对地震的感知”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '605e84e4-620d-4b13-9a06-fab69e3270a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猎人对风向地感知很强。", "corrected_sentence": "猎人对风向的感知很强。", "error_description": "“地”用错了。修饰名词“感知”要用“的”，不能用“地”，应为“对风向的感知”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '605e84e4-620d-4b13-9a06-fab69e3270a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12855, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "近", "is_correct": true, "explanation": "近：与“远”相对，是距离上的反义词。"}, {"text": "深", "is_correct": false, "explanation": "深与远不构成反义，深的反义是“浅”。"}, {"text": "轻", "is_correct": false, "explanation": "轻与远不构成反义，轻的反义是“重”。"}, {"text": "慢", "is_correct": false, "explanation": "慢与远不构成反义，慢的反义是“快”。"}], "correct_answer": "近", "explanations": {"近": "近：与“远”相对，是距离上的反义词。", "深": "深与远不构成反义，深的反义是“浅”。", "轻": "轻与远不构成反义，轻的反义是“重”。", "慢": "慢与远不构成反义，慢的反义是“快”。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12855, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "近", "is_correct": true, "explanation": "近：与“远”相对，是距离上的反义词。"}, {"text": "浅", "is_correct": false, "explanation": "浅与远不构成反义，浅的反义是“深”。"}, {"text": "窄", "is_correct": false, "explanation": "窄与远不构成反义，窄的反义是“宽”。"}, {"text": "矮", "is_correct": false, "explanation": "矮与远不构成反义，矮的反义是“高”。"}], "correct_answer": "近", "explanations": {"近": "近：与“远”相对，是距离上的反义词。", "浅": "浅与远不构成反义，浅的反义是“深”。", "窄": "窄与远不构成反义，窄的反义是“宽”。", "矮": "矮与远不构成反义，矮的反义是“高”。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12855, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "距离长，与‘近’相对。", "primary_collocate": null, "pronunciation": "yuǎn", "ipa": "ɥɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "我家离学校很远，要坐一小时车。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个地方太远，我不想去。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路不远，走十分钟就到。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他住得很远，每天上班要两个小时。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行离这儿很远，你最好坐出租车去。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边离城市很远，开车要三个小时。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校太远了，所以他每天坐地铁去。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的家不远，我们可以走着去。", "target_word": "远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的小学离城里很远，孩子们每天要走很久。", "target_word": "远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市太远，我们就在网上买吧。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "更远", "label": "比较"}, {"form": "最远", "label": "最高级"}, {"form": "远远", "label": "重叠"}, {"form": "遠", "label": "繁体"}], "register": "中性", "sense_fingerprint": "距离长，与近相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f895ac-25cd-46d5-9ed8-238277971775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12855, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "远", "is_correct": true, "explanation": "远：距离长，与“近”相对。"}, {"text": "院", "is_correct": false, "explanation": "yuàn（第四声）与 yuǎn（第三声）声调不同，意思是院子。"}, {"text": "愿", "is_correct": false, "explanation": "yuàn（第四声）与 yuǎn（第三声）声调不同，意思是愿望。"}, {"text": "元", "is_correct": false, "explanation": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是钱的单位。"}, {"text": "园", "is_correct": false, "explanation": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是花园。"}], "explanations": {"远": "远：距离长，与“近”相对。", "院": "yuàn（第四声）与 yuǎn（第三声）声调不同，意思是院子。", "愿": "yuàn（第四声）与 yuǎn（第三声）声调不同，意思是愿望。", "元": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是钱的单位。", "园": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是花园。"}, "sentence_index": null, "correct_answer": "远"}, "level_3": {"options": [{"text": "远", "is_correct": true, "explanation": "远：距离长，与“很远”搭配，句意是离学校距离远，要坐一小时车。"}, {"text": "高", "is_correct": false, "explanation": "搭配：距离不说“高”，“很高”不能修饰“离学校”。"}, {"text": "宽", "is_correct": false, "explanation": "搭配：“宽”说宽度，不能用于说明距离。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”说速度，与“离学校”的距离无关，句意不通。"}], "explanations": {"远": "远：距离长，与“很远”搭配，句意是离学校距离远，要坐一小时车。", "高": "搭配：距离不说“高”，“很高”不能修饰“离学校”。", "宽": "搭配：“宽”说宽度，不能用于说明距离。", "快": "语义：“快”说速度，与“离学校”的距离无关，句意不通。"}, "sentence_index": 0, "correct_answer": "远"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他等了很远。", "explanation": "这里应该用〈久〉。远只说空间距离，等待的时间长要用“久”。"}, {"text": "这道题很远，我不会做。", "explanation": "这里应该用〈难〉。远说空间距离，说题目不容易要用“难”。"}, {"text": "她的头发很远，到腰了。", "explanation": "这里应该用〈长〉。远说两地之间的距离，说头发的长度要用“长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12855, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "远", "is_correct": true, "explanation": "远：距离长，与“近”相对。"}, {"text": "圆", "is_correct": false, "explanation": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是圆形。"}, {"text": "员", "is_correct": false, "explanation": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是人员。"}, {"text": "冤", "is_correct": false, "explanation": "yuān（第一声）与 yuǎn（第三声）声调不同，意思是冤枉。"}, {"text": "怨", "is_correct": false, "explanation": "yuàn（第四声）与 yuǎn（第三声）声调不同，意思是怨恨。"}], "explanations": {"远": "远：距离长，与“近”相对。", "圆": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是圆形。", "员": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是人员。", "冤": "yuān（第一声）与 yuǎn（第三声）声调不同，意思是冤枉。", "怨": "yuàn（第四声）与 yuǎn（第三声）声调不同，意思是怨恨。"}, "sentence_index": null, "correct_answer": "远"}, "level_3": {"options": [{"text": "远", "is_correct": true, "explanation": "远：距离长，与“太远了，所以坐地铁”的理由相符。"}, {"text": "近", "is_correct": false, "explanation": "语义：“太近了”与后半句“所以坐地铁”的理由相矛盾。"}, {"text": "小", "is_correct": false, "explanation": "语义：“学校小”不能构成坐地铁的理由，句意不连贯。"}, {"text": "旧", "is_correct": false, "explanation": "语义：“太旧了”说的是老旧程度，与“坐地铁去”的原因无关。"}], "explanations": {"远": "远：距离长，与“太远了，所以坐地铁”的理由相符。", "近": "语义：“太近了”与后半句“所以坐地铁”的理由相矛盾。", "小": "语义：“学校小”不能构成坐地铁的理由，句意不连贯。", "旧": "语义：“太旧了”说的是老旧程度，与“坐地铁去”的原因无关。"}, "sentence_index": 6, "correct_answer": "远"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天天气很远，我们去游泳吧。", "explanation": "这里应该用〈热〉。远说距离，说气温高要用“热”。"}, {"text": "他的个子很远，是班里最高的。", "explanation": "这里应该用〈高〉。远说距离，说身高要用“高”。"}, {"text": "这碗汤的味道很远，放了太多盐。", "explanation": "这里应该用〈咸〉。远说距离，说味道要用“咸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家离车站远远，每天都要走很久。", "corrected_sentence": "我家离车站很远，每天都要走很久。", "error_description": "重叠错误：“远远”是副词形式，不能直接作谓语，应说“很远”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市中心离这儿远很，坐车要半小时。", "corrected_sentence": "市中心离这儿很远，坐车要半小时。", "error_description": "语序错误：程度副词“很”应放在形容词“远”之前，应说“很远”，不能说“远很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
