INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12857, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用于实验、测量、观测、检验等工作的器具或设备。", "primary_collocate": null, "pronunciation": "yí qì", "ipa": "i˧˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "实验室里有很多贵重的仪器。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "使用仪器前，请先看说明书。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用仪器检查了我的心脏。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台仪器可以测量很小的东西。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家把仪器放进了海水里。", "target_word": "仪器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "精密仪器要放在干燥的地方。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在调试新买的仪器。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司专门生产测量用的仪器。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "仪器坏了，实验只好明天再做。", "target_word": "仪器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们小心地擦着实验仪器。", "target_word": "仪器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "精密仪器", "label": "复合"}, {"form": "测量仪器", "label": "复合"}], "register": "中性", "sense_fingerprint": "实验、测量、观测、检验等工作用的器具或设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bede058a-09f7-4687-907e-4a8684b48d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12857, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仪器", "is_correct": true, "explanation": "仪器（yí qì）：用于实验、测量、观测、检验等工作的器具或设备，是正确答案。"}, {"text": "一起", "is_correct": false, "explanation": "yì qǐ 两个音节的声调都与 yí qì 不同，意思是“在一起”。"}, {"text": "一齐", "is_correct": false, "explanation": "yì qí 两个音节的声调都与 yí qì 不同，意思是“一同、同时”。"}, {"text": "瓷器", "is_correct": false, "explanation": "cí qì 与 yí qì 声母不同（c 与 y），意思是瓷做的器物。"}, {"text": "意气", "is_correct": false, "explanation": "yì qì 与 yí qì 第一音节声调不同（第四声），意思是志气或情绪。"}], "explanations": {"仪器": "仪器（yí qì）：用于实验、测量、观测、检验等工作的器具或设备，是正确答案。", "一起": "yì qǐ 两个音节的声调都与 yí qì 不同，意思是“在一起”。", "一齐": "yì qí 两个音节的声调都与 yí qì 不同，意思是“一同、同时”。", "瓷器": "cí qì 与 yí qì 声母不同（c 与 y），意思是瓷做的器物。", "意气": "yì qì 与 yí qì 第一音节声调不同（第四声），意思是志气或情绪。"}, "sentence_index": null, "correct_answer": "仪器"}, "level_3": {"options": [{"text": "仪器", "is_correct": true, "explanation": "仪器：指用于实验的器具，“贵重”和“实验室”两处线索都与之相符。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是贵重物品，与“贵重”直接矛盾。"}, {"text": "粮食", "is_correct": false, "explanation": "搭配：“贵重”一般不修饰粮食，实验室也不存放粮食。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜与“实验室”的语境不符，不属于实验室里的贵重物品。"}], "explanations": {"仪器": "仪器：指用于实验的器具，“贵重”和“实验室”两处线索都与之相符。", "垃圾": "语义：垃圾不是贵重物品，与“贵重”直接矛盾。", "粮食": "搭配：“贵重”一般不修饰粮食，实验室也不存放粮食。", "蔬菜": "语义：蔬菜与“实验室”的语境不符，不属于实验室里的贵重物品。"}, "sentence_index": 0, "correct_answer": "仪器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司刚买了一批新的办公仪器。", "explanation": "这里应该用〈设备〉。仪器限于做实验、测量用的器具，办公用的电脑、打印机要说“设备”。"}, {"text": "教室里新装了一台空调仪器。", "explanation": "这里应该用〈设备〉。仪器限于做实验和测量用的器具，空调要说“设备”。"}, {"text": "这座公园的游乐仪器很老旧了。", "explanation": "这里应该用〈设施〉。仪器限于实验和测量，滑梯、秋千等游乐设施要说“设施”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12857, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "仪器", "is_correct": true, "explanation": "仪器（yí qì）：用于实验、测量、观测、检验等工作的器具或设备，是正确答案。"}, {"text": "一气", "is_correct": false, "explanation": "yī qì 第一音节声调不同（第一声），意思是一股劲儿、一口气。"}, {"text": "义气", "is_correct": false, "explanation": "yì qì 第一音节声调不同（第四声），意思是讲义气、重情义。"}, {"text": "石器", "is_correct": false, "explanation": "shí qì 与 yí qì 声母不同（sh 与 y），意思是石头做的工具。"}, {"text": "遗迹", "is_correct": false, "explanation": "yí jì 与 yí qì 第二音节声母不同（j 与 q），意思是遗留下来的古迹。"}], "explanations": {"仪器": "仪器（yí qì）：用于实验、测量、观测、检验等工作的器具或设备，是正确答案。", "一气": "yī qì 第一音节声调不同（第一声），意思是一股劲儿、一口气。", "义气": "yì qì 第一音节声调不同（第四声），意思是讲义气、重情义。", "石器": "shí qì 与 yí qì 声母不同（sh 与 y），意思是石头做的工具。", "遗迹": "yí jì 与 yí qì 第二音节声母不同（j 与 q），意思是遗留下来的古迹。"}, "sentence_index": null, "correct_answer": "仪器"}, "level_3": {"options": [{"text": "仪器", "is_correct": true, "explanation": "仪器：是“调试”的对象，与“新买的”相符。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不是机器，不能“调试”。"}, {"text": "书籍", "is_correct": false, "explanation": "搭配：“调试”针对机器设备，不用于书籍。"}, {"text": "面条", "is_correct": false, "explanation": "语义：面条是食物，与“调试”的语境不符。"}], "explanations": {"仪器": "仪器：是“调试”的对象，与“新买的”相符。", "饼干": "语义：饼干不是机器，不能“调试”。", "书籍": "搭配：“调试”针对机器设备，不用于书籍。", "面条": "语义：面条是食物，与“调试”的语境不符。"}, "sentence_index": 6, "correct_answer": "仪器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "钢琴是一种很好的仪器。", "explanation": "这里应该用〈乐器〉。仪器限于做实验和测量用的工具，钢琴这类乐器要说“乐器”。"}, {"text": "书桌是新买的仪器。", "explanation": "这里应该用〈家具〉。仪器限于做实验和测量用的工具，书桌、椅子等要说“家具”。"}, {"text": "妈妈每天洗厨房仪器。", "explanation": "这里应该用〈用具〉。仪器专指实验或测量的器具，厨房里的器具要说“用具”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师为我们准备了一条仪器。", "corrected_sentence": "老师为我们准备了一台仪器。", "error_description": "量词错误：仪器应用“台”或“套”。“条”用于细长的东西，这里应改为“台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12857, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人搬来了一张仪器。", "corrected_sentence": "工人搬来了一套仪器。", "error_description": "量词错误：仪器应用“套”或“台”。“张”用于平面物品，这里应改为“套”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
