INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12858, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "土壤中水分的含量，通常用百分比表示。", "primary_collocate": null, "pronunciation": "tǔ rǎng shī dù", "ipa": "tʰu˨˩˦ ɻɑŋ˨˩˦ ʂɨ˥ tu˥˩", "syllable_count": 4, "sentences": [{"text": "人类学研究表明，许多本土社群对水文变化的感知能力远超现代仪器所能捕捉的范畴，他们通过植物生长状态、土壤湿度、风向变化等细微线索，预判干旱趋势并调整耕作安排。", "target_word": "土壤湿度", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "土壤湿度太低，花需要浇水。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民每天都看土壤湿度。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下过雨以后，土壤湿度会升高。", "target_word": "土壤湿度", "complexity_tier": "T3", "furigana": "xià guo yǔ yǐhòu, tǔrǎng shīdù huì shēnggāo.", "sentence_source": "generated"}, {"text": "这台机器可以测量土壤湿度。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙地的土壤湿度比黑土地低。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "土壤湿度太高，树根会坏。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机上能看到花盆里的土壤湿度。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气很热，土壤湿度下降得很快。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "种菜以前，先查一下土壤湿度。", "target_word": "土壤湿度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "土壤濕度", "label": "繁体"}], "register": "书面", "sense_fingerprint": "土壤含水量，常用百分比表示", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f895ac-25cd-46d5-9ed8-238277971775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12858, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土壤湿度", "is_correct": true, "explanation": "“土壤湿度”指土壤的含水量，是感知干旱的线索，与句意相符。"}, {"text": "地震烈度", "is_correct": false, "explanation": "语义：地震烈度不是本土社群用来预判干旱的水文或植物线索。"}, {"text": "股市行情", "is_correct": false, "explanation": "语义：股市行情不属于植物、风向之类的自然线索，与水文变化无关。"}, {"text": "血糖水平", "is_correct": false, "explanation": "搭配：“血糖水平”指人体指标，不能与“细微线索”并列用于自然环境的观察。"}], "explanations": {"土壤湿度": "“土壤湿度”指土壤的含水量，是感知干旱的线索，与句意相符。", "地震烈度": "语义：地震烈度不是本土社群用来预判干旱的水文或植物线索。", "股市行情": "语义：股市行情不属于植物、风向之类的自然线索，与水文变化无关。", "血糖水平": "搭配：“血糖水平”指人体指标，不能与“细微线索”并列用于自然环境的观察。"}, "sentence_index": 0, "correct_answer": "土壤湿度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地的土壤湿度有两百克。", "explanation": "这里应该用〈土壤水分〉。湿度是百分比，不用“克”计量，说水的重量才用“土壤水分”。"}, {"text": "这块地的土壤湿度是六点五，偏酸。", "explanation": "这里应该用〈酸碱度〉。“偏酸”说的是酸碱度，土壤湿度是土里水分的百分比，不能用来说酸性。"}, {"text": "这块地的土壤湿度是零下五度。", "explanation": "这里应该用〈土壤温度〉。零下几度说的是温度，湿度用百分比表示，不会是负数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土壤湿度", "is_correct": true, "explanation": "“太高”说明含水量过多，树根会坏，符合土壤含水量的意思。"}, {"text": "房子价格", "is_correct": false, "explanation": "语义：房子价格高低和树根坏不坏没有关系。"}, {"text": "土壤颜色", "is_correct": false, "explanation": "搭配：颜色不能用“太高”来形容。"}, {"text": "土地面积", "is_correct": false, "explanation": "搭配：面积不说“太高”，应说“太大”。"}], "explanations": {"土壤湿度": "“太高”说明含水量过多，树根会坏，符合土壤含水量的意思。", "房子价格": "语义：房子价格高低和树根坏不坏没有关系。", "土壤颜色": "搭配：颜色不能用“太高”来形容。", "土地面积": "搭配：面积不说“太高”，应说“太大”。"}, "sentence_index": 6, "correct_answer": "土壤湿度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块地的土壤湿度很深，庄稼长得好。", "explanation": "这里应该用〈土壤颜色〉。“深”描述颜色，湿度是百分比数值，不说深浅。"}, {"text": "这块地的土壤湿度很松，庄稼长得好。", "explanation": "这里应该用〈土壤质地〉。“松”形容土的质地，湿度不说松软。"}, {"text": "这块地的土壤湿度有三十厘米。", "explanation": "这里应该用〈土壤深度〉。厘米计量的是深度，湿度不用厘米计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地的土壤湿度在很高，所以庄稼长得很好。", "corrected_sentence": "这块地的土壤湿度很高，所以庄稼长得很好。", "error_description": "形容词谓语“很高”前面不能加“在”，应说“土壤湿度很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "土壤湿度的太高，草根容易烂。", "corrected_sentence": "土壤湿度太高，草根容易烂。", "error_description": "“的”位置错误：“土壤湿度”后直接接“太高”作谓语，中间不能加“的”，应说“土壤湿度太高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
