INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12860, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事物非常微小，不易察觉。", "primary_collocate": null, "pronunciation": "xì wēi", "ipa": "ɕi˥˩ wei˥", "syllable_count": 2, "sentences": [{"text": "人类学研究表明，许多本土社群对水文变化的感知能力远超现代仪器所能捕捉的范畴，他们通过植物生长状态、土壤湿度、风向变化等细微线索，预判干旱趋势并调整耕作安排。", "target_word": "细微", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两个答案只有细微的差别。", "target_word": "细微", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她注意到了他表情的细微变化。", "target_word": "细微", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生发现了病人身体上的细微变化。", "target_word": "细微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器能听到最细微的声音。", "target_word": "细微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈能看出孩子情绪的细微变化。", "target_word": "细微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种颜色的差别很细微。", "target_word": "细微", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师看到了他细微的动作。", "target_word": "细微", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家测量了温度的细微变化。", "target_word": "细微", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的服务要注意每一个细微的地方。", "target_word": "细微", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "細微", "label": "繁体"}], "register": "书面", "sense_fingerprint": "细微|微小而不易察觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd07fe6f-230a-43d0-a4fb-bb51bcd47393') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清脆", "is_correct": false, "explanation": "语义：清脆形容声音清亮，不能用来修饰水文、植物这类线索。"}, {"text": "细微", "is_correct": true, "explanation": "细微：非常微小、不易察觉，修饰“线索”，符合句意。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：高大形容体形或外表，不能修饰能预判干旱的线索。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：甜美多用来形容声音、笑容，不能与“线索”搭配。"}], "explanations": {"清脆": "语义：清脆形容声音清亮，不能用来修饰水文、植物这类线索。", "细微": "细微：非常微小、不易察觉，修饰“线索”，符合句意。", "高大": "体貌：高大形容体形或外表，不能修饰能预判干旱的线索。", "甜美": "搭配：甜美多用来形容声音、笑容，不能与“线索”搭配。"}, "sentence_index": 0, "correct_answer": "细微"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那座大楼很细微，远远就能看见。", "explanation": "这里应该用〈高大〉。细微形容微小、不易察觉的事物，不能形容建筑的体量；说建筑大要用高大。"}, {"text": "这家公司的规模很细微。", "explanation": "这里应该用〈庞大〉。细微指微小到不易察觉，不能形容规模；说规模大要用庞大。"}, {"text": "这头大象很细微，站在那里像一座小山。", "explanation": "这里应该用〈庞大〉。细微指微小到不易察觉，不能形容体形巨大的动物；说体形大要用庞大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻松", "is_correct": false, "explanation": "语义：轻松形容心情或事情不费力，不能用来形容差别的大小。"}, {"text": "细微", "is_correct": true, "explanation": "细微：差别非常小、不易察觉，符合句意。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：滚烫多修饰水、温度，不能说差别很滚烫。"}, {"text": "冰凉", "is_correct": false, "explanation": "搭配：冰凉多修饰手、水等触感，不能说差别很冰凉。"}], "explanations": {"轻松": "语义：轻松形容心情或事情不费力，不能用来形容差别的大小。", "细微": "细微：差别非常小、不易察觉，符合句意。", "滚烫": "搭配：滚烫多修饰水、温度，不能说差别很滚烫。", "冰凉": "搭配：冰凉多修饰手、水等触感，不能说差别很冰凉。"}, "sentence_index": 6, "correct_answer": "细微"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条马路很细微，车辆可以并排行驶。", "explanation": "这里应该用〈宽阔〉。细微指微小难以察觉，不能形容路面的宽窄；说路宽要用宽阔。"}, {"text": "夜市里很细微，人来人往。", "explanation": "这里应该用〈喧闹〉。细微不能形容场面的热闹；说人声嘈杂要用喧闹。"}, {"text": "草原很细微，一眼望不到头。", "explanation": "这里应该用〈辽阔〉。细微不能形容草原的范围；说范围广要用辽阔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块布料上有细微地裂纹。", "corrected_sentence": "这块布料上有细微的裂纹。", "error_description": "错误：“细微地裂纹”，“地”误用。修饰名词要用“的”，应为“细微的裂纹”；“地”用来修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个答案只有细微得差别。", "corrected_sentence": "这两个答案只有细微的差别。", "error_description": "错误：“细微得差别”。形容词修饰名词要用“的”，应为“细微的差别”；“得”用在动词或形容词后面引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
