INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12861, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻解决问题的途径或提示性的信息。", "primary_collocate": null, "pronunciation": "xiàn suǒ", "ipa": "ɕjɛn˥˩ swo˨˩˦", "syllable_count": 2, "sentences": [{"text": "人类学研究表明，许多本土社群对水文变化的感知能力远超现代仪器所能捕捉的范畴，他们通过植物生长状态、土壤湿度、风向变化等细微线索，预判干旱趋势并调整耕作安排。", "target_word": "线索", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "警察找到了一条重要的线索。", "target_word": "线索", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这封信是破案的关键线索。", "target_word": "线索", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们沿着这条线索继续找。", "target_word": "线索", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有留下任何线索就走了。", "target_word": "线索", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者从这些线索中发现了真相。", "target_word": "线索", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电话给我们提供了新线索。", "target_word": "线索", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有线索，事情很难查清楚。", "target_word": "线索", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上的脚印是唯一的线索。", "target_word": "线索", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你想想，还有别的线索吗？", "target_word": "线索", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "線索", "label": "繁体"}], "register": "中性", "sense_fingerprint": "线索|解决问题的提示性信息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd07fe6f-230a-43d0-a4fb-bb51bcd47393') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12861, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "线索", "is_correct": true, "explanation": "“线索”指细微的自然迹象，前文用它说明可据以预判干旱的依据。"}, {"text": "面容", "is_correct": false, "explanation": "体貌：“面容”指人的脸，不能用来描述植物、土壤和风向的变化。"}, {"text": "情绪", "is_correct": false, "explanation": "语义：“情绪”是心理状态，不能作为通过自然状况预判干旱的依据。"}, {"text": "风俗", "is_correct": false, "explanation": "语义：“风俗”是社会习惯，不是可以观察到的自然迹象。"}], "explanations": {"线索": "“线索”指细微的自然迹象，前文用它说明可据以预判干旱的依据。", "面容": "体貌：“面容”指人的脸，不能用来描述植物、土壤和风向的变化。", "情绪": "语义：“情绪”是心理状态，不能作为通过自然状况预判干旱的依据。", "风俗": "语义：“风俗”是社会习惯，不是可以观察到的自然迹象。"}, "sentence_index": 0, "correct_answer": "线索"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的线索很流畅。", "explanation": "这里应该用〈线条〉。线索是引导查找的提示信息，流畅只能用来形容线条。"}, {"text": "我们用这条线索测量了温度。", "explanation": "这里应该用〈工具〉。线索是提示信息，不能拿来测量温度。"}, {"text": "这条公交线索经过三个区。", "explanation": "这里应该用〈线路〉。线索是提示信息，公交行驶的路径要说线路，不能说线索。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12861, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "线索", "is_correct": true, "explanation": "“线索”指可以帮助查找答案的提示，电话提供的正是这类信息。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“提供”多接信息、资源或帮助，“颜色”不能被“提供”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：电话不能提供体温，体温是人体自身的状态。"}, {"text": "体态", "is_correct": false, "explanation": "体貌：“体态”指人的身材姿态，与电话提供信息的语境不符。"}], "explanations": {"线索": "“线索”指可以帮助查找答案的提示，电话提供的正是这类信息。", "颜色": "搭配：“提供”多接信息、资源或帮助，“颜色”不能被“提供”。", "体温": "语义：电话不能提供体温，体温是人体自身的状态。", "体态": "体貌：“体态”指人的身材姿态，与电话提供信息的语境不符。"}, "sentence_index": 6, "correct_answer": "线索"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一口吃掉了那条线索。", "explanation": "这里误把线索当作〈食物〉。线索是提示信息，不能吃。"}, {"text": "这条线索很苦。", "explanation": "这里误把线索当作〈味道〉可感的东西。线索是提示信息，没有味道，不能用“苦”形容。"}, {"text": "这条线索很重，我一个人搬不动。", "explanation": "这里误把线索当作〈实物〉来搬运。线索是提示信息，没有重量，搬不动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12861, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些线索们都很重要。", "corrected_sentence": "这些线索都很重要。", "error_description": "“们”只用于指人的名词，线索是无生命的事物。应说“这些线索”，不能说“这些线索们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12861, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们找到了三线索。", "corrected_sentence": "他们找到了三条线索。", "error_description": "数词后缺少量词：“三”后面要加量词“条”，应说“三条线索”，不能省略量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
