INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12862, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在事情发生之前，根据线索或经验做出推测或判断。", "primary_collocate": null, "pronunciation": "yù pàn", "ipa": "y˥˩ pʰan˥˩", "syllable_count": 2, "sentences": [{"text": "人类学研究表明，许多本土社群对水文变化的感知能力远超现代仪器所能捕捉的范畴，他们通过植物生长状态、土壤湿度、风向变化等细微线索，预判干旱趋势并调整耕作安排。", "target_word": "预判", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "现代风力涡轮机已集成智能控制系统：激光雷达预判风速变化，实时调节桨距角以优化转矩；数字孪生技术则构建虚拟机组模型，实现故障预测性维护。", "target_word": "预判", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老农看云的样子，就能预判明天的天气。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经验丰富的医生能预判病人的恢复情况。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他根据对手的动作预判了球的方向。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "棋手要学会预判对方的下一步。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机预判前方会堵车，就换了路线。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家根据数据预判明年房价会上涨。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "守门员预判了射门的方向，扑出了球。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她预判得很准，今天果然下雨了。", "target_word": "预判", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预判了", "label": "完成体"}, {"form": "预判过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "事前依据线索或经验作出推测判断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c3d54eb-37c5-4193-8809-1266ef82ae7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12862, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预判", "is_correct": true, "explanation": "预判（yù pàn）：在事情发生之前，根据线索或经验作出推测。"}, {"text": "玉盘", "is_correct": false, "explanation": "pán（第二声）与 pàn（第四声）声调不同，玉盘指玉做的盘子。"}, {"text": "预拌", "is_correct": false, "explanation": "bàn 与 pàn 声母不同（b 与 p），预拌指预先搅拌好的材料。"}, {"text": "预探", "is_correct": false, "explanation": "tàn 与 pàn 声母不同（t 与 p），预探指事先勘探。"}, {"text": "鱼盘", "is_correct": false, "explanation": "yú 与 yù 声调不同，pán 与 pàn 声调也不同，鱼盘指盛鱼的盘子。"}], "explanations": {"预判": "预判（yù pàn）：在事情发生之前，根据线索或经验作出推测。", "玉盘": "pán（第二声）与 pàn（第四声）声调不同，玉盘指玉做的盘子。", "预拌": "bàn 与 pàn 声母不同（b 与 p），预拌指预先搅拌好的材料。", "预探": "tàn 与 pàn 声母不同（t 与 p），预探指事先勘探。", "鱼盘": "yú 与 yù 声调不同，pán 与 pàn 声调也不同，鱼盘指盛鱼的盘子。"}, "sentence_index": null, "correct_answer": "预判"}, "level_3": {"options": [{"text": "预判", "is_correct": true, "explanation": "正确：预判指事前根据线索推测，与“通过细微线索”“调整耕作安排”的语境相合。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：前文说靠线索推测干旱，忽视干旱趋势与此因果相反。"}, {"text": "擦除", "is_correct": false, "explanation": "语义：擦除指抹去，与“通过细微线索”提前推测干旱趋势的逻辑相反。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记与前文靠线索提前推测干旱趋势的逻辑相反。"}], "explanations": {"预判": "正确：预判指事前根据线索推测，与“通过细微线索”“调整耕作安排”的语境相合。", "忽视": "语义：前文说靠线索推测干旱，忽视干旱趋势与此因果相反。", "擦除": "语义：擦除指抹去，与“通过细微线索”提前推测干旱趋势的逻辑相反。", "忘记": "语义：忘记与前文靠线索提前推测干旱趋势的逻辑相反。"}, "sentence_index": 0, "correct_answer": "预判"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我预判了小时候住过的那栋房子。", "explanation": "这里应该用〈回忆〉。预判指对尚未发生的事作推测，小时候住过的房子已经过去，只能回忆。"}, {"text": "我预判了窗外的天空是蓝色的。", "explanation": "这里应该用〈看见〉。窗外的景象就在眼前，不是尚未发生的事，不能用预判。"}, {"text": "我预判了书架上那本书的书名。", "explanation": "这里应该用〈看清〉。预判针对尚未发生的事，书名就在眼前，应直接看清。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预判", "is_correct": true, "explanation": "正确：“预判前方会堵车”是事前推测，与“就换了路线”的因果相合。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：拖延指把事情往后推，不能用于“前方会堵车”，句意不通。"}, {"text": "目睹", "is_correct": false, "explanation": "语义：目睹指亲眼见到已经发生的事，“会堵车”说的是还没发生的事，不能目睹。"}, {"text": "推迟", "is_correct": false, "explanation": "搭配：“推迟”的对象是会议、计划等安排，不能说推迟堵车。"}], "explanations": {"预判": "正确：“预判前方会堵车”是事前推测，与“就换了路线”的因果相合。", "拖延": "语义：拖延指把事情往后推，不能用于“前方会堵车”，句意不通。", "目睹": "语义：目睹指亲眼见到已经发生的事，“会堵车”说的是还没发生的事，不能目睹。", "推迟": "搭配：“推迟”的对象是会议、计划等安排，不能说推迟堵车。"}, "sentence_index": 6, "correct_answer": "预判"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人预判了刚才那场雨。", "explanation": "这里应该用〈经历〉。预判只针对尚未发生的事，刚才的雨已经过去，不能再预判。"}, {"text": "她预判了那只杯子。", "explanation": "这里应该用〈看〉或〈拿〉。预判只用于对尚未发生的事作推测，杯子是眼前的具体物品，要说看或拿。"}, {"text": "他预判了屏幕上显示的数字。", "explanation": "这里应该用〈读〉。屏幕上的数字就在眼前，直接读出即可，预判只能用于对尚未发生的事作推测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师正在预判了考试的难度。", "corrected_sentence": "老师正在预判考试的难度。", "error_description": "“正在”表示动作进行中，不能与表示完成的“了”同用，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没预判到了这场雨。", "corrected_sentence": "我没预判到这场雨。", "error_description": "“预判到”是动补结构，否定后不能再加“了”，应说“没预判到这场雨”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12864, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12864, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12864, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在土地上翻土、播种、除草等，为种植庄稼做准备。", "primary_collocate": null, "pronunciation": "gēng zuò", "ipa": "kɤŋ˥ tsuo˥˩", "syllable_count": 2, "sentences": [{"text": "人类学研究表明，许多本土社群对水文变化的感知能力远超现代仪器所能捕捉的范畴，他们通过植物生长状态、土壤湿度、风向变化等细微线索，预判干旱趋势并调整耕作安排。", "target_word": "耕作", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "某些国家已启动“授粉者保护区”计划，通过立法限制特定神经毒性农药的使用，并鼓励农场主采用生态友好型耕作方式。", "target_word": "耕作", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "农民在田里耕作了一整天。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地太硬，不适合耕作。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天一到，村民就开始耕作。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷耕作了一辈子，从不离开土地。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用老办法耕作，收成不太好。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的梯田很难用机器耕作。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后土地变软，正好耕作。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的人世代耕作，种玉米和水稻。", "target_word": "耕作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "耕作了", "label": "完成体"}, {"form": "耕作过", "label": "经历体"}, {"form": "耕作着", "label": "持续体"}], "register": "书面语", "sense_fingerprint": "在土地上翻土播种除草，为种庄稼做准备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c3d54eb-37c5-4193-8809-1266ef82ae7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12864, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耕作", "is_correct": true, "explanation": "正确：“调整耕作安排”指调整农事安排，与前文的农业语境相符。"}, {"text": "放映", "is_correct": false, "explanation": "语义：前文讲的是农事和干旱，“放映”指播放影片，与此无关。"}, {"text": "排版", "is_correct": false, "explanation": "搭配：“排版”是印刷用语，不能用来指农事安排。"}, {"text": "腌制", "is_correct": false, "explanation": "语义：腌制指加工食品，与干旱趋势、土壤湿度的语境无关。"}], "explanations": {"耕作": "正确：“调整耕作安排”指调整农事安排，与前文的农业语境相符。", "放映": "语义：前文讲的是农事和干旱，“放映”指播放影片，与此无关。", "排版": "搭配：“排版”是印刷用语，不能用来指农事安排。", "腌制": "语义：腌制指加工食品，与干旱趋势、土壤湿度的语境无关。"}, "sentence_index": 0, "correct_answer": "耕作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服太湿，需要耕作。", "explanation": "这里应该用〈晾〉。耕作只用于土地上的农事，湿衣服要说晾干。"}, {"text": "渔民每天在船上耕作。", "explanation": "这里应该用〈捕鱼〉。耕作是在土地上进行的农事，船上应说捕鱼。"}, {"text": "他耕作了那张桌子。", "explanation": "这里应该用〈修〉。耕作是翻土、播种等农事，桌子要修理，不能用耕作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耕作", "is_correct": true, "explanation": "正确：“用老办法耕作”指用传统方式种地，与“收成不太好”因果相连。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：演奏是奏乐，与“老办法”和“收成”都无关，句子说不通。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”的对象是房屋等建筑，不能用于“收成”的语境。"}, {"text": "拍摄", "is_correct": false, "explanation": "语义：拍摄是拍摄影像，与“老办法”和收成无关。"}], "explanations": {"耕作": "正确：“用老办法耕作”指用传统方式种地，与“收成不太好”因果相连。", "演奏": "语义：演奏是奏乐，与“老办法”和“收成”都无关，句子说不通。", "装修": "搭配：“装修”的对象是房屋等建筑，不能用于“收成”的语境。", "拍摄": "语义：拍摄是拍摄影像，与“老办法”和收成无关。"}, "sentence_index": 6, "correct_answer": "耕作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨师在厨房里耕作，做了一桌菜。", "explanation": "这里应该用〈烹饪〉。耕作指在田里种庄稼，做菜要说烹饪。"}, {"text": "这条河每天都在耕作。", "explanation": "这里应该用〈流淌〉。河水是自然流动的，耕作是人在田里做的农事，不能用于河流。"}, {"text": "他用剪刀耕作。", "explanation": "这里应该用〈修剪〉。剪刀用于修剪枝叶，耕作要用锄头、犁等农具翻土。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民正在田里耕作了。", "corrected_sentence": "农民正在田里耕作。", "error_description": "“正在”表示动作正在进行，不能与“了”同用，应说“正在田里耕作”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们不耕作过这块地。", "corrected_sentence": "我们没耕作过这块地。", "error_description": "表示经历过的事情否定要用“没”，不能用“不”，应说“没耕作过”，不说“不耕作过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d501c33-c21b-43f8-9ac6-864766fdbc5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12865, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "运动", "is_correct": true, "explanation": "“运动”与“静止”互为反义，指物体的位置或状态发生变化。"}, {"text": "吃饭", "is_correct": false, "explanation": "“吃饭”与“静止”没有反义关系，二者不构成对立。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”与“静止”没有反义关系，二者不构成对立。"}, {"text": "写字", "is_correct": false, "explanation": "“写字”与“静止”没有反义关系，二者不构成对立。"}], "correct_answer": "运动", "explanations": {"运动": "“运动”与“静止”互为反义，指物体的位置或状态发生变化。", "吃饭": "“吃饭”与“静止”没有反义关系，二者不构成对立。", "唱歌": "“唱歌”与“静止”没有反义关系，二者不构成对立。", "写字": "“写字”与“静止”没有反义关系，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12865, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "运动", "is_correct": true, "explanation": "“运动”与“静止”互为反义，指物体的位置或状态发生变化。"}, {"text": "读书", "is_correct": false, "explanation": "“读书”与“静止”没有反义关系，二者不构成对立。"}, {"text": "洗澡", "is_correct": false, "explanation": "“洗澡”与“静止”没有反义关系，二者不构成对立。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”与“静止”没有反义关系，二者不构成对立。"}], "correct_answer": "运动", "explanations": {"运动": "“运动”与“静止”互为反义，指物体的位置或状态发生变化。", "读书": "“读书”与“静止”没有反义关系，二者不构成对立。", "洗澡": "“洗澡”与“静止”没有反义关系，二者不构成对立。", "睡觉": "“睡觉”与“静止”没有反义关系，二者不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12865, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "物体保持原来的位置不变，没有运动或变化。", "primary_collocate": null, "pronunciation": "jìng zhǐ", "ipa": "tɕiŋ˥˩ ʈʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "因此，这些传统并非静止的“历史遗存”，而是持续演化的知识生态系统。", "target_word": "静止", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "照片里的小船是静止的。", "target_word": "静止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，静止的物体也有重量。", "target_word": "静止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌上的杯子一直保持静止。", "target_word": "静止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在地面上看，路边的树是静止的，开过的车是运动的。", "target_word": "静止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水面静止时，能看见山的影子。", "target_word": "静止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月球上没有风，插在那里的旗子几乎是静止的。", "target_word": "静止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有相对静止，没有绝对静止。", "target_word": "静止", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "他看着屏幕上静止的画面，不知道电脑是不是坏了。", "target_word": "静止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物体不受力时，会保持静止或匀速运动。", "target_word": "静止", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "相对静止", "label": "复合"}, {"form": "绝对静止", "label": "复合"}, {"form": "静止状态", "label": "复合"}, {"form": "靜止", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体保持原位、没有运动或变化的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd07fe6f-230a-43d0-a4fb-bb51bcd47393') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12865, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "静止", "is_correct": true, "explanation": "“静止”指没有运动或变化，与后文“持续演化”形成对比。"}, {"text": "凉爽", "is_correct": false, "explanation": "语义：“凉爽”形容温度的感受，不能修饰“历史遗存”，也不能与“持续演化”形成对比。"}, {"text": "活泼", "is_correct": false, "explanation": "搭配：“活泼”多用于形容人或动物的性格，不能修饰“历史遗存”。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”描写滋味或感情，与讨论传统和知识系统的语境不符。"}], "explanations": {"静止": "“静止”指没有运动或变化，与后文“持续演化”形成对比。", "凉爽": "语义：“凉爽”形容温度的感受，不能修饰“历史遗存”，也不能与“持续演化”形成对比。", "活泼": "搭配：“活泼”多用于形容人或动物的性格，不能修饰“历史遗存”。", "甜蜜": "语义：“甜蜜”描写滋味或感情，与讨论传统和知识系统的语境不符。"}, "sentence_index": 0, "correct_answer": "静止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是个很静止的孩子。", "explanation": "这里应该用〈安静〉。静止指物体保持不动，不能用来形容人的性格安静。"}, {"text": "她听到消息后，心情很静止。", "explanation": "这里应该用〈平静〉。静止指物体不动，不用来形容人心情的安定。"}, {"text": "水在零下十度时会静止成冰。", "explanation": "这里应该用〈凝固〉。静止只表示不动，不表示液体变为固体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12865, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "静止", "is_correct": true, "explanation": "“静止”与前文“没有风”相呼应，说明旗子不动。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”形容人的心情，不能用来修饰旗子。"}, {"text": "湿润", "is_correct": false, "explanation": "语义：月球上没有水，旗子不可能是湿润的，与语境冲突。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容人的态度，不能用来形容旗子。"}], "explanations": {"静止": "“静止”与前文“没有风”相呼应，说明旗子不动。", "高兴": "搭配：“高兴”形容人的心情，不能用来修饰旗子。", "湿润": "语义：月球上没有水，旗子不可能是湿润的，与语境冲突。", "热情": "搭配：“热情”形容人的态度，不能用来形容旗子。"}, "sentence_index": 6, "correct_answer": "静止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "通话突然静止了，我们只好重新打一次。", "explanation": "这里应该用〈中断〉。静止指物体不动，通话中断并不是“不动”。"}, {"text": "他从早上起就静止地工作，一直没有休息。", "explanation": "这里误把静止当成〈勤奋〉的意思。静止只表示物体不动，不能用来形容人努力干活。"}, {"text": "这台电风扇静止地转动，吹出了凉风。", "explanation": "这里误把静止当成〈平稳〉的意思。静止只表示没有运动，不能用来形容风扇转得平稳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张照片里的树静止的。", "corrected_sentence": "这张照片里的树是静止的。", "error_description": "漏字与语法：句末用“……的”作状态谓语时，前面需要“是”，应说“树是静止的”，不能说“树静止的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "船一直静止水面上。", "corrected_sentence": "船一直静止在水面上。", "error_description": "漏字：表示位置时“静止”后要用介词“在”，应说“静止在水面上”，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
