INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12866, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12866, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指古代或过去遗留下来的物体、文化、痕迹等。", "primary_collocate": null, "pronunciation": "yí cún", "ipa": "i˧˥ tsʰuən˧˥", "syllable_count": 2, "sentences": [{"text": "因此，这些传统并非静止的“历史遗存”，而是持续演化的知识生态系统。", "target_word": "遗存", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "考古队在山下发现了一处古代遗存。", "target_word": "遗存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些文化遗存让我们了解古人的生活。", "target_word": "遗存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座老城里保存着不少明清时期的遗存。", "target_word": "遗存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，这处遗存已经有三千年的历史。", "target_word": "遗存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河边的新石器时代遗存需要认真保护。", "target_word": "遗存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆里展出了从古墓中出土的遗存。", "target_word": "遗存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争遗存至今还提醒着人们要珍惜和平。", "target_word": "遗存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古桥是当地最重要的文化遗存之一。", "target_word": "遗存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客不能随便触摸遗存，以免造成破坏。", "target_word": "遗存", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "处", "label": "量词"}, {"form": "文化遗存", "label": "复合"}, {"form": "历史遗存", "label": "复合"}, {"form": "遺存", "label": "繁体"}], "register": "书面", "sense_fingerprint": "古代或过去遗留下来的物体、文化、痕迹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd07fe6f-230a-43d0-a4fb-bb51bcd47393') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12866, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遗存", "is_correct": true, "explanation": "遗存：指历史遗留下来的物件或痕迹，与“历史”搭配，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“历史”修饰的是过去留下的人事物，不能说“历史天气”。"}, {"text": "午餐", "is_correct": false, "explanation": "语义：句子说的是传统与知识体系的延续，“午餐”只是一顿饭，句意不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“历史”后不接“体温”这类身体状况，“历史体温”不成立。"}], "explanations": {"遗存": "遗存：指历史遗留下来的物件或痕迹，与“历史”搭配，符合句意。", "天气": "搭配：“历史”修饰的是过去留下的人事物，不能说“历史天气”。", "午餐": "语义：句子说的是传统与知识体系的延续，“午餐”只是一顿饭，句意不通。", "体温": "搭配：“历史”后不接“体温”这类身体状况，“历史体温”不成立。"}, "sentence_index": 0, "correct_answer": "遗存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父亲去世后，他继承了一笔不小的遗存。", "explanation": "这里应该用〈遗产〉。遗产指留给后人的财产，遗存指古代或过去留下的物件和痕迹，不指金钱。"}, {"text": "考古队在山下发现了一本古代遗存。", "explanation": "这里应该用〈处〉。遗存多指一处或一批痕迹、遗物，“本”用于书册，不用于遗存。"}, {"text": "老人临终前说出了自己的遗存。", "explanation": "这里应该用〈遗愿〉。遗愿指临终前的心愿，遗存指古代或过去留下的物件和痕迹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌声", "is_correct": false, "explanation": "搭配：“出土”指从地下挖出实物，“歌声”是声音，无法出土。"}, {"text": "遗存", "is_correct": true, "explanation": "遗存：指古墓中出土的古代遗留物，与“出土”搭配，符合句意。"}, {"text": "晚餐", "is_correct": false, "explanation": "语义：博物馆展出的是可以陈列的物件，“晚餐”是一顿饭，不能在展览中展出。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“出土”只能用于器物或遗迹，“空气”不能从地下挖出。"}], "explanations": {"歌声": "搭配：“出土”指从地下挖出实物，“歌声”是声音，无法出土。", "遗存": "遗存：指古墓中出土的古代遗留物，与“出土”搭配，符合句意。", "晚餐": "语义：博物馆展出的是可以陈列的物件，“晚餐”是一顿饭，不能在展览中展出。", "空气": "搭配：“出土”只能用于器物或遗迹，“空气”不能从地下挖出。"}, "sentence_index": 6, "correct_answer": "遗存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父留下的遗存教导我们要诚实做人。", "explanation": "这里应该用〈遗训〉。遗训指前人留下的教导，遗存指古代或过去留下的物件和痕迹，不指教导。"}, {"text": "考古学家在地下发现了一首古代遗存。", "explanation": "这里应该用〈处〉或〈批〉。“首”用于诗词歌曲，遗存指遗留下来的古物或痕迹，不能用“首”计量。"}, {"text": "这种病是父母遗存给他的。", "explanation": "这里应该用〈遗传〉。遗传指疾病或特征通过基因传给后代，遗存指古代或过去留下的物件和痕迹，不能用来表示传给后代。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "博物馆正在整理这一只古代遗存。", "corrected_sentence": "博物馆正在整理这批古代遗存。", "error_description": "量词错误：遗存应与“批”或“处”搭配，应说“这批古代遗存”，不能说“这一只古代遗存”；“只”多用于单个的动物或器物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "考古队在这一带发现了几处古代地遗存。", "corrected_sentence": "考古队在这一带发现了几处古代遗存。", "error_description": "助词错误：“古代”修饰名词时不加“地”，“地”用于修饰动词。应删去“地”，说“古代遗存”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12868, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12868, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12868, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种修建在河流或海峡上用于拦水、调节水量的建筑物。", "primary_collocate": null, "pronunciation": "dà bà", "ipa": "tɑ˥˩ pɑ˥˩", "syllable_count": 2, "sentences": [{"text": "当现代工程试图以大坝与海水淡化解决缺水问题时，传统实践提醒我们：可持续的资源管理，或许不在于征服自然，而在于深刻理解并尊重其内在秩序。", "target_word": "大坝", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座大坝修在河上，可以调节水量。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大坝拦住了河水，下游的水变少了。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨季到了，工人打开大坝的闸门放水。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河上建了一座很高的大坝。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大坝建成以后，附近的农田不缺水了。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船去看了河上的大坝。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大坝可以发电，也能防止洪水。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了调节水量，政府决定修一座大坝。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大坝的水库里有很多鱼。", "target_word": "大坝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座大坝", "label": "量词"}, {"form": "大壩", "label": "繁体"}], "register": "中性", "sense_fingerprint": "修在河流上拦水、调节水量的水利工程建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3bbb28-ef77-4126-94bd-0d4dcabd7445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12868, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大坝", "is_correct": true, "explanation": "正确答案：读 dà bà，指修在河流上拦水的建筑。"}, {"text": "大把", "is_correct": false, "explanation": "第二个音节声调不同：bǎ（第三声）与 bà（第四声）不同，意思是很多。"}, {"text": "大巴", "is_correct": false, "explanation": "第二个音节声调不同：bā（第一声）与 bà（第四声）不同，意思是大型客车。"}, {"text": "大半", "is_correct": false, "explanation": "第二个音节韵母不同：bàn 比 bà 多了 n，意思是大部分。"}, {"text": "大骂", "is_correct": false, "explanation": "第二个音节声母不同：mà 与 bà 的声母 m、b 不同，意思是严厉地责骂。"}], "explanations": {"大坝": "正确答案：读 dà bà，指修在河流上拦水的建筑。", "大把": "第二个音节声调不同：bǎ（第三声）与 bà（第四声）不同，意思是很多。", "大巴": "第二个音节声调不同：bā（第一声）与 bà（第四声）不同，意思是大型客车。", "大半": "第二个音节韵母不同：bàn 比 bà 多了 n，意思是大部分。", "大骂": "第二个音节声母不同：mà 与 bà 的声母 m、b 不同，意思是严厉地责骂。"}, "sentence_index": null, "correct_answer": "大坝"}, "level_3": {"options": [{"text": "大坝", "is_correct": true, "explanation": "大坝：修在河上、能拦水调节水量的水利建筑，与海水淡化一样能解决缺水问题，符合句意。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁是金属材料，不能拦水或调节水量，无法用来解决缺水问题。"}, {"text": "大家伙", "is_correct": false, "explanation": "语域：“大家伙”是口语词，语体随意，与这段书面论述不合；而且它也不能解决缺水问题。"}, {"text": "公路", "is_correct": false, "explanation": "语义：公路用于通行车辆，与拦水、解决缺水问题无关。"}], "explanations": {"大坝": "大坝：修在河上、能拦水调节水量的水利建筑，与海水淡化一样能解决缺水问题，符合句意。", "钢铁": "语义：钢铁是金属材料，不能拦水或调节水量，无法用来解决缺水问题。", "大家伙": "语域：“大家伙”是口语词，语体随意，与这段书面论述不合；而且它也不能解决缺水问题。", "公路": "语义：公路用于通行车辆，与拦水、解决缺水问题无关。"}, "sentence_index": 0, "correct_answer": "大坝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨季到了，工人关上大坝防止河水上涨。", "explanation": "这里应该用〈水闸〉。关闭、打开的是闸门，大坝是整座拦水的建筑，不能说“关上大坝”。"}, {"text": "夏天我们常在大坝里游泳。", "explanation": "这里应该用〈水库〉。游泳要在水库或河里，大坝是拦水的建筑，人不能在里面游泳。"}, {"text": "这座大坝很有名，菜很好吃。", "explanation": "这里应该用〈饭店〉。饭店是吃饭的地方，菜可以好吃；大坝是拦水的建筑，不能说菜好吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12868, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大坝", "is_correct": true, "explanation": "正确答案：读 dà bà，指修在河流上拦水的建筑。"}, {"text": "打靶", "is_correct": false, "explanation": "两个音节声调都不同：dǎ（第三声）、bǎ（第三声），意思是朝靶子射击。"}, {"text": "大败", "is_correct": false, "explanation": "第二个音节韵母不同：bài 比 bà 多了 i，意思是惨败。"}, {"text": "大棒", "is_correct": false, "explanation": "第二个音节韵母不同：bàng 比 bà 多了 ng，意思是粗棍子。"}], "explanations": {"大坝": "正确答案：读 dà bà，指修在河流上拦水的建筑。", "打靶": "两个音节声调都不同：dǎ（第三声）、bǎ（第三声），意思是朝靶子射击。", "大败": "第二个音节韵母不同：bài 比 bà 多了 i，意思是惨败。", "大棒": "第二个音节韵母不同：bàng 比 bà 多了 ng，意思是粗棍子。"}, "sentence_index": null, "correct_answer": "大坝"}, "level_3": {"options": [{"text": "大坝", "is_correct": true, "explanation": "大坝：河上可以坐船前去观看的水利建筑，句意合理。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：河上不会有钢琴供人坐船去看，句子说的是河上的建筑。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不是可以坐船去看的河上景物。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”一般说看得见的东西，不说“看声音”，这里该用“听”。"}], "explanations": {"大坝": "大坝：河上可以坐船前去观看的水利建筑，句意合理。", "钢琴": "语义：河上不会有钢琴供人坐船去看，句子说的是河上的建筑。", "作业": "语义：作业是学习任务，不是可以坐船去看的河上景物。", "声音": "搭配：“看”一般说看得见的东西，不说“看声音”，这里该用“听”。"}, "sentence_index": 6, "correct_answer": "大坝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座大坝有二十层，住着很多人。", "explanation": "这里应该用〈楼房〉。楼房供人居住，大坝是拦水的建筑，不住人。"}, {"text": "这座大坝很深，夏天能打出凉水。", "explanation": "这里应该用〈井〉。井可以打水，大坝是拦水的建筑，不能从里面打出水来。"}, {"text": "这座大坝很大，里面卖很多衣服。", "explanation": "这里应该用〈商店〉。商店用来买卖东西，大坝是拦水的建筑，里面不卖衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子靠一张大坝防洪。", "corrected_sentence": "这个村子靠一座大坝防洪。", "error_description": "量词错：大坝是建筑，应该用“座”；“张”用于纸、桌子等平面的东西，不能用来数大坝。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村民们盼着这只大坝早点建成。", "corrected_sentence": "村民们盼着这座大坝早点建成。", "error_description": "量词错：“大坝”是建筑，应该用“座”；“只”用于动物等，不能用来数大坝。正确形式：这座大坝。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12869, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12869, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12869, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海水是海洋中的水，含有盐分和其他矿物质，覆盖了地球表面大部分区域。", "primary_collocate": null, "pronunciation": "hǎi shuǐ", "ipa": "xaɪ˨˩˦ ʂueɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在海边走了很久，衣服上全是海水的咸味。", "target_word": "海水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海水又咸又苦，不能直接喝。", "target_word": "海水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在海边玩的时候，不小心喝了一口海水。", "target_word": "海水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天的海水很暖和，孩子们都想下去游泳。", "target_word": "海水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把海水放在太阳下晒，就能得到盐。", "target_word": "海水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天风很大，海水一下一下地拍打着岸边。", "target_word": "海水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水退了以后，沙滩上留下了很多小贝壳。", "target_word": "海水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清晨的海水是深蓝色的，远处还有几只海鸟。", "target_word": "海水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水里有很多盐，所以人在海里更容易浮起来。", "target_word": "海水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水进了他的耳朵，他觉得很难受。", "target_word": "海水", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "杯", "label": "量词"}, {"form": "桶", "label": "量词"}, {"form": "海水鱼", "label": "复合"}, {"form": "海水浴", "label": "复合"}], "register": "中性", "sense_fingerprint": "海洋中含盐分和矿物质的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd07fe6f-230a-43d0-a4fb-bb51bcd47393') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12869, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "河水", "is_correct": false, "explanation": "语义：河水是淡水，没有咸味，不能说“河水的咸味”。"}, {"text": "海水", "is_correct": true, "explanation": "海水：海里的水带有咸味，衣服上的咸味正是海水留下的，符合句意。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水是淡水，不带咸味，“雨水的咸味”不成立。"}, {"text": "汽油", "is_correct": false, "explanation": "搭配：汽油没有咸味，不能说“汽油的咸味”。"}], "explanations": {"河水": "语义：河水是淡水，没有咸味，不能说“河水的咸味”。", "海水": "海水：海里的水带有咸味，衣服上的咸味正是海水留下的，符合句意。", "雨水": "语义：雨水是淡水，不带咸味，“雨水的咸味”不成立。", "汽油": "搭配：汽油没有咸味，不能说“汽油的咸味”。"}, "sentence_index": 0, "correct_answer": "海水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个湖的海水很清，村里人天天来这里取水。", "explanation": "这里应该用〈淡水〉。湖里的是淡水，海水只存在于海洋中，不会出现在湖里。"}, {"text": "他用一块海水把杯子洗干净了。", "explanation": "这里应该用〈桶〉或〈杯〉。海水是液体，“块”用于块状的东西，不能用于海水。"}, {"text": "海水吹来，带着一阵咸味。", "explanation": "这里应该用〈海风〉。风会吹来，海水是水，不会被吹来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "搭配：“退”多用于潮水、水位等，不能说太阳退了。"}, {"text": "海水", "is_correct": true, "explanation": "海水：指海里的水，退潮后留下贝壳，符合句意。"}, {"text": "草原", "is_correct": false, "explanation": "语义：草原不会退去，也与沙滩和贝壳无关。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不会退，句子说的是海水的退潮。"}], "explanations": {"太阳": "搭配：“退”多用于潮水、水位等，不能说太阳退了。", "海水": "海水：指海里的水，退潮后留下贝壳，符合句意。", "草原": "语义：草原不会退去，也与沙滩和贝壳无关。", "玻璃": "语义：玻璃不会退，句子说的是海水的退潮。"}, "sentence_index": 6, "correct_answer": "海水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下完雨，院子里积了一摊海水。", "explanation": "这里应该用〈雨水〉。海水来自海洋，院子里积的是雨水。"}, {"text": "他在碗里倒了一粒海水。", "explanation": "这里应该用〈滴〉或〈杯〉。海水是液体，“粒”用于颗粒状的东西。"}, {"text": "这瓶海水是从山泉里接来的，喝起来很甜。", "explanation": "这里应该用〈山泉水〉。海水来自海洋，又咸又苦；山泉是淡水，喝起来是甜的，不会是海水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们每天从海边带回一只海水做实验。", "corrected_sentence": "他们每天从海边带回一瓶海水做实验。", "error_description": "量词错误：海水是液体，应说“一瓶海水”或“一桶海水”；“只”用于单个的动物或器物，不能用于液体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "涨潮时，海水慢慢漫下了沙滩。", "corrected_sentence": "涨潮时，海水慢慢漫上了沙滩。", "error_description": "补语错误：涨潮时海水从海里向岸上涌，应说“漫上”；“漫下”方向相反，不合句意。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa055015-14b9-4c20-9a50-c54ca8533eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12870, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "强化", "is_correct": true, "explanation": "强化指使程度、影响增强，与淡化（使程度、重要性减弱）互为反义。"}, {"text": "维持", "is_correct": false, "explanation": "语义：“维持”是保持原状，与淡化不构成反义关系。"}, {"text": "开始", "is_correct": false, "explanation": "语义：“开始”指起始，与淡化不构成反义关系。"}, {"text": "完成", "is_correct": false, "explanation": "语义：“完成”指做完，与淡化不构成反义关系。"}], "correct_answer": "强化", "explanations": {"强化": "强化指使程度、影响增强，与淡化（使程度、重要性减弱）互为反义。", "维持": "语义：“维持”是保持原状，与淡化不构成反义关系。", "开始": "语义：“开始”指起始，与淡化不构成反义关系。", "完成": "语义：“完成”指做完，与淡化不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12870, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "强化", "is_correct": true, "explanation": "强化指使程度、影响增强，与淡化（使程度、重要性减弱）互为反义。"}, {"text": "收获", "is_correct": false, "explanation": "语义：“收获”指得到成果，与淡化不构成反义关系。"}, {"text": "打开", "is_correct": false, "explanation": "语义：“打开”指使封闭的东西敞开，与淡化不构成反义关系。"}, {"text": "检查", "is_correct": false, "explanation": "语义：“检查”指查看是否正确，与淡化不构成反义关系。"}], "correct_answer": "强化", "explanations": {"强化": "强化指使程度、影响增强，与淡化（使程度、重要性减弱）互为反义。", "收获": "语义：“收获”指得到成果，与淡化不构成反义关系。", "打开": "语义：“打开”指使封闭的东西敞开，与淡化不构成反义关系。", "检查": "语义：“检查”指查看是否正确，与淡化不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12870, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使浓度、强度、重要性等降低或减弱。", "primary_collocate": null, "pronunciation": "dàn huà", "ipa": "tan˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "这些年来，两国之间的敌意已经慢慢淡化了。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间会慢慢淡化他心里的痛苦。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能淡化这次事故的严重性。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有淡化这个问题的重要性。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过很多年，两家人的矛盾淡化了。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想淡化自己过去的错误。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里淡化了这件事的影响。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，我和老朋友的联系慢慢淡化了。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着把大家的紧张情绪淡化了。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影淡化了战争的残酷。", "target_word": "淡化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "淡化了", "label": "体标"}, {"form": "淡化过", "label": "体标"}, {"form": "淡化处理", "label": "复合"}], "register": "中性", "sense_fingerprint": "使程度、影响或重要性减弱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bede058a-09f7-4687-907e-4a8684b48d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12870, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "淡化", "is_correct": true, "explanation": "dàn huà，意思是使浓度、强度或重要性降低或减弱。"}, {"text": "汉化", "is_correct": false, "explanation": "hàn 与 dàn 声母不同（h 与 d），意思是本地化，如把游戏汉化。"}, {"text": "碳化", "is_correct": false, "explanation": "tàn 与 dàn 声母不同（t 与 d），意思是变成碳的化学过程。"}, {"text": "简化", "is_correct": false, "explanation": "jiǎn 与 dàn 声母不同（j 与 d），声调也不同，意思是把复杂的东西变简单。"}, {"text": "蛋花", "is_correct": false, "explanation": "huā 与 huà 声调不同（第一声与第四声），意思是蛋花，如蛋花汤。"}], "explanations": {"淡化": "dàn huà，意思是使浓度、强度或重要性降低或减弱。", "汉化": "hàn 与 dàn 声母不同（h 与 d），意思是本地化，如把游戏汉化。", "碳化": "tàn 与 dàn 声母不同（t 与 d），意思是变成碳的化学过程。", "简化": "jiǎn 与 dàn 声母不同（j 与 d），声调也不同，意思是把复杂的东西变简单。", "蛋花": "huā 与 huà 声调不同（第一声与第四声），意思是蛋花，如蛋花汤。"}, "sentence_index": null, "correct_answer": "淡化"}, "level_3": {"options": [{"text": "淡化", "is_correct": true, "explanation": "淡化：使两国之间的敌意减弱，与“这些年来”“慢慢”的语境相符。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：“冷冻”是降低温度使东西变硬，不能用于敌意。"}, {"text": "污染", "is_correct": false, "explanation": "语义：“污染”是使环境或物质变坏，不能用于敌意。"}, {"text": "挖掘", "is_correct": false, "explanation": "搭配：“挖掘”一般搭配潜力、资源，不能说挖掘敌意。"}], "explanations": {"淡化": "淡化：使两国之间的敌意减弱，与“这些年来”“慢慢”的语境相符。", "冷冻": "语义：“冷冻”是降低温度使东西变硬，不能用于敌意。", "污染": "语义：“污染”是使环境或物质变坏，不能用于敌意。", "挖掘": "搭配：“挖掘”一般搭配潜力、资源，不能说挖掘敌意。"}, "sentence_index": 0, "correct_answer": "淡化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重淡化了三公斤。", "explanation": "这里应该用〈减轻〉。淡化说的是程度、影响的减弱，体重减少要说减轻，不能用淡化。"}, {"text": "这个仓库的存货淡化了两百件。", "explanation": "这里应该用〈减少〉。淡化说的是程度、影响的减弱，存货等数量要用减少，不能用淡化。"}, {"text": "这座桥淡化了两岸之间的距离。", "explanation": "这里应该用〈缩短〉。淡化说的是程度、影响的减弱，距离要用缩短，不能用淡化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12870, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "淡化", "is_correct": true, "explanation": "dàn huà，意思是使浓度、强度或重要性降低或减弱。"}, {"text": "炭化", "is_correct": false, "explanation": "tàn 与 dàn 声母不同（t 与 d），意思是变成炭的化学过程，与碳化同音。"}, {"text": "泛化", "is_correct": false, "explanation": "fàn 与 dàn 声母不同（f 与 d），意思是范围变宽、概括化。"}, {"text": "分化", "is_correct": false, "explanation": "fēn 与 dàn 声母、声调都不同（f 与 d，第一声与第四声），意思是分开、分裂。"}, {"text": "感化", "is_correct": false, "explanation": "gǎn 与 dàn 声母、声调都不同（g 与 d，第三声与第四声），意思是用道理影响使人改变。"}, {"text": "演化", "is_correct": false, "explanation": "yǎn 与 dàn 声母、声调都不同（零声母与 d，第三声与第四声），意思是逐步发展变化。"}], "explanations": {"淡化": "dàn huà，意思是使浓度、强度或重要性降低或减弱。", "炭化": "tàn 与 dàn 声母不同（t 与 d），意思是变成炭的化学过程，与碳化同音。", "泛化": "fàn 与 dàn 声母不同（f 与 d），意思是范围变宽、概括化。", "分化": "fēn 与 dàn 声母、声调都不同（f 与 d，第一声与第四声），意思是分开、分裂。", "感化": "gǎn 与 dàn 声母、声调都不同（g 与 d，第三声与第四声），意思是用道理影响使人改变。", "演化": "yǎn 与 dàn 声母、声调都不同（零声母与 d，第三声与第四声），意思是逐步发展变化。"}, "sentence_index": null, "correct_answer": "淡化"}, "level_3": {"options": [{"text": "淡化", "is_correct": true, "explanation": "淡化：使这件事的影响变弱，符合新闻报道的语境。"}, {"text": "开启", "is_correct": false, "explanation": "搭配：“开启”搭配门、程序等，不能用于“影响”。"}, {"text": "分割", "is_correct": false, "explanation": "语义：“分割”指把整体切开，影响不能被切分。"}, {"text": "注入", "is_correct": false, "explanation": "搭配：“注入”多搭配资金、活力，不能说注入影响。"}], "explanations": {"淡化": "淡化：使这件事的影响变弱，符合新闻报道的语境。", "开启": "搭配：“开启”搭配门、程序等，不能用于“影响”。", "分割": "语义：“分割”指把整体切开，影响不能被切分。", "注入": "搭配：“注入”多搭配资金、活力，不能说注入影响。"}, "sentence_index": 6, "correct_answer": "淡化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的英语水平淡化了很多。", "explanation": "这里应该用〈下降〉。淡化只用于浓度、强度、影响等程度的减弱，英语水平变差要说下降，不能用淡化。"}, {"text": "这个班的学生人数淡化了五个。", "explanation": "这里应该用〈减少〉。人数等数量的减少要用减少，淡化不用于计数。"}, {"text": "这次事故淡化了污染范围。", "explanation": "这里应该用〈扩大〉。范围、面积要用扩大，淡化说的是程度或影响变弱，不能用于范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事的影响淡化了得很快。", "corrected_sentence": "这件事的影响淡化得很快。", "error_description": "“了”与补语“得”不能同用，应去掉“了”，说“淡化得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这件事的影响淡化。", "corrected_sentence": "他把这件事的影响淡化了。", "error_description": "“把”字句中，动词“淡化”后面要有“了”等成分，不能只说“把这件事的影响淡化”，应说“把这件事的影响淡化了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
