INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12871, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "指缺乏或不足够的水分供应。", "primary_collocate": null, "pronunciation": "quē shuǐ", "ipa": "tɕʰɥe˥ ʂwei̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "有些地方缺水，这就是水资源短缺。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "修建大坝、淡化海水，可以解决缺水问题。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天天气热，人容易缺水。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市每年夏天都缺水。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花缺水了，叶子都黄了。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们村去年很缺水，大家要去远处打水。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步以后缺水，人会觉得头晕。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，小草缺水就会变黄。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里缺水，所以很少有人住。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区缺水，洗澡要省着用水。", "target_word": "缺水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缺水了", "label": "体标"}, {"form": "缺过水", "label": "体标"}, {"form": "缺水地区", "label": "复合"}], "register": "通用", "sense_fingerprint": "地方、植物或人体得不到足够的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b139446e-7524-4719-8232-ba3bfc86546e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12871, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缺水", "is_correct": true, "explanation": "“缺水”指缺乏水分，与“水资源短缺”相符，是句中原词。"}, {"text": "节水", "is_correct": false, "explanation": "语义：“节水”是节约用水，与“水资源短缺”的因果关系相反。"}, {"text": "有水", "is_correct": false, "explanation": "语义：“有水”表示有水，与“水资源短缺”直接矛盾。"}, {"text": "丰沛", "is_correct": false, "explanation": "语义：“丰沛”指充足，与“水资源短缺”直接矛盾。"}], "explanations": {"缺水": "“缺水”指缺乏水分，与“水资源短缺”相符，是句中原词。", "节水": "语义：“节水”是节约用水，与“水资源短缺”的因果关系相反。", "有水": "语义：“有水”表示有水，与“水资源短缺”直接矛盾。", "丰沛": "语义：“丰沛”指充足，与“水资源短缺”直接矛盾。"}, "sentence_index": 0, "correct_answer": "缺水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子很闷，里面的氧气都缺水了。", "explanation": "这里应该用〈缺氧〉。“缺水”只指水分不足，不能用于氧气。"}, {"text": "他这个月缺水，要省着花。", "explanation": "这里应该用〈缺钱〉。“缺水”只指水分不足，不能用来说金钱。"}, {"text": "这家店的牛奶卖完了，现在缺水。", "explanation": "这里应该用〈缺货〉。“缺水”指水分不足，商品卖完要用“缺货”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12871, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缺水", "is_correct": true, "explanation": "“缺水”指水分不足，是跑步后头晕的原因，是句中原词。"}, {"text": "喝水", "is_correct": false, "explanation": "语义：跑步后喝水不会导致头晕，与“缺水”造成头晕的因果不符。"}, {"text": "补水", "is_correct": false, "explanation": "语义：“补水”是补充水分，与“头晕”由缺水引起的因果相反。"}, {"text": "浇水", "is_correct": false, "explanation": "搭配：“浇水”的对象是植物或土地，不能用于人。"}], "explanations": {"缺水": "“缺水”指水分不足，是跑步后头晕的原因，是句中原词。", "喝水": "语义：跑步后喝水不会导致头晕，与“缺水”造成头晕的因果不符。", "补水": "语义：“补水”是补充水分，与“头晕”由缺水引起的因果相反。", "浇水": "搭配：“浇水”的对象是植物或土地，不能用于人。"}, "sentence_index": 6, "correct_answer": "缺水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他最近心里缺水，整天闷闷不乐。", "explanation": "这里应该用〈缺爱〉。“缺水”只指水分不足，说感情上缺少关爱要用“缺爱”，不能用“缺水”。"}, {"text": "这家公司最近缺水，正在招聘员工。", "explanation": "这里应该用〈缺人〉。“缺水”指水分不足，不能用来说人手短缺。"}, {"text": "这个孩子长得快，骨头却缺水。", "explanation": "这里应该用〈缺钙〉。“缺水”指水分，骨头不足应说“缺钙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12871, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子缺水过，大家要去远处挑水。", "corrected_sentence": "这个村子缺水，大家要去远处挑水。", "error_description": "错误：“缺水过”；正确：“缺水”（去掉“过”）。“过”只能接在动词“缺”后面，不能放在宾语“水”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12871, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏天的时候，这个地区缺水很，大家要省着用。", "corrected_sentence": "夏天的时候，这个地区缺水，大家要省着用。", "error_description": "错误：“缺水很”；正确：“缺水”（去掉“很”）。程度副词“很”不能放在动词宾语“水”的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
