INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12872, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "用来表示某事被允许或可以这样做", "primary_collocate": null, "pronunciation": "kě", "ipa": "kʰɤ˨˩˦", "syllable_count": 1, "sentences": [{"text": "此处可停车，但每次不能超过两小时。", "target_word": "可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "凭学生证，学生可半价买票。", "target_word": "可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张卡一年内可随时退，不用说明原因。", "target_word": "可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议室开着门，有事的人可直接进来。", "target_word": "可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如有问题，您可打电话联系我们。", "target_word": "可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆的书可借三个星期。", "target_word": "可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "参加活动的人可免费喝茶，也可免费吃点心。", "target_word": "可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子耐高温，可放进微波炉。", "target_word": "可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三岁以下的小孩，可不买票进公园。", "target_word": "可", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上的字很小，需要时可拿放大镜来看。", "target_word": "可", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面语情态词，放在动词前，表示允许或可以这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 4 words above tier T1 (max 2): 杯子 (Zipf 3.82), 耐 (Zipf 3.89), 放进 (Zipf 3.8), 微波炉 (Zipf 3.33)']::text[], '3728d7ac-a5c9-42ec-9c46-36da5936aa49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12872, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "可", "is_correct": true, "explanation": "正确答案。“可”读作 kě（第三声），表示允许。"}, {"text": "肯", "is_correct": false, "explanation": "肯 kěn 与“可” kě 只差韵尾 n（声调相同），意思是愿意。"}, {"text": "课", "is_correct": false, "explanation": "课 kè 与“可” kě 声母相同，声调不同（第四声），意思是课程。"}, {"text": "棵", "is_correct": false, "explanation": "棵 kē 与“可” kě 声母韵母相同，声调不同（第一声），是量词。"}, {"text": "卡", "is_correct": false, "explanation": "卡 kǎ 与“可” kě 只差韵母（a 与 e），声调相同，都是第三声，意思是卡片。"}], "explanations": {"可": "正确答案。“可”读作 kě（第三声），表示允许。", "肯": "肯 kěn 与“可” kě 只差韵尾 n（声调相同），意思是愿意。", "课": "课 kè 与“可” kě 声母相同，声调不同（第四声），意思是课程。", "棵": "棵 kē 与“可” kě 声母韵母相同，声调不同（第一声），是量词。", "卡": "卡 kǎ 与“可” kě 只差韵母（a 与 e），声调相同，都是第三声，意思是卡片。"}, "sentence_index": null, "correct_answer": "可"}, "level_3": {"options": [{"text": "可", "is_correct": true, "explanation": "正确答案。“此处可停车”表示允许，与“但每次不能超过两小时”相符。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”表示有胆量，不表示允许，与句意不符。"}, {"text": "会", "is_correct": false, "explanation": "搭配：“会”表示能力或可能，不用于说某处允许停车。"}, {"text": "愿", "is_correct": false, "explanation": "语义：“愿”表示愿意，不表示许可，与句意不符。"}], "explanations": {"可": "正确答案。“此处可停车”表示允许，与“但每次不能超过两小时”相符。", "敢": "语义：“敢”表示有胆量，不表示允许，与句意不符。", "会": "搭配：“会”表示能力或可能，不用于说某处允许停车。", "愿": "语义：“愿”表示愿意，不表示许可，与句意不符。"}, "sentence_index": 0, "correct_answer": "可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "看这天色，等一会儿可下雨。", "explanation": "这里应该用〈会〉。“可”表示许可，不表示可能会发生。"}, {"text": "我明天可早起，要赶早班车。", "explanation": "这里应该用〈得〉（děi）。“可”表示许可，不能表示“必须”。"}, {"text": "她明天可来参加会议，却被禁止进入会场。", "explanation": "这里“可”表示许可，与后半句“被禁止进入会场”自相矛盾，句子不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12872, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "可", "is_correct": true, "explanation": "正确答案。“可”读作 kě（第三声），表示允许。"}, {"text": "咳", "is_correct": false, "explanation": "咳 ké 与“可” kě 声母韵母相同，声调不同（第二声），意思是咳嗽。"}, {"text": "客", "is_correct": false, "explanation": "客 kè 与“可” kě 声母相同，声调不同（第四声），意思是客人。"}, {"text": "科", "is_correct": false, "explanation": "科 kē 与“可” kě 声母相同，声调不同（第一声），意思是科目。"}], "explanations": {"可": "正确答案。“可”读作 kě（第三声），表示允许。", "咳": "咳 ké 与“可” kě 声母韵母相同，声调不同（第二声），意思是咳嗽。", "客": "客 kè 与“可” kě 声母相同，声调不同（第四声），意思是客人。", "科": "科 kē 与“可” kě 声母相同，声调不同（第一声），意思是科目。"}, "sentence_index": null, "correct_answer": "可"}, "level_3": {"options": [{"text": "可", "is_correct": true, "explanation": "正确答案。“可免费喝茶”表示允许，与后面“也可免费吃点心”并列。"}, {"text": "宜", "is_correct": false, "explanation": "语义：“宜”表示适宜或应当，不表示允许，“也宜免费吃点心”搭配不通。"}, {"text": "需", "is_correct": false, "explanation": "语义：“需”表示需要，不表示允许，与“免费”搭配不通。"}, {"text": "得", "is_correct": false, "explanation": "语义：“得”（děi）表示必须，与并列结构中的允许含义相反。"}], "explanations": {"可": "正确答案。“可免费喝茶”表示允许，与后面“也可免费吃点心”并列。", "宜": "语义：“宜”表示适宜或应当，不表示允许，“也宜免费吃点心”搭配不通。", "需": "语义：“需”表示需要，不表示允许，与“免费”搭配不通。", "得": "语义：“得”（děi）表示必须，与并列结构中的允许含义相反。"}, "sentence_index": 6, "correct_answer": "可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妹妹去年学了游泳，现在可游泳了。", "explanation": "这里应该用〈会〉。学会的能力用“会”，“可”表示许可。"}, {"text": "天这么黑，明天可下大雨。", "explanation": "这里应该用〈可能〉。“可”表示许可，不表示推测。"}, {"text": "他还没学过开车，所以不可开车。", "explanation": "这里应该用〈会〉。没学过是能力问题，应说“不会开车”，“不可”表示不允许。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口没有人守着，有事的人没可直接进去。", "corrected_sentence": "门口没有人守着，有事的人可直接进去。", "error_description": "“可”是能愿动词，前面不能加“没”，应说“可直接进去”，去掉“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在这里可过拍照，但不能用闪光灯。", "corrected_sentence": "在这里可拍照，但不能用闪光灯。", "error_description": "“可”是能愿动词，后面不能加“过”，应去掉“过”，说“可拍照”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
