INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12873, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用武力或意志使对方服从、屈服。", "primary_collocate": null, "pronunciation": "zhēng fú", "ipa": "ʈʂɤŋ˥ fu˧˥", "syllable_count": 2, "sentences": [{"text": "古代的国王想用军队征服邻国。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支军队征服了整个北方。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秦国先后征服了其他六个国家。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用坚强的意志征服了困难。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王派兵去征服那个小国。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的勇气和智慧征服了对手。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们一直想征服大自然。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位将军一生征服过很多地方。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用武力征服别的民族，但没有成功。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的意志很强，没有人能征服她。", "target_word": "征服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "征服了", "label": "体标"}, {"form": "征服过", "label": "体标"}, {"form": "征服者", "label": "复合"}], "register": "中性", "sense_fingerprint": "以武力或意志使对方屈服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bede058a-09f7-4687-907e-4a8684b48d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12873, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "征服", "is_correct": true, "explanation": "zhēng fú，意思是用武力或意志使对方服从、屈服。"}, {"text": "政府", "is_correct": false, "explanation": "zhèng fǔ 两个音节都变了调，与 zhēng fú 声调不同，意思是政府。"}, {"text": "增幅", "is_correct": false, "explanation": "zēng 与 zhēng 声母不同（z 与 zh），意思是增加的幅度。"}, {"text": "正负", "is_correct": false, "explanation": "zhèng fù 两个音节都变了调，与 zhēng fú 声调不同，意思是正数与负数。"}], "explanations": {"征服": "zhēng fú，意思是用武力或意志使对方服从、屈服。", "政府": "zhèng fǔ 两个音节都变了调，与 zhēng fú 声调不同，意思是政府。", "增幅": "zēng 与 zhēng 声母不同（z 与 zh），意思是增加的幅度。", "正负": "zhèng fù 两个音节都变了调，与 zhēng fú 声调不同，意思是正数与负数。"}, "sentence_index": null, "correct_answer": "征服"}, "level_3": {"options": [{"text": "征服", "is_correct": true, "explanation": "征服：用军队使邻国屈服，与语境相合。"}, {"text": "游览", "is_correct": false, "explanation": "语义：“游览”是游玩观光，与用军队无关。"}, {"text": "拜访", "is_correct": false, "explanation": "语义：“拜访”是登门看望，没有强制意味，与用军队不合。"}, {"text": "祝福", "is_correct": false, "explanation": "搭配：“祝福”是善意的祝愿，不能与“用军队”搭配。"}], "explanations": {"征服": "征服：用军队使邻国屈服，与语境相合。", "游览": "语义：“游览”是游玩观光，与用军队无关。", "拜访": "语义：“拜访”是登门看望，没有强制意味，与用军队不合。", "祝福": "搭配：“祝福”是善意的祝愿，不能与“用军队”搭配。"}, "sentence_index": 0, "correct_answer": "征服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他征服了一笔存款，大家都很高兴。", "explanation": "这里应该用〈存〉。征服的对象是要压服的人、国家或困难，存款要说存。"}, {"text": "老师征服了学生的信任。", "explanation": "这里应该用〈赢得〉。信任、尊重是赢得的对象，不能说征服。"}, {"text": "他征服了一个难忘的假期。", "explanation": "这里应该用〈度过〉。假期是用来度过的时间，不是被征服的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12873, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "征服", "is_correct": true, "explanation": "zhēng fú，意思是用武力或意志使对方服从、屈服。"}, {"text": "升幅", "is_correct": false, "explanation": "shēng 与 zhēng 声母不同（sh 与 zh），意思是上升的幅度。"}, {"text": "正副", "is_correct": false, "explanation": "zhèng fù 两个音节的声调都与 zhēng fú 不同，意思是正职和副职，如正副主任。"}, {"text": "整幅", "is_correct": false, "explanation": "zhěng 与 zhēng 声调不同（第三声与第一声），意思是整块的布或画面。"}], "explanations": {"征服": "zhēng fú，意思是用武力或意志使对方服从、屈服。", "升幅": "shēng 与 zhēng 声母不同（sh 与 zh），意思是上升的幅度。", "正副": "zhèng fù 两个音节的声调都与 zhēng fú 不同，意思是正职和副职，如正副主任。", "整幅": "zhěng 与 zhēng 声调不同（第三声与第一声），意思是整块的布或画面。"}, "sentence_index": null, "correct_answer": "征服"}, "level_3": {"options": [{"text": "征服", "is_correct": true, "explanation": "征服：用力量使大自然屈服，符合人们一直想的语境。"}, {"text": "制造", "is_correct": false, "explanation": "语义：人不能制造大自然，“制造”指做出人造物。"}, {"text": "创造", "is_correct": false, "explanation": "语义：大自然本来就存在，不能被“创造”。"}, {"text": "咨询", "is_correct": false, "explanation": "搭配：“咨询”的对象是人或专家，不能用于大自然。"}], "explanations": {"征服": "征服：用力量使大自然屈服，符合人们一直想的语境。", "制造": "语义：人不能制造大自然，“制造”指做出人造物。", "创造": "语义：大自然本来就存在，不能被“创造”。", "咨询": "搭配：“咨询”的对象是人或专家，不能用于大自然。"}, "sentence_index": 6, "correct_answer": "征服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们征服了这座博物馆。", "explanation": "这里应该用〈参观〉。征服的对象是要压服的人、国家或困难，博物馆要用参观。"}, {"text": "大家热烈地征服了新年。", "explanation": "这里应该用〈迎接〉。新年是要迎接的时间，不能被征服。"}, {"text": "他每天早上征服自己的房间。", "explanation": "这里应该用〈打扫〉。征服的对象是要压服的人、国家或困难，房间是要打扫的，不能说征服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位将军征服了过那个国家。", "corrected_sentence": "这位将军征服过那个国家。", "error_description": "“了”和“过”不能同时用。表示曾经有过的经历只用“过”，应说“征服过”，不能说“征服了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们终于把这片草原征服。", "corrected_sentence": "他们终于把这片草原征服了。", "error_description": "“把”字句中，动词“征服”后面要有“了”等成分，不能只说“把这片草原征服”，应说“把这片草原征服了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
