INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12874, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "深深地扎根；比喻牢固地树立或融入。", "primary_collocate": null, "pronunciation": "shēn zhí", "ipa": "ʂən˥ ʈʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "这个想法深植在孩子们的心里。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱国思想深植于每个人的心中。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好习惯要从小深植在孩子心里。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种文化深植于这片土地。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诚实的观念早已深植人心。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话深植在他的记忆里。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想把安全意识深植到每个员工心里。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个传统深植于农村的生活中。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家乡的味道深植在她心里。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对父母的爱深植他心底。", "target_word": "深植", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "深植着", "label": "体标"}], "register": "书面", "sense_fingerprint": "思想、观念牢固地扎根于人心或文化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bede058a-09f7-4687-907e-4a8684b48d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12874, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深植", "is_correct": true, "explanation": "深植 shēn zhí 是本词条，指思想或文化牢固扎根于人心，即本句的意思。"}, {"text": "深知", "is_correct": false, "explanation": "语音对比：深知 shēnzhī 与 深植 shēn zhí 只有第二音节声调不同（zhī 第一声，zhí 第二声），意思是深深地了解。"}, {"text": "神志", "is_correct": false, "explanation": "语音对比：神志 shénzhì 的两个音节声调都与 深植 不同（shén 第二声，zhì 第四声），意思是神智、意识。"}, {"text": "生殖", "is_correct": false, "explanation": "语音对比：生殖 shēngzhí 只把第一音节的韵尾从 n 换成 ng（shēng 与 shēn），意思是生育繁殖。"}], "explanations": {"深植": "深植 shēn zhí 是本词条，指思想或文化牢固扎根于人心，即本句的意思。", "深知": "语音对比：深知 shēnzhī 与 深植 shēn zhí 只有第二音节声调不同（zhī 第一声，zhí 第二声），意思是深深地了解。", "神志": "语音对比：神志 shénzhì 的两个音节声调都与 深植 不同（shén 第二声，zhì 第四声），意思是神智、意识。", "生殖": "语音对比：生殖 shēngzhí 只把第一音节的韵尾从 n 换成 ng（shēng 与 shēn），意思是生育繁殖。"}, "sentence_index": null, "correct_answer": "深植"}, "level_3": {"options": [{"text": "深植", "is_correct": true, "explanation": "正确：深植 指想法牢固地留在心中，与“这个想法……在孩子们的心里”相合。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚击打，不能用来说想法留在心里。"}, {"text": "拔", "is_correct": false, "explanation": "语义：“拔”是把东西从所在处拉出，与想法留在心里的意思相反。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”多接纸张、布料等具体物体，不能与“想法在心里”搭配。"}], "explanations": {"深植": "正确：深植 指想法牢固地留在心中，与“这个想法……在孩子们的心里”相合。", "踢": "语义：“踢”是用脚击打，不能用来说想法留在心里。", "拔": "语义：“拔”是把东西从所在处拉出，与想法留在心里的意思相反。", "撕": "搭配：“撕”多接纸张、布料等具体物体，不能与“想法在心里”搭配。"}, "sentence_index": 0, "correct_answer": "深植"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他决定深植进农村，去做一年的调查。", "explanation": "这里应该用〈深入〉。深植 讲牢固扎根或树立，不指人下到农村去做调查，应说深入。"}, {"text": "医生在他体内深植了一个芯片。", "explanation": "这里应该用〈植入〉。深植 讲想法或文化牢固扎根，不指把物体放进身体；芯片是物件，应说植入。"}, {"text": "他用胶水把标签深植在盒子上。", "explanation": "这里应该用〈粘贴〉。深植 讲牢固扎根或树立，不指把标签贴在物体表面，应说粘贴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12874, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "深植", "is_correct": true, "explanation": "深植 shēn zhí 是本词条，指思想或文化牢固扎根于人心，即本句的意思。"}, {"text": "神职", "is_correct": false, "explanation": "语音对比：神职 shénzhí 只有第一音节声调不同（shén 第二声，shēn 第一声），意思是神职人员的职务。"}, {"text": "升职", "is_correct": false, "explanation": "语音对比：升职 shēngzhí 只把第一音节的韵尾从 n 换成 ng（shēng 与 shēn），意思是职位提升。"}, {"text": "深挚", "is_correct": false, "explanation": "语音对比：深挚 shēnzhì 只有第二音节声调不同（zhì 第四声，zhí 第二声），意思是感情深厚真挚。"}], "explanations": {"深植": "深植 shēn zhí 是本词条，指思想或文化牢固扎根于人心，即本句的意思。", "神职": "语音对比：神职 shénzhí 只有第一音节声调不同（shén 第二声，shēn 第一声），意思是神职人员的职务。", "升职": "语音对比：升职 shēngzhí 只把第一音节的韵尾从 n 换成 ng（shēng 与 shēn），意思是职位提升。", "深挚": "语音对比：深挚 shēnzhì 只有第二音节声调不同（zhì 第四声，zhí 第二声），意思是感情深厚真挚。"}, "sentence_index": null, "correct_answer": "深植"}, "level_3": {"options": [{"text": "深植", "is_correct": true, "explanation": "正确：深植 指思想牢固地留在人心里，与“想把安全意识……到每个员工心里”相合。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“想让安全意识留在员工心里”的意图相反。"}, {"text": "挤", "is_correct": false, "explanation": "搭配：“挤”一般接“挤进、挤出、挤到前面”，不能说把意识挤到心里。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是让东西掉下或用力扔下，不能用来说让意识留在员工心里。"}], "explanations": {"深植": "正确：深植 指思想牢固地留在人心里，与“想把安全意识……到每个员工心里”相合。", "扔": "语义：“扔”是丢弃，与“想让安全意识留在员工心里”的意图相反。", "挤": "搭配：“挤”一般接“挤进、挤出、挤到前面”，不能说把意识挤到心里。", "摔": "语义：“摔”是让东西掉下或用力扔下，不能用来说让意识留在员工心里。"}, "sentence_index": 6, "correct_answer": "深植"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把宝藏深植进了沙子里。", "explanation": "这里应该用〈埋〉。深植 讲牢固扎根或树立，不用于人把宝物藏进沙子。"}, {"text": "他把新书深植进了书包里。", "explanation": "这里应该用〈放进〉。深植 讲牢固扎根或树立，不指把东西装进包里，应说放进。"}, {"text": "水库向农田深植了大量清水。", "explanation": "这里应该用〈注入〉。深植 指扎根或树立，不指液体流入田地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种责任感很深植于每个学生的心中。", "corrected_sentence": "这种责任感深植于每个学生的心中。", "error_description": "错误在于“深植”前加了程度副词“很”。“深植”是动作性动词，一般不受“很”修饰；应去掉“很”，说“这种责任感深植于每个学生的心中”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份感情早已深植了在他心中。", "corrected_sentence": "这份感情早已深植在他心中。", "error_description": "“深植”后接处所词“在他心中”时，不能在动词后直接加“了”。“早已”已表示完成，应去掉多余的“了”，说“这份感情早已深植在他心中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
