INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12876, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物或问题中最受关注的部分。", "primary_collocate": null, "pronunciation": "jiāo diǎn", "ipa": "tɕjɑʊ˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种深植于文化土壤中的生态理性，正在成为跨学科研究的焦点，为气候适应政策提供不可或缺的参照系。", "target_word": "焦点", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个问题成了大家讨论的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明星一走进来，就成了所有人的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议的焦点是怎么提高质量。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新电影的上映成了媒体关注的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着红衣服，站在舞台上成为焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的争论焦点在于价格。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把讨论的焦点放在环境问题上。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房价一直是市民关心的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，冠军成了记者的焦点。", "target_word": "焦点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个焦点", "label": "量词"}, {"form": "焦點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物或问题中最受关注的核心部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3bbb28-ef77-4126-94bd-0d4dcabd7445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12876, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焦点", "is_correct": true, "explanation": "焦点：研究中最受关注、最核心的部分，与“成为跨学科研究的”语境相符。"}, {"text": "障碍", "is_correct": false, "explanation": "语义：障碍会阻碍研究，与句末“为……提供不可或缺的参照系”相矛盾。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”是废弃物，把研究说成垃圾，与“不可或缺的参照系”的褒义相反。"}, {"text": "噱头", "is_correct": false, "explanation": "语域：“噱头”是口语词，带有贬义，与这段学术语体不合，也与“不可或缺”的褒义矛盾。"}], "explanations": {"焦点": "焦点：研究中最受关注、最核心的部分，与“成为跨学科研究的”语境相符。", "障碍": "语义：障碍会阻碍研究，与句末“为……提供不可或缺的参照系”相矛盾。", "垃圾": "语义：“垃圾”是废弃物，把研究说成垃圾，与“不可或缺的参照系”的褒义相反。", "噱头": "语域：“噱头”是口语词，带有贬义，与这段学术语体不合，也与“不可或缺”的褒义矛盾。"}, "sentence_index": 0, "correct_answer": "焦点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个物体的焦点在最底下，所以很稳。", "explanation": "这里应该用〈重心〉。重心是物体受力的中心，决定稳不稳；「焦点」指大家最注意的地方，不能用来指重力中心。"}, {"text": "这个焦点很快就溶解在水里了。", "explanation": "这里应该用〈糖〉。糖能溶解在水里；「焦点」指大家最注意的地方，是抽象的，不能溶解。"}, {"text": "这个焦点很甜，大家都爱吃。", "explanation": "这里应该用〈苹果〉。苹果有甜味，人可以吃；「焦点」不能吃，也没有甜味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焦点", "is_correct": true, "explanation": "焦点：争论中最关键的部分，句子说争论的关键在于价格。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物不是可以争论的对象，“争论礼物”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是争论的关键点，句子说的是争论的核心问题。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”口语性强，这段叙述语体偏书面，且不能与“争论”搭配。"}], "explanations": {"焦点": "焦点：争论中最关键的部分，句子说争论的关键在于价格。", "礼物": "语义：礼物不是可以争论的对象，“争论礼物”说不通。", "天气": "语义：天气不是争论的关键点，句子说的是争论的核心问题。", "玩意儿": "语域：“玩意儿”口语性强，这段叙述语体偏书面，且不能与“争论”搭配。"}, "sentence_index": 6, "correct_answer": "焦点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的焦点下了很久，地上都湿了。", "explanation": "这里应该用〈雨〉。雨会下，会把地弄湿；「焦点」指大家最注意的地方，不会下雨，也不会弄湿地面。"}, {"text": "他的焦点很大，隔壁都听得见。", "explanation": "这里应该用〈声音〉。声音可以大，能让人听见；「焦点」不能说大，也不能被隔壁听见。"}, {"text": "这个焦点很重，装满了课本。", "explanation": "这里应该用〈书包〉。书包可以装课本，也有重量；「焦点」不能装东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个问题是大家讨论的一条焦点。", "corrected_sentence": "这个问题是大家讨论的一个焦点。", "error_description": "量词错：“焦点”应说“个”；“条”用于长条形的东西，不能用来数“焦点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次争论有一首焦点，就是价格。", "corrected_sentence": "这次争论有一个焦点，就是价格。", "error_description": "量词错：“焦点”应说“个”；“首”用于诗歌、歌曲，不能用来数“焦点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
