INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12877, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为了确定物体位置或运动状态而选作标准的物体或系统。", "primary_collocate": null, "pronunciation": "cān zhào xì", "ipa": "tsʰan˥ ʈʂɑʊ˥˩ ɕi˥˩", "syllable_count": 3, "sentences": [{"text": "判断物体是动是静，首先要选定一个参照系。", "target_word": "参照系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选不同的参照系，物体的运动状态就不同。", "target_word": "参照系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究运动时，要先选好参照系。", "target_word": "参照系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以火车为参照系，坐在车里的人是静止的。", "target_word": "参照系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以地面为参照系，这辆车正在向东开。", "target_word": "参照系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们说说什么是参照系。", "target_word": "参照系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "物理课上，我们学了怎么选择参照系。", "target_word": "参照系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同一个物体，换了参照系，结论就不一样。", "target_word": "参照系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有参照系，就没法说物体动不动。", "target_word": "参照系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "选船作为参照系，岸边的树在向后退。", "target_word": "参照系", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "参考系", "label": "异形词"}], "register": "书面语", "sense_fingerprint": "物理学中选作标准、用来判断物体位置或运动状态的物体或系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bede058a-09f7-4687-907e-4a8684b48d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12877, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参照系", "is_correct": true, "explanation": "正确：参照系 指判断运动或位置的标准，与“判断物体是动是静，首先要选定……”相合。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是材料，不能作为判断物体动静的标准。"}, {"text": "钟表", "is_correct": false, "explanation": "语义：钟表是计时工具，不能作为判断物体动静的标准。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔是高度数值，不是可以选作判断动静标准的物体或系统。"}], "explanations": {"参照系": "正确：参照系 指判断运动或位置的标准，与“判断物体是动是静，首先要选定……”相合。", "玻璃": "语义：玻璃是材料，不能作为判断物体动静的标准。", "钟表": "语义：钟表是计时工具，不能作为判断物体动静的标准。", "海拔": "语义：海拔是高度数值，不是可以选作判断动静标准的物体或系统。"}, "sentence_index": 0, "correct_answer": "参照系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们选了一只参照系来研究物体的运动。", "explanation": "这里应该用〈个〉。参照系 的量词是个，“只”多用于动物，不能配参照系。"}, {"text": "这个参照系把火车的速度测得很准。", "explanation": "这里的“参照系”被当成了测速仪器。本词条指为确定物体运动而选作标准的物体或系统，它本身不能测量速度，应说〈测速仪〉。"}, {"text": "为了确定物体的运动，我们把石头的颜色作为参照系。", "explanation": "这里应该用〈物体〉。参照系 选作标准的是物体或系统，颜色不是物体，不能充当参照系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12877, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参照系", "is_correct": true, "explanation": "正确：参照系 是物理学中的概念，与“物理课上，我们学了怎么选择……”相合。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，不是可以选择的对象，与物理课的内容不合。"}, {"text": "呼吸", "is_correct": false, "explanation": "搭配：“选择”接可选的事物，“呼吸”是动作，不能被选择。"}, {"text": "风暴", "is_correct": false, "explanation": "语义：风暴是天气现象，不能作为选择的对象，与这句的语境不合。"}], "explanations": {"参照系": "正确：参照系 是物理学中的概念，与“物理课上，我们学了怎么选择……”相合。", "地震": "语义：地震是自然灾害，不是可以选择的对象，与物理课的内容不合。", "呼吸": "搭配：“选择”接可选的事物，“呼吸”是动作，不能被选择。", "风暴": "语义：风暴是天气现象，不能作为选择的对象，与这句的语境不合。"}, "sentence_index": 6, "correct_answer": "参照系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师拿来一条参照系，给同学们讲解运动。", "explanation": "这里应该用〈个〉。“条”多用于细长的东西，参照系 应用“个”。"}, {"text": "路口立着一个参照系，指示去城里的方向。", "explanation": "这里应该用〈路标〉。参照系 是选作标准的物体或系统，不是指示方向的标志。"}, {"text": "做函数图像时，要先画好参照系。", "explanation": "这里应该用〈坐标系〉。坐标系可以画出来，参照系是判断运动的标准，不能用“画”来表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12877, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "选定一只参照系，才能判断物体动不动。", "corrected_sentence": "选定一个参照系，才能判断物体动不动。", "error_description": "错误在于量词“只”。参照系 的量词用“个”，“只”多用于动物。应说“一个参照系”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12877, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "判断火车快不快，得先选的好参照系。", "corrected_sentence": "判断火车快不快，得先选好参照系。", "error_description": "错误在于“选”和“好”之间多了“的”。“选好”是动补结构，表示选得妥当，应说“先选好参照系”，不能说“选的好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5033c34-0cde-4fbd-a37a-0f0e815d9155') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
