INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12879, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12879, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指没有见到或消失。", "primary_collocate": null, "pronunciation": "bú jiàn", "ipa": "pu˧˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "有一种新塑料，它能慢慢变小，最后不见了。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机不见了，你看到了吗？", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳出来后，山上的雾就不见了。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，那只小鸟不见了。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的钥匙明明在桌子上，现在不见了。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一转身就不见了，妈妈很着急。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天一过，河边的雪都不见了。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放在门口的雨伞不见了，是谁拿走了？", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳一出来，草上的水珠就不见了。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只小猫跑进树林，一会儿就不见了。", "target_word": "不见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不见了", "label": "体标"}], "register": "口语", "sense_fingerprint": "不见·消失·找不到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3bbb28-ef77-4126-94bd-0d4dcabd7445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12879, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不见", "is_correct": true, "explanation": "正确。“慢慢变小，最后不见”描述塑料最终消失。"}, {"text": "出现", "is_correct": false, "explanation": "语义：“出现”指露出来，与“慢慢变小，最后”的消失过程相反。"}, {"text": "变大", "is_correct": false, "explanation": "语义：“变大”与前文“慢慢变小”矛盾。"}, {"text": "存在", "is_correct": false, "explanation": "搭配：“存在”是持续的状态，不能与表示结果的“最后”搭配。"}], "explanations": {"不见": "正确。“慢慢变小，最后不见”描述塑料最终消失。", "出现": "语义：“出现”指露出来，与“慢慢变小，最后”的消失过程相反。", "变大": "语义：“变大”与前文“慢慢变小”矛盾。", "存在": "搭配：“存在”是持续的状态，不能与表示结果的“最后”搭配。"}, "sentence_index": 0, "correct_answer": "不见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在远处不见了那只小鸟。", "explanation": "这里应该用〈看不见〉。“不见了”是不及物用法，后面不能直接带宾语；表示没看到要说“看不见”。"}, {"text": "我一想起她的名字，就不见了。", "explanation": "这里应该用〈忘记〉。“不见”指东西消失或看不到，不能用来说想不起来。"}, {"text": "天黑以后，那只小鸟不见了我。", "explanation": "这里应该用〈离开〉。“不见”指看不到或消失，不能用来表示离开某人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12879, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不见", "is_correct": true, "explanation": "正确。“冬天一过”说明雪融化了，所以“不见了”。"}, {"text": "增多", "is_correct": false, "explanation": "语义：“增多”与“冬天一过”的融化语境相反。"}, {"text": "变厚", "is_correct": false, "explanation": "语义：“变厚”与“冬天一过”的融化语境矛盾。"}, {"text": "冒出", "is_correct": false, "explanation": "搭配：“冒出”多指新出现的东西，不用于雪的消失。"}], "explanations": {"不见": "正确。“冬天一过”说明雪融化了，所以“不见了”。", "增多": "语义：“增多”与“冬天一过”的融化语境相反。", "变厚": "语义：“变厚”与“冬天一过”的融化语境矛盾。", "冒出": "搭配：“冒出”多指新出现的东西，不用于雪的消失。"}, "sentence_index": 6, "correct_answer": "不见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那只小猫跑进树林，一会儿就不见面了。", "explanation": "“不见面”指没有见面。这里说的是小猫消失，不是没有见面，“不见面”用在这里不通。"}, {"text": "那只小猫跑进树林，一会儿就不见客了。", "explanation": "“不见客”指拒绝接待客人，多用于人，不能用来说小猫跑进树林后的状态。"}, {"text": "那场比赛一会儿就不见了。", "explanation": "这里应该用〈结束〉。“不见”指东西消失或看不到，比赛结束不能说“不见”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12879, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那串钥匙不见，我找了半天。", "corrected_sentence": "那串钥匙不见了，我找了半天。", "error_description": "“不见”后面要带“了”，表示已经消失。省略后句子不完整。正确形式：不见了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12879, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的雨伞一会儿就不见过。", "corrected_sentence": "我的雨伞一会儿就不见了。", "error_description": "体标错：“不见”表示消失的结果，要用“了”，不能用表示经历的“过”。正确形式：一会儿就不见了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12882, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12882, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12882, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指一类个体微小、结构简单的单细胞或多细胞原核生物，广泛分布于自然界，部分种类可导致人类或动植物疾病。", "primary_collocate": null, "pronunciation": "xì jūn", "ipa": "ɕi˥˩ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "大自然里的小生物，如细菌，可以吃这种塑料。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "手上有很多细菌，吃饭以前要洗手。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细菌太小了，我们用眼睛看不见。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些细菌会让人生病。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶放久了，里面会有很多细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这种药可以杀死细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "显微镜下面，我看到了很多细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的细菌很多，要经常打扫。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酸奶里有一种对身体好的细菌。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细菌喜欢又湿又热的地方。", "target_word": "细菌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "细菌学", "label": "复合"}], "register": "中性", "sense_fingerprint": "细菌·微生物·原核生物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3bbb28-ef77-4126-94bd-0d4dcabd7445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12882, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "细菌", "is_correct": true, "explanation": "细菌是微小的生物，能分解塑料，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是生物，与「大自然里的小生物」矛盾。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：「可以吃」要求能进食的生物做主语，蛋糕不会吃东西。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是机器，不是生物，也不能分解塑料。"}], "explanations": {"细菌": "细菌是微小的生物，能分解塑料，符合句意。", "石头": "语义：石头不是生物，与「大自然里的小生物」矛盾。", "蛋糕": "搭配：「可以吃」要求能进食的生物做主语，蛋糕不会吃东西。", "汽车": "语义：汽车是机器，不是生物，也不能分解塑料。"}, "sentence_index": 0, "correct_answer": "细菌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上用细菌刷牙。", "explanation": "这里应该用〈牙膏〉。刷牙用的是牙膏，细菌是很小的生物，不能用来刷牙。"}, {"text": "我的电脑昨天感染了细菌。", "explanation": "这里应该用〈病毒〉。电脑感染的是病毒，细菌是生物体中的微生物，不用于说电脑中毒。"}, {"text": "这种蘑菇属于细菌。", "explanation": "这里应该用〈真菌〉。蘑菇属于真菌，细菌是原核生物，二者不是同一类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "细菌", "is_correct": true, "explanation": "细菌要在显微镜下才能看到，符合句意。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星在天上，不会出现在显微镜的视野里。"}, {"text": "卡车", "is_correct": false, "explanation": "语义：卡车体积巨大，不可能出现在显微镜的视野中。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：天上只有一个月亮，「很多月亮」不合常理。"}], "explanations": {"细菌": "细菌要在显微镜下才能看到，符合句意。", "星星": "语义：星星在天上，不会出现在显微镜的视野里。", "卡车": "语义：卡车体积巨大，不可能出现在显微镜的视野中。", "月亮": "搭配：天上只有一个月亮，「很多月亮」不合常理。"}, "sentence_index": 6, "correct_answer": "细菌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕里有很多细菌，所以特别甜。", "explanation": "这里应该用〈糖〉。细菌不会让食物变甜，甜味来自糖；细菌多了，食物反而容易变质变酸。"}, {"text": "人体是由很多细菌组成的。", "explanation": "这里应该用〈细胞〉。人体由细胞组成，细菌是独立的微生物，不是构成人体的单位。"}, {"text": "蛔虫是一种细菌。", "explanation": "这里应该用〈寄生虫〉。蛔虫属于动物，是寄生虫，不是细菌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "显微镜里能看到一只细菌。", "corrected_sentence": "显微镜里能看到一种细菌。", "error_description": "「细菌」的量词应用「种」或「个」，「只」多用于动物。「一只细菌」错误，应为「一种细菌」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一种很小细菌，要用显微镜才能看见。", "corrected_sentence": "这是一种很小的细菌，要用显微镜才能看见。", "error_description": "修饰语错：「很小」修饰名词时要加「的」，应说「很小的细菌」；「很小细菌」缺少「的」，不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12883, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合并", "is_correct": true, "explanation": "合并：把分开的部分合在一起，与「分成」的分开方向相反。"}, {"text": "建造", "is_correct": false, "explanation": "无关：「建造」指修建房屋等，与「分成」没有反义关系。"}, {"text": "阅读", "is_correct": false, "explanation": "无关：「阅读」指看书报，与「分成」没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：「唱歌」指发出歌声，与「分成」没有反义关系。"}], "correct_answer": "合并", "explanations": {"合并": "合并：把分开的部分合在一起，与「分成」的分开方向相反。", "建造": "无关：「建造」指修建房屋等，与「分成」没有反义关系。", "阅读": "无关：「阅读」指看书报，与「分成」没有反义关系。", "唱歌": "无关：「唱歌」指发出歌声，与「分成」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12883, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合并", "is_correct": true, "explanation": "合并：把分开的部分合在一起，与「分成」的分开方向相反。"}, {"text": "种植", "is_correct": false, "explanation": "无关：「种植」指把植物种在土里，与「分成」没有反义关系。"}, {"text": "检查", "is_correct": false, "explanation": "无关：「检查」指仔细查看，与「分成」没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：「打扫」指清除脏物，与「分成」没有反义关系。"}], "correct_answer": "合并", "explanations": {"合并": "合并：把分开的部分合在一起，与「分成」的分开方向相反。", "种植": "无关：「种植」指把植物种在土里，与「分成」没有反义关系。", "检查": "无关：「检查」指仔细查看，与「分成」没有反义关系。", "打扫": "无关：「打扫」指清除脏物，与「分成」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12883, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将整体事物分开；使整体不再是整体。", "primary_collocate": null, "pronunciation": "fēn chéng", "ipa": "fən˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "它们把塑料分成很小的部分。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "老师把我们分成三个小组。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个苹果分成两半。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年可以分成四个季节。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把蛋糕分成八块。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书分成上下两本。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先把大家分成两队，再开始比赛。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱分成两份，一份存起来。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班分成了三个小组。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些水果可以分成红的和绿的。", "target_word": "分成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分成了", "label": "体标"}, {"form": "分成过", "label": "体标"}], "register": "中性", "sense_fingerprint": "分成·把整体分为几部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3bbb28-ef77-4126-94bd-0d4dcabd7445') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12883, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分成", "is_correct": true, "explanation": "分成：把整体分为若干部分，符合句意。"}, {"text": "合并", "is_correct": false, "explanation": "语义：合并是合在一起，与「分成很小的部分」方向相反。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化指变成液体，与「很小的部分」无关。"}, {"text": "连接", "is_correct": false, "explanation": "搭配：「连接」要求两个以上的事物接在一起，不能直接带「很小的部分」作宾语。"}], "explanations": {"分成": "分成：把整体分为若干部分，符合句意。", "合并": "语义：合并是合在一起，与「分成很小的部分」方向相反。", "融化": "语义：融化指变成液体，与「很小的部分」无关。", "连接": "搭配：「连接」要求两个以上的事物接在一起，不能直接带「很小的部分」作宾语。"}, "sentence_index": 0, "correct_answer": "分成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这本英文书分成了中文。", "explanation": "这里应该用〈翻译成〉。把一种语言变成另一种语言是翻译，「分成」是把整体分为几部分。"}, {"text": "我把一块蛋糕分成了朋友。", "explanation": "这里应该用〈分给〉。分成的结果是部分，不能指向人，把蛋糕给朋友要用〈分给〉。"}, {"text": "这些零件分成了一台机器。", "explanation": "这里应该用〈组成〉。零件合在一起组成机器，「分成」是把整体分开，两者方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12883, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分成", "is_correct": true, "explanation": "分成两队：把大家分为两组，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是烹饪，用于食物，不能用于分队。"}, {"text": "归还", "is_correct": false, "explanation": "搭配：「归还」的宾语是借来的物品，不能用于人。"}, {"text": "存入", "is_correct": false, "explanation": "搭配：「存入」用于钱或物品，不能用于人。"}], "explanations": {"分成": "分成两队：把大家分为两组，符合句意。", "煮": "语义：煮是烹饪，用于食物，不能用于分队。", "归还": "搭配：「归还」的宾语是借来的物品，不能用于人。", "存入": "搭配：「存入」用于钱或物品，不能用于人。"}, "sentence_index": 6, "correct_answer": "分成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两家公司分成了一家公司。", "explanation": "这里应该用〈合并〉。合并是合在一起，分成是分开，二者意思相反。"}, {"text": "这些颜料分成了一种新颜色。", "explanation": "这里应该用〈合成〉。颜料混合在一起才能得到新颜色，「分成」是把整体分开。"}, {"text": "他分成了我们的小组。", "explanation": "这里应该用〈加入〉。人是加入小组，而不是被分成小组。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本厚书可以分成了三章。", "corrected_sentence": "这本厚书可以分成三章。", "error_description": "「可以」表示可能，后面的动词不能再加「了」。「可以分成了三章」错误，应为「可以分成三章」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把一块面团分成五本。", "corrected_sentence": "妈妈把一块面团分成五份。", "error_description": "量词错：面团分成的份应用「份」，「本」只用于书册等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43a228a1-c900-48ff-a399-84f529466afb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12884, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "很大", "is_correct": true, "explanation": "正确：“大”与“小”在体积上互为反义，“很大”与“很小”相对。"}, {"text": "安静", "is_correct": false, "explanation": "无反义关系：“安静”描述声音或环境，与体积大小无关。"}, {"text": "聪明", "is_correct": false, "explanation": "无反义关系：“聪明”形容智力，不涉及大小。"}, {"text": "干净", "is_correct": false, "explanation": "无反义关系：“干净”指清洁程度，反义词是“脏”，与体积无关。"}], "correct_answer": "很大", "explanations": {"很大": "正确：“大”与“小”在体积上互为反义，“很大”与“很小”相对。", "安静": "无反义关系：“安静”描述声音或环境，与体积大小无关。", "聪明": "无反义关系：“聪明”形容智力，不涉及大小。", "干净": "无反义关系：“干净”指清洁程度，反义词是“脏”，与体积无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12884, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大", "is_correct": true, "explanation": "正确：“大”与“小”在体积上互为反义，“身体很小”的反义是“身体很大”，这里取“大”。"}, {"text": "勇敢", "is_correct": false, "explanation": "无反义关系：“勇敢”形容胆量，与体积无关。"}, {"text": "认真", "is_correct": false, "explanation": "无反义关系：“认真”形容态度，与体积无关。"}, {"text": "清楚", "is_correct": false, "explanation": "无反义关系：“清楚”形容明白或可见的程度，与体积大小无关。"}], "correct_answer": "大", "explanations": {"大": "正确：“大”与“小”在体积上互为反义，“身体很小”的反义是“身体很大”，这里取“大”。", "勇敢": "无反义关系：“勇敢”形容胆量，与体积无关。", "认真": "无反义关系：“认真”形容态度，与体积无关。", "清楚": "无反义关系：“清楚”形容明白或可见的程度，与体积大小无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12884, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容体积、数量、程度等比较小。", "primary_collocate": null, "pronunciation": "hěn xiǎo", "ipa": "xən˨˩ ɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "它们把塑料分成很小的部分。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "微生物很小，人看不见。", "target_word": "很小", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "这只小鸟很小，能放在手心里。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚂蚁的眼睛很小，我们几乎看不见。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间很小，只能放一张床。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的院子很小，种不了多少花。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗种子很小，像一粒沙子。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手很小，拿不住这个大杯子。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字写得很小，我看不清楚。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只小狗刚出生，身体很小。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "体积、数量或程度很小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf9d64f7-d6db-410b-8410-52799dc0c108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12884, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "很小", "is_correct": true, "explanation": "正确答案：很小（hěn xiǎo），形容体积、数量或程度比较小。"}, {"text": "很想", "is_correct": false, "explanation": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“非常想念”。"}, {"text": "很响", "is_correct": false, "explanation": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“声音大”。"}, {"text": "很险", "is_correct": false, "explanation": "xiǎn 与 xiǎo 只差韵母（an 与 ao），意思是“情况危险”。"}], "explanations": {"很小": "正确答案：很小（hěn xiǎo），形容体积、数量或程度比较小。", "很想": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“非常想念”。", "很响": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“声音大”。", "很险": "xiǎn 与 xiǎo 只差韵母（an 与 ao），意思是“情况危险”。"}, "sentence_index": null, "correct_answer": "很小"}, "level_3": {"options": [{"text": "很小", "is_correct": true, "explanation": "正确：“很小”修饰“部分”，表示每一块的体积小，与“分成”的语境相符。"}, {"text": "很甜", "is_correct": false, "explanation": "语义：塑料块没有味道，“甜”无法描述“部分”的体积。"}, {"text": "很聪明", "is_correct": false, "explanation": "语义：“聪明”形容有智力的人或动物，不能修饰塑料的部分。"}, {"text": "很安静", "is_correct": false, "explanation": "搭配：“安静”多用于声音、环境或人的状态，不说“安静的部分”。"}], "explanations": {"很小": "正确：“很小”修饰“部分”，表示每一块的体积小，与“分成”的语境相符。", "很甜": "语义：塑料块没有味道，“甜”无法描述“部分”的体积。", "很聪明": "语义：“聪明”形容有智力的人或动物，不能修饰塑料的部分。", "很安静": "搭配：“安静”多用于声音、环境或人的状态，不说“安静的部分”。"}, "sentence_index": 0, "correct_answer": "很小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次假期很小，只有三天。", "explanation": "〈很短〉。说时间的长短要用“很短”，“很小”不用于形容假期的长短。"}, {"text": "他的心情很小，一直笑不出来。", "explanation": "〈很重〉。说心情沉重要用“很重”，“很小”不用于形容心情。"}, {"text": "这座城市离我家很小，坐车要两个小时。", "explanation": "〈很远〉。说距离要用“很远”，“很小”不用于表示距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很小", "is_correct": true, "explanation": "正确：“很小”与“像一粒沙子”的比喻相合，说明种子体积小。"}, {"text": "很重", "is_correct": false, "explanation": "语义：“重”说分量大，与“像一粒沙子”的轻小形象矛盾。"}, {"text": "很高", "is_correct": false, "explanation": "体貌：“高”描写形体的高矮，与像沙子的细小不相符。"}, {"text": "很酸", "is_correct": false, "explanation": "语义：“酸”指味道，与“像一粒沙子”所比较的大小无关。"}], "explanations": {"很小": "正确：“很小”与“像一粒沙子”的比喻相合，说明种子体积小。", "很重": "语义：“重”说分量大，与“像一粒沙子”的轻小形象矛盾。", "很高": "体貌：“高”描写形体的高矮，与像沙子的细小不相符。", "很酸": "语义：“酸”指味道，与“像一粒沙子”所比较的大小无关。"}, "sentence_index": 6, "correct_answer": "很小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的气温很小，大家都开了空调。", "explanation": "〈很高〉。说气温高低要用“很高”，“很小”不用于形容气温。"}, {"text": "这道菜的味道很小，大家都爱吃。", "explanation": "〈很好〉。说味道好坏要用“很好”，“很小”不用于形容味道。"}, {"text": "这次旅行很小，我们坐了三天火车。", "explanation": "〈很远〉。说路程远近要用“很远”，“很小”不用于形容旅行的路程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个盒子很很小，装不下三本书。", "corrected_sentence": "这个盒子很小，装不下三本书。", "error_description": "错误：“很很小”。正确：“很小”。程度副词“很”不能重叠使用，应只用一个“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只猫很小小的，刚出生。", "corrected_sentence": "那只猫很小，刚出生。", "error_description": "错误：“很小小的”。正确：“很小”或“小小的”。“很”与重叠形式“小小的”不能同时用，应去掉“小的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
