INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12888, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用塑料制成的袋子，常用于装物品。", "primary_collocate": null, "pronunciation": "sù liào dài", "ipa": "su⁵¹ liau̯⁵¹ tai̯⁵¹", "syllable_count": 3, "sentences": [{"text": "它能在土里慢慢分解，和普通的塑料袋不一样。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "普通的塑料袋用石油做。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这种新塑料袋用玉米或土豆做。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "超市里的塑料袋要收钱。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把水果放进塑料袋里。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我提着一个塑料袋去买菜。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风把塑料袋吹到了树上。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个塑料袋破了，东西会掉出来。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多海龟把塑料袋当成水母吃掉。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从塑料袋里拿出一个面包。", "target_word": "塑料袋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个塑料袋", "label": "量词"}, {"form": "塑料袋子", "label": "复合"}], "register": "中性", "sense_fingerprint": "塑料做的装东西的袋子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f52a17a-78f7-4fb3-bb7f-3ca4d49b212e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12888, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塑料袋", "is_correct": true, "explanation": "正确。“它能在土里慢慢分解”指可降解的袋子，与“普通的塑料袋”形成对比，应填“塑料袋”。"}, {"text": "人", "is_correct": false, "explanation": "语义：句中用“它”指代，“它”指物，不能指人，无法与“普通的人”相比。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不能“在土里慢慢分解”，与“它”的所指不合。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”是抽象概念，不是可以与“它”并列比较的具体物件。"}], "explanations": {"塑料袋": "正确。“它能在土里慢慢分解”指可降解的袋子，与“普通的塑料袋”形成对比，应填“塑料袋”。", "人": "语义：句中用“它”指代，“它”指物，不能指人，无法与“普通的人”相比。", "大海": "语义：大海不能“在土里慢慢分解”，与“它”的所指不合。", "时间": "语义：“时间”是抽象概念，不是可以与“它”并列比较的具体物件。"}, "sentence_index": 0, "correct_answer": "塑料袋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下雨了，他戴上塑料袋去上班。", "explanation": "这里应该用〈帽子〉。“他戴上帽子去上班”是自然的说法；塑料袋是装东西的袋子，不是戴在头上的东西。"}, {"text": "这家超市的塑料袋都是用布做的。", "explanation": "这里应该用〈布袋〉。“这家超市的布袋都是用布做的”是自然的说法；塑料袋指用塑料做的袋子，不能说成用布做的。"}, {"text": "我穿着塑料袋去上学。", "explanation": "这里应该用〈衣服〉。“我穿着衣服去上学”是自然的说法；塑料袋是装东西的袋子，不是穿在身上的衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塑料袋", "is_correct": true, "explanation": "正确。“风把塑料袋吹到了树上”符合句意，塑料袋是轻物，能被风吹到树上。"}, {"text": "石油", "is_correct": false, "explanation": "语义：石油是液体，不是能被风吹到树上的轻物，句意不合。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”指人，风吹的对象应是可以被吹动的轻物，句意不合。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水是液体，不是能被风吹到树上的轻物，句意不合。"}], "explanations": {"塑料袋": "正确。“风把塑料袋吹到了树上”符合句意，塑料袋是轻物，能被风吹到树上。", "石油": "语义：石油是液体，不是能被风吹到树上的轻物，句意不合。", "老师": "语义：“老师”指人，风吹的对象应是可以被吹动的轻物，句意不合。", "墨水": "语义：墨水是液体，不是能被风吹到树上的轻物，句意不合。"}, "sentence_index": 6, "correct_answer": "塑料袋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用塑料袋擦了擦嘴。", "explanation": "这里应该用〈纸巾〉。“他用纸巾擦了擦嘴”是自然的说法；擦嘴要用纸巾，塑料袋不是擦拭用品。"}, {"text": "他用塑料袋切菜。", "explanation": "这里应该用〈菜刀〉。“他用菜刀切菜”是自然的说法；切菜要用菜刀，塑料袋不能用来切东西。"}, {"text": "他用塑料袋喝水。", "explanation": "这里应该用〈杯子〉。“他用杯子喝水”是自然的说法；喝水要用杯子等容器，塑料袋不用来喝水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一本塑料袋。", "corrected_sentence": "他买了一个塑料袋。", "error_description": "错误形式是量词“一本”，正确形式是“一个”。“本”用于书册，塑料袋应用量词“个”，说“一个塑料袋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一个了塑料袋。", "corrected_sentence": "我买了一个塑料袋。", "error_description": "多余的“了”插在数量短语“一个”与名词“塑料袋”之间，应删去，说“买了一个塑料袋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
