INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12889, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种从地下开采的天然液态烃类混合物，是重要的能源和化工原料。", "primary_collocate": null, "pronunciation": "shí yóu", "ipa": "ʂɻ̩˧˥ jou̯˧˥", "syllable_count": 2, "sentences": [{"text": "普通的塑料袋用石油做。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个国家有很多石油。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车用的汽油是用石油做的。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在海边开采石油。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油是黑色的液体，很难洗掉。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂用石油生产塑料。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油价格上涨，汽油也变贵了。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船漏了，海里流出很多石油。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油公司在沙漠里发现了新油田。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下的石油用完以后，就没有了。", "target_word": "石油", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一桶石油", "label": "量词"}, {"form": "石油气", "label": "复合"}], "register": "中性", "sense_fingerprint": "地下开采的液态烃，能源和化工原料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f52a17a-78f7-4fb3-bb7f-3ca4d49b212e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12889, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "石油", "is_correct": true, "explanation": "正确。石油（shí yóu）是目标词，指地下开采的液态烃。"}, {"text": "时有", "is_correct": false, "explanation": "shí yǒu（第三声）与 shí yóu（第二声）声调不同，意思是“有时”。"}, {"text": "事由", "is_correct": false, "explanation": "shì yóu（第四声）与 shí yóu（第二声）第一音节声调不同，意思是“事情的缘由”。"}, {"text": "实有", "is_correct": false, "explanation": "shí yǒu（第二音节第三声）与 shí yóu（第二声）声调不同，意思是“实际存在”。"}], "explanations": {"石油": "正确。石油（shí yóu）是目标词，指地下开采的液态烃。", "时有": "shí yǒu（第三声）与 shí yóu（第二声）声调不同，意思是“有时”。", "事由": "shì yóu（第四声）与 shí yóu（第二声）第一音节声调不同，意思是“事情的缘由”。", "实有": "shí yǒu（第二音节第三声）与 shí yóu（第二声）声调不同，意思是“实际存在”。"}, "sentence_index": null, "correct_answer": "石油"}, "level_3": {"options": [{"text": "石油", "is_correct": true, "explanation": "正确。“普通的塑料袋用石油做”符合事实，石油是塑料的常见原料。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不能用来做塑料袋，句意不合。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶不是制作塑料的原料，句意不合。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“用……做”要求可加工的具体原料，“时间”是抽象概念。"}], "explanations": {"石油": "正确。“普通的塑料袋用石油做”符合事实，石油是塑料的常见原料。", "大海": "语义：大海不能用来做塑料袋，句意不合。", "牛奶": "语义：牛奶不是制作塑料的原料，句意不合。", "时间": "搭配：“用……做”要求可加工的具体原料，“时间”是抽象概念。"}, "sentence_index": 0, "correct_answer": "石油"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人在河边抽石油灌溉田地。", "explanation": "这里应该用〈水〉。“抽水灌溉”是自然的说法；灌溉要用水，石油不能用来灌溉。"}, {"text": "他往花上浇了一些石油，让花长得快。", "explanation": "这里应该用〈水〉。“往花上浇水”是自然的说法；浇花要用水，石油会让花死掉。"}, {"text": "这个菜用石油炒。", "explanation": "这里应该用〈食用油〉。“这个菜用食用油炒”是自然的说法；石油是工业原料，不能用来烹饪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12889, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石油", "is_correct": true, "explanation": "正确。“石油价格上涨，汽油也变贵了”符合句意，石油涨价带动汽油涨价。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“价格”只用于可买卖的商品，“友谊”不能标价。"}, {"text": "智慧", "is_correct": false, "explanation": "搭配：“智慧”不能标价，不说“智慧价格”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”不是可买卖的商品，与“汽油也变贵了”的关联也不成立，句意不合。"}], "explanations": {"石油": "正确。“石油价格上涨，汽油也变贵了”符合句意，石油涨价带动汽油涨价。", "友谊": "搭配：“价格”只用于可买卖的商品，“友谊”不能标价。", "智慧": "搭配：“智慧”不能标价，不说“智慧价格”。", "河流": "语义：“河流”不是可买卖的商品，与“汽油也变贵了”的关联也不成立，句意不合。"}, "sentence_index": 6, "correct_answer": "石油"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用石油在纸上写字。", "explanation": "这里应该用〈墨水〉。“他用墨水在纸上写字”是自然的说法；写字要用墨水等，石油不能用来写字。"}, {"text": "我每天早上喝一杯石油。", "explanation": "这里应该用〈牛奶〉。“喝一杯牛奶”是自然的说法；石油不能饮用。"}, {"text": "他穿着石油去上学。", "explanation": "这里应该用〈衣服〉。“他穿着衣服去上学”是自然的说法；石油不是衣物，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12889, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们买了一个石油。", "corrected_sentence": "他们买了一桶石油。", "error_description": "错误形式是量词“一个”，正确形式是“一桶”。石油是液体，以桶计，应说“一桶石油”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12889, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂用了很石油。", "corrected_sentence": "这家工厂用了很多石油。", "error_description": "错误形式是“很”后缺少“多”，“很石油”不成词。石油是不可数的液体，表示数量多要说“很多石油”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
