INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12890, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种重要的粮食作物，果实可食用，也可制作成玉米面、爆米花等。", "primary_collocate": null, "pronunciation": "yù mǐ", "ipa": "y⁵¹ mi²¹⁴", "syllable_count": 2, "sentences": [{"text": "这种新塑料袋用玉米或土豆做。", "target_word": "玉米", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "这块地适合种玉米和大豆。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在地里种了很多玉米。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的玉米大多在秋天收割。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种粮食叫玉米，也可以做爆米花。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方的玉米长得很高。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天到了，地里的玉米熟了。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用玉米做了一碗热汤。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟在地上找玉米吃。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉米和小麦都是重要的粮食。", "target_word": "玉米", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "玉米面", "label": "复合"}, {"form": "玉米粒", "label": "复合"}], "register": "中性", "sense_fingerprint": "重要的粮食作物，可做玉米面、爆米花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc9b4b69-ef94-4dfb-a579-4a5298524f1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玉米", "is_correct": true, "explanation": "正确：玉米是作物，与土豆并列，可以作为制作塑料袋的原料。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：句中并列的是土豆这类作物，塑料袋不用钢铁做，与语境冲突。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不能用来做塑料袋，与句中“用……或土豆做”的语境不合。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“做”的原料要是实物，空气不能用来做塑料袋。"}], "explanations": {"玉米": "正确：玉米是作物，与土豆并列，可以作为制作塑料袋的原料。", "钢铁": "语义：句中并列的是土豆这类作物，塑料袋不用钢铁做，与语境冲突。", "玻璃": "语义：玻璃不能用来做塑料袋，与句中“用……或土豆做”的语境不合。", "空气": "搭配：“做”的原料要是实物，空气不能用来做塑料袋。"}, "sentence_index": 0, "correct_answer": "玉米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在玉米里散步。", "explanation": "这里应该用〈玉米地〉。玉米指作物本身，表示场所要说“玉米地”，“在玉米里”不这么用。"}, {"text": "农民用玉米收割了一大片麦子。", "explanation": "这里不能把〈玉米〉当作收割的工具。玉米指作物，不是工具；“收割”要用〈收割机〉之类的机械。"}, {"text": "妈妈用玉米给宝宝织了一件毛衣。", "explanation": "这里应该用〈毛线〉。玉米是粮食作物，不能作织衣的材料；织毛衣要用毛线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玉米", "is_correct": true, "explanation": "正确：句中“地里”“熟了”说的是庄稼成熟，玉米可以熟。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“熟”用于果实或庄稼成熟，花只说开放，不说熟。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会成熟，与句中秋天地里庄稼成熟的语境相冲突。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会“熟”，与句中庄稼成熟的语境相冲突。"}], "explanations": {"玉米": "正确：句中“地里”“熟了”说的是庄稼成熟，玉米可以熟。", "花": "搭配：“熟”用于果实或庄稼成熟，花只说开放，不说熟。", "石头": "语义：石头不会成熟，与句中秋天地里庄稼成熟的语境相冲突。", "房子": "语义：房子不会“熟”，与句中庄稼成熟的语境相冲突。"}, "sentence_index": 6, "correct_answer": "玉米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们坐玉米去学校上课。", "explanation": "这里不能把〈玉米〉当作交通工具。玉米是作物，坐车要说〈公交车〉之类的交通工具。"}, {"text": "他每天看玉米就知道该起床了。", "explanation": "这里应该用〈钟表〉。玉米不能用来计时，看时间要用钟表。"}, {"text": "这个玉米每天都在唱歌。", "explanation": "这里不能把〈玉米〉当作会唱歌的生物。玉米是植物，不会唱歌，应该说〈鸟〉之类的动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民在地里种了三只玉米。", "corrected_sentence": "农民在地里种了三棵玉米。", "error_description": "错误形式：“三只玉米”；正确形式：“三棵玉米”。〈只〉用于动物或成对物品中的一个，玉米植株应用〈棵〉计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地里长着一头玉米。", "corrected_sentence": "地里长着一棵玉米。", "error_description": "错误形式：“一头玉米”；正确形式：“一棵玉米”。〈头〉用于大型牲畜，玉米植株应用〈棵〉计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '765fbac3-ed43-4621-9312-2c276857151c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
