INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12891, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "土豆，又称马铃薯，是一种常见的块茎类蔬菜，可以做成多种菜肴。", "primary_collocate": null, "pronunciation": "tǔ dòu", "ipa": "tʰu˨˩˦ toʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这种新塑料袋用玉米或土豆做。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我晚饭想吃土豆。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了五个土豆。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把土豆洗干净，再切成片。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土豆和牛肉一起做，味道很好。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在地里挖土豆。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个土豆太大了，一个人吃不完。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爱吃炸土豆。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土豆长在土里，不长在树上。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用土豆和鸡肉做了一锅汤。", "target_word": "土豆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个土豆", "label": "量词"}, {"form": "土豆泥", "label": "复合"}], "register": "中性", "sense_fingerprint": "马铃薯，常见块茎蔬菜，可做多种菜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f52a17a-78f7-4fb3-bb7f-3ca4d49b212e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12891, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土豆", "is_correct": true, "explanation": "正确：土豆是一种植物，可以作为做塑料袋的原料，符合句意。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：塑料袋不会用钢铁做，与“塑料袋”不相符。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子不能用来做塑料袋。"}, {"text": "朋友", "is_correct": false, "explanation": "搭配：“做”的材料应是物质，不说用朋友做。"}], "explanations": {"土豆": "正确：土豆是一种植物，可以作为做塑料袋的原料，符合句意。", "钢铁": "语义：塑料袋不会用钢铁做，与“塑料袋”不相符。", "沙子": "语义：沙子不能用来做塑料袋。", "朋友": "搭配：“做”的材料应是物质，不说用朋友做。"}, "sentence_index": 0, "correct_answer": "土豆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用土豆在本子上写字。", "explanation": "这里应该用〈铅笔〉。“他用铅笔在本子上写字”是自然的说法；土豆是蔬菜，不能用来写字。"}, {"text": "我把土豆穿在脚上去跑步。", "explanation": "这里应该用〈鞋〉。“我穿上鞋去跑步”是自然的说法；土豆是食物，不能穿在脚上。"}, {"text": "他每天早上喝一杯土豆。", "explanation": "这里应该用〈牛奶〉。“喝一杯牛奶”是自然的说法；土豆是固体蔬菜，不能直接喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12891, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土豆", "is_correct": true, "explanation": "正确：土豆可以很大，一个人吃不完，符合句意。"}, {"text": "芝麻", "is_correct": false, "explanation": "语义：芝麻很小，不会大到一个人吃不完。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“吃”的对象应是食物，石头不能吃。"}, {"text": "蚂蚁", "is_correct": false, "explanation": "语义：蚂蚁很小，不会大到一个人吃不完。"}], "explanations": {"土豆": "正确：土豆可以很大，一个人吃不完，符合句意。", "芝麻": "语义：芝麻很小，不会大到一个人吃不完。", "石头": "搭配：“吃”的对象应是食物，石头不能吃。", "蚂蚁": "语义：蚂蚁很小，不会大到一个人吃不完。"}, "sentence_index": 6, "correct_answer": "土豆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他坐在土豆上看电视。", "explanation": "这里应该用〈椅子〉。“他坐在椅子上看电视”是自然的说法；土豆是蔬菜，不是坐的家具。"}, {"text": "切土豆时，眼睛会流泪。", "explanation": "这里应该用〈洋葱〉。切洋葱时会释放刺激性气味使人流泪，土豆切开没有这种作用。"}, {"text": "这个土豆很酸，我不爱吃。", "explanation": "这里应该用〈西红柿〉。西红柿有酸味，土豆没有酸味，“很酸”要用西红柿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12891, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了三张土豆。", "corrected_sentence": "他买了三个土豆。", "error_description": "错误形式是量词“张”，正确形式是“个”。“张”用于纸、桌子等平面的东西，土豆按“个”计。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12891, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前吃了过土豆。", "corrected_sentence": "我以前吃过土豆。", "error_description": "错误形式是“吃了过”，“过”须紧贴动词“吃”，应说“吃过土豆”，“了”不能插在两者之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0defd26-0587-41c1-b427-02bf228d33be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12895, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "看得见", "is_correct": true, "explanation": "反义：「看得见」与「看不见」相对，表示能用眼睛看到。"}, {"text": "摸到", "is_correct": false, "explanation": "非反义：「摸到」指用手碰到，与视觉无关，也不是「看不见」的相对义。"}, {"text": "闻到", "is_correct": false, "explanation": "非反义：「闻到」指用鼻子感知气味，与「看不见」不构成反义。"}, {"text": "吃掉", "is_correct": false, "explanation": "非反义：「吃掉」指把东西吞下去，与「看不见」没有相对关系。"}], "correct_answer": "看得见", "explanations": {"看得见": "反义：「看得见」与「看不见」相对，表示能用眼睛看到。", "摸到": "非反义：「摸到」指用手碰到，与视觉无关，也不是「看不见」的相对义。", "闻到": "非反义：「闻到」指用鼻子感知气味，与「看不见」不构成反义。", "吃掉": "非反义：「吃掉」指把东西吞下去，与「看不见」没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12895, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "看得见", "is_correct": true, "explanation": "反义：「看得见」与「看不见」相对，表示能用眼睛看到。"}, {"text": "听到", "is_correct": false, "explanation": "非反义：「听到」指用耳朵感知声音，与视觉无关，不是相对义。"}, {"text": "尝到", "is_correct": false, "explanation": "非反义：「尝到」指用舌头感受味道，不是「看不见」的相对义。"}, {"text": "想到", "is_correct": false, "explanation": "非反义：「想到」指在脑中想起，与「看不见」不构成反义。"}], "correct_answer": "看得见", "explanations": {"看得见": "反义：「看得见」与「看不见」相对，表示能用眼睛看到。", "听到": "非反义：「听到」指用耳朵感知声音，与视觉无关，不是相对义。", "尝到": "非反义：「尝到」指用舌头感受味道，不是「看不见」的相对义。", "想到": "非反义：「想到」指在脑中想起，与「看不见」不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12895, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指无法用眼睛看见。", "primary_collocate": null, "pronunciation": "kàn bu jiàn", "ipa": "kʰan˥˩ pu tɕjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "微生物是一种非常小、眼睛看不见的生物，它们生活在土壤和水中。", "target_word": "看不见", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "微生物很小，人看不见。", "target_word": "看不见", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "天太黑了，我什么都看不见。", "target_word": "看不见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站得太远，我看不见他的脸。", "target_word": "看不见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气是看不见的，但我们每天都需要它。", "target_word": "看不见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有眼镜，奶奶连报纸上的字都看不见。", "target_word": "看不见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上雾很大，十米以外的路都看不见。", "target_word": "看不见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "细菌很小，不用显微镜就看不见。", "target_word": "看不见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前面的人太高，我看不见台上的歌手。", "target_word": "看不见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "星星白天也在天上，只是我们看不见。", "target_word": "看不见", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "看得见", "label": "反义形式"}, {"form": "看不见了", "label": "体标"}], "register": "中性", "sense_fingerprint": "因太小、太远或不可见而无法用眼睛看到某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859509cb-ef91-48f7-818c-847e5d1c3de5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12895, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看不见", "is_correct": true, "explanation": "正确。「眼睛看不见的生物」说微生物因非常小而眼睛无法看到，与前文一致。"}, {"text": "看得见", "is_correct": false, "explanation": "语义：「看得见」与前面的「非常小」矛盾，读起来说的是眼睛能看见的生物。"}, {"text": "听得见", "is_correct": false, "explanation": "搭配：「听」要用耳朵，不能用「眼睛」来听，与「眼睛」搭配不通。"}, {"text": "看不起", "is_correct": false, "explanation": "搭配：「看不起」用于瞧不起人，不能说眼睛看不起生物。"}], "explanations": {"看不见": "正确。「眼睛看不见的生物」说微生物因非常小而眼睛无法看到，与前文一致。", "看得见": "语义：「看得见」与前面的「非常小」矛盾，读起来说的是眼睛能看见的生物。", "听得见": "搭配：「听」要用耳朵，不能用「眼睛」来听，与「眼睛」搭配不通。", "看不起": "搭配：「看不起」用于瞧不起人，不能说眼睛看不起生物。"}, "sentence_index": 0, "correct_answer": "看不见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章太难，我看不见它的意思。", "explanation": "这里应该用〈看不懂〉。看不见指眼睛看不到东西，理解文字的意思要用看不懂。"}, {"text": "从他的表情，我看不见他生气了。", "explanation": "这里应该用〈看不出〉。看不见指眼睛看不到，通过表情判断出来要用看不出。"}, {"text": "他这种说话方式，我真看不见。", "explanation": "这里应该用〈看不惯〉。看不见只说眼睛看不到东西，表示接受不了某种做法要用看不惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看不见", "is_correct": true, "explanation": "正确。雾大时十米以外的路眼睛无法看到，与前文一致。"}, {"text": "看得清", "is_correct": false, "explanation": "语义：「看得清」说能看清楚，与前面的「雾很大」矛盾。"}, {"text": "闻不到", "is_correct": false, "explanation": "搭配：「闻」用于气味，「路」不能用鼻子闻到，搭配不通。"}, {"text": "吃不下", "is_correct": false, "explanation": "搭配：「吃不下」只能用于食物，不能用于「路」。"}], "explanations": {"看不见": "正确。雾大时十米以外的路眼睛无法看到，与前文一致。", "看得清": "语义：「看得清」说能看清楚，与前面的「雾很大」矛盾。", "闻不到": "搭配：「闻」用于气味，「路」不能用鼻子闻到，搭配不通。", "吃不下": "搭配：「吃不下」只能用于食物，不能用于「路」。"}, "sentence_index": 6, "correct_answer": "看不见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影太长，我看不见。", "explanation": "这里应该用〈看不完〉。看不见指眼睛看不到东西，表示内容看不完要用看不完。"}, {"text": "他这样欺负小孩，我真看不见。", "explanation": "这里应该用〈看不过去〉。看不见只说眼睛看不到，表示不忍心看下去要用看不过去。"}, {"text": "他的心思很深，我看不见他。", "explanation": "这里应该用〈看不透〉。看不见指眼睛看不到，说无法看透别人的心思要用看不透。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么小的虫子，我看不见把它。", "corrected_sentence": "这么小的虫子，我看不见它。", "error_description": "错误形式：「看不见把它」；正确形式：「看不见它」。「看不见」后面不能再加「把」引出宾语，宾语应直接放在动词之后，应说「看不见它」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里没有灯，我在屋里什么看不见。", "corrected_sentence": "夜里没有灯，我在屋里什么也看不见。", "error_description": "错误形式：「什么看不见」；正确形式：「什么也看不见」。表示全都看不到时要用「什么也」或「什么都」，缺少「也」，句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12896, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "干燥", "is_correct": true, "explanation": "反义：“干燥”指缺少水分，与“潮湿”相对。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”描写光线，与“潮湿”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”描写声音或环境的状态，与“潮湿”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”指人多、有声响，与“潮湿”没有反义关系。"}], "correct_answer": "干燥", "explanations": {"干燥": "反义：“干燥”指缺少水分，与“潮湿”相对。", "明亮": "“明亮”描写光线，与“潮湿”没有反义关系。", "安静": "“安静”描写声音或环境的状态，与“潮湿”没有反义关系。", "热闹": "“热闹”指人多、有声响，与“潮湿”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
