INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12896, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "含有较多水分，湿润", "primary_collocate": null, "pronunciation": "cháo shī", "ipa": "tʂʰau̯³⁵ ʂɻ̩⁵⁵", "syllable_count": 2, "sentences": [{"text": "它们喜欢温暖潮湿的地方。", "target_word": "潮湿", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "南方的春天空气很潮湿。", "target_word": "潮湿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这间屋子又小又潮湿。", "target_word": "潮湿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下雨以后，地上很潮湿。", "target_word": "潮湿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "潮湿的衣服不要放在包里。", "target_word": "潮湿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地下室太潮湿，不能住人。", "target_word": "潮湿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雨后的森林里很潮湿。", "target_word": "潮湿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里夏天又热又潮湿。", "target_word": "潮湿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不喜欢潮湿的天气。", "target_word": "潮湿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "墙很潮湿，要打开窗户。", "target_word": "潮湿", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "潮濕", "label": "繁体"}], "register": "中性", "sense_fingerprint": "空气、地方、房间等含水分多，让人觉得湿润", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fa5d8e-2296-45e3-ab90-df9c0be39312') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12896, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "潮湿", "is_correct": true, "explanation": "正确答案，指含有较多水分、湿润。"}, {"text": "超市", "is_correct": false, "explanation": "chāo（第一声）与 cháo（第二声）声调不同，意思是超市。"}, {"text": "尝试", "is_correct": false, "explanation": "cháng（阳平）与 cháo 的韵母不同（ang 与 ao），shì（第四声）与 shī（第一声）声调不同，意思是尝试。"}, {"text": "长诗", "is_correct": false, "explanation": "cháng 与 cháo 的韵母不同（ang 与 ao），shī 不变，意思是长诗。"}, {"text": "禅师", "is_correct": false, "explanation": "chán 与 cháo 的韵母不同（an 与 ao），shī 不变，意思是禅师。"}], "explanations": {"潮湿": "正确答案，指含有较多水分、湿润。", "超市": "chāo（第一声）与 cháo（第二声）声调不同，意思是超市。", "尝试": "cháng（阳平）与 cháo 的韵母不同（ang 与 ao），shì（第四声）与 shī（第一声）声调不同，意思是尝试。", "长诗": "cháng 与 cháo 的韵母不同（ang 与 ao），shī 不变，意思是长诗。", "禅师": "chán 与 cháo 的韵母不同（an 与 ao），shī 不变，意思是禅师。"}, "sentence_index": null, "correct_answer": "潮湿"}, "level_3": {"options": [{"text": "潮湿", "is_correct": true, "explanation": "正确：“潮湿”指地方含水分多，与“温暖”搭配，句意通顺。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”与“温暖”意思相反，地方不能既温暖又寒冷。"}, {"text": "凉爽", "is_correct": false, "explanation": "语义：“凉爽”指微凉舒适，与“温暖”相互矛盾，句子不成立。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”形容质地，不能修饰地方的温度，“温暖坚硬”搭配不当。"}], "explanations": {"潮湿": "正确：“潮湿”指地方含水分多，与“温暖”搭配，句意通顺。", "寒冷": "语义：“寒冷”与“温暖”意思相反，地方不能既温暖又寒冷。", "凉爽": "语义：“凉爽”指微凉舒适，与“温暖”相互矛盾，句子不成立。", "坚硬": "搭配：“坚硬”形容质地，不能修饰地方的温度，“温暖坚硬”搭配不当。"}, "sentence_index": 0, "correct_answer": "潮湿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道数学题太潮湿了，我不会做。", "explanation": "这里应该用〈难〉。“难”形容题目不容易做；“潮湿”只形容空气、地方、物体含水分多，不能形容题目。"}, {"text": "这个桃子又大又潮湿，很好吃。", "explanation": "这里应该用〈水灵〉。水灵形容水果饱满多汁，潮湿不用于形容水果。"}, {"text": "这盏台灯的光线很潮湿。", "explanation": "这里应该用〈柔和〉。柔和形容光线温和，潮湿只用于有水分的环境或物体，不能形容光线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12896, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "潮湿", "is_correct": true, "explanation": "正确答案，指含有较多水分、湿润。"}, {"text": "超时", "is_correct": false, "explanation": "chāo（第一声）与 cháo（第二声）声调不同，shí（第二声）与 shī（第一声）声调也不同，意思是超时。"}, {"text": "常识", "is_correct": false, "explanation": "cháng 与 cháo 的韵母不同（ang 与 ao），shí（第二声）与 shī（第一声）声调不同，意思是常识。"}, {"text": "潮汐", "is_correct": false, "explanation": "xī 与 shī 的声母不同（x 与 sh），cháo 不变，意思是潮汐。"}, {"text": "常事", "is_correct": false, "explanation": "cháng 与 cháo 的韵母不同（ang 与 ao），shì（第四声）与 shī（第一声）声调不同，意思是平常的事。"}], "explanations": {"潮湿": "正确答案，指含有较多水分、湿润。", "超时": "chāo（第一声）与 cháo（第二声）声调不同，shí（第二声）与 shī（第一声）声调也不同，意思是超时。", "常识": "cháng 与 cháo 的韵母不同（ang 与 ao），shí（第二声）与 shī（第一声）声调不同，意思是常识。", "潮汐": "xī 与 shī 的声母不同（x 与 sh），cháo 不变，意思是潮汐。", "常事": "cháng 与 cháo 的韵母不同（ang 与 ao），shì（第四声）与 shī（第一声）声调不同，意思是平常的事。"}, "sentence_index": null, "correct_answer": "潮湿"}, "level_3": {"options": [{"text": "潮湿", "is_correct": true, "explanation": "正确：“潮湿”描写森林里含水分多，与“雨后”的语境相符。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：雨后应当湿润，“干燥”与“雨后”的语境矛盾。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”形容液体或物体的温度极高，不用于描述森林的整体环境。"}, {"text": "光秃", "is_correct": false, "explanation": "语义：“光秃”指没有草木，与茂密的“森林”相矛盾。"}], "explanations": {"潮湿": "正确：“潮湿”描写森林里含水分多，与“雨后”的语境相符。", "干燥": "语义：雨后应当湿润，“干燥”与“雨后”的语境矛盾。", "滚烫": "搭配：“滚烫”形容液体或物体的温度极高，不用于描述森林的整体环境。", "光秃": "语义：“光秃”指没有草木，与茂密的“森林”相矛盾。"}, "sentence_index": 6, "correct_answer": "潮湿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块玉很潮湿，摸起来很舒服。", "explanation": "这里应该用〈温润〉。温润形容玉石温和润泽，潮湿用于空气、地面等环境，不用于形容玉石。"}, {"text": "他的声音很潮湿，让人安心。", "explanation": "这里应该用〈温和〉。温和形容声音、性情平和，潮湿不用于形容声音。"}, {"text": "她的笑容很潮湿。", "explanation": "这里应该用〈灿烂〉。灿烂形容笑容明亮，潮湿不能用来形容表情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间屋子潮湿很，我们换个房间吧。", "corrected_sentence": "这间屋子潮湿得很，我们换个房间吧。", "error_description": "错误：“潮湿很”。正确应为“潮湿得很”，形容词后作程度补语要用“得”连接，“潮湿很”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间地下室很的潮湿，不能住人。", "corrected_sentence": "这间地下室很潮湿，不能住人。", "error_description": "错误：“很的潮湿”。“潮湿”作谓语时不加“的”，应为“很潮湿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
