INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12899, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "指在日常的生活情境里。", "primary_collocate": null, "pronunciation": "zài shēng huó zhōng", "ipa": "tsaɪ˥˩ ʂɤŋ˥ xuo˧˥ ʈʂʊŋ˥", "syllable_count": 4, "sentences": [{"text": "塑料在生活中很常见，但很多塑料不容易分解，会对环境造成影响。", "target_word": "在生活中", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "在生活中，我们常常需要和别人商量。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在生活中，你遇到过这样的问题吗？", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在生活中，小事也能让人开心。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在生活中很细心，从来不乱放东西。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学在生活中很有用，买东西就要算钱。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在生活中，我们要学会照顾自己。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多好习惯都是在生活中慢慢养成的。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，在生活中也能学到很多知识。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在生活中，水和电都是不能少的。", "target_word": "在生活中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "在生活中-在日常生活的情境里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c937a50d-2199-49ee-9ea8-5faf8f53680f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12899, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在生活中", "is_correct": true, "explanation": "正确：“在生活中”表示日常情境，句意通顺。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”表示很少发生，与“很常见”意思相反，不能搭配。"}, {"text": "在古代", "is_correct": false, "explanation": "语义：古代还没有大量生产和使用塑料，与“很常见”的事实不符。"}, {"text": "在月球上", "is_correct": false, "explanation": "语义：句子讲的是塑料对环境的影响，月球上的情境与句意不合。"}], "explanations": {"在生活中": "正确：“在生活中”表示日常情境，句意通顺。", "偶尔": "搭配：“偶尔”表示很少发生，与“很常见”意思相反，不能搭配。", "在古代": "语义：古代还没有大量生产和使用塑料，与“很常见”的事实不符。", "在月球上": "语义：句子讲的是塑料对环境的影响，月球上的情境与句意不合。"}, "sentence_index": 0, "correct_answer": "在生活中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天在生活中，我丢了钱包。", "explanation": "这里应该用〈在路上〉。“在生活中”指日常的一般情况，不能用来说明某一天发生的具体事件。"}, {"text": "桌子在生活中放在窗户旁边。", "explanation": "此句错在把“在生活中”当作位置使用。它表示一般情境，不能说明物体的位置。"}, {"text": "这次比赛，他在生活中跑出了好成绩。", "explanation": "这里应该用〈在比赛中〉。“在生活中”指日常情境，不能用来说明具体比赛的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12899, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在生活中", "is_correct": true, "explanation": "正确：“在生活中”引出日常情境，句意通顺。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”表示不常发生，与“要学会”这种长期要求相矛盾。"}, {"text": "在梦里", "is_correct": false, "explanation": "语义：梦里的情境不是现实中的日常生活，与“学会照顾自己”的要求不合。"}, {"text": "在墙上", "is_correct": false, "explanation": "语义：墙上不是人照顾自己的场所，“在墙上，我们要学会照顾自己”说不通。"}], "explanations": {"在生活中": "正确：“在生活中”引出日常情境，句意通顺。", "偶尔": "搭配：“偶尔”表示不常发生，与“要学会”这种长期要求相矛盾。", "在梦里": "语义：梦里的情境不是现实中的日常生活，与“学会照顾自己”的要求不合。", "在墙上": "语义：墙上不是人照顾自己的场所，“在墙上，我们要学会照顾自己”说不通。"}, "sentence_index": 6, "correct_answer": "在生活中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的书包在生活中放在桌子下面。", "explanation": "此句把“在生活中”当作位置使用，它表示一般情境，不能说明物体放在哪里。"}, {"text": "他昨天在生活中吃了三个包子。", "explanation": "此句中“在生活中”表示一般情境，不能与“昨天”这类具体时间搭配来说明某次具体发生的事，这里不这样用。"}, {"text": "他在生活中参加了昨天的比赛。", "explanation": "此句中“在生活中”表示日常情境，不能用来说明昨天的具体比赛，这里不这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12899, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在生活中里，我们要注意节约用水。", "corrected_sentence": "在生活中，我们要注意节约用水。", "error_description": "多余成分：“在生活中”已含方位词“中”，后面不能再加“里”。把“在生活中里”改为“在生活中”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12899, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在生活中的，人们需要学会等待。", "corrected_sentence": "在生活中，人们需要学会等待。", "error_description": "多余成分：“在生活中”作状语，后面不能加“的”。把“在生活中的”改为“在生活中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
