INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12901, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指构成事物的各种不同的物质或因素。", "primary_collocate": null, "pronunciation": "chéng fèn", "ipa": "tʂʰɤŋ˧˥ fən˥˩", "syllable_count": 2, "sentences": [{"text": "它的主要成分是一种叫聚合物的物质，这种物质的结构可以让微生物“吃掉”它。", "target_word": "成分", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这瓶牛奶的成分是水、糖和蛋白质。", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先看看这种药的成分，你会不会过敏？", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包的主要成分是面粉。", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果的成分很简单，只有糖和水。", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种洗发水含有天然成分。", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "包装上写着食品的成分。", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气的主要成分是氮气和氧气。", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个化学成分对人体有好处。", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究这种草药的成分。", "target_word": "成分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "成分-构成事物的物质或因素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c937a50d-2199-49ee-9ea8-5faf8f53680f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12901, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成分", "is_correct": true, "explanation": "成分指构成事物的物质或因素，“主要成分是一种物质”符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的性质，不能是“一种叫聚合物的物质”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，不是构成事物的物质，不能说“主要体重是一种物质”。"}, {"text": "作用", "is_correct": false, "explanation": "语义：“作用”指效果，不能等同于一种物质。"}], "explanations": {"成分": "成分指构成事物的物质或因素，“主要成分是一种物质”符合语境。", "颜色": "语义：颜色是事物的性质，不能是“一种叫聚合物的物质”。", "体重": "语义：“体重”指身体的重量，不是构成事物的物质，不能说“主要体重是一种物质”。", "作用": "语义：“作用”指效果，不能等同于一种物质。"}, "sentence_index": 0, "correct_answer": "成分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对她有很深的成分。", "explanation": "这里应该用〈感情〉。“成分”指构成事物的物质或因素，不能用来表示对人的感情。"}, {"text": "他给我讲了一个成分。", "explanation": "这里应该用〈笑话〉。“成分”指构成事物的物质或因素，不能拿来讲述。"}, {"text": "妈妈给我倒了成分。", "explanation": "这里应该用〈水〉。“成分”指构成事物的物质或因素，不能倒出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12901, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成分", "is_correct": true, "explanation": "成分指食品所含的各种物质，包装上标注的正是这些。"}, {"text": "体温", "is_correct": false, "explanation": "语义：包装上不会写食品的体温，体温是人或动物的身体状态。"}, {"text": "性格", "is_correct": false, "explanation": "语义：食品没有性格，“食品的性格”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人或生物的外形特征，食品没有身高。"}], "explanations": {"成分": "成分指食品所含的各种物质，包装上标注的正是这些。", "体温": "语义：包装上不会写食品的体温，体温是人或动物的身体状态。", "性格": "语义：食品没有性格，“食品的性格”说不通。", "身高": "体貌：身高是人或生物的外形特征，食品没有身高。"}, "sentence_index": 6, "correct_answer": "成分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的成分很高，比你高一头。", "explanation": "这里应该用〈个子〉。“成分”指构成事物的物质或因素，不能用来形容人的高矮。"}, {"text": "今天的成分很好。", "explanation": "这里应该用〈天气〉。“成分”指构成事物的物质或因素，不能用来描述天气。"}, {"text": "我们下午去成分看电影。", "explanation": "这里应该用〈电影院〉。“成分”指构成事物的物质或因素，不能作为去的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "药里有两只成分，你要注意。", "corrected_sentence": "药里有两种成分，你要注意。", "error_description": "“成分”的量词应为“种”，“只”用于动物、手等，“两只成分”应改为“两种成分”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种洗发水含有很多天然成分们。", "corrected_sentence": "这种洗发水含有很多天然成分。", "error_description": "“们”只用于指人的名词，“成分”不能加“们”表示复数。把“成分们”改为“成分”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
