INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12903, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指把食物整个吃下去，也用于比喻消灭或吞并。", "primary_collocate": null, "pronunciation": "chī diào", "ipa": "tʂʰɻ̩˥ tiɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "它的主要成分是一种叫聚合物的物质，这种物质的结构可以让微生物“吃掉”它。", "target_word": "吃掉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "小猫把盘子里的鱼吃掉了。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一口气把三个包子都吃掉了。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大鱼会吃掉小鱼。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家大公司想吃掉那家小公司。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的“车”吃掉了他的“马”。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把碗里的饭全吃掉了。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚂蚁慢慢吃掉了那块饼干。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别把我的蛋糕吃掉。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟吃掉了树上的虫子。", "target_word": "吃掉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吃掉了", "label": "体标"}, {"form": "吃不掉", "label": "否定可能补语"}, {"form": "吃得掉", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "吃光、吃完；比喻消灭或吞并", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c937a50d-2199-49ee-9ea8-5faf8f53680f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12903, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吃掉", "is_correct": true, "explanation": "正确答案：吃掉（chī diào），指把食物整个吃下去，也比喻消灭。"}, {"text": "失掉", "is_correct": false, "explanation": "shī（第一声）与 chī（第一声）声母不同（sh 与 ch），意思是丢失，不是吃下去。"}, {"text": "踢掉", "is_correct": false, "explanation": "tī 与 chī 声母不同（t 与 ch），韵母读音也不同，意思是踢走。"}, {"text": "吃到", "is_correct": false, "explanation": "dào 与 diào 只差介音 i，意思是吃到某物，不是吃光或消灭。"}, {"text": "熄掉", "is_correct": false, "explanation": "xī 与 chī 声母不同（x 与 ch），韵母读音也不同，意思是熄灭。"}], "explanations": {"吃掉": "正确答案：吃掉（chī diào），指把食物整个吃下去，也比喻消灭。", "失掉": "shī（第一声）与 chī（第一声）声母不同（sh 与 ch），意思是丢失，不是吃下去。", "踢掉": "tī 与 chī 声母不同（t 与 ch），韵母读音也不同，意思是踢走。", "吃到": "dào 与 diào 只差介音 i，意思是吃到某物，不是吃光或消灭。", "熄掉": "xī 与 chī 声母不同（x 与 ch），韵母读音也不同，意思是熄灭。"}, "sentence_index": null, "correct_answer": "吃掉"}, "level_3": {"options": [{"text": "吃掉", "is_correct": true, "explanation": "吃掉指把东西整个吃下去，比喻消灭，“微生物把聚合物消灭掉”符合语境。"}, {"text": "读", "is_correct": false, "explanation": "语义：微生物不会“读”东西，“让微生物读它”说不通。"}, {"text": "相信", "is_correct": false, "explanation": "语义：微生物没有思想，不能“相信”一种物质。"}, {"text": "唱", "is_correct": false, "explanation": "语义：微生物不能“唱”聚合物，句子说不通。"}], "explanations": {"吃掉": "吃掉指把东西整个吃下去，比喻消灭，“微生物把聚合物消灭掉”符合语境。", "读": "语义：微生物不会“读”东西，“让微生物读它”说不通。", "相信": "语义：微生物没有思想，不能“相信”一种物质。", "唱": "语义：微生物不能“唱”聚合物，句子说不通。"}, "sentence_index": 0, "correct_answer": "吃掉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一口气把一杯牛奶吃掉了。", "explanation": "这里应该用〈喝掉〉。牛奶是用喝的，“吃掉”只用于固体食物。"}, {"text": "他一口气把那张桌子吃掉了。", "explanation": "这里应该用〈搬走〉。“吃掉”的字面义是把食物咽进肚子，这句说人把整张桌子吃下去，不合常理；表示移走应用〈搬走〉。"}, {"text": "他把这个道理吃掉了，很快就记住了。", "explanation": "这里应该用〈记住〉。“吃掉”的对象是食物或敌人，不能用于道理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12903, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃掉", "is_correct": true, "explanation": "吃掉指把食物整个吃下去，句中说饭全部吃完了。"}, {"text": "生气", "is_correct": false, "explanation": "配价：“生气”是不及物动词，不能带“把”字宾语。"}, {"text": "骂", "is_correct": false, "explanation": "语义：不能“骂”饭，句子说不通。"}, {"text": "写", "is_correct": false, "explanation": "语义：饭不能被“写”，句子说不通。"}], "explanations": {"吃掉": "吃掉指把食物整个吃下去，句中说饭全部吃完了。", "生气": "配价：“生气”是不及物动词，不能带“把”字宾语。", "骂": "语义：不能“骂”饭，句子说不通。", "写": "语义：饭不能被“写”，句子说不通。"}, "sentence_index": 6, "correct_answer": "吃掉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把手上的泥吃掉了。", "explanation": "这里应该用〈洗掉〉。“吃掉”的字面义是把食物咽进肚子，泥不是食物；表示去掉手上的泥应用〈洗掉〉。"}, {"text": "这块石头吃掉了那只小鸟。", "explanation": "这里应该用〈压死〉。“吃掉”的主语须是能进食或能吞并他物的主体，石头两者都不是，与“吃掉”不合。"}, {"text": "我把那首歌吃掉了，大家都说很好听。", "explanation": "这里应该用〈唱完〉。歌是用来唱的，不能“吃掉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12903, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹没有把苹果吃掉了。", "corrected_sentence": "妹妹没有把苹果吃掉。", "error_description": "体标错误：用“没有”否定“吃掉”时，后面不能再加“了”。把“没有把苹果吃掉了”改为“没有把苹果吃掉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12903, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小狗把肉吃掉着。", "corrected_sentence": "小狗把肉吃掉了。", "error_description": "“吃掉”表示动作已完成，不能接“着”，应用“了”，“吃掉着”应改为“吃掉了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
