INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12904, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人或动物身上用来感知光线、识别物体形状和颜色的视觉器官。", "primary_collocate": null, "pronunciation": "yǎn jing", "ipa": "jɛn˨˩ tɕiŋ", "syllable_count": 2, "sentences": [{"text": "微生物太小了，眼睛看不见，它们生活在土壤和水中。", "target_word": "眼睛", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "他的眼睛很大，也很亮。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的眼睛有点累，想休息一下。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请闭上眼睛，听听这首歌。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫有一双蓝色的眼睛。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看书太久，眼睛很不舒服。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了我的眼睛。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大，沙子进了我的眼睛。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫头鹰的眼睛晚上也能看清东西。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别用手揉眼睛，会疼的。", "target_word": "眼睛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一双眼睛", "label": "量词"}, {"form": "一只眼睛", "label": "量词"}, {"form": "大眼睛", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或动物的视觉器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c937a50d-2199-49ee-9ea8-5faf8f53680f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12904, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "眼睛", "is_correct": true, "explanation": "正确：眼睛（yǎn jing）指人或动物的视觉器官。"}, {"text": "眼镜", "is_correct": false, "explanation": "“镜”是 jìng（第四声），与“眼睛”的轻声 jing 声调不同，意思是眼镜。"}, {"text": "演讲", "is_correct": false, "explanation": "第二音节 jiǎng（第三声）与 jing 的韵母不同（iang／ing），意思是演讲。"}, {"text": "严禁", "is_correct": false, "explanation": "yán（第二声）与 yǎn（第三声）声调不同，jìn 与 jing 韵尾不同（n／ng），意思是严格禁止。"}, {"text": "险境", "is_correct": false, "explanation": "xiǎn 与 yǎn 声母不同（x／零声母），jìng 与 jing 声调不同，意思是危险的处境。"}, {"text": "严谨", "is_correct": false, "explanation": "yán 与 yǎn 声调不同，jǐn 与 jing 韵尾和声调都不同，意思是严密、谨慎。"}], "explanations": {"眼睛": "正确：眼睛（yǎn jing）指人或动物的视觉器官。", "眼镜": "“镜”是 jìng（第四声），与“眼睛”的轻声 jing 声调不同，意思是眼镜。", "演讲": "第二音节 jiǎng（第三声）与 jing 的韵母不同（iang／ing），意思是演讲。", "严禁": "yán（第二声）与 yǎn（第三声）声调不同，jìn 与 jing 韵尾不同（n／ng），意思是严格禁止。", "险境": "xiǎn 与 yǎn 声母不同（x／零声母），jìng 与 jing 声调不同，意思是危险的处境。", "严谨": "yán 与 yǎn 声调不同，jǐn 与 jing 韵尾和声调都不同，意思是严密、谨慎。"}, "sentence_index": null, "correct_answer": "眼睛"}, "level_3": {"options": [{"text": "眼睛", "is_correct": true, "explanation": "正确：“眼睛看不见的生物”指肉眼看不到的微小生物，此处需要视觉器官作主语。"}, {"text": "显微镜", "is_correct": false, "explanation": "语义：显微镜正是用来看见微生物的，与“看不见”的句意相反。"}, {"text": "耳朵", "is_correct": false, "explanation": "搭配：耳朵不用于看，“耳朵看不见的生物”与“看”不搭配。"}, {"text": "手指", "is_correct": false, "explanation": "语义：手指不是看东西的器官，“手指看不见的生物”句意不通。"}], "explanations": {"眼睛": "正确：“眼睛看不见的生物”指肉眼看不到的微小生物，此处需要视觉器官作主语。", "显微镜": "语义：显微镜正是用来看见微生物的，与“看不见”的句意相反。", "耳朵": "搭配：耳朵不用于看，“耳朵看不见的生物”与“看”不搭配。", "手指": "语义：手指不是看东西的器官，“手指看不见的生物”句意不通。"}, "sentence_index": 0, "correct_answer": "眼睛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小猫有一条蓝色的眼睛。", "explanation": "这里应该用〈双〉或〈只〉。“条”用于长条形的东西，眼睛不用“条”。"}, {"text": "我戴着一副眼睛去上课。", "explanation": "这里的“眼睛”是器官，不是“眼镜”。“戴”后接的是“眼镜”，不能说“戴一副眼睛”，应说“戴一副眼镜”。"}, {"text": "那只狗有一张黑色的眼睛。", "explanation": "这里应该用〈双〉或〈只〉。“张”用于平面的东西，眼睛不用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12904, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "眼睛", "is_correct": true, "explanation": "正确：眼睛（yǎn jing）指人或动物的视觉器官。"}, {"text": "演进", "is_correct": false, "explanation": "jìn 与 jing 韵尾不同（n／ng），且声调不同，意思是逐步发展、演变。"}, {"text": "眼形", "is_correct": false, "explanation": "xíng 与 jing 声母不同（x／j），声调也不同，意思是眼睛的形状。"}, {"text": "眼睑", "is_correct": false, "explanation": "jiǎn 与 jing 韵尾不同（n／ng），声调也不同，意思是眼皮。"}], "explanations": {"眼睛": "正确：眼睛（yǎn jing）指人或动物的视觉器官。", "演进": "jìn 与 jing 韵尾不同（n／ng），且声调不同，意思是逐步发展、演变。", "眼形": "xíng 与 jing 声母不同（x／j），声调也不同，意思是眼睛的形状。", "眼睑": "jiǎn 与 jing 韵尾不同（n／ng），声调也不同，意思是眼皮。"}, "sentence_index": null, "correct_answer": "眼睛"}, "level_3": {"options": [{"text": "眼睛", "is_correct": true, "explanation": "正确：“医生检查了我的眼睛”指医生检查视觉器官，符合句意。"}, {"text": "作业", "is_correct": false, "explanation": "语义：医生一般不检查作业，“医生检查了我的作业”句意不通。"}, {"text": "行李", "is_correct": false, "explanation": "语义：检查行李通常由安检人员进行，与“医生”的身份不符。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“检查”不与“脚步”搭配，不能说“检查脚步”。"}], "explanations": {"眼睛": "正确：“医生检查了我的眼睛”指医生检查视觉器官，符合句意。", "作业": "语义：医生一般不检查作业，“医生检查了我的作业”句意不通。", "行李": "语义：检查行李通常由安检人员进行，与“医生”的身份不符。", "脚步": "搭配：“检查”不与“脚步”搭配，不能说“检查脚步”。"}, "sentence_index": 6, "correct_answer": "眼睛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天戴眼睛看书。", "explanation": "这里应该用〈眼镜〉。“戴”用于眼镜、帽子等，“眼睛”是器官，不能戴。"}, {"text": "做了手术以后，他的眼睛提高了很多。", "explanation": "这里应该用〈视力〉。“提高”用于水平、能力，“眼睛”是器官，不说“眼睛提高”。"}, {"text": "这几年，他的眼睛明显下降了。", "explanation": "这里应该用〈视力〉。“下降”用于视力、数量，说“眼睛下降”不自然，应说“视力下降”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一张大眼睛。", "corrected_sentence": "他有一双大眼睛。", "error_description": "量词错误：“张”用于脸、纸等平面的东西，眼睛成对时要用“双”。应说“一双大眼睛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的眼睛们都很亮。", "corrected_sentence": "我们的眼睛都很亮。", "error_description": "复数错误：“们”只能加在指人的名词或代词后，“眼睛”不指人，后面不能加“们”。应说“我们的眼睛都很亮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12905, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12905, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12905, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "丢失，遗失；或指扔掉、抛弃。", "primary_collocate": null, "pronunciation": "diū", "ipa": "tiou̯˥", "syllable_count": 1, "sentences": [{"text": "当可降解塑料被丢在土里，微生物就会靠近它，把它当作食物，一点一点地分解。", "target_word": "丢", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我把旧报纸丢进了垃圾桶。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把垃圾丢在地上。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不要这双鞋了，就丢了。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双旧拖鞋太破了，把它丢进垃圾桶吧。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的自行车丢了，我只好走路。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，别把护照丢了。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她丢了工作，心情很不好。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝完的饮料瓶，请丢进回收箱。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我在公园丢了一件外套。", "target_word": "丢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "丢了", "label": "体标"}, {"form": "丢过", "label": "体标"}, {"form": "丢掉", "label": "复合"}, {"form": "丟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "丢失东西；扔掉、抛弃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c937a50d-2199-49ee-9ea8-5faf8f53680f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12905, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "丢", "is_correct": true, "explanation": "正确：丢（diū）指丢失或扔掉。"}, {"text": "秋", "is_correct": false, "explanation": "qiū（第一声）与 diū 声母不同（q／d），意思是秋天。"}, {"text": "球", "is_correct": false, "explanation": "qiú 与 diū 声母不同（q／d），声调也不同，意思是球。"}, {"text": "牛", "is_correct": false, "explanation": "niú 与 diū 声母不同（n／d），声调也不同，意思是牛。"}, {"text": "扭", "is_correct": false, "explanation": "niǔ 与 diū 声母不同（n／d），声调也不同，意思是扭动。"}], "explanations": {"丢": "正确：丢（diū）指丢失或扔掉。", "秋": "qiū（第一声）与 diū 声母不同（q／d），意思是秋天。", "球": "qiú 与 diū 声母不同（q／d），声调也不同，意思是球。", "牛": "niú 与 diū 声母不同（n／d），声调也不同，意思是牛。", "扭": "niǔ 与 diū 声母不同（n／d），声调也不同，意思是扭动。"}, "sentence_index": null, "correct_answer": "丢"}, "level_3": {"options": [{"text": "丢", "is_correct": true, "explanation": "正确：“被丢在土里”指塑料被扔到土里，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能表示放置在某处，“被吃在土里”与句意不符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“在土里”搭配，不能表示放置的动作。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与“放在土里”的意思完全无关。"}], "explanations": {"丢": "正确：“被丢在土里”指塑料被扔到土里，符合句意。", "吃": "语义：“吃”不能表示放置在某处，“被吃在土里”与句意不符。", "洗": "搭配：“洗”不能与“在土里”搭配，不能表示放置的动作。", "唱": "语义：“唱”与“放在土里”的意思完全无关。"}, "sentence_index": 0, "correct_answer": "丢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被撞后丢了知觉。", "explanation": "这里应该用〈失去〉。“丢”用于东西不见了或被扔掉，知觉不能“丢”，应说“失去知觉”。"}, {"text": "潮水慢慢丢了，岸边的沙滩露了出来。", "explanation": "这里应该用〈退〉。“丢”用于东西遗失或被扔掉，潮水是退去，不说“潮水丢了”，应说“潮水退了”。"}, {"text": "冬天，屋子里的热量很快就丢了。", "explanation": "这里应该用〈流失〉。“丢”指东西被弄丢、找不到，热量是慢慢散失，应说“热量流失”，不说“热量丢了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12905, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "丢", "is_correct": true, "explanation": "正确：丢（diū）指丢失或扔掉。"}, {"text": "休", "is_correct": false, "explanation": "xiū 与 diū 声母不同（x／d），声调相同（均为第一声），意思是休息。"}, {"text": "留", "is_correct": false, "explanation": "liú 与 diū 声母不同（l／d），声调也不同，意思是留下。"}, {"text": "抖", "is_correct": false, "explanation": "dǒu 与 diū 韵母不同（ou／iou），声调也不同，意思是抖动。"}], "explanations": {"丢": "正确：丢（diū）指丢失或扔掉。", "休": "xiū 与 diū 声母不同（x／d），声调相同（均为第一声），意思是休息。", "留": "liú 与 diū 声母不同（l／d），声调也不同，意思是留下。", "抖": "dǒu 与 diū 韵母不同（ou／iou），声调也不同，意思是抖动。"}, "sentence_index": null, "correct_answer": "丢"}, "level_3": {"options": [{"text": "丢", "is_correct": true, "explanation": "正确：“别把护照丢了”指护照丢失，符合句意。"}, {"text": "找", "is_correct": false, "explanation": "语义：“找”表示寻找，“别把护照找了”与提醒的意思不符。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”不用于护照，“修护照”不说，不能与“把护照”搭配。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”不能用于护照，“别把护照吹了”句意不通。"}], "explanations": {"丢": "正确：“别把护照丢了”指护照丢失，符合句意。", "找": "语义：“找”表示寻找，“别把护照找了”与提醒的意思不符。", "修": "搭配：“修”不用于护照，“修护照”不说，不能与“把护照”搭配。", "吹": "语义：“吹”不能用于护照，“别把护照吹了”句意不通。"}, "sentence_index": 6, "correct_answer": "丢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一边哭一边丢眼泪。", "explanation": "这里应该用〈掉〉。“掉眼泪”是固定说法，“丢”不与“眼泪”搭配。"}, {"text": "他的头发一根根地丢下来。", "explanation": "这里应该用〈掉〉。“掉下来”指脱落，“丢下来”不能表示头发脱落。"}, {"text": "他的衣服丢色了。", "explanation": "这里应该用〈掉〉。“掉色”指颜色脱落，“丢色”不说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把钱包丢。", "corrected_sentence": "他把钱包丢了。", "error_description": "了缺失：“把”字句要求动词后带“了”等成分，“他把钱包丢”不完整，应说“他把钱包丢了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把书了丢。", "corrected_sentence": "我把书丢了。", "error_description": "了位置错误：“了”要放在动词后，“把书了丢”顺序错误，应说“我把书丢了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dbf9d64-aa29-4ba5-964e-226fef086eac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12906, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远离", "is_correct": true, "explanation": "正确：“远离”与“靠近”构成反义，指距离变远，与“距离缩短”相对。"}, {"text": "停留", "is_correct": false, "explanation": "“停留”指在某处不再移动，与“距离变小”的方向无关，不构成反义。"}, {"text": "移动", "is_correct": false, "explanation": "“移动”是“靠近”的上位概念，并非与之相反，不构成反义。"}, {"text": "旋转", "is_correct": false, "explanation": "“旋转”指绕轴转动，与距离的远近变化无关，不构成反义。"}], "correct_answer": "远离", "explanations": {"远离": "正确：“远离”与“靠近”构成反义，指距离变远，与“距离缩短”相对。", "停留": "“停留”指在某处不再移动，与“距离变小”的方向无关，不构成反义。", "移动": "“移动”是“靠近”的上位概念，并非与之相反，不构成反义。", "旋转": "“旋转”指绕轴转动，与距离的远近变化无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12906, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远离", "is_correct": true, "explanation": "正确：“远离”与“靠近”构成反义，指距离变远。"}, {"text": "漂浮", "is_correct": false, "explanation": "“漂浮”指浮在液面或空中，与距离的远近变化无关，不构成反义。"}, {"text": "站立", "is_correct": false, "explanation": "“站立”描述姿势，与向某处移动使距离变小无关，不构成反义。"}, {"text": "翻滚", "is_correct": false, "explanation": "“翻滚”指身体或物体反复转动，与距离变化无关，不构成反义。"}], "correct_answer": "远离", "explanations": {"远离": "正确：“远离”与“靠近”构成反义，指距离变远。", "漂浮": "“漂浮”指浮在液面或空中，与距离的远近变化无关，不构成反义。", "站立": "“站立”描述姿势，与向某处移动使距离变小无关，不构成反义。", "翻滚": "“翻滚”指身体或物体反复转动，与距离变化无关，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12906, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指物体或人向某目标移动，使彼此间的距离缩短。", "primary_collocate": null, "pronunciation": "kào jìn", "ipa": "kʰau̯˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "当可降解塑料被丢在土里，微生物就会靠近它，把它当作食物，一点一点地分解。", "target_word": "靠近", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "天黑了，小鸟慢慢靠近了窗边的树。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要靠近正在工作的机器，太危险。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗看见我，高兴地向我靠近。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们一听见音乐，就靠近舞台去看。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生慢慢靠近病人，小声问他哪里疼。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你再靠近一点儿，我就能看清楚了。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船慢慢靠近海岸，岸上的人都在招手。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天，人们喜欢靠近火炉取暖。", "target_word": "靠近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走到我身边，靠近我的耳朵小声说话。", "target_word": "靠近", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "靠近了", "label": "体标"}, {"form": "靠近过", "label": "体标"}], "register": "中性", "sense_fingerprint": "人或物向某个目标移动，使距离缩短", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82fc455b-0366-4ce7-88da-88494763821a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12906, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "靠近", "is_correct": true, "explanation": "正确：“靠近”指微生物向塑料移动，与后文“一点一点地分解”的语境相合。"}, {"text": "远离", "is_correct": false, "explanation": "语义：“远离”表示距离拉大，与“微生物就会……分解”的语境相反。"}, {"text": "抵达", "is_correct": false, "explanation": "搭配：“抵达”后面接的是地点，“它”指塑料，不能作抵达的对象。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”表示躲开，微生物若逃避塑料，就不会去分解它，与后文矛盾。"}], "explanations": {"靠近": "正确：“靠近”指微生物向塑料移动，与后文“一点一点地分解”的语境相合。", "远离": "语义：“远离”表示距离拉大，与“微生物就会……分解”的语境相反。", "抵达": "搭配：“抵达”后面接的是地点，“它”指塑料，不能作抵达的对象。", "逃避": "语义：“逃避”表示躲开，微生物若逃避塑料，就不会去分解它，与后文矛盾。"}, "sentence_index": 0, "correct_answer": "靠近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩靠近班里第一名了。", "explanation": "这里应该用〈接近〉。靠近指人或物在空间上挨近，说成绩、水平的接近要用接近。"}, {"text": "他和爷爷很靠近，经常一起散步。", "explanation": "这里应该用〈亲近〉。靠近只表示空间距离缩短，人与人之间感情亲密要用亲近。"}, {"text": "他和弟弟的性格很靠近，几乎不吵架。", "explanation": "这里应该用〈相近〉。靠近指位置挨近，说性格相似要用相近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "靠近", "is_correct": true, "explanation": "正确：“靠近”表示距离变小，与“再……一点儿，我就能看清楚”的语境相合。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”表示避开，与“能看清楚”的目的正好相反。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”表示流泪，与位置远近无关，“再哭一点儿”也不能让人看清楚。"}, {"text": "倒", "is_correct": false, "explanation": "搭配：“倒”多用于液体或物品的倾倒，不用来表示人的位移。"}], "explanations": {"靠近": "正确：“靠近”表示距离变小，与“再……一点儿，我就能看清楚”的语境相合。", "躲": "语义：“躲”表示避开，与“能看清楚”的目的正好相反。", "哭": "语义：“哭”表示流泪，与位置远近无关，“再哭一点儿”也不能让人看清楚。", "倒": "搭配：“倒”多用于液体或物品的倾倒，不用来表示人的位移。"}, "sentence_index": 6, "correct_answer": "靠近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他累了，靠近椅子背上睡着了。", "explanation": "这里应该用〈靠在〉。靠近只表示移到附近，身体倚着某物要用靠在。"}, {"text": "我们的服务很靠近顾客的需要。", "explanation": "这里应该用〈贴近〉。靠近指位置挨近，说服务切合实际需求要用贴近。"}, {"text": "这两件衣服的款式很靠近，几乎分不出区别。", "explanation": "这里应该用〈相似〉。靠近指位置挨近，说款式相像要用相似。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小狗慢慢靠近到我的脚边。", "corrected_sentence": "小狗慢慢靠近了我的脚边。", "error_description": "错误：“靠近到我的脚边”，正确：“靠近了我的脚边”。“靠近”后面直接接处所，不需要再加“到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渡船缓缓靠近在码头，乘客开始下船。", "corrected_sentence": "渡船缓缓靠近码头，乘客开始下船。", "error_description": "错误：“靠近在码头”，正确：“靠近码头”。“靠近”后面直接接处所，不能再加“在”；“靠在”才带“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
