INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12907, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12907, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "符合心意或实际情况，令人满意。", "primary_collocate": null, "pronunciation": "hé shì", "ipa": "xɤ˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这个过程需要时间和合适的条件，比如足够的湿气和温度。", "target_word": "合适", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这件外套的大小很合适。", "target_word": "合适", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想找一个合适的工作。", "target_word": "合适", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个房间给一个人住，不大不小，很合适。", "target_word": "合适", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们需要选一个合适的时间开会。", "target_word": "合适", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种菜放多少盐才合适呢？", "target_word": "合适", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天穿这条厚裤子不合适。", "target_word": "合适", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话很有礼貌，用词也非常合适。", "target_word": "合适", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子离公司不远，价格也合适，我们就租了。", "target_word": "合适", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师帮他找了一个合适的座位。", "target_word": "合适", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不合适", "label": "复合"}], "register": "中性", "sense_fingerprint": "符合要求或实际情况，让人满意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82fc455b-0366-4ce7-88da-88494763821a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12907, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合适", "is_correct": true, "explanation": "正确：“合适”指条件符合要求，与“足够的湿气和温度”相合。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”与后文“足够的湿气”相矛盾，不能作条件的要求。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”说声音或环境，与“时间和条件”的所指不符。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容人或物的体型，不用来修饰“条件”。"}], "explanations": {"合适": "正确：“合适”指条件符合要求，与“足够的湿气和温度”相合。", "干燥": "语义：“干燥”与后文“足够的湿气”相矛盾，不能作条件的要求。", "吵闹": "语义：“吵闹”说声音或环境，与“时间和条件”的所指不符。", "高大": "搭配：“高大”形容人或物的体型，不用来修饰“条件”。"}, "sentence_index": 0, "correct_answer": "合适"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气很合适，大家都喜欢跟他聊天。", "explanation": "这里应该用〈和气〉。合适表示符合心意或实际情况，不用来形容人的脾气。"}, {"text": "这次考试他的成绩合适了。", "explanation": "这里应该用〈合格〉。合适指符合心意或实际要求，成绩达到标准要用合格。"}, {"text": "她唱歌唱得很合适，大家都鼓掌。", "explanation": "这里应该用〈好听〉。合适表示符合要求或情况，不用来评价歌声本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12907, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合适", "is_correct": true, "explanation": "正确：“不合适”是否定形式，说厚裤子在夏天穿不符合实际情况。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”说价钱，与穿着的感受无关，句子不通。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线或颜色，与裤子在夏天穿着是否适宜无关，句子不通。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”说明晰程度，与厚裤子的穿着无关。"}], "explanations": {"合适": "正确：“不合适”是否定形式，说厚裤子在夏天穿不符合实际情况。", "便宜": "语义：“便宜”说价钱，与穿着的感受无关，句子不通。", "明亮": "语义：“明亮”形容光线或颜色，与裤子在夏天穿着是否适宜无关，句子不通。", "清楚": "语义：“清楚”说明晰程度，与厚裤子的穿着无关。"}, "sentence_index": 6, "correct_answer": "合适"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他来到新城市没几天就合适了。", "explanation": "这里应该用〈适应〉。合适表示符合要求或令人满意，人对新环境逐渐习惯要用适应。"}, {"text": "这家人很合适，从来不吵架。", "explanation": "这里应该用〈和睦〉。合适表示符合心意或情况，说家人关系融洽要用和睦。"}, {"text": "两家公司终于合适了。", "explanation": "这里应该用〈合并〉。合适是形容词，表示符合要求，不表示组合成一体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12907, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件衣服我穿着没合适，换一件吧。", "corrected_sentence": "这件衣服我穿着不合适，换一件吧。", "error_description": "错误：“没合适”，正确：“不合适”。“合适”是形容词，否定要用“不”，不能用“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12907, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套家具的颜色没合适，放在客厅正好。", "corrected_sentence": "这套家具的颜色很合适，放在客厅正好。", "error_description": "错误：“没合适”，正确：“很合适”。“合适”是形容词，表示程度或状态时不能用“没”否定，应当用程度副词“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
