INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12909, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指空气中含有的水分较多，让人觉得潮湿、不干爽的自然现象。", "primary_collocate": null, "pronunciation": "shī qì", "ipa": "ʂɻ̩˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "这个过程需要时间和合适的条件，比如足够的湿气和温度。", "target_word": "湿气", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "下雨以后，房间里有很重的湿气。", "target_word": "湿气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "南方夏天湿气大，衣服不容易干。", "target_word": "湿气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打开窗户吧，屋里的湿气太重了。", "target_word": "湿气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地下室有一股湿气，让人不舒服。", "target_word": "湿气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空调可以减少房间里的湿气。", "target_word": "湿气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨季的湿气让墙上长出了黑点。", "target_word": "湿气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停以后，空气里的湿气还是很重。", "target_word": "湿气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种粉能吸走柜子里的湿气。", "target_word": "湿气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的湿气很重，铁门很快就生锈了。", "target_word": "湿气", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股湿气", "label": "量词"}, {"form": "濕氣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "空气中水分多，使人觉得潮湿不干爽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82fc455b-0366-4ce7-88da-88494763821a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12909, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "湿气", "is_correct": true, "explanation": "正确答案。湿气指空气中水分多，让人觉得潮湿、不干爽。"}, {"text": "失去", "is_correct": false, "explanation": "shī 相同，qì 与 qù 的韵母不同（i 与 ü），声调同为第四声，意思是失去。"}, {"text": "石器", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是石头做的工具。"}, {"text": "时期", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，qī（第一声）与 qì（第四声）声调也不同，意思是一段时期。"}, {"text": "十七", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，qī（第一声）与 qì（第四声）声调也不同，意思是数字十七。"}], "explanations": {"湿气": "正确答案。湿气指空气中水分多，让人觉得潮湿、不干爽。", "失去": "shī 相同，qì 与 qù 的韵母不同（i 与 ü），声调同为第四声，意思是失去。", "石器": "shí（第二声）与 shī（第一声）声调不同，意思是石头做的工具。", "时期": "shí（第二声）与 shī（第一声）声调不同，qī（第一声）与 qì（第四声）声调也不同，意思是一段时期。", "十七": "shí（第二声）与 shī（第一声）声调不同，qī（第一声）与 qì（第四声）声调也不同，意思是数字十七。"}, "sentence_index": null, "correct_answer": "湿气"}, "level_3": {"options": [{"text": "湿气", "is_correct": true, "explanation": "正确答案。“足够的湿气”是这一过程需要的条件之一，与温度并列，符合句意。"}, {"text": "钱", "is_correct": false, "explanation": "语义：钱不是促成这一过程的自然条件，“足够的钱和温度”说不通。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不能作为促成过程的条件，与“温度”并列不合常理。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“足够的”一般修饰可量或可数的条件，不能说“足够的颜色”。"}], "explanations": {"湿气": "正确答案。“足够的湿气”是这一过程需要的条件之一，与温度并列，符合句意。", "钱": "语义：钱不是促成这一过程的自然条件，“足够的钱和温度”说不通。", "玻璃": "语义：玻璃不能作为促成过程的条件，与“温度”并列不合常理。", "颜色": "搭配：“足够的”一般修饰可量或可数的条件，不能说“足够的颜色”。"}, "sentence_index": 0, "correct_answer": "湿气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨后，屋里飘着一只湿气，有点闷。", "explanation": "这里应该用〈股〉。湿气作量词用“股”，“只”多用于动物或成对的东西。"}, {"text": "他跑完步，脸上全是湿气。", "explanation": "这里应该用〈汗水〉。湿气指空气中的水分，人身上流出的是汗水。"}, {"text": "锅里的水烧开了，锅盖上凝着很多湿气。", "explanation": "这里应该用〈水蒸气〉。水蒸气是水受热后变成的气体，会从热水里冒出来；“湿气”指空气里的水分，不指锅盖上凝结的水汽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12909, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湿气", "is_correct": true, "explanation": "正确答案。“雨季的湿气”使墙面长霉，句意通顺。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：“冬天”与“雨季”时间上矛盾，不能说“雨季的冬天”。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声不能让墙上长出黑点，句子的因果关系不成立。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“寿命”一般说“某物的寿命”，不说“雨季的寿命”，词组搭配不通。"}], "explanations": {"湿气": "正确答案。“雨季的湿气”使墙面长霉，句意通顺。", "冬天": "语义：“冬天”与“雨季”时间上矛盾，不能说“雨季的冬天”。", "歌声": "语义：歌声不能让墙上长出黑点，句子的因果关系不成立。", "寿命": "搭配：“寿命”一般说“某物的寿命”，不说“雨季的寿命”，词组搭配不通。"}, "sentence_index": 6, "correct_answer": "湿气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "西瓜里有很多湿气，吃起来特别甜。", "explanation": "这里应该用〈水分〉。水分指物体内所含的水，西瓜里的是水分；“湿气”指空气中的水分，不能说果肉里有湿气。"}, {"text": "他哭了，眼睛里都是湿气。", "explanation": "这里应该用〈泪水〉。湿气指空气中的水分，眼里流出的是泪水。"}, {"text": "这口井里有很多湿气，可以打上来喝。", "explanation": "这里应该用〈水〉。湿气指空气中的水分，井里能喝的是水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "打开窗户以后，屋里的湿气散过不少。", "corrected_sentence": "打开窗户以后，屋里的湿气散了不少。", "error_description": "“散过”表示曾经有过的经历，这里说的是已经发生的变化，应该用“散了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海边的湿气重很，铁门容易生锈。", "corrected_sentence": "海边的湿气很重，铁门容易生锈。", "error_description": "错误：“重很”，正确：“很重”。“很”是程度副词，应放在形容词前面，不能放在形容词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
