INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12911, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "结束，完成。", "primary_collocate": null, "pronunciation": "wán", "ipa": "wan˧˥", "syllable_count": 1, "sentences": [{"text": "有些东西几个月就能分解完，有些则需要几年。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影完了，我们回家吧。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议还没完，请你等一下。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事还没完。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下午的课完了，我去打球。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛完了，大家都很高兴。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话还没完，你别走。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试完了，我们去玩。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节目完了以后，我就睡觉。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场会什么时候完？", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "完了", "label": "体标"}, {"form": "完成", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情、活动结束、到头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a33efdb-f4f8-4a3e-8e16-958ebcfd42fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12911, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "完", "is_correct": true, "explanation": "正确。「完」wán 表示结束、完成。"}, {"text": "万", "is_correct": false, "explanation": "wàn（第四声）与 wán（第二声）声调不同，意思是一万。"}, {"text": "王", "is_correct": false, "explanation": "wáng 与 wán 韵母不同（ang／an），意思是国王。"}, {"text": "湾", "is_correct": false, "explanation": "wān（第一声）与 wán（第二声）声调不同，意思是海湾。"}], "explanations": {"完": "正确。「完」wán 表示结束、完成。", "万": "wàn（第四声）与 wán（第二声）声调不同，意思是一万。", "王": "wáng 与 wán 韵母不同（ang／an），意思是国王。", "湾": "wān（第一声）与 wán（第二声）声调不同，意思是海湾。"}, "sentence_index": null, "correct_answer": "完"}, "level_3": {"options": [{"text": "完", "is_correct": true, "explanation": "正确。「分解完」表示分解过程结束，与“几个月就能”呼应。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「分解喝」不成立，「喝」不能作分解的结果补语。"}, {"text": "错", "is_correct": false, "explanation": "语义：「分解错」指分解出错，与“几个月就能”的语境不符。"}, {"text": "卖", "is_correct": false, "explanation": "搭配：「分解卖」不成立，「卖」不能作分解的结果补语。"}], "explanations": {"完": "正确。「分解完」表示分解过程结束，与“几个月就能”呼应。", "喝": "搭配：「分解喝」不成立，「喝」不能作分解的结果补语。", "错": "语义：「分解错」指分解出错，与“几个月就能”的语境不符。", "卖": "搭配：「分解卖」不成立，「卖」不能作分解的结果补语。"}, "sentence_index": 0, "correct_answer": "完"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们终于完了这场演出。", "explanation": "这里应该用〈结束〉。「完」表示“结束”义时不能带宾语，演出结束要说「结束」。"}, {"text": "他很快完了作业。", "explanation": "这里应该用〈完成〉或「做完」。「完」作动词时不能直接带宾语「作业」。"}, {"text": "我们很快完了这本书。", "explanation": "这里应该用〈读完〉。「完」表示“结束”义时不能带宾语，读完书要说「读完」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12911, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "完", "is_correct": true, "explanation": "正确。「完」wán 表示结束、完成。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn（第三声）与 wán（第二声）声调不同，意思是碗。"}, {"text": "文", "is_correct": false, "explanation": "wén 与 wán 元音不同（e／a），意思是文字。"}, {"text": "腕", "is_correct": false, "explanation": "wàn（第四声）与 wán（第二声）声调不同，意思是手腕。"}], "explanations": {"完": "正确。「完」wán 表示结束、完成。", "碗": "wǎn（第三声）与 wán（第二声）声调不同，意思是碗。", "文": "wén 与 wán 元音不同（e／a），意思是文字。", "腕": "wàn（第四声）与 wán（第二声）声调不同，意思是手腕。"}, "sentence_index": null, "correct_answer": "完"}, "level_3": {"options": [{"text": "完", "is_correct": true, "explanation": "正确。「话还没完」表示话还没说完，与“你别走”呼应。"}, {"text": "烧", "is_correct": false, "explanation": "语义：「烧」指燃烧，不能用于话说完。"}, {"text": "掉", "is_correct": false, "explanation": "语义：「掉」表示丢失或脱落，与话还没说完不符。"}, {"text": "乱", "is_correct": false, "explanation": "搭配：「乱」不能用来说明「话」的结束情况。"}], "explanations": {"完": "正确。「话还没完」表示话还没说完，与“你别走”呼应。", "烧": "语义：「烧」指燃烧，不能用于话说完。", "掉": "语义：「掉」表示丢失或脱落，与话还没说完不符。", "乱": "搭配：「乱」不能用来说明「话」的结束情况。"}, "sentence_index": 6, "correct_answer": "完"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她很快完了这封信。", "explanation": "这里应该用〈写完〉。「完」表示“结束”义时不能直接带宾语，写完信要说「写完这封信」。"}, {"text": "小明三点就完了那道数学题。", "explanation": "这里应该用〈做完〉。「完」作不及物动词时不能直接带宾语「数学题」，要用「做完」。"}, {"text": "我们终于完了比赛。", "explanation": "这里应该用〈结束〉。「完」作不及物动词，不能带宾语「比赛」，要用「结束」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12911, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "期末考试完了了以后，大家就放假了。", "corrected_sentence": "期末考试完了以后，大家就放假了。", "error_description": "「完了」中的「了」已经表示完成，后面不能再加一个「了」。应说「考试完了以后」，去掉多余的「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12911, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "节目已经了完，我们走吧。", "corrected_sentence": "节目已经完了，我们走吧。", "error_description": "「完」后面的「了」是完成标记，要接在「完」后面。应说「完了」，不能说「了完」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
