INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12914, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容物体坚固、耐用，不易损坏。", "primary_collocate": null, "pronunciation": "jiē shi", "ipa": "t͡ɕjɛ˥ ʂɨ", "syllable_count": 2, "sentences": [{"text": "现在，科学家还在继续研究如何让这种塑料既结实又容易分解。", "target_word": "结实", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这把椅子很结实，坐上去不会坏。", "target_word": "结实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的书包很结实，用了三年还很好。", "target_word": "结实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根绳子不结实，拿东西时容易断。", "target_word": "结实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷做的桌子又大又结实。", "target_word": "结实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥看起来很结实，可以放心走。", "target_word": "结实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买鞋要买结实的，孩子跑来跑去很容易坏。", "target_word": "结实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙盖得不够结实，下大雨就会倒。", "target_word": "结实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子很结实，里面放书也不怕。", "target_word": "结实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一把结实的锁，放在门上。", "target_word": "结实", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "结结实实", "label": "重叠"}], "register": "中性", "sense_fingerprint": "物体坚固耐用不易坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82fc455b-0366-4ce7-88da-88494763821a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12914, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "结实", "is_correct": true, "explanation": "正确答案。结实指物体坚固、耐用，不易损坏。"}, {"text": "解释", "is_correct": false, "explanation": "jiě（第三声）与 jiē（第一声）声调不同，shì（第四声）与 shi（轻声）也不同，意思是说明清楚。"}, {"text": "节食", "is_correct": false, "explanation": "jié（第二声）与 jiē（第一声）声调不同，shí（第二声）与 shi（轻声）也不同，意思是控制饮食。"}, {"text": "皆是", "is_correct": false, "explanation": "shì（第四声）与 shi（轻声）声调不同，意思是全都是。"}], "explanations": {"结实": "正确答案。结实指物体坚固、耐用，不易损坏。", "解释": "jiě（第三声）与 jiē（第一声）声调不同，shì（第四声）与 shi（轻声）也不同，意思是说明清楚。", "节食": "jié（第二声）与 jiē（第一声）声调不同，shí（第二声）与 shi（轻声）也不同，意思是控制饮食。", "皆是": "shì（第四声）与 shi（轻声）声调不同，意思是全都是。"}, "sentence_index": null, "correct_answer": "结实"}, "level_3": {"options": [{"text": "结实", "is_correct": true, "explanation": "正确答案。「既……又……」连接两种性质，「结实」与「容易分解」形成对比，符合句意。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：「热闹」形容场面或环境，不能说塑料「既热闹」，句意不通。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：「聪明」形容人的智力，不能用来形容塑料。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：「胖」多用来描写人或动物的体形，不用于描写塑料。"}], "explanations": {"结实": "正确答案。「既……又……」连接两种性质，「结实」与「容易分解」形成对比，符合句意。", "热闹": "语义：「热闹」形容场面或环境，不能说塑料「既热闹」，句意不通。", "聪明": "语义：「聪明」形容人的智力，不能用来形容塑料。", "胖": "体貌：「胖」多用来描写人或动物的体形，不用于描写塑料。"}, "sentence_index": 0, "correct_answer": "结实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的手艺很结实，客人都夸他。", "explanation": "这里应该用〈精湛〉。精湛形容技艺高超，结实形容物体坚固耐用，不能用来形容手艺。"}, {"text": "这个办法很结实，大家都愿意试一下。", "explanation": "这里应该用〈实在〉。实在形容办法或话语可靠，结实用于说物体坚固，不说办法结实。"}, {"text": "他为人很结实，从不说假话。", "explanation": "这里应该用〈诚实〉。诚实形容人为人真诚、不说假话；结实形容物体坚固，不用来说人的为人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12914, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "结实", "is_correct": true, "explanation": "正确答案。结实指物体坚固、耐用，不易损坏。"}, {"text": "结识", "is_correct": false, "explanation": "jié（第二声）与 jiē（第一声）声调不同，shí（第二声）与 shi（轻声）也不同，意思是认识、交往。"}, {"text": "结石", "is_correct": false, "explanation": "jié（第二声）与 jiē（第一声）声调不同，shí（第二声）与 shi（轻声）也不同，意思是体内形成的硬块。"}, {"text": "届时", "is_correct": false, "explanation": "jiè（第四声）与 jiē（第一声）声调不同，shí（第二声）与 shi（轻声）也不同，意思是到那个时候。"}], "explanations": {"结实": "正确答案。结实指物体坚固、耐用，不易损坏。", "结识": "jié（第二声）与 jiē（第一声）声调不同，shí（第二声）与 shi（轻声）也不同，意思是认识、交往。", "结石": "jié（第二声）与 jiē（第一声）声调不同，shí（第二声）与 shi（轻声）也不同，意思是体内形成的硬块。", "届时": "jiè（第四声）与 jiē（第一声）声调不同，shí（第二声）与 shi（轻声）也不同，意思是到那个时候。"}, "sentence_index": null, "correct_answer": "结实"}, "level_3": {"options": [{"text": "结实", "is_correct": true, "explanation": "正确答案。买鞋要买结实的，才经得起孩子跑来跑去，符合句意。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：「高大」多形容人或建筑的体积，不用来描述鞋子的质地。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：「冷静」形容人的情绪或态度，不能用来挑选鞋子。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：「温柔」形容人的性格或声音，用来形容鞋子说不通。"}], "explanations": {"结实": "正确答案。买鞋要买结实的，才经得起孩子跑来跑去，符合句意。", "高大": "搭配：「高大」多形容人或建筑的体积，不用来描述鞋子的质地。", "冷静": "语义：「冷静」形容人的情绪或态度，不能用来挑选鞋子。", "温柔": "语义：「温柔」形容人的性格或声音，用来形容鞋子说不通。"}, "sentence_index": 6, "correct_answer": "结实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做事很结实，从不偷懒。", "explanation": "这里应该用〈踏实〉。踏实形容做事认真可靠，结实形容物体坚固，不用于做事。"}, {"text": "他写的论文很结实，导师看了很满意。", "explanation": "这里应该用〈严谨〉。严谨形容态度或论证细致可靠，结实说的是物体坚固，不能用来形容论文。"}, {"text": "这个计划很结实，大家都没有异议。", "explanation": "这里应该用〈周密〉。周密形容计划细致完整，结实形容物体坚固，不能用来形容计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双鞋结实很，穿了一年还没坏。", "corrected_sentence": "这双鞋结实得很，穿了一年还没坏。", "error_description": "错误：「结实很」。正确：「结实得很」。形容词后作程度补语时，「得」不能省略，不能直接在形容词后接「很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把绳子结实一点，再拿去搬东西。", "corrected_sentence": "我们把绳子弄结实一点，再拿去搬东西。", "error_description": "「结实」是形容词，用在「把」字句中作结果补语时，前面要加动词，应说「弄结实」，不能直接说「把绳子结实」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba62c99f-b3cf-4f52-97be-4f8fbbc49ada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
