INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12917, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指由多个环节连接而成的、长度较大的链子；也可比喻连续的事物。", "primary_collocate": null, "pronunciation": "cháng liàn", "ipa": "ʈʂʰɑŋ˧˥ ljɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这条长链很重，我一个人拿不动。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "码头上有一条长链，用来拦住小船。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一条长链挂在门口，防止别人进来。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用长链把大石头吊了起来。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条长链由很多小环连在一起。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情的原因像一条长链，一环接一环。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船上的铁锚连着一条长链。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条长链是铁做的，摸起来很冷。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥的两边各有一条长链，可以扶。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把锁连着一条长链，很难剪断。", "target_word": "长链", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条长链", "label": "量词"}, {"form": "長鏈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由许多环节连成的长链子，也比喻连续的事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a94ae4-79af-4eab-97ed-f48899b3b919') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12917, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长链", "is_correct": true, "explanation": "正确：“长链”指由环节连成的长链子，与“很重，我一个人拿不动”的语境相符。"}, {"text": "项链", "is_correct": false, "explanation": "语义：“项链”很轻，不会重到让人拿不动，与语境矛盾。"}, {"text": "手链", "is_correct": false, "explanation": "语义：“手链”是小饰品，不可能重到让人拿不动，与语境不合。"}, {"text": "短信", "is_correct": false, "explanation": "语义：短信没有重量，不能说“很重，拿不动”。"}], "explanations": {"长链": "正确：“长链”指由环节连成的长链子，与“很重，我一个人拿不动”的语境相符。", "项链": "语义：“项链”很轻，不会重到让人拿不动，与语境矛盾。", "手链": "语义：“手链”是小饰品，不可能重到让人拿不动，与语境不合。", "短信": "语义：短信没有重量，不能说“很重，拿不动”。"}, "sentence_index": 0, "correct_answer": "长链"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天用长链洗脸，洗得很干净。", "explanation": "这里应该用〈毛巾〉。毛巾可以用来洗脸；长链是链子，不能当作洗脸的工具。"}, {"text": "他买了一条长链，用来写字。", "explanation": "这里应该用〈毛笔〉。毛笔可以用来写字；长链是链子，不能当作写字的工具。"}, {"text": "他在水里用长链划水，游得很快。", "explanation": "这里应该用〈手〉。手可以用来划水；长链是链子，不能当作划水的工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长链", "is_correct": true, "explanation": "正确：铁锚靠一条长长的链子与船相连，“一条长链”符合语境。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球不能把铁锚和船连在一起，量词“条”也不配“篮球”。"}, {"text": "铁路", "is_correct": false, "explanation": "语义：铁路是陆上交通设施，船上的铁锚不会连着铁路。"}, {"text": "长城", "is_correct": false, "explanation": "语义：长城是古代建筑，铁锚不可能连着长城。"}], "explanations": {"长链": "正确：铁锚靠一条长长的链子与船相连，“一条长链”符合语境。", "篮球": "语义：篮球不能把铁锚和船连在一起，量词“条”也不配“篮球”。", "铁路": "语义：铁路是陆上交通设施，船上的铁锚不会连着铁路。", "长城": "语义：长城是古代建筑，铁锚不可能连着长城。"}, "sentence_index": 6, "correct_answer": "长链"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用一条长链做了一顿晚饭。", "explanation": "这里应该用〈锅〉。锅可以用来做饭；长链是链子，不能当作做饭的工具。"}, {"text": "她每天用长链梳头发。", "explanation": "这里应该用〈梳子〉。梳子可以用来梳头发；长链是链子，不能当作梳头的工具。"}, {"text": "那条长链的路很远。", "explanation": "长链是名词，不能直接当作“很长”的形容词修饰“路”，应说“很长的路”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把长链捆起了来。", "corrected_sentence": "他把长链捆起来了。", "error_description": "补语错误：复合补语“起来”不能拆开说成“起了来”，应说“捆起来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直握了着那根长链。", "corrected_sentence": "他一直握着那根长链。", "error_description": "体标错误：动态持续体“着”应紧接动词“握”，不能说“握了着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23cf20d0-df96-48cf-936f-9200c442a284') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12918, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12918, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12918, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自然环境指人类生存和发展所依赖的各种自然条件的总和，包括大气、水、土壤、生物等。", "primary_collocate": null, "pronunciation": "zì rán huán jìng", "ipa": "tsɨ ʐan xwan tɕiŋ", "syllable_count": 4, "sentences": [{"text": "科学家指出，塑料在自然环境中很难分解，会对海洋生物造成伤害。", "target_word": "自然环境", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "传统塑料由长链聚合物构成，这些聚合物在自然环境中极难断裂，导致数百年不腐的污染累积。", "target_word": "自然环境", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "保护自然环境，是每个人的责任。", "target_word": "自然环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的自然环境很好，空气干净。", "target_word": "自然环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂排出的废水会破坏自然环境。", "target_word": "自然环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同的自然环境里，生活着不同的动物。", "target_word": "自然环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大气、水和土壤都是自然环境的一部分。", "target_word": "自然环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然环境变化以后，很多鸟飞走了。", "target_word": "自然环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带学生去了解当地的自然环境。", "target_word": "自然环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林减少，让当地的自然环境越来越差。", "target_word": "自然环境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自然環境", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人类生存所依赖的大气、水、土壤、生物等自然条件的总和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3728d7ac-a5c9-42ec-9c46-36da5936aa49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然环境", "is_correct": true, "explanation": "正确。“自然环境”指大气、水、土壤等自然条件，符合“塑料在……中很难分解”的语境。"}, {"text": "社会制度", "is_correct": false, "explanation": "语义：社会制度不是塑料可以“分解”的场所，句意不通。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“塑料在水果中”不合常理，与“海洋生物”的语境无关。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“在……中”表示空间范围，“时间”不作“塑料在……中分解”的处所。"}], "explanations": {"自然环境": "正确。“自然环境”指大气、水、土壤等自然条件，符合“塑料在……中很难分解”的语境。", "社会制度": "语义：社会制度不是塑料可以“分解”的场所，句意不通。", "水果": "语义：“塑料在水果中”不合常理，与“海洋生物”的语境无关。", "时间": "搭配：“在……中”表示空间范围，“时间”不作“塑料在……中分解”的处所。"}, "sentence_index": 0, "correct_answer": "自然环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的自然环境很正规，管理也很严格。", "explanation": "这里应该用〈工作环境〉。“自然环境”指自然界的条件，不指公司的管理或工作条件。"}, {"text": "我们班同学互相帮助，班里的自然环境很好。", "explanation": "这里应该用〈学习氛围〉。“自然环境”指自然界的条件，不指班级里的人际关系。"}, {"text": "这所学校的自然环境很有学术氛围。", "explanation": "这里应该用〈学习环境〉。“自然环境”指自然界的山水草木，不指学校的学习氛围或条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然环境", "is_correct": true, "explanation": "正确。“大气、水和土壤”是自然环境的组成部分，符合“的一部分”的说法。"}, {"text": "人类", "is_correct": false, "explanation": "语义：大气、水和土壤不是人类的一部分，句意不成立。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂不包含大气、水和土壤，句子说的是它们属于自然界。"}, {"text": "意义", "is_correct": false, "explanation": "搭配：“意义”是抽象概念，不与“大气、水和土壤”构成“部分”的关系。"}], "explanations": {"自然环境": "正确。“大气、水和土壤”是自然环境的组成部分，符合“的一部分”的说法。", "人类": "语义：大气、水和土壤不是人类的一部分，句意不成立。", "工厂": "语义：工厂不包含大气、水和土壤，句子说的是它们属于自然界。", "意义": "搭配：“意义”是抽象概念，不与“大气、水和土壤”构成“部分”的关系。"}, "sentence_index": 6, "correct_answer": "自然环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本小说写了城市的自然环境，到处是高楼和商场。", "explanation": "这里应该用〈社会环境〉。高楼和商场是人造的，不属于“自然环境”。"}, {"text": "这台电脑的自然环境太旧了，软件装不上。", "explanation": "这里应该用〈系统环境〉。“自然环境”指大气、水、土壤等，不指电脑的运行条件。"}, {"text": "开会的时候，会场的自然环境很紧张。", "explanation": "这里应该用〈气氛〉。“自然环境”不指人们之间的气氛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂排出的废水会污染自然环境们。", "corrected_sentence": "工厂排出的废水会污染自然环境。", "error_description": "词缀错误：“自然环境”后不能加“们”，“们”只用于人。正确形式是“自然环境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是人类共同自然环境。", "corrected_sentence": "这是人类共同的自然环境。", "error_description": "“的”遗漏：“共同”修饰“自然环境”时要加“的”，应说“人类共同的自然环境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
