INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12920, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12920, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体在外力作用下分成两段或几部分。", "primary_collocate": null, "pronunciation": "duàn liè", "ipa": "twan˥˩ ljɛ˥˩", "syllable_count": 2, "sentences": [{"text": "传统塑料由长链聚合物构成，这些聚合物在自然环境中极难断裂，导致数百年不腐的污染累积。", "target_word": "断裂", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "绳子拉得太紧，突然断裂了。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震时，这座桥的钢梁断裂了。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力一折，竹竿从中间断裂。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根钢筋承受不了重量，断裂成了两段。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根细铁丝经不起反复弯折，终于断裂了。", "target_word": "断裂", "complexity_tier": "T3", "furigana": "zhè gēn xì tiě sī jīng bù qǐ fǎn fù wān zhé, zhōng yú duàn liè le。", "sentence_source": "generated"}, {"text": "吊桥的铁链断裂，车掉进了河里。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "材料太脆，一用力就容易断裂。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，树枝断裂的声音很响。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验中，钢丝断裂前被拉长了一点。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "断裂了", "label": "体标"}, {"form": "断裂过", "label": "体标"}, {"form": "断裂带", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体受力后断成两段或几部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9585d0-18df-4185-ab2e-1482e7a5a6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "断裂", "is_correct": true, "explanation": "断裂指物体受力后断成几段，符合“极难……”的语境，也能导致污染长期累积。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”只用于金属，聚合物不会生锈，句子说不通。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”只用于种子或植物，聚合物不能发芽。"}, {"text": "沸腾", "is_correct": false, "explanation": "语义：“沸腾”指液体受热剧烈翻滚，聚合物在自然环境中不会沸腾，与语境不符。"}], "explanations": {"断裂": "断裂指物体受力后断成几段，符合“极难……”的语境，也能导致污染长期累积。", "生锈": "搭配：“生锈”只用于金属，聚合物不会生锈，句子说不通。", "发芽": "搭配：“发芽”只用于种子或植物，聚合物不能发芽。", "沸腾": "语义：“沸腾”指液体受热剧烈翻滚，聚合物在自然环境中不会沸腾，与语境不符。"}, "sentence_index": 0, "correct_answer": "断裂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "气球吹得太大，终于断裂了。", "explanation": "这里应该用〈破裂〉。断裂指长条或块状的固体受力后断成几段；气球鼓胀爆开属于破裂。"}, {"text": "这件衬衫的袖子穿久了，断裂了。", "explanation": "这里应该用〈磨破〉。布料穿久了出现破洞要说磨破；断裂指长条或块状的固体受力后断成几段。"}, {"text": "他一拳打下去，鸡蛋就断裂了。", "explanation": "这里应该用〈打破〉。鸡蛋被打碎要说打破；断裂只用于受力后断成几段的长条或块状固体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "断裂", "is_correct": true, "explanation": "断裂表示铁链断开，才会导致车掉进河里，符合句子的因果关系。"}, {"text": "生长", "is_correct": false, "explanation": "语义：铁链是金属，不会“生长”，无法解释车掉进河里。"}, {"text": "歌唱", "is_correct": false, "explanation": "搭配：“歌唱”只用于人或鸟，不能用于铁链。"}, {"text": "闪烁", "is_correct": false, "explanation": "搭配：“闪烁”形容光亮忽明忽暗，铁链不能闪烁。"}], "explanations": {"断裂": "断裂表示铁链断开，才会导致车掉进河里，符合句子的因果关系。", "生长": "语义：铁链是金属，不会“生长”，无法解释车掉进河里。", "歌唱": "搭配：“歌唱”只用于人或鸟，不能用于铁链。", "闪烁": "搭配：“闪烁”形容光亮忽明忽暗，铁链不能闪烁。"}, "sentence_index": 6, "correct_answer": "断裂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冰块放在太阳下，断裂了。", "explanation": "这里应该用〈融化〉。冰受热变成水是融化，不是物体受力断成几段。"}, {"text": "盐放进热水里，断裂了。", "explanation": "这里应该用〈溶解〉。盐在水中化开属于溶解，断裂只表示受力后分成几段。"}, {"text": "苹果放久了，断裂了。", "explanation": "这里应该用〈腐烂〉。水果放久变质要说腐烂，断裂只用于受力断成几段的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根铁丝一弯就断裂两段。", "corrected_sentence": "这根铁丝一弯就断裂成两段。", "error_description": "“断裂”后要用“成”引出结果，应说“断裂成两段”；直接接数量词是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "木桶的底板被断裂了，水全漏光了。", "corrected_sentence": "木桶的底板断裂了，水全漏光了。", "error_description": "“断裂”是不及物动词，前面不能加“被”，应说“木桶的底板断裂了”；加“被”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12922, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12922, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12922, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指两种事物之间的差异非常明显、突出。", "primary_collocate": null, "pronunciation": "xiān míng duì bǐ", "ipa": "ɕjɛn˥ miŋ˧˥ twei˥˩ pi˨˩˦", "syllable_count": 4, "sentences": [{"text": "与此形成鲜明对比的是，可降解塑料的设计理念在于其分子结构的“可控不稳定性”——即在特定生态条件下，聚合物链能被环境中的微生物识别为可代谢的有机基质，从而启动生物降解过程。", "target_word": "鲜明对比", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他的热情和哥哥的冷淡形成了鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色的花和绿色的叶子形成鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的热闹与乡村的安静形成鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两张照片放在一起，明暗形成了鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "furigana": "zhè liǎng zhāng zhào piàn fàng zài yì qǐ, míng àn xíng chéng le xiān míng duì bǐ。", "sentence_source": "generated"}, {"text": "昨天很冷，今天很热，天气形成鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住的小房子和旁边的大楼形成鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家用黑色背景衬托白花，两者形成鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "furigana": "huà jiā yòng hēi sè bèi jǐng chèn tuō bái huā, liǎng zhě xíng chéng xiān míng duì bǐ。", "sentence_source": "generated"}, {"text": "老人的慢和孩子的快，形成了鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两家的生活条件形成了鲜明对比。", "target_word": "鲜明对比", "complexity_tier": "T3", "furigana": "tā men liǎng jiā de shēng huó tiáo jiàn xíng chéng le xiān míng duì bǐ。", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两种事物差异非常明显突出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9585d0-18df-4185-ab2e-1482e7a5a6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12922, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鲜明对比", "is_correct": true, "explanation": "“形成”后接“鲜明对比”，指两种事物差异明显，符合句子语境。"}, {"text": "年轮", "is_correct": false, "explanation": "语义：“年轮”是树木的年龄标记，与设计理念之间的关系无关，读不通。"}, {"text": "地震", "is_correct": false, "explanation": "搭配：“形成”不能与“地震”构成合理搭配，地震是突发灾害，不是对比关系。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“形成”不能与“咖啡”构成合理搭配，咖啡是饮品，与句子的对比关系无关。"}], "explanations": {"鲜明对比": "“形成”后接“鲜明对比”，指两种事物差异明显，符合句子语境。", "年轮": "语义：“年轮”是树木的年龄标记，与设计理念之间的关系无关，读不通。", "地震": "搭配：“形成”不能与“地震”构成合理搭配，地震是突发灾害，不是对比关系。", "咖啡": "搭配：“形成”不能与“咖啡”构成合理搭配，咖啡是饮品，与句子的对比关系无关。"}, "sentence_index": 0, "correct_answer": "鲜明对比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个人都很高兴，形成了鲜明对比。", "explanation": "这里应该用〈相似〉。两人的状态一致、没有差异，应说相似；鲜明对比指两种事物之间的差异非常突出。"}, {"text": "只有一只猫，却形成了鲜明对比。", "explanation": "这里应该用〈孤单〉。只有一只猫、没有可比的对象，应说孤单；鲜明对比需要两种或以上事物相互映衬。"}, {"text": "两篇文章的字数差不多，却形成了鲜明对比。", "explanation": "这里应该用〈相近〉。两篇文章字数差别很小，应说相近；鲜明对比指两种事物差异非常突出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鲜明对比", "is_correct": true, "explanation": "“形成”后接“鲜明对比”，指两者差异明显，符合房屋与大楼的语境。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：“友谊”指人与人之间的感情，房屋与大楼之间不能形成友谊。"}, {"text": "宿命", "is_correct": false, "explanation": "语义：“宿命”指命中注定的命运，房子和大楼之间不能“形成宿命”。"}, {"text": "潮汐", "is_correct": false, "explanation": "语义：“潮汐”是海水的涨落现象，与房屋和大楼无关，读不通。"}], "explanations": {"鲜明对比": "“形成”后接“鲜明对比”，指两者差异明显，符合房屋与大楼的语境。", "友谊": "语义：“友谊”指人与人之间的感情，房屋与大楼之间不能形成友谊。", "宿命": "语义：“宿命”指命中注定的命运，房子和大楼之间不能“形成宿命”。", "潮汐": "语义：“潮汐”是海水的涨落现象，与房屋和大楼无关，读不通。"}, "sentence_index": 6, "correct_answer": "鲜明对比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛两队的得分一模一样，形成了鲜明对比。", "explanation": "这里应该用〈不相上下〉。两队得分相同，应说不相上下；鲜明对比指两者差异非常突出。"}, {"text": "窗外只有一棵树，却形成了鲜明对比。", "explanation": "这里应该用〈孤零零〉。只有一棵树、没有可比的对象，应说孤零零；鲜明对比需要两种或以上事物相互映衬。"}, {"text": "两个城市的人口几乎一样，形成了鲜明对比。", "explanation": "这里应该用〈接近〉。两地人口几乎相同，应说接近；鲜明对比指两种事物差异非常突出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两种颜色放在一起，做成了鲜明对比。", "corrected_sentence": "这两种颜色放在一起，形成了鲜明对比。", "error_description": "动词搭配错误：“鲜明对比”要和“形成”搭配，说“形成了鲜明对比”，不能说“做成了鲜明对比”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两家饭店的装修风格形成了很鲜明对比。", "corrected_sentence": "这两家饭店的装修风格形成了鲜明对比。", "error_description": "“鲜明对比”是固定搭配，前面不能直接加“很”；应说“形成了鲜明对比”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
