INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12923, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "分子中原子通过化学键连接形成的空间排列方式。", "primary_collocate": null, "pronunciation": "fēn zǐ jié gòu", "ipa": "fən˥ tsɨ˨˩˦ tɕjɛ˧˥ kou˥˩", "syllable_count": 4, "sentences": [{"text": "水的分子结构很简单。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究这种药的分子结构。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同物质的分子结构不一样。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钻石和石墨的分子结构不同，所以性质也不同。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用模型展示了蛋白质的分子结构。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分子结构改变以后，材料的性质也变了。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画出了酒精的分子结构。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料能不能降解，和分子结构有关系。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新材料的分子结构像一张网。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学课上，我们学习了二氧化碳的分子结构。", "target_word": "分子结构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分子结构式", "label": "复合"}], "register": "书面", "sense_fingerprint": "分子中原子连接排列的空间方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9585d0-18df-4185-ab2e-1482e7a5a6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12923, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分子结构", "is_correct": true, "explanation": "“分子结构”指分子中原子的排列方式，说水的“很简单”正合理。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱的数额，与物质的结构无关，不能说“很简单”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指存在的时长，“水的年龄很简单”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”用于人或动物，不用于描述水。"}], "explanations": {"分子结构": "“分子结构”指分子中原子的排列方式，说水的“很简单”正合理。", "价格": "语义：“价格”指钱的数额，与物质的结构无关，不能说“很简单”。", "年龄": "语义：“年龄”指存在的时长，“水的年龄很简单”说不通。", "体重": "搭配：“体重”用于人或动物，不用于描述水。"}, "sentence_index": 0, "correct_answer": "分子结构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋楼的分子结构很坚固。", "explanation": "这里应该用〈构造〉。“分子结构”只指分子内原子的连接，不能形容楼房；楼房的内部组成要用“构造”。"}, {"text": "这种饮料的分子结构是水和糖。", "explanation": "这里应该用〈成分〉。“分子结构”说的是原子怎样排列，列出由什么组成要用“成分”。"}, {"text": "这个公司的分子结构很严密。", "explanation": "这里应该用〈组织〉。“分子结构”不能形容公司的管理；公司的组织安排要用“组织”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12923, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分子结构", "is_correct": true, "explanation": "“分子结构”指分子中原子的排列，老师可以在黑板上画出它。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“画出”后接的是可见的图形，不说“画出味道”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度看不见，无法被画在黑板上。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是数额，不是能被画出来的内容。"}], "explanations": {"分子结构": "“分子结构”指分子中原子的排列，老师可以在黑板上画出它。", "味道": "搭配：“画出”后接的是可见的图形，不说“画出味道”。", "温度": "语义：温度看不见，无法被画在黑板上。", "价格": "语义：价格是数额，不是能被画出来的内容。"}, "sentence_index": 6, "correct_answer": "分子结构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的分子结构很复杂。", "explanation": "这里应该用〈地形〉。“分子结构”指分子中原子的排列，不能形容山的地势；山的形状要用“地形”。"}, {"text": "这个游戏的分子结构很简单。", "explanation": "这里应该用〈规则〉。“分子结构”不用于游戏；游戏的规定要说“规则”。"}, {"text": "这家餐厅的分子结构很精致。", "explanation": "这里应该用〈装修〉。“分子结构”指物质中原子的排列，不能形容餐厅的装潢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12923, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两种金属的一条分子结构不一样。", "corrected_sentence": "这两种金属的分子结构不一样。", "error_description": "量词错误：“分子结构”是抽象名词，不能用“条”计量；“条”多用于细长的东西。这里不加数量词，直接说“这两种金属的分子结构不一样”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12923, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书里画着葡萄糖地分子结构。", "corrected_sentence": "这本书里画着葡萄糖的分子结构。", "error_description": "助词错误：“分子结构”是名词，修饰名词的定语后面要用“的”，不能用“地”，应说“葡萄糖的分子结构”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
