INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12924, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12924, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指能够被控制或管理。", "primary_collocate": null, "pronunciation": "kě kòng", "ipa": "kʰɤ˨˩˦ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "与此形成鲜明对比的是，可降解塑料的设计理念在于其分子结构的“可控不稳定性”——即在特定生态条件下，聚合物链能被环境中的微生物识别为可代谢的有机基质，从而启动生物降解过程。", "target_word": "可控", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这次实验的温度是可控的。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的风险还是可控的。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的病情基本可控。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的速度可控，你可以随便调。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提前准备，成本就可控。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火灾很快就变得可控了。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的作息时间是可控的，家长要多管。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格可控，大家都买得起。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说这件事完全可控，不用担心。", "target_word": "可控", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可控性", "label": "复合"}, {"form": "不可控", "label": "复合"}], "register": "书面", "sense_fingerprint": "事物的状态能够被人控制或管理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9585d0-18df-4185-ab2e-1482e7a5a6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12924, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可控", "is_correct": true, "explanation": "“可控不稳定性”指不稳定的程度能被控制，与文中“启动生物降解”的设计意图一致。"}, {"text": "可靠", "is_correct": false, "explanation": "语义：“可靠”指值得信赖，与“不稳定性”的意思相矛盾。"}, {"text": "可食", "is_correct": false, "explanation": "语义：“可食”指能被食用，与“不稳定性”搭配不通。"}, {"text": "可爱", "is_correct": false, "explanation": "搭配：“可爱”形容讨人喜欢的人或事物，不与“不稳定性”搭配。"}], "explanations": {"可控": "“可控不稳定性”指不稳定的程度能被控制，与文中“启动生物降解”的设计意图一致。", "可靠": "语义：“可靠”指值得信赖，与“不稳定性”的意思相矛盾。", "可食": "语义：“可食”指能被食用，与“不稳定性”搭配不通。", "可爱": "搭配：“可爱”形容讨人喜欢的人或事物，不与“不稳定性”搭配。"}, "sentence_index": 0, "correct_answer": "可控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个桥的结构很可控。", "explanation": "这里应该用〈稳定〉。“可控”指能被人控制，“稳定”说的是结构不易变化；桥的结构是否牢固要用“稳定”。"}, {"text": "这次地震的强度很可控，人们都很放心。", "explanation": "这里应该用〈轻微〉。“可控”指能被人控制，地震的强度无法由人决定，说强度小要用“轻微”。"}, {"text": "他的答案很可控，老师给了高分。", "explanation": "这里应该用〈正确〉。“可控”指能被控制，不用来评价答案的对错；说答案对要用“正确”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可控", "is_correct": true, "explanation": "“可控”指能被控制，说火灾“很快就变得可控了”，表示火势被控制住。"}, {"text": "可燃", "is_correct": false, "explanation": "语义：“可燃”指能燃烧，与“变得可控”所说的被控制状态相反。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：火灾不能“可爱”，“可爱”形容讨人喜欢的事物。"}, {"text": "可口", "is_correct": false, "explanation": "搭配：“可口”用于食物，不用于描述火灾。"}], "explanations": {"可控": "“可控”指能被控制，说火灾“很快就变得可控了”，表示火势被控制住。", "可燃": "语义：“可燃”指能燃烧，与“变得可控”所说的被控制状态相反。", "可爱": "语义：火灾不能“可爱”，“可爱”形容讨人喜欢的事物。", "可口": "搭配：“可口”用于食物，不用于描述火灾。"}, "sentence_index": 6, "correct_answer": "可控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一个可控的朋友，大家都信任他。", "explanation": "这里应该用〈可靠〉。“可控”指事物能被控制，形容人值得信赖要用“可靠”。"}, {"text": "这块蛋糕很可控。", "explanation": "这里应该用〈可口〉。“可控”不形容食物；形容好吃要用“可口”。"}, {"text": "这次旅行的天气很可控，大家都很开心。", "explanation": "这里应该用〈晴朗〉。“可控”指能被人控制，天气不能由人控制；说天气好要用“晴朗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个项目的进度基本没可控。", "corrected_sentence": "这个项目的进度基本不可控。", "error_description": "否定词错误：“可控”是形容词，否定要用“不”，说“不可控”，不能说“没可控”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个局面很快就被可控了。", "corrected_sentence": "这个局面很快就可控了。", "error_description": "被动用法错误：“可控”是形容词，不能用“被”引出，不能说“被可控”。应说“很快就可控了”，不加“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12925, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12925, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12925, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指事物或情况容易发生变化，不能保持稳定。", "primary_collocate": null, "pronunciation": "bù wěn dìng xìng", "ipa": "pu˥˩ wən˨˩˦ tiŋ˥˩ ɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "与此形成鲜明对比的是，可降解塑料的设计理念在于其分子结构的“可控不稳定性”——即在特定生态条件下，聚合物链能被环境中的微生物识别为可代谢的有机基质，从而启动生物降解过程。", "target_word": "不稳定性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种材料的不稳定性很高，要放在冰箱里。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场的不稳定性让很多人不敢买房。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在研究这种药的不稳定性。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气的不稳定性给旅行带来了麻烦。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的情绪有明显的不稳定性。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为不稳定性太大，这个方法没有用。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络的不稳定性常常影响工作。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种气体的不稳定性很危险，一碰就会炸。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作的不稳定性让她很担心。", "target_word": "不稳定性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不稳定", "label": "复合"}, {"form": "不穩定性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物容易变化、难以保持稳定的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9585d0-18df-4185-ab2e-1482e7a5a6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12925, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不稳定性", "is_correct": true, "explanation": "“不稳定性”指材料结构容易变化的性质，与“可控”的语境相符，可以填入空格。"}, {"text": "多样性", "is_correct": false, "explanation": "语义：“多样性”指种类丰富，与“可控”的分子结构特性不符，句意不通。"}, {"text": "透明度", "is_correct": false, "explanation": "语义：“透明度”说的是能否透光，与文中的分子结构和降解过程无关。"}, {"text": "延展性", "is_correct": false, "explanation": "语义：“延展性”指材料能被拉伸，与文中“可控”降解的语境不符。"}], "explanations": {"不稳定性": "“不稳定性”指材料结构容易变化的性质，与“可控”的语境相符，可以填入空格。", "多样性": "语义：“多样性”指种类丰富，与“可控”的分子结构特性不符，句意不通。", "透明度": "语义：“透明度”说的是能否透光，与文中的分子结构和降解过程无关。", "延展性": "语义：“延展性”指材料能被拉伸，与文中“可控”降解的语境不符。"}, "sentence_index": 0, "correct_answer": "不稳定性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议的不稳定性很讨人喜欢，大家都爱参加。", "explanation": "这里应该用〈活跃〉。“活跃”形容会议气氛热闹、积极；“不稳定性”指容易变化，不能用来说会议讨人喜欢。"}, {"text": "这座桥的不稳定性很好，行人可以放心走。", "explanation": "这里应该用〈牢固〉。“牢固”形容结构结实、不易坏；“不稳定性”指容易变化，不能用来说桥的状况好。"}, {"text": "他的不稳定性很健康，每天都坚持运动。", "explanation": "这里应该用〈强壮〉。“强壮”形容身体结实有力；“不稳定性”指事物易变，不能用来形容身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12925, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不稳定性", "is_correct": true, "explanation": "“不稳定性”指事物容易变化，与“太大”搭配，能解释“这个方法没有用”的原因。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能说“太大”，与句中的因果关系不通。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：“字数”通常说“太多”，不说“太大”，与句意不符。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容人的性格，不能说“温柔太大”，也不能解释方法没有用。"}], "explanations": {"不稳定性": "“不稳定性”指事物容易变化，与“太大”搭配，能解释“这个方法没有用”的原因。", "颜色": "搭配：“颜色”不能说“太大”，与句中的因果关系不通。", "字数": "搭配：“字数”通常说“太多”，不说“太大”，与句意不符。", "温柔": "语义：“温柔”形容人的性格，不能说“温柔太大”，也不能解释方法没有用。"}, "sentence_index": 6, "correct_answer": "不稳定性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的不稳定性很好，睡得很香。", "explanation": "这里应该用〈安稳〉。“安稳”形容睡得踏实；“不稳定性”指事物易变，不能用来形容睡眠好坏。"}, {"text": "她的不稳定性让我很高兴，请继续。", "explanation": "这里应该用〈开心〉。“开心”形容心情好；“不稳定性”是事物易变的性质，不能表示令人高兴的情绪。"}, {"text": "这首歌的不稳定性很好听，我想再听一遍。", "explanation": "这里应该用〈旋律〉。“旋律”指歌曲的曲调；“不稳定性”是事物易变的性质，不能说好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12925, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种药有一把明显的不稳定性。", "corrected_sentence": "这种药有一种明显的不稳定性。", "error_description": "量词错误：“不稳定性”应搭配“种”，“把”用于有柄的器具，不能用于抽象性质。应改为“一种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12925, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条不稳定性让我很担心。", "corrected_sentence": "这种不稳定性让我很担心。", "error_description": "量词错误：“不稳定性”是抽象名词，应搭配“种”，“条”用于细长的东西，不能修饰这种性质。应改为“这种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
