INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12926, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指影响生物生存和发展的各种环境因素的总和，包括气候、土壤、水分等。", "primary_collocate": null, "pronunciation": "shēng tài tiáo jiàn", "ipa": "ʂɤŋ˥ tʰaɪ˥˩ tʰjaʊ˧˥ tɕjɛn˥˩", "syllable_count": 4, "sentences": [{"text": "这片湿地的生态条件很好，候鸟都来过冬。", "target_word": "生态条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的植物需要不同的生态条件。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙漠的生态条件很差，树很难活下来。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家正在研究这种鱼的生态条件。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "污染改变了河流的生态条件，鱼变少了。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生态条件好的地方，生物种类也多。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生态条件变坏后，很多动物都离开了。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种草只在特定的生态条件下生长。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保护森林就是保护动物的生态条件。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高山上的生态条件和平原很不一样。", "target_word": "生态条件", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "影响生物生存发展的气候、土壤、水分等环境因素总和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1464a407-3635-4c26-9c56-965320c82102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12926, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学历", "is_correct": false, "explanation": "搭配：“学历”指人受教育的程度，只能用于人，不能用来形容湿地。"}, {"text": "生态条件", "is_correct": true, "explanation": "正确。指影响生物生存发展的环境因素，与“很好”搭配，也与候鸟过冬的语境相符。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：“相貌”指人或动物的外形，湿地没有相貌可言。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”指一地的居民数量，与湿地和候鸟的语境不符。"}], "explanations": {"学历": "搭配：“学历”指人受教育的程度，只能用于人，不能用来形容湿地。", "生态条件": "正确。指影响生物生存发展的环境因素，与“很好”搭配，也与候鸟过冬的语境相符。", "相貌": "体貌：“相貌”指人或动物的外形，湿地没有相貌可言。", "人口": "语义：“人口”指一地的居民数量，与湿地和候鸟的语境不符。"}, "sentence_index": 0, "correct_answer": "生态条件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校的生态条件很好，同学们学习起来很专心。", "explanation": "这里应该用〈环境〉。生态条件指影响生物生存的自然因素，学校的学习氛围应说“学习环境”，不能说生态条件。"}, {"text": "他的生态条件很好，每天跑步也不累。", "explanation": "这里应该用〈身体条件〉。生态条件指生物生存的环境因素，不能用来形容人的身体状况。"}, {"text": "这里的生态条件很好，超市和医院都在附近。", "explanation": "这里应该用〈生活条件〉。生活条件指人的衣食住行和便利程度，超市、医院这类设施应说“生活条件”；生态条件只指生物生存的自然环境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语义：“工资”指劳动报酬，动物不会因工资变坏而离开。"}, {"text": "生态条件", "is_correct": true, "explanation": "正确。指影响生物生存的环境因素，变坏后动物离开，语义连贯。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”只能说大小、长短，不能说变坏。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人或动物的体格特征，不会因环境变坏而导致动物离开。"}], "explanations": {"工资": "语义：“工资”指劳动报酬，动物不会因工资变坏而离开。", "生态条件": "正确。指影响生物生存的环境因素，变坏后动物离开，语义连贯。", "年龄": "搭配：“年龄”只能说大小、长短，不能说变坏。", "身高": "体貌：“身高”是人或动物的体格特征，不会因环境变坏而导致动物离开。"}, "sentence_index": 6, "correct_answer": "生态条件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家的生态条件不太好，但他很努力。", "explanation": "这里应该用〈经济条件〉。生态条件指生物生存的环境因素，不能用来说家庭的经济状况。"}, {"text": "这台电脑的生态条件很好，运行非常快。", "explanation": "这里应该用〈硬件条件〉。生态条件指生物的自然环境，电脑的配置要说“硬件条件”。"}, {"text": "这个工地的生态条件很差，工人很辛苦。", "explanation": "这里应该用〈施工条件〉。生态条件指生物生存的自然因素，工地的施工环境要说“施工条件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片湿地的生态条件了很好，不少鸟都愿意在这里过冬。", "corrected_sentence": "这片湿地的生态条件很好，不少鸟都愿意在这里过冬。", "error_description": "助词错误：“了”误加在“生态条件”之后。“生态条件”后不能直接接“了”，应去掉“了”，说“生态条件很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片山林得生态条件很好，很多鸟都在这里安家。", "corrected_sentence": "这片山林的生态条件很好，很多鸟都在这里安家。", "error_description": "助词错误：修饰名词“生态条件”的“的”误写成“得”。“得”用于动词后作补语，此处应用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
