INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12928, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12928, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生物体能分解并吸收作为食物的有机材料", "primary_collocate": null, "pronunciation": "jī zhì", "ipa": "tɕi˥ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "理想的堆肥原料应包含“绿色”与“棕色”两类物料：前者如蔬菜残叶、果核、咖啡渣，富含氮元素，提供微生物繁殖所需的蛋白质基质；后者如干落叶、碎纸板、秸秆，富含纤维素与木质素，作为碳源维持能量代谢，并改善物料孔隙度。", "target_word": "基质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "与此形成鲜明对比的是，可降解塑料的设计理念在于其分子结构的“可控不稳定性”——即在特定生态条件下，聚合物链能被环境中的微生物识别为可代谢的有机基质，从而启动生物降解过程。", "target_word": "基质", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "微生物靠分解有机基质得到能量。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细菌把这种基质当成食物。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酵母菌吸收糖类基质，产生酒精。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基质不够时，细菌就会停止生长。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆肥里的微生物每天分解大量基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种细菌能分解有机基质，所以可以处理垃圾。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水池里的有机基质太多，细菌长得很快。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验中，我们给细菌加了葡萄糖当基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有机基质", "label": "复合"}, {"form": "培养基质", "label": "复合"}, {"form": "种", "label": "量词"}, {"form": "基質", "label": "繁体"}], "register": "书面", "sense_fingerprint": "微生物等生物分解并吸收的有机食物材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfd7af12-1a73-462f-9399-277b88dbbcd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12928, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。基质指生物体能分解并吸收的有机食物材料。"}, {"text": "极致", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是达到的最高程度。"}, {"text": "几只", "is_correct": false, "explanation": "jǐ zhī（第三声、第一声）与 jī zhì 声调不同，意思是几只（动物）。"}, {"text": "寄至", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是寄送到某处。"}], "explanations": {"基质": "正确。基质指生物体能分解并吸收的有机食物材料。", "极致": "jí（第二声）与 jī（第一声）声调不同，意思是达到的最高程度。", "几只": "jǐ zhī（第三声、第一声）与 jī zhì 声调不同，意思是几只（动物）。", "寄至": "jì（第四声）与 jī（第一声）声调不同，意思是寄送到某处。"}, "sentence_index": null, "correct_answer": "基质"}, "level_3": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。此处指微生物繁殖所需的营养物质，与“蛋白质”搭配。"}, {"text": "容器", "is_correct": false, "explanation": "语义：蛋白质是营养成分，不是盛放物料的容器，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“蛋白质”不与“颜色”组合，这里要说营养物质的类别。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是物理状态，不是可供微生物繁殖的营养物质，句意不通。"}], "explanations": {"基质": "正确。此处指微生物繁殖所需的营养物质，与“蛋白质”搭配。", "容器": "语义：蛋白质是营养成分，不是盛放物料的容器，句意不通。", "颜色": "搭配：“蛋白质”不与“颜色”组合，这里要说营养物质的类别。", "温度": "语义：温度是物理状态，不是可供微生物繁殖的营养物质，句意不通。"}, "sentence_index": 0, "correct_answer": "基质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用基质给汽车加油。", "explanation": "这里应该用〈汽油〉。基质指生物体吸收的食物材料，不是汽车的燃料。"}, {"text": "画家用基质调颜色。", "explanation": "这里应该用〈颜料〉。基质是生物可分解吸收的有机材料，不用于调色。"}, {"text": "焊工用基质焊接钢管。", "explanation": "这里应该用〈焊料〉。基质是生物可分解吸收的有机材料，不能用于焊接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12928, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。基质指生物体能分解并吸收的有机食物材料。"}, {"text": "资质", "is_correct": false, "explanation": "zī（第一声）与 jī 声母不同（z 与 j），意思是资格和能力。"}, {"text": "精致", "is_correct": false, "explanation": "jīng 比 jī 多一个韵尾 -ng，意思是精巧细致。"}, {"text": "鸡只", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，意思是鸡的数量。"}], "explanations": {"基质": "正确。基质指生物体能分解并吸收的有机食物材料。", "资质": "zī（第一声）与 jī 声母不同（z 与 j），意思是资格和能力。", "精致": "jīng 比 jī 多一个韵尾 -ng，意思是精巧细致。", "鸡只": "zhī（第一声）与 zhì（第四声）声调不同，意思是鸡的数量。"}, "sentence_index": null, "correct_answer": "基质"}, "level_3": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。微生物分解的对象是有机食物材料，与“分解”搭配。"}, {"text": "光线", "is_correct": false, "explanation": "语义：微生物分解的是有机物，光线不能被分解，句意不通。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不是有机食物材料，微生物无法分解它。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“分解”的对象应为物质，不能与“脚步”组合。"}], "explanations": {"基质": "正确。微生物分解的对象是有机食物材料，与“分解”搭配。", "光线": "语义：微生物分解的是有机物，光线不能被分解，句意不通。", "音乐": "语义：音乐不是有机食物材料，微生物无法分解它。", "脚步": "搭配：“分解”的对象应为物质，不能与“脚步”组合。"}, "sentence_index": 6, "correct_answer": "基质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人每天用基质擦玻璃。", "explanation": "这里应该用〈抹布〉。基质指生物体吸收的食物材料，不能用来擦拭。"}, {"text": "孩子用基质搭房子。", "explanation": "这里应该用〈积木〉。基质指生物体吸收的食物材料，不能用来搭建。"}, {"text": "司机用基质修补轮胎。", "explanation": "这里应该用〈补胎胶〉。基质不是修补轮胎的材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "细菌每天要分解一只有机基质。", "corrected_sentence": "细菌每天要分解一种有机基质。", "error_description": "量词错误：“基质”应搭配量词“种”，不能用“只”（“只”多用于动物或成对的物件）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "细菌能分解这种基质们。", "corrected_sentence": "细菌能分解这种基质。", "error_description": "“们”表示复数，一般只用于指人的名词；“基质”是物质名词，应说“这种基质”，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12929, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12929, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12929, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指完整的东西因受到外力而变得不完整，裂成碎块。", "primary_collocate": null, "pronunciation": "pò suì", "ipa": "pʰo˥˩ sueɪ˥˩", "syllable_count": 2, "sentences": [{"text": "杯子掉在地上，破碎了。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玻璃受到撞击，一下子破碎了。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花瓶摔在地上，破碎成很多小块。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰面承受不住重量，慢慢破碎了。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不小心让镜子破碎了。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大风过后，路边的玻璃全都破碎了。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上的碗已经破碎，别用手去捡。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机器一开，大石头很快就破碎了。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机屏幕破碎了，我要去修一下。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的花瓶破碎过，后来用胶粘好了。", "target_word": "破碎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "破碎了", "label": "完成体"}, {"form": "破碎过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "完整的东西受外力裂成碎块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1464a407-3635-4c26-9c56-965320c82102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12929, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "笑", "is_correct": false, "explanation": "语义：“笑”的主语需是人或动物，杯子不会笑。"}, {"text": "破碎", "is_correct": true, "explanation": "正确。指完整的东西裂成碎块，与“掉在地上”的语境相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与摔落的杯子无关。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”需要以文字为宾语，“杯子掉在地上，写了”句意不通。"}], "explanations": {"笑": "语义：“笑”的主语需是人或动物，杯子不会笑。", "破碎": "正确。指完整的东西裂成碎块，与“掉在地上”的语境相符。", "唱": "语义：“唱”指发出歌声，与摔落的杯子无关。", "写": "语义：“写”需要以文字为宾语，“杯子掉在地上，写了”句意不通。"}, "sentence_index": 0, "correct_answer": "破碎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条水管冻了一夜，已经破碎了，水一直往外流。", "explanation": "这里应该用〈破裂〉。破碎指东西碎成小块；水管裂开一道口子，应说“破裂”。"}, {"text": "我的裤子膝盖破碎了，妈妈帮我补好了。", "explanation": "这里应该用〈磨破〉。布料磨出一个洞应说“磨破”；破碎指硬的东西碎成很多小块。"}, {"text": "气球吹得太大，“砰”的一声破碎了。", "explanation": "这里应该用〈爆〉。气球胀破应说“爆了”；破碎指完整的硬物裂成碎块。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12929, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飞", "is_correct": false, "explanation": "语义：“飞”的主语需要会飞，碗不会飞。"}, {"text": "破碎", "is_correct": true, "explanation": "正确。指碗碎成小块，与“别用手去捡”的语境一致。"}, {"text": "醒", "is_correct": false, "explanation": "语义：“醒”指从睡眠中恢复，碗不能醒。"}, {"text": "放", "is_correct": false, "explanation": "配价：“放”需要带处所宾语，只说“碗已经放”不成立。"}], "explanations": {"飞": "语义：“飞”的主语需要会飞，碗不会飞。", "破碎": "正确。指碗碎成小块，与“别用手去捡”的语境一致。", "醒": "语义：“醒”指从睡眠中恢复，碗不能醒。", "放": "配价：“放”需要带处所宾语，只说“碗已经放”不成立。"}, "sentence_index": 6, "correct_answer": "破碎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥的钢索破碎了，车只能绕路走。", "explanation": "这里应该用〈断裂〉。破碎指东西碎成小块；钢索整根断开应说“断裂”。"}, {"text": "这个信封的封口破碎了，里面的信掉了出来。", "explanation": "这里应该用〈撕破〉。信封被撕开一个口子，不是碎成小块，应说“撕破”。"}, {"text": "这根绳子破碎了，我们只好换一根。", "explanation": "这里应该用〈绷断〉。绳子整根断开应说“绷断”，破碎指东西碎成很多小块。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个花瓶从架子上掉下来，把它破碎了。", "corrected_sentence": "一个花瓶从架子上掉下来，破碎了。", "error_description": "配价错误：“破碎”是不及物动词，不能带“把”字宾语。应说“花瓶破碎了”，不说“把它破碎了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个玻璃杯从桌子上摔下来，被破碎了。", "corrected_sentence": "一个玻璃杯从桌子上摔下来，破碎了。", "error_description": "被动错误：“破碎”是不及物动词，不能用“被”字句。应说“玻璃杯……破碎了”，去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
