INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12930, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "化学物质之间发生的变化过程", "primary_collocate": null, "pronunciation": "fǎn yìng", "ipa": "fan˨˩˦ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "铁和氧气会发生反应，生成铁锈。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个反应需要加热才能开始。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "醋和小苏打混合后，反应很快就开始了。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反应结束后，试管里出现了白色的沉淀。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种液体放在一起，马上就有反应。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度越高，这个反应进行得越快。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铜和稀盐酸之间没有反应。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验中，气泡说明反应正在进行。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把盐酸倒进杯子，反应立刻开始了。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个反应会放出热量，试管变热了。", "target_word": "反应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "化学反应", "label": "复合"}, {"form": "反應", "label": "繁体"}], "register": "书面", "sense_fingerprint": "化学物质之间发生变化的过程；化学反应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1464a407-3635-4c26-9c56-965320c82102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反应", "is_correct": true, "explanation": "正确：“会发生反应”是化学变化的常用说法，与“生成铁锈”相符。"}, {"text": "事故", "is_correct": false, "explanation": "语义：铁和氧气不会“发生事故”，与化学变化的语境不符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“生成铁锈”说明这是化学变化，“声音”不是化学变化的结果。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“发生”后面不能直接接“颜色”，应说“颜色发生变化”。"}], "explanations": {"反应": "正确：“会发生反应”是化学变化的常用说法，与“生成铁锈”相符。", "事故": "语义：铁和氧气不会“发生事故”，与化学变化的语境不符。", "声音": "语义：“生成铁锈”说明这是化学变化，“声音”不是化学变化的结果。", "颜色": "搭配：“发生”后面不能直接接“颜色”，应说“颜色发生变化”。"}, "sentence_index": 0, "correct_answer": "反应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章反应了农民的生活。", "explanation": "这里应该用〈反映〉。反映指把事物的情况显示出来，多用于文章、作品；反应指物质之间的变化或对刺激的回应。"}, {"text": "光线照到镜面上会发生反应。", "explanation": "这里应该用〈反射〉。光线碰到镜面后返回属于反射，不是化学变化，所以不能用“反应”。"}, {"text": "这次实验只产生了一只反应。", "explanation": "这里应该用〈个〉。“只”多用于动物等，反应的量词应用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反应", "is_correct": true, "explanation": "正确：“之间没有反应”说的是两种物质之间不起变化，与句意相符。"}, {"text": "节日", "is_correct": false, "explanation": "语义：“铜和稀盐酸之间没有节日”不通，节日与化学物质无关。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是化学物质之间的关系，不能填入此处。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“之间”后接的应是相互作用或关系的词，“没有早餐”与此不搭配。"}], "explanations": {"反应": "正确：“之间没有反应”说的是两种物质之间不起变化，与句意相符。", "节日": "语义：“铜和稀盐酸之间没有节日”不通，节日与化学物质无关。", "课本": "语义：课本不是化学物质之间的关系，不能填入此处。", "早餐": "搭配：“之间”后接的应是相互作用或关系的词，“没有早餐”与此不搭配。"}, "sentence_index": 6, "correct_answer": "反应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个部门采取了新的反应。", "explanation": "这里应该用〈措施〉。“采取”后接措施、办法；反应是对刺激的回应，不能被采取。"}, {"text": "这个反应已经修好了，可以接着用了。", "explanation": "这里应该用〈装置〉。反应是物质发生变化的过程，不是可以修理、使用的东西。"}, {"text": "这个反应讲的是他的家事。", "explanation": "这里应该用〈事情〉。反应指化学变化或对刺激的回应，不能用来指事情或话题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只反应在常温下很难发生。", "corrected_sentence": "这个反应在常温下很难发生。", "error_description": "量词错误：“反应”应使用量词“个”，不能用“只”（“只”多用于动物等）。正确说法是“这个反应”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "加热后，这个反应进行很快。", "corrected_sentence": "加热后，这个反应进行得很快。", "error_description": "补语错误：“进行”后带程度补语须用“得”，应说“进行得很快”，不说“进行很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
