INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12931, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生物体内产生并排出某种物质，如汗液、唾液等。", "primary_collocate": null, "pronunciation": "fēn mì", "ipa": "fən˥˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "胃会分泌胃酸帮助消化食物。", "target_word": "分泌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气热的时候，皮肤会分泌汗液。", "target_word": "分泌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂的腺体能分泌蜡。", "target_word": "分泌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃东西时，嘴里会分泌唾液。", "target_word": "分泌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "胰岛能分泌胰岛素，调节血糖。", "target_word": "分泌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜗牛爬过的地方，会留下它分泌的黏液。", "target_word": "分泌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "紧张的时候，身体会分泌更多肾上腺素。", "target_word": "分泌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚕分泌出细细的丝，做成茧。", "target_word": "分泌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肝脏分泌胆汁，帮助分解脂肪。", "target_word": "分泌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人睡觉时，大脑会分泌褪黑素。", "target_word": "分泌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分泌了", "label": "体标"}, {"form": "分泌过", "label": "体标"}, {"form": "分泌物", "label": "复合"}, {"form": "内分泌", "label": "复合"}], "register": "书面", "sense_fingerprint": "生物体的腺体或细胞产生并排出汗液、激素等物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1464a407-3635-4c26-9c56-965320c82102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12931, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分泌", "is_correct": true, "explanation": "正确：分泌 fēn mì，指生物体的腺体产生并排出某种物质。"}, {"text": "蜂蜜", "is_correct": false, "explanation": "fēng 与 fēn 韵母不同（-ng 与 -n），意思是蜂蜜。"}, {"text": "分米", "is_correct": false, "explanation": "mǐ（第三声）与 mì（第四声）声调不同，意思是分米（长度单位）。"}, {"text": "分立", "is_correct": false, "explanation": "lì 与 mì 声母不同（l 与 m），意思是分开设立。"}], "explanations": {"分泌": "正确：分泌 fēn mì，指生物体的腺体产生并排出某种物质。", "蜂蜜": "fēng 与 fēn 韵母不同（-ng 与 -n），意思是蜂蜜。", "分米": "mǐ（第三声）与 mì（第四声）声调不同，意思是分米（长度单位）。", "分立": "lì 与 mì 声母不同（l 与 m），意思是分开设立。"}, "sentence_index": null, "correct_answer": "分泌"}, "level_3": {"options": [{"text": "分泌", "is_correct": true, "explanation": "正确：“胃会分泌胃酸”说明胃的消化功能，与句意相符。"}, {"text": "观看", "is_correct": false, "explanation": "语义：“胃会观看胃酸”不成立，观看的对象不能是胃酸。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”不能接“胃酸”作宾语，搭配不通。"}, {"text": "旅行", "is_correct": false, "explanation": "配价：“旅行”是不及物动词，不能带“胃酸”作宾语。"}], "explanations": {"分泌": "正确：“胃会分泌胃酸”说明胃的消化功能，与句意相符。", "观看": "语义：“胃会观看胃酸”不成立，观看的对象不能是胃酸。", "演奏": "搭配：“演奏”不能接“胃酸”作宾语，搭配不通。", "旅行": "配价：“旅行”是不及物动词，不能带“胃酸”作宾语。"}, "sentence_index": 0, "correct_answer": "分泌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汽车会分泌尾气。", "explanation": "这里应该用〈排出〉。分泌指生物体的腺体产生并排出物质，汽车排放尾气不能用分泌。"}, {"text": "墙壁上分泌了水珠。", "explanation": "这里应该用〈渗出〉。分泌的主体是生物的腺体，墙壁渗出水珠不能用分泌。"}, {"text": "工厂分泌了大量废水。", "explanation": "这里应该用〈产生〉。分泌的主语必须是生物体，工厂不能分泌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12931, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分泌", "is_correct": true, "explanation": "正确：“紧张的时候身体会分泌肾上腺素”是生理过程，与句意相符。"}, {"text": "观赏", "is_correct": false, "explanation": "语义：观赏的对象是景物或艺术，不能是肾上腺素。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”要求交通工具作宾语，不能带“肾上腺素”。"}, {"text": "复习", "is_correct": false, "explanation": "搭配：“复习”的对象是学习内容，与“肾上腺素”不搭配。"}], "explanations": {"分泌": "正确：“紧张的时候身体会分泌肾上腺素”是生理过程，与句意相符。", "观赏": "语义：观赏的对象是景物或艺术，不能是肾上腺素。", "驾驶": "配价：“驾驶”要求交通工具作宾语，不能带“肾上腺素”。", "复习": "搭配：“复习”的对象是学习内容，与“肾上腺素”不搭配。"}, "sentence_index": 6, "correct_answer": "分泌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电池会分泌能量。", "explanation": "这里应该用〈释放〉。分泌的主体是生物的腺体，电池不能分泌能量。"}, {"text": "烟囱里分泌出黑烟。", "explanation": "这里应该用〈冒出〉。烟囱不是生物体，不能分泌。"}, {"text": "雨水从屋檐分泌下来。", "explanation": "这里应该用〈滴下〉。雨水是从外部落下的，分泌只用于生物体内的物质排出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12931, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蚂蚁会分泌来一种气味，用来标记路线。", "corrected_sentence": "蚂蚁会分泌出一种气味，用来标记路线。", "error_description": "补语错误：“分泌”后的趋向补语应为“出”，不能用“来”。“分泌来”不成立，应说“分泌出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12931, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "运动后，人的皮肤很分泌汗液。", "corrected_sentence": "运动后，人的皮肤会分泌汗液。", "error_description": "状语错误：“分泌”前应用能愿动词“会”表示将会发生，不能用程度副词“很”修饰动词。正确说法是“会分泌汗液”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
