INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12932, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水解酶是催化水解反应的一类酶，能将大分子物质（如淀粉、蛋白质）分解为小分子。", "primary_collocate": null, "pronunciation": "shuǐ jiě méi", "ipa": "ʂuei˨˩˦ tɕjɛ˨˩˦ mei˧˥", "syllable_count": 3, "sentences": [{"text": "这一过程并非简单的物理破碎，而是一系列复杂的生化反应：微生物分泌特定的水解酶，作用于聚合物的酯键或酰胺键，将其逐步裂解为低聚物、单体乃至二氧化碳、水和生物质。", "target_word": "水解酶", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水解酶能把淀粉分解成葡萄糖。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唾液里有一种水解酶，能分解淀粉。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣粉里加入水解酶，可以去掉污渍。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "胃里的水解酶帮助人分解蛋白质。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水解酶在高温下会失去活性。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家从细菌中找到了新的水解酶。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水解酶需要水才能完成分解工作。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每种水解酶只能分解一种物质。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酿酒时，水解酶先把粮食变成糖。", "target_word": "水解酶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "科技", "sense_fingerprint": "催化水解反应、把大分子分解为小分子的一类酶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1464a407-3635-4c26-9c56-965320c82102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "激素", "is_correct": false, "explanation": "语义：激素是内分泌系统的信号分子，不会作用于聚合物的酯键或酰胺键，与句中的作用对象不符。"}, {"text": "抗体", "is_correct": false, "explanation": "语义：抗体与抗原结合以完成免疫防御，不会去裂解聚合物的化学键。"}, {"text": "细菌", "is_correct": false, "explanation": "搭配：“分泌”的宾语应是酶、激素等物质，不能说分泌细菌。"}, {"text": "水解酶", "is_correct": true, "explanation": "正确：水解酶是催化水解反应的酶，可由微生物分泌，并作用于酯键、酰胺键等化学键。"}], "explanations": {"激素": "语义：激素是内分泌系统的信号分子，不会作用于聚合物的酯键或酰胺键，与句中的作用对象不符。", "抗体": "语义：抗体与抗原结合以完成免疫防御，不会去裂解聚合物的化学键。", "细菌": "搭配：“分泌”的宾语应是酶、激素等物质，不能说分泌细菌。", "水解酶": "正确：水解酶是催化水解反应的酶，可由微生物分泌，并作用于酯键、酰胺键等化学键。"}, "sentence_index": 0, "correct_answer": "水解酶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "用水解酶溶解这块矿石，效果很好。", "explanation": "水解酶的作用是催化水解反应，把淀粉、蛋白质等大分子拆成小分子；它不是能让矿石溶化的溶剂，这里误把它当成溶剂用了。"}, {"text": "这些板子用水解酶发电，很环保。", "explanation": "水解酶的作用是催化大分子的水解反应，它本身不能把能量转化成电能，这里误把它当成能产生电能的东西用了。"}, {"text": "夏天用水解酶给房间降温。", "explanation": "水解酶的作用是催化大分子的水解反应，它没有制冷的功能，这里误把它当成制冷的东西用了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "岩石", "is_correct": false, "explanation": "语义：岩石是地壳中的矿物，不可能从细菌中找到，与“从细菌中找到”的说法冲突。"}, {"text": "行星", "is_correct": false, "explanation": "语义：行星是天体，不可能从细菌中找到，与句意不符。"}, {"text": "化石", "is_correct": false, "explanation": "语义：化石是古代生物埋在岩层中的遗迹，句中找到的应是能催化反应的物质，化石与之不符。"}, {"text": "水解酶", "is_correct": true, "explanation": "正确：科学家从细菌中找到的新物质是能催化水解反应的水解酶，与句意相符。"}], "explanations": {"岩石": "语义：岩石是地壳中的矿物，不可能从细菌中找到，与“从细菌中找到”的说法冲突。", "行星": "语义：行星是天体，不可能从细菌中找到，与句意不符。", "化石": "语义：化石是古代生物埋在岩层中的遗迹，句中找到的应是能催化反应的物质，化石与之不符。", "水解酶": "正确：科学家从细菌中找到的新物质是能催化水解反应的水解酶，与句意相符。"}, "sentence_index": 6, "correct_answer": "水解酶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "实验室里有一条水解酶，正在分解淀粉。", "explanation": "量词用错：「条」用于细长的东西，酶不能用「条」来数，应说「一种水解酶」。"}, {"text": "厨房的柜子里放着一根水解酶。", "explanation": "量词用错：「根」用于细长的条状物，酶不能用「根」来数，应说「一种水解酶」。"}, {"text": "药店的柜台上摆着一只水解酶。", "explanation": "量词用错：「只」用于动物或成对的物件，酶不能用「只」来数，应说「一种水解酶」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些水解酶们能分解淀粉。", "corrected_sentence": "这些水解酶能分解淀粉。", "error_description": "错误在于“水解酶”后面多加了“们”。“们”只用于指人的名词，水解酶是物质，应去掉“们”，说“这些水解酶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员发现了一位新的水解酶。", "corrected_sentence": "研究人员发现了一种新的水解酶。", "error_description": "错误在于量词。“位”用于指人的名词，水解酶是物质，应使用量词“种”，说“一种新的水解酶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
