INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12933, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "连接脂肪酸和甘油等分子形成的化学键，用于构成脂肪等物质。", "primary_collocate": null, "pronunciation": "zhǐ jiàn", "ipa": "ʈʂɨ˨˩˦ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这一过程并非简单的物理破碎，而是一系列复杂的生化反应：微生物分泌特定的水解酶，作用于聚合物的酯键或酰胺键，将其逐步裂解为低聚物、单体乃至二氧化碳、水和生物质。", "target_word": "酯键", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "脂肪里有酯键，它连着脂肪酸和甘油。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水解酶可以打断油脂中的酯键。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脂肪酸和甘油通过酯键连在一起。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酯键断开后，脂肪就变成了小分子。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个分子有三个酯键。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油脂分子里的酯键很容易水解。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画出了酯键的结构。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酯键是脂肪分子中的一种化学键。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "微生物能分解塑料里的酯键。", "target_word": "酯键", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "酯鍵", "label": "繁体"}], "register": "科技", "sense_fingerprint": "脂肪酸与甘油相连的化学键", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d87bd1f-744f-4914-a5d1-ee173b9f4aec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12933, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酯键", "is_correct": true, "explanation": "酯键是化学键，能被水解酶作用，与后面的酰胺键并列作为作用对象。"}, {"text": "电子", "is_correct": false, "explanation": "语义：电子不是化学键，不能被水解酶作用，也不能与酰胺键并列。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“作用于”不接“体积”，体积不是可以被裂解的结构。"}, {"text": "水分", "is_correct": false, "explanation": "语义：水分是物质而非化学键，不能与酰胺键并列作为水解对象。"}], "explanations": {"酯键": "酯键是化学键，能被水解酶作用，与后面的酰胺键并列作为作用对象。", "电子": "语义：电子不是化学键，不能被水解酶作用，也不能与酰胺键并列。", "体积": "搭配：“作用于”不接“体积”，体积不是可以被裂解的结构。", "水分": "语义：水分是物质而非化学键，不能与酰胺键并列作为水解对象。"}, "sentence_index": 0, "correct_answer": "酯键"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蛋白质中的氨基酸通过酯键相连。", "explanation": "这里应该用〈酰胺键〉。氨基酸之间靠酰胺键连接，酯键连接的是脂肪酸和甘油。"}, {"text": "淀粉里的葡萄糖靠酯键相连。", "explanation": "这里应该用〈糖苷键〉。葡萄糖分子之间靠糖苷键连接，酯键连接的是脂肪酸和甘油。"}, {"text": "碱基对靠酯键连在一起。", "explanation": "这里应该用〈氢键〉。碱基对之间靠氢键配对，酯键连接的是脂肪酸和甘油。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12933, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酯键", "is_correct": true, "explanation": "酯键是可以被水解的化学键，与“很容易水解”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“水解”针对化学键或物质，颜色不能水解，“很容易水解”说不通。"}, {"text": "酶", "is_correct": false, "explanation": "语义：酶是催化剂，本身不是可以水解的化学键，“油脂分子里的酶”不成立。"}, {"text": "电压", "is_correct": false, "explanation": "语义：电压是电学量，与油脂分子结构无关，不能“水解”。"}], "explanations": {"酯键": "酯键是可以被水解的化学键，与“很容易水解”相合。", "颜色": "搭配：“水解”针对化学键或物质，颜色不能水解，“很容易水解”说不通。", "酶": "语义：酶是催化剂，本身不是可以水解的化学键，“油脂分子里的酶”不成立。", "电压": "语义：电压是电学量，与油脂分子结构无关，不能“水解”。"}, "sentence_index": 6, "correct_answer": "酯键"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上吃一个酯键当早餐。", "explanation": "这里的“酯键”被当成了食物。酯键是分子中的化学键，并不是可以吃的东西。"}, {"text": "他把酯键送给妈妈当生日礼物。", "explanation": "这里的“酯键”被当成了可以送人的物品。酯键是分子结构中的化学键，不是礼物。"}, {"text": "公园里的酯键在草地上跑来跑去。", "explanation": "这里的“酯键”被当成了会行动的东西。酯键是化学键，不会跑动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个分子里有四只酯键。", "corrected_sentence": "这个分子里有四个酯键。", "error_description": "量词错误：“酯键”的量词应为“个”，“只”多用于动物或成对物件，不能说“四只酯键”，应说“四个酯键”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水解酶酯键切断了，油脂就分解了。", "corrected_sentence": "水解酶把酯键切断了，油脂就分解了。", "error_description": "把字句遗漏：处置式中“酯键”须由“把”引出，应说“水解酶把酯键切断了”；省去“把”后“水解酶酯键切断了”结构不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
