INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12934, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "酰胺键是酰胺分子中连接碳原子和氮原子的化学键，常见于蛋白质和多肽中。", "primary_collocate": null, "pronunciation": "xiān àn jiàn", "ipa": "ɕjɛn˥ an˥˩ tɕjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "这一过程并非简单的物理破碎，而是一系列复杂的生化反应：微生物分泌特定的水解酶，作用于聚合物的酯键或酰胺键，将其逐步裂解为低聚物、单体乃至二氧化碳、水和生物质。", "target_word": "酰胺键", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "蛋白质中的氨基酸通过酰胺键相连。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酰胺键连接着碳原子和氮原子。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多肽里有很多酰胺键。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋白酶能打断蛋白质里的酰胺键。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加热时，酰胺键可能会断开。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肽键是一种酰胺键。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条多肽链上有十个酰胺键。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尼龙的分子中也有酰胺键。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生画出了酰胺键的结构式。", "target_word": "酰胺键", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "醯胺鍵", "label": "繁体"}], "register": "科技", "sense_fingerprint": "连接碳和氮、见于蛋白质的化学键", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d87bd1f-744f-4914-a5d1-ee173b9f4aec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酰胺键", "is_correct": true, "explanation": "酰胺键是化学键，能被水解酶作用，与前面的酯键并列。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“作用于”不接“颜色”，颜色不是可以被裂解的结构。"}, {"text": "电压", "is_correct": false, "explanation": "语义：电压是电学量，不是化学键，不能与酯键并列作为作用对象。"}, {"text": "水分", "is_correct": false, "explanation": "语义：水分是物质而非化学键，不能与酯键并列作为水解对象。"}], "explanations": {"酰胺键": "酰胺键是化学键，能被水解酶作用，与前面的酯键并列。", "颜色": "搭配：“作用于”不接“颜色”，颜色不是可以被裂解的结构。", "电压": "语义：电压是电学量，不是化学键，不能与酯键并列作为作用对象。", "水分": "语义：水分是物质而非化学键，不能与酯键并列作为水解对象。"}, "sentence_index": 0, "correct_answer": "酰胺键"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "脂肪酸和甘油通过酰胺键连在一起。", "explanation": "这里应该用〈酯键〉。脂肪酸与甘油之间靠酯键连接，酰胺键连接的是氨基酸。"}, {"text": "淀粉里的葡萄糖靠酰胺键相连。", "explanation": "这里应该用〈糖苷键〉。葡萄糖之间靠糖苷键连接，酰胺键主要连接氨基酸。"}, {"text": "DNA的两条链靠酰胺键配对。", "explanation": "这里应该用〈氢键〉。DNA两条链之间靠氢键配对，酰胺键连接的是碳原子和氮原子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酰胺键", "is_correct": true, "explanation": "肽键是一种酰胺键，二者的关系成立。"}, {"text": "蛋白质", "is_correct": false, "explanation": "语义：肽键是化学键，蛋白质是大分子物质，“肽键是一种蛋白质”不成立。"}, {"text": "氨基酸", "is_correct": false, "explanation": "语义：氨基酸是构成蛋白质的小分子，不是化学键，句子说不通。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“是一种”后应接同类概念，“体积”是物理量，与化学键不属同一类。"}], "explanations": {"酰胺键": "肽键是一种酰胺键，二者的关系成立。", "蛋白质": "语义：肽键是化学键，蛋白质是大分子物质，“肽键是一种蛋白质”不成立。", "氨基酸": "语义：氨基酸是构成蛋白质的小分子，不是化学键，句子说不通。", "体积": "搭配：“是一种”后应接同类概念，“体积”是物理量，与化学键不属同一类。"}, "sentence_index": 6, "correct_answer": "酰胺键"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把酰胺键放进汤里炖。", "explanation": "这里的“酰胺键”被当成了食材。酰胺键是分子中的化学键，不能放进汤里炖。"}, {"text": "我们在操场上把酰胺键当球踢。", "explanation": "这里的“酰胺键”被当成了球。酰胺键是化学键，不能当球来踢。"}, {"text": "他把酰胺键送给同学当生日礼物。", "explanation": "这里的“酰胺键”被当成了可以送人的物品。酰胺键是化学结构，不是礼物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个分子里有一只酰胺键。", "corrected_sentence": "这个分子里有一个酰胺键。", "error_description": "量词错误：“酰胺键”的量词应为“个”，“只”多用于动物或成对物件，不能说“一只酰胺键”，应说“一个酰胺键”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "加热时，酰胺键断了开。", "corrected_sentence": "加热时，酰胺键断开了。", "error_description": "“了”位置错误：“断开”是动补结构，“了”应放在补语之后，应说“断开了”，不能说“断了开”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
