INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12935, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，相当于“把”，用来引出动作的处置对象。", "primary_collocate": null, "pronunciation": "jiāng", "ipa": "tɕjɑŋ˥", "syllable_count": 1, "sentences": [{"text": "请将这份文件交给王经理。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他将书放在桌子上。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师将作业发给了同学们。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请将手机调成静音。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们将旧房子拆掉了。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她将这个好消息告诉了妈妈。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要将垃圾送到楼下。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请将窗户关好。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他将水倒进杯子里。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民将河水引到田里。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "介词，相当于“把”：引出动作处置的对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '924b73f8-6511-4651-8db4-395d31541c64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12935, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "将", "is_correct": true, "explanation": "正确答案：将，jiāng（第一声），本句中读作此音。"}, {"text": "奖", "is_correct": false, "explanation": "奖 jiǎng（第三声）与 jiāng（第一声）声调不同，意思是奖品。"}, {"text": "酱", "is_correct": false, "explanation": "酱 jiàng（第四声）与 jiāng（第一声）声调不同，意思是酱料。"}, {"text": "间", "is_correct": false, "explanation": "间 jiān 与 jiāng 韵尾不同（an 与 ang），意思是中间或房间。"}, {"text": "煎", "is_correct": false, "explanation": "煎 jiān 与 jiāng 韵尾不同（an 与 ang），意思是煎炸。"}], "explanations": {"将": "正确答案：将，jiāng（第一声），本句中读作此音。", "奖": "奖 jiǎng（第三声）与 jiāng（第一声）声调不同，意思是奖品。", "酱": "酱 jiàng（第四声）与 jiāng（第一声）声调不同，意思是酱料。", "间": "间 jiān 与 jiāng 韵尾不同（an 与 ang），意思是中间或房间。", "煎": "煎 jiān 与 jiāng 韵尾不同（an 与 ang），意思是煎炸。"}, "sentence_index": null, "correct_answer": "将"}, "level_3": {"options": [{"text": "将", "is_correct": true, "explanation": "正确：将引出被处置的对象“这份文件”，与“交给”组成处置句。"}, {"text": "替", "is_correct": false, "explanation": "语义：替表示代替别人做事，“这份文件”不能被替代去交给王经理，句意不通。"}, {"text": "向", "is_correct": false, "explanation": "搭配：向后接动作的方向或对象，不能直接引出“这份文件”作为被处置的对象。"}, {"text": "用", "is_correct": false, "explanation": "配价：用需要带工具或方式，不能引出被交付的对象，与“交给”不相容。"}], "explanations": {"将": "正确：将引出被处置的对象“这份文件”，与“交给”组成处置句。", "替": "语义：替表示代替别人做事，“这份文件”不能被替代去交给王经理，句意不通。", "向": "搭配：向后接动作的方向或对象，不能直接引出“这份文件”作为被处置的对象。", "用": "配价：用需要带工具或方式，不能引出被交付的对象，与“交给”不相容。"}, "sentence_index": 0, "correct_answer": "将"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他听了这个消息，将信将疑。", "explanation": "这里的“将”表示“一半”（如“将信将疑”），不是“把”或“将要”的用法。"}, {"text": "我们已经将近一年没见面了。", "explanation": "这里的“将”表示“接近、大约”，不是“把”或“将要”的用法。"}, {"text": "既然事情已经这样，我们就将错就错吧。", "explanation": "这里的“将”表示“顺着、就着”（如“将错就错”），不是“把”或“将要”的用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12935, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "将", "is_correct": true, "explanation": "正确答案：将，jiāng（第一声），本句中读作此音。"}, {"text": "讲", "is_correct": false, "explanation": "讲 jiǎng（第三声）与 jiāng（第一声）声调不同，意思是讲话。"}, {"text": "降", "is_correct": false, "explanation": "降 jiàng（第四声）与 jiāng（第一声）声调不同，意思是下降。"}, {"text": "尖", "is_correct": false, "explanation": "尖 jiān 与 jiāng 韵尾不同（an 与 ang），意思是尖锐。"}, {"text": "肩", "is_correct": false, "explanation": "肩 jiān 与 jiāng 韵尾不同（an 与 ang），意思是肩膀。"}], "explanations": {"将": "正确答案：将，jiāng（第一声），本句中读作此音。", "讲": "讲 jiǎng（第三声）与 jiāng（第一声）声调不同，意思是讲话。", "降": "降 jiàng（第四声）与 jiāng（第一声）声调不同，意思是下降。", "尖": "尖 jiān 与 jiāng 韵尾不同（an 与 ang），意思是尖锐。", "肩": "肩 jiān 与 jiāng 韵尾不同（an 与 ang），意思是肩膀。"}, "sentence_index": null, "correct_answer": "将"}, "level_3": {"options": [{"text": "将", "is_correct": true, "explanation": "正确：将引出被搬运的对象“垃圾”，表示处置。"}, {"text": "对", "is_correct": false, "explanation": "搭配：“对”后接的对象不能是被搬运的物品，“我们要对垃圾送到楼下”不成立。"}, {"text": "与", "is_correct": false, "explanation": "配价：“与”引出的是共同进行动作的人，不能引出“垃圾”这样的被搬运物。"}, {"text": "给", "is_correct": false, "explanation": "语义：给表示给予，垃圾不能成为“送”的给予对象，与句意冲突。"}], "explanations": {"将": "正确：将引出被搬运的对象“垃圾”，表示处置。", "对": "搭配：“对”后接的对象不能是被搬运的物品，“我们要对垃圾送到楼下”不成立。", "与": "配价：“与”引出的是共同进行动作的人，不能引出“垃圾”这样的被搬运物。", "给": "语义：给表示给予，垃圾不能成为“送”的给予对象，与句意冲突。"}, "sentence_index": 6, "correct_answer": "将"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们将近十点才到家。", "explanation": "这里的“将”表示“接近”（如“将近”），不是“把”或“将要”的用法。"}, {"text": "他将心比心，理解了朋友的处境。", "explanation": "这里的“将”表示“拿、用”（如“将心比心”），不是“把”或“将要”的用法。"}, {"text": "他在家将养身体，好几个月没出门。", "explanation": "这里的“将”表示“调养”（如“将养”），不是“把”或“将要”的用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12935, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请将这封信寄出了去。", "corrected_sentence": "请将这封信寄出去。", "error_description": "错误：「了」插在了趋向补语「出去」的中间，把补语拆开了。正确：请将这封信寄出去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12935, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把将照片挂到墙上。", "corrected_sentence": "他将照片挂到墙上。", "error_description": "「把」与「将」都是引出处置对象的标记，不能同时使用。应删去「把」，改为「他将照片挂到墙上。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11f4889c-b619-43f4-885a-c7a5a833fda1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
