INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12936, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在化学中，指将复杂分子通过加热等方式分解为简单分子的过程；也泛指分裂或分解。", "primary_collocate": null, "pronunciation": "liè jiě", "ipa": "ljɛ˥˩ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这一过程并非简单的物理破碎，而是一系列复杂的生化反应：微生物分泌特定的水解酶，作用于聚合物的酯键或酰胺键，将其逐步裂解为低聚物、单体乃至二氧化碳、水和生物质。", "target_word": "裂解", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "因此，前沿研究正转向合成生物学路径，设计可编程的工程菌株，使其在特定信号触发下高效表达聚合物裂解酶，实现“精准生物降解”。", "target_word": "裂解", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "石油在高温下裂解成小分子。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加热后，大分子裂解为简单的分子。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种酶能把塑料裂解成小分子。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用高温裂解石油，得到乙烯。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋白质在酶的作用下裂解了。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料裂解后，变成了小分子。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个反应让大分子慢慢裂解。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高温会使这种分子裂解。", "target_word": "裂解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "裂解了", "label": "体标"}, {"form": "裂解过", "label": "体标"}, {"form": "裂解酶", "label": "复合"}, {"form": "热裂解", "label": "复合"}], "register": "科技", "sense_fingerprint": "复杂大分子分解为简单小分子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d87bd1f-744f-4914-a5d1-ee173b9f4aec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12936, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "裂解", "is_correct": true, "explanation": "正确答案：裂解（liè jiě），指复杂大分子断裂为简单分子。"}, {"text": "理解", "is_correct": false, "explanation": "lǐ 与 liè 韵母不同（i 与 ie），声调也不同（第三声与第四声），意思是理解。"}, {"text": "礼节", "is_correct": false, "explanation": "lǐ 与 liè 韵母不同（i 与 ie），声调也不同；jié（第二声）与 jiě（第三声）声调不同，意思是礼节。"}, {"text": "历届", "is_correct": false, "explanation": "lì 与 liè 韵母不同（i 与 ie），jiè（第四声）与 jiě（第三声）声调也不同，意思是历届。"}, {"text": "离解", "is_correct": false, "explanation": "lí 与 liè 韵母不同（i 与 ie），声调也不同（第二声与第四声），意思是化学中的离解。"}], "explanations": {"裂解": "正确答案：裂解（liè jiě），指复杂大分子断裂为简单分子。", "理解": "lǐ 与 liè 韵母不同（i 与 ie），声调也不同（第三声与第四声），意思是理解。", "礼节": "lǐ 与 liè 韵母不同（i 与 ie），声调也不同；jié（第二声）与 jiě（第三声）声调不同，意思是礼节。", "历届": "lì 与 liè 韵母不同（i 与 ie），jiè（第四声）与 jiě（第三声）声调也不同，意思是历届。", "离解": "lí 与 liè 韵母不同（i 与 ie），声调也不同（第二声与第四声），意思是化学中的离解。"}, "sentence_index": null, "correct_answer": "裂解"}, "level_3": {"options": [{"text": "裂解", "is_correct": true, "explanation": "裂解：复杂大分子被分解为简单分子，与“水解酶”“酯键”等语境相符。"}, {"text": "破碎", "is_correct": false, "explanation": "语义：“破碎”指物体因外力碎裂，句中已说明“并非简单的物理破碎”，与语境矛盾。"}, {"text": "合成", "is_correct": false, "explanation": "语义：“合成”指简单物质结合成复杂物质，与句中大分子分解为低聚物、单体等产物的方向相反。"}, {"text": "凝固", "is_correct": false, "explanation": "搭配：“凝固”指液体变为固体，不能与“低聚物、单体、二氧化碳、水”搭配，作为分解的产物。"}], "explanations": {"裂解": "裂解：复杂大分子被分解为简单分子，与“水解酶”“酯键”等语境相符。", "破碎": "语义：“破碎”指物体因外力碎裂，句中已说明“并非简单的物理破碎”，与语境矛盾。", "合成": "语义：“合成”指简单物质结合成复杂物质，与句中大分子分解为低聚物、单体等产物的方向相反。", "凝固": "搭配：“凝固”指液体变为固体，不能与“低聚物、单体、二氧化碳、水”搭配，作为分解的产物。"}, "sentence_index": 0, "correct_answer": "裂解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些单体在催化剂作用下裂解成了一个大分子。", "explanation": "这里应该用〈聚合〉。裂解指复杂分子断裂为简单分子，这里是简单的单体结合成大分子，方向正好相反。"}, {"text": "两种元素裂解成了一种新的化合物。", "explanation": "这里应该用〈结合〉。裂解表示分开，不能说两种元素分开后合成一种新化合物。"}, {"text": "冰块在阳光下裂解成了水。", "explanation": "这里应该用〈融化〉。冰受热只是由固态变为液态，分子并没有断裂，不能用裂解。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12936, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裂解", "is_correct": true, "explanation": "裂解：蛋白质在酶的作用下断裂为小分子，符合句意。"}, {"text": "分泌", "is_correct": false, "explanation": "语义：“分泌”是细胞向外排出物质的生理过程，与句中“在酶的作用下”发生的化学断裂语境不符。"}, {"text": "生长", "is_correct": false, "explanation": "语义：“生长”指生物体的发育，不能描述蛋白质在酶作用下发生的化学变化。"}, {"text": "包装", "is_correct": false, "explanation": "语义：“包装”指用容器或材料把物品包裹起来，与酶的化学作用无关。"}], "explanations": {"裂解": "裂解：蛋白质在酶的作用下断裂为小分子，符合句意。", "分泌": "语义：“分泌”是细胞向外排出物质的生理过程，与句中“在酶的作用下”发生的化学断裂语境不符。", "生长": "语义：“生长”指生物体的发育，不能描述蛋白质在酶作用下发生的化学变化。", "包装": "语义：“包装”指用容器或材料把物品包裹起来，与酶的化学作用无关。"}, "sentence_index": 6, "correct_answer": "裂解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "酒精在常温下会裂解。", "explanation": "这里应该用〈蒸发〉。酒精在常温下变成气体是蒸发，分子并未断裂成更简单的分子，不能用裂解。"}, {"text": "这锅蜡油冷却后会裂解成蜡块。", "explanation": "这里应该用〈凝固〉。蜡油变硬是状态改变，不是大分子断裂为小分子。"}, {"text": "这块干冰在常温下会裂解成气体。", "explanation": "这里应该用〈升华〉。干冰直接由固态变为气态，是状态变化，不是分子断裂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "加热能使大分子裂解小分子。", "corrected_sentence": "加热能使大分子裂解成小分子。", "error_description": "补语缺失：“裂解”后应接结果补语“成”，应说“裂解成小分子”；省去“成”后“裂解小分子”结构不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种酶能让蛋白质裂解过成多肽。", "corrected_sentence": "这种酶能让蛋白质裂解成多肽。", "error_description": "体标错误：动词“裂解”后不能加“过”再接结果补语，应说“裂解成多肽”；“过”表示经历，与此处的结果无关。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12937, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12937, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12937, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由少量单体单元通过化学键连接而成的聚合物，分子量较低。", "primary_collocate": null, "pronunciation": "dī jù wù", "ipa": "ti˥ tɕy˥˩ u˥˩", "syllable_count": 3, "sentences": [{"text": "这一过程并非简单的物理破碎，而是一系列复杂的生化反应：微生物分泌特定的水解酶，作用于聚合物的酯键或酰胺键，将其逐步裂解为低聚物、单体乃至二氧化碳、水和生物质。", "target_word": "低聚物", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "低聚物的分子比普通聚合物小得多。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验中，我们先得到了一些低聚物。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低聚物只由几个单体连成，所以分子量不高。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种低聚物在常温下是一种透明的液体。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聚合反应还没结束时，瓶里主要是低聚物。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，低聚物的熔点比高分子低。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把低聚物加热后，继续聚合成长链。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水解后的产物中，有不少低聚物。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低聚物太小，不能做成坚固的塑料。", "target_word": "低聚物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "专业", "sense_fingerprint": "低聚物|由少量单体连成、分子量较低的聚合物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d87bd1f-744f-4914-a5d1-ee173b9f4aec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12937, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低聚物", "is_correct": true, "explanation": "低聚物：由少量单体连成的聚合物，是裂解产物之一，符合句意。"}, {"text": "聚合物", "is_correct": false, "explanation": "语义：“聚合物”正是句中“作用于聚合物”的反应对象，不能再作裂解的产物。"}, {"text": "合金", "is_correct": false, "explanation": "搭配：“合金”是金属混合材料，不是生化裂解的产物，不能与“单体、二氧化碳、水”并列。"}, {"text": "石油", "is_correct": false, "explanation": "语义：石油是化石燃料，与句中微生物酶作用下的生化产物不符。"}], "explanations": {"低聚物": "低聚物：由少量单体连成的聚合物，是裂解产物之一，符合句意。", "聚合物": "语义：“聚合物”正是句中“作用于聚合物”的反应对象，不能再作裂解的产物。", "合金": "搭配：“合金”是金属混合材料，不是生化裂解的产物，不能与“单体、二氧化碳、水”并列。", "石油": "语义：石油是化石燃料，与句中微生物酶作用下的生化产物不符。"}, "sentence_index": 0, "correct_answer": "低聚物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种低聚物由上千个单体连成，所以分子量很大。", "explanation": "这里应该用〈高分子〉。低聚物只由少量单体连成，分子量不高；由上千个单体连成、分子量很大的应是高分子。"}, {"text": "低聚物的分子量很大，所以不易熔化。", "explanation": "这里应该用〈聚合物〉。聚合物分子量大，所以不易熔化；低聚物分子量低，不能说分子量很大。"}, {"text": "低聚物的链很长，弯曲得很厉害。", "explanation": "这里应该用〈长链分子〉。低聚物只由少量单体连成，链很短；链很长、弯曲明显的是长链分子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12937, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低聚物", "is_correct": true, "explanation": "低聚物：与“比高分子低”的比较相符，句意通顺。"}, {"text": "高分子", "is_correct": false, "explanation": "语义：句中已以“高分子”作比较基准，“高分子的熔点比高分子低”自相矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气是混合气体，没有固定熔点，不能说“空气的熔点”。"}, {"text": "火焰", "is_correct": false, "explanation": "语义：火焰是燃烧时的发光现象，不是物质，没有熔点。"}], "explanations": {"低聚物": "低聚物：与“比高分子低”的比较相符，句意通顺。", "高分子": "语义：句中已以“高分子”作比较基准，“高分子的熔点比高分子低”自相矛盾。", "空气": "搭配：空气是混合气体，没有固定熔点，不能说“空气的熔点”。", "火焰": "语义：火焰是燃烧时的发光现象，不是物质，没有熔点。"}, "sentence_index": 6, "correct_answer": "低聚物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "低聚物是构成聚合物的最小单位。", "explanation": "这里应该用〈单体〉。单体才是构成聚合物的最小单位，低聚物由少量单体连成，本身不是最小单位。"}, {"text": "低聚物是构成塑料的主要材料。", "explanation": "这里应该用〈高聚物〉。塑料的主要材料是分子量很大的高聚物，低聚物分子太小，不能作为主要材料。"}, {"text": "他用低聚物炼出了纯铁。", "explanation": "这里应该用〈矿石〉。炼铁要用矿石；低聚物是少量单体连成的聚合物，不能用来炼铁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12937, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "实验室里常把一只低聚物倒进烧杯里。", "corrected_sentence": "实验室里常把一瓶低聚物倒进烧杯里。", "error_description": "量词错误：“低聚物”是物质名称，应用“瓶”“种”等量词，“只”用于动物或单个器物，不能说“一只低聚物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12937, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人低聚物倒进了空罐子里。", "corrected_sentence": "工人把低聚物倒进了空罐子里。", "error_description": "把字句遗漏：处置式中“低聚物”须由“把”引出，应说“工人把低聚物倒进了空罐子里”；省去“把”后结构不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
