INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12938, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指单独一个物体或个体，与整体或多个相对。", "primary_collocate": null, "pronunciation": "dān tǐ", "ipa": "tan˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这组模型拆开以后，每一个单体都能单独搬运。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架的每个单体都可以单独取下来。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套积木可以拆成一个个单体。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个组合柜可以分开，每个单体都能单独用。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "单体和整体不一样，要分开来看。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套玩具里，每个单体都很小。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里可以买整套，也可以只买单体。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器人由五个单体拼成。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "单体的力量小，合在一起就大了。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把沙发拆成了几个单体。", "target_word": "单体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "單體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "单体|单独的一个物体或个体，与整体相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d87bd1f-744f-4914-a5d1-ee173b9f4aec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12938, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "单体", "is_correct": true, "explanation": "“每一个单体都能单独搬运”指拆开后可以单独移动的单个部件，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是气体，无法拆成一个个可以单独搬运的物件。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“每一个”后接可数的个体，钢铁是材料，不能这样计数。"}, {"text": "石油", "is_correct": false, "explanation": "搭配：石油是液体材料，不能说“每一个石油”，也不能像部件那样单独搬运。"}], "explanations": {"单体": "“每一个单体都能单独搬运”指拆开后可以单独移动的单个部件，符合句意。", "空气": "语义：空气是气体，无法拆成一个个可以单独搬运的物件。", "钢铁": "搭配：“每一个”后接可数的个体，钢铁是材料，不能这样计数。", "石油": "搭配：石油是液体材料，不能说“每一个石油”，也不能像部件那样单独搬运。"}, "sentence_index": 0, "correct_answer": "单体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个足球队是一个单体，大家一起踢球。", "explanation": "这里误把“单体”用于整体。足球队由很多队员组成，是整体，不能说是单体。"}, {"text": "这首歌是一个单体，不能拆成几段。", "explanation": "这里误把“单体”用于整体。“单体”指单独一个物体，整首歌是一个整体，不能说是单体。"}, {"text": "这支乐队是一个单体，成员们都很团结。", "explanation": "这里误把“单体”用于整体。“单体”指单独的一个物体，乐队由多人组成，是整体，不能说是单体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "单体", "is_correct": true, "explanation": "“只买单体”与“买整套”相对，指单独一个物件，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以单独买卖的物件，与“只买”搭配不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能被买下来。"}, {"text": "风", "is_correct": false, "explanation": "搭配：“买”要搭配可以买卖的物品，“风”不能这样搭配。"}], "explanations": {"单体": "“只买单体”与“买整套”相对，指单独一个物件，符合句意。", "空气": "语义：空气不是可以单独买卖的物件，与“只买”搭配不通。", "月亮": "语义：月亮是天体，不能被买下来。", "风": "搭配：“买”要搭配可以买卖的物品，“风”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "单体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班是一个单体，同学们都很熟。", "explanation": "这里误把“单体”用于整体。“单体”指单独一个物体，一个班级是整体，不能说是单体。"}, {"text": "这座森林是一个单体，树木连在一起不能分开。", "explanation": "这里误把“单体”用于整体。森林由许多树木组成，是整体，不能说是单体。"}, {"text": "我们全家是一个单体，每天一起吃饭。", "explanation": "这里误把“单体”用于整体。一家人由几个人组成，是整体，不能说是单体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套家具可以拆成几张单体。", "corrected_sentence": "这套家具可以拆成几个单体。", "error_description": "量词错误：“单体”是独立的物件，应该用“个”，不能用“张”。“张”多用于纸、桌子等平面的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他拆了出三个单体。", "corrected_sentence": "他拆出了三个单体。", "error_description": "补语错误：趋向补语“出”应紧跟动词，说“拆出了”，不能说“拆了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
