INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12939, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "无色、无味、透明的液体，化学式为H₂O，是生命必需的物质。", "primary_collocate": null, "pronunciation": "shuǐ", "ipa": "ʂuei˨˩˦", "syllable_count": 1, "sentences": [{"text": "人每天都要喝水。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水是生命必需的东西。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯水没有颜色，也没有味道。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水在零度会变成冰。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验时，我们往瓶里加了一点水。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水由氢和氧两种元素组成。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一杯水，谢谢。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物没有水就活不下去。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "氢和氧可以变成水。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把水倒进了锅里。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "杯", "label": "量词"}, {"form": "瓶", "label": "量词"}], "register": "中性", "sense_fingerprint": "水|无色无味透明的液体H₂O，生命必需", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d87bd1f-744f-4914-a5d1-ee173b9f4aec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12939, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水", "is_correct": true, "explanation": "shuǐ（第三声）：无色、无味、透明的液体，即“水”。"}, {"text": "谁", "is_correct": false, "explanation": "shuí（第二声）与 shuǐ（第三声）声调不同，意思是“谁”。"}, {"text": "睡", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是“睡”。"}, {"text": "鼠", "is_correct": false, "explanation": "shǔ 与 shuǐ 韵母不同：shǔ 为 u，shuǐ 为 ui，意思是“老鼠”。"}], "explanations": {"水": "shuǐ（第三声）：无色、无味、透明的液体，即“水”。", "谁": "shuí（第二声）与 shuǐ（第三声）声调不同，意思是“谁”。", "睡": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是“睡”。", "鼠": "shǔ 与 shuǐ 韵母不同：shǔ 为 u，shuǐ 为 ui，意思是“老鼠”。"}, "sentence_index": null, "correct_answer": "水"}, "level_3": {"options": [{"text": "水", "is_correct": true, "explanation": "水是液体，可以喝，符合“每天都要喝”的语境。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，“饭”要用“吃”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是气体，不能像饮用液体那样被“喝”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是固体，不能被“喝”。"}], "explanations": {"水": "水是液体，可以喝，符合“每天都要喝”的语境。", "饭": "搭配：“喝”的对象是液体，“饭”要用“吃”。", "空气": "语义：空气是气体，不能像饮用液体那样被“喝”。", "石头": "语义：石头是固体，不能被“喝”。"}, "sentence_index": 0, "correct_answer": "水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "池塘上的水很硬，小心别滑倒。", "explanation": "这里应该用〈冰〉。水是液体，没有硬度，“很硬”和“滑倒”说的是固体的冰。"}, {"text": "冬天到了，他穿上了厚厚的水。", "explanation": "这里应该用〈衣服〉。“穿上”说的是衣服，水是液体，不能穿。"}, {"text": "这杯水很脆，一摔就碎了。", "explanation": "这里应该用〈玻璃〉。水是液体，没有脆性；“一摔就碎”说的是玻璃这类固体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12939, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "水", "is_correct": true, "explanation": "shuǐ（第三声）：无色、无味、透明的液体，即“水”。"}, {"text": "税", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是“税”。"}, {"text": "毁", "is_correct": false, "explanation": "huǐ（第三声）与 shuǐ 声母不同（h 与 sh），意思是“毁坏”。"}, {"text": "耍", "is_correct": false, "explanation": "shuǎ（第三声）与 shuǐ 韵母不同（ua 与 ui），意思是“耍”。"}], "explanations": {"水": "shuǐ（第三声）：无色、无味、透明的液体，即“水”。", "税": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是“税”。", "毁": "huǐ（第三声）与 shuǐ 声母不同（h 与 sh），意思是“毁坏”。", "耍": "shuǎ（第三声）与 shuǐ 韵母不同（ua 与 ui），意思是“耍”。"}, "sentence_index": null, "correct_answer": "水"}, "level_3": {"options": [{"text": "水", "is_correct": true, "explanation": "“一杯水”是常见的说法，水可以用杯子盛着递给别人，符合句意。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不是可以用杯子盛着递过去的东西。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：量词“杯”不用于木头，木头应说“根”或“块”。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：量词“杯”不用于钢笔，钢笔应说“支”。"}], "explanations": {"水": "“一杯水”是常见的说法，水可以用杯子盛着递给别人，符合句意。", "书": "语义：书不是可以用杯子盛着递过去的东西。", "木头": "搭配：量词“杯”不用于木头，木头应说“根”或“块”。", "钢笔": "搭配：量词“杯”不用于钢笔，钢笔应说“支”。"}, "sentence_index": 6, "correct_answer": "水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妈妈在厨房里把水切成了几块。", "explanation": "这里应该用〈豆腐〉。“切成块”说的是固体食物，水是液体，不能切。"}, {"text": "炉子里的水很旺，快添柴吧。", "explanation": "这里应该用〈火〉。“旺”说的是火，水不能说“旺”。"}, {"text": "地里的水很干。", "explanation": "这里应该用〈土〉。“干”说的是土壤，水是液体，不能说“干”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12939, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的杯子里有一只水。", "corrected_sentence": "我的杯子里有一杯水。", "error_description": "量词错误：“水”应该用“杯”或“瓶”计量，“只”多用于动物或小东西，不能用于水。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12939, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把水烧了开。", "corrected_sentence": "他把水烧开了。", "error_description": "补语错误：结果补语“开”应紧跟动词，说“烧开了”，不能说“烧了开”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
