INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12940, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生物质是指来自生物体（如植物、动物及其废弃物）的有机物质，可以作为能源或材料使用。", "primary_collocate": null, "pronunciation": "shēng wù zhì", "ipa": "ʂɤŋ˥ u˥˩ ʈʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "农民把玉米秆当作生物质，用来发电。", "target_word": "生物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头、稻草和落叶都是生物质。", "target_word": "生物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂用生物质代替煤来供暖。", "target_word": "生物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物质燃烧时会放出热量。", "target_word": "生物质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多国家正在研究如何利用生物质。", "target_word": "生物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物的粪便也是一种生物质。", "target_word": "生物质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座电站每天烧掉很多生物质。", "target_word": "生物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用生物质做成了环保的燃料。", "target_word": "生物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和石油相比，生物质更环保。", "target_word": "生物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场里的废弃草料是很好的生物质。", "target_word": "生物质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生物质能", "label": "复合"}, {"form": "生物质燃料", "label": "复合"}], "register": "中性", "sense_fingerprint": "来自动植物及其废弃物的有机物质，可作能源或材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc05871b-dbfb-4323-99f2-f0bf55bd0d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生物质", "is_correct": true, "explanation": "正确：玉米秆是农业废弃物，句中的“生物质”指可作能源的动植物及其废弃物。"}, {"text": "饲料", "is_correct": false, "explanation": "语义：饲料是用来喂养牲畜的，不能当作发电的材料，与“用来发电”冲突。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物是供人或动物吃的，玉米秆不能当食物用来发电，与后半句冲突。"}, {"text": "化肥", "is_correct": false, "explanation": "搭配：“用来发电”要接能源类名词，化肥是肥料，不能用来发电。"}], "explanations": {"生物质": "正确：玉米秆是农业废弃物，句中的“生物质”指可作能源的动植物及其废弃物。", "饲料": "语义：饲料是用来喂养牲畜的，不能当作发电的材料，与“用来发电”冲突。", "食物": "语义：食物是供人或动物吃的，玉米秆不能当食物用来发电，与后半句冲突。", "化肥": "搭配：“用来发电”要接能源类名词，化肥是肥料，不能用来发电。"}, "sentence_index": 0, "correct_answer": "生物质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座公园里种了很多生物质。", "explanation": "这里应该用〈植物〉。种植、观赏的是植物；生物质指可作能源或材料的有机物质，不能拿来种。"}, {"text": "妈妈用生物质包饺子。", "explanation": "这里应该用〈面粉〉。包饺子用面粉，生物质是能源或原料，不能用来包饺子。"}, {"text": "厨师每天往汤里放一勺生物质。", "explanation": "这里应该用〈食盐〉。汤里调味用食盐，生物质是能源或原料，不能当调料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生物质", "is_correct": true, "explanation": "正确：电站烧的是可作燃料的生物质，符合“烧掉”的对象。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥是建筑材料，本身不能燃烧，电站不会烧水泥。"}, {"text": "食盐", "is_correct": false, "explanation": "搭配：“烧掉”不搭配食盐，食盐是调味品，不能拿来烧。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不能燃烧，电站每天烧的不可能是玻璃。"}], "explanations": {"生物质": "正确：电站烧的是可作燃料的生物质，符合“烧掉”的对象。", "水泥": "语义：水泥是建筑材料，本身不能燃烧，电站不会烧水泥。", "食盐": "搭配：“烧掉”不搭配食盐，食盐是调味品，不能拿来烧。", "玻璃": "语义：玻璃不能燃烧，电站每天烧的不可能是玻璃。"}, "sentence_index": 6, "correct_answer": "生物质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人用生物质修路。", "explanation": "这里应该用〈水泥〉。修路要用水泥等建材，生物质是能源或原料，不能拿来修路。"}, {"text": "这辆车的油箱里加满了生物质。", "explanation": "这里应该用〈生物燃料〉。油箱要加燃料，生物质是固体原料，不能直接加进油箱。"}, {"text": "这扇窗户是用生物质做的。", "explanation": "这里应该用〈玻璃〉。窗户要用玻璃，生物质不能用来做窗户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子用生物质了做饭。", "corrected_sentence": "这个村子用生物质做饭。", "error_description": "“了”的位置错误：“了”不能放在“用生物质”和“做饭”之间。这句说的是平常的做法，不需要“了”，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂用生物质过发电。", "corrected_sentence": "这家工厂用生物质发电。", "error_description": "“过”的位置错误：“过”是经历体标记，应紧跟动词，且这里不需要经历体；“过”不能放在宾语“生物质”后面，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12941, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独立于", "is_correct": true, "explanation": "正确：“独立于”与“依赖于”构成反义，表示不以某事为必要条件。"}, {"text": "分享", "is_correct": false, "explanation": "分享：与“依赖于”没有反义关系，说的是共同拥有某物。"}, {"text": "完成", "is_correct": false, "explanation": "完成：与“依赖于”没有反义关系，表示把事情做成。"}, {"text": "储存", "is_correct": false, "explanation": "储存：与“依赖于”没有反义关系，表示把东西保存起来。"}], "correct_answer": "独立于", "explanations": {"独立于": "正确：“独立于”与“依赖于”构成反义，表示不以某事为必要条件。", "分享": "分享：与“依赖于”没有反义关系，说的是共同拥有某物。", "完成": "完成：与“依赖于”没有反义关系，表示把事情做成。", "储存": "储存：与“依赖于”没有反义关系，表示把东西保存起来。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12941, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独立于", "is_correct": true, "explanation": "正确：“独立于”与“依赖于”构成反义，表示不以某事为必要条件。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论：与“依赖于”没有反义关系，表示交流意见。"}, {"text": "提供", "is_correct": false, "explanation": "提供：与“依赖于”没有反义关系，表示供给所需的东西。"}, {"text": "出发", "is_correct": false, "explanation": "出发：与“依赖于”没有反义关系，表示动身前往某地。"}], "correct_answer": "独立于", "explanations": {"独立于": "正确：“独立于”与“依赖于”构成反义，表示不以某事为必要条件。", "讨论": "讨论：与“依赖于”没有反义关系，表示交流意见。", "提供": "提供：与“依赖于”没有反义关系，表示供给所需的东西。", "出发": "出发：与“依赖于”没有反义关系，表示动身前往某地。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12941, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "表示一个事物或情况以另一个事物或情况为必要条件。", "primary_collocate": null, "pronunciation": "yī lài yú", "ipa": "i˥ laɪ˥˩ y˧˥", "syllable_count": 3, "sentences": [{"text": "其效率高度依赖于材料的化学组成、结晶度、玻璃化转变温度以及环境的湿度、温度与微生物群落构成。", "target_word": "依赖于", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "农作物的生长依赖于充足的阳光和水。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的经济依赖于旅游业。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛能不能举行，依赖于明天的天气。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的成长依赖于父母的关爱。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种植物的生存依赖于湿润的环境。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的成功不能只依赖于一个人。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的使用时间依赖于电池的大小。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的好成绩依赖于每天的努力学习。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产量依赖于土地和天气，也依赖于技术。", "target_word": "依赖于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "依赖性", "label": "复合"}, {"form": "相互依赖", "label": "复合"}], "register": "书面", "sense_fingerprint": "某事物或情况以另一事物或情况为必要条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc05871b-dbfb-4323-99f2-f0bf55bd0d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12941, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "依赖于", "is_correct": true, "explanation": "正确：“依赖于”表示效率以材料组成、环境等条件为必要条件，与句中罗列的因素相合。"}, {"text": "漠视", "is_correct": false, "explanation": "语义：效率是事物的性能，不能“漠视”材料的组成；“漠视”要求有意识的主体。"}, {"text": "分为", "is_correct": false, "explanation": "配价：“分为”后接类别，不能直接接“材料的化学组成”这类因素，与句意不合。"}, {"text": "满足于", "is_correct": false, "explanation": "语义：“满足于”需要有感受的主体，效率不能“满足于”材料的组成，与句意相悖。"}], "explanations": {"依赖于": "正确：“依赖于”表示效率以材料组成、环境等条件为必要条件，与句中罗列的因素相合。", "漠视": "语义：效率是事物的性能，不能“漠视”材料的组成；“漠视”要求有意识的主体。", "分为": "配价：“分为”后接类别，不能直接接“材料的化学组成”这类因素，与句意不合。", "满足于": "语义：“满足于”需要有感受的主体，效率不能“满足于”材料的组成，与句意相悖。"}, "sentence_index": 0, "correct_answer": "依赖于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋顶的吊钩依赖于这盏灯。", "explanation": "主客颠倒：吊钩不依赖于灯，不能这样说。"}, {"text": "明天的天气依赖于比赛能不能举行。", "explanation": "主客颠倒：天气不依赖于比赛，应说比赛依赖于天气。"}, {"text": "墙壁依赖于那把椅子的摆放。", "explanation": "主客颠倒：墙不依赖于椅子，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12941, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "依赖于", "is_correct": true, "explanation": "正确：“依赖于”表示成功以一个人或团队为必要条件，与“不能只”搭配。"}, {"text": "忙于", "is_correct": false, "explanation": "搭配：“忙于”接的是事务，不能接“一个人”，与句子的语义不搭。"}, {"text": "陷于", "is_correct": false, "explanation": "语义：“陷于”表示困在不利的境地，成功不会陷于一个人，与句意不合。"}, {"text": "隶属于", "is_correct": false, "explanation": "语义：“隶属于”指归属关系，成功不隶属于一个人，与句意不合。"}], "explanations": {"依赖于": "正确：“依赖于”表示成功以一个人或团队为必要条件，与“不能只”搭配。", "忙于": "搭配：“忙于”接的是事务，不能接“一个人”，与句子的语义不搭。", "陷于": "语义：“陷于”表示困在不利的境地，成功不会陷于一个人，与句意不合。", "隶属于": "语义：“隶属于”指归属关系，成功不隶属于一个人，与句意不合。"}, "sentence_index": 6, "correct_answer": "依赖于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "土地依赖于产量和天气，也依赖于技术。", "explanation": "主客颠倒：土地不依赖于产量，应说产量依赖于土地。"}, {"text": "父母的关爱依赖于孩子的成长。", "explanation": "主客颠倒：应说孩子的成长依赖于父母的关爱。"}, {"text": "山坡依赖于这座老房子才能建造。", "explanation": "主客颠倒：山坡不依赖于房子，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划不依赖于了天气。", "corrected_sentence": "这个计划不依赖于天气。", "error_description": "“了”的位置错误：“了”不能插在介词“于”和宾语“天气”之间，此句陈述必要条件，无需“了”，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动的成功完全依赖于着团队合作。", "corrected_sentence": "这次活动的成功完全依赖于团队合作。", "error_description": "“着”用法错误：“着”不能插在介词“于”和宾语“团队合作”之间。“依赖于”表示必要条件，不加“着”，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
