INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12942, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由部分或个体结合成为整体；作名词时指整体由哪些部分构成。", "primary_collocate": null, "pronunciation": "zǔ chéng", "ipa": "tsu˨˩˦ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "水由氢和氧组成。", "target_word": "组成", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个班由二十个学生组成。", "target_word": "组成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们五个人组成了一支足球队。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气主要由氮气和氧气组成。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的组成很简单，只有两部分。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的小组由三男两女组成。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯果汁的组成是苹果、梨和水。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国由五十六个民族组成。", "target_word": "组成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个乐队由四位年轻人组成。", "target_word": "组成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我这种药的组成。", "target_word": "组成", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "组成部分", "label": "复合"}], "register": "中性", "sense_fingerprint": "整体由哪些部分结合构成；也指构成情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc05871b-dbfb-4323-99f2-f0bf55bd0d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12942, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "组成", "is_correct": true, "explanation": "组成：由部分结合成整体，正是这里要的词。"}, {"text": "主城", "is_correct": false, "explanation": "“主城”与“组成”只有声母不同（翘舌与平舌），意思是城市的中心城区。"}, {"text": "做成", "is_correct": false, "explanation": "“做成”与“组成”韵母不同，意思是做出来、办成某事。"}, {"text": "作成", "is_correct": false, "explanation": "“作成”(zuòchéng)与“组成”(zǔchéng)只有第一个字的声调和韵母略有不同，意思是做成、写成。"}], "explanations": {"组成": "组成：由部分结合成整体，正是这里要的词。", "主城": "“主城”与“组成”只有声母不同（翘舌与平舌），意思是城市的中心城区。", "做成": "“做成”与“组成”韵母不同，意思是做出来、办成某事。", "作成": "“作成”(zuòchéng)与“组成”(zǔchéng)只有第一个字的声调和韵母略有不同，意思是做成、写成。"}, "sentence_index": null, "correct_answer": "组成"}, "level_3": {"options": [{"text": "组成", "is_correct": true, "explanation": "组成：与“由……”搭配，表示整体由哪些部分构成，符合句意。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”指数量变多，“水由氢和氧增加”说不通。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”用于水平、质量，不能用来说明物质的构成。"}, {"text": "分解", "is_correct": false, "explanation": "语义：“分解”指把整体拆成部分，与“由氢和氧……”的方向相反。"}], "explanations": {"组成": "组成：与“由……”搭配，表示整体由哪些部分构成，符合句意。", "增加": "语义：“增加”指数量变多，“水由氢和氧增加”说不通。", "提高": "搭配：“提高”用于水平、质量，不能用来说明物质的构成。", "分解": "语义：“分解”指把整体拆成部分，与“由氢和氧……”的方向相反。"}, "sentence_index": 0, "correct_answer": "组成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两种意见组成了共识。", "explanation": "这里应该用〈达成〉。“组成”指把部分拼成整体，“共识”是达成的结果，要说“达成共识”。"}, {"text": "我的努力组成了很好的成绩。", "explanation": "这里应该用〈取得〉。“组成”指把部分拼合成实体，成绩是结果，要说“取得成绩”。"}, {"text": "水组成氢和氧。", "explanation": "这里应该说“氢和氧组成水”，或用〈含有〉。“组成”是部分结合成整体，主语应是“氢和氧”，“水组成氢和氧”把关系说反了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12942, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "组成", "is_correct": true, "explanation": "组成：由部分结合成整体，正是这里要的词。"}, {"text": "赌城", "is_correct": false, "explanation": "“赌城”与“组成”声母不同，意思是以赌博闻名的城市（拉斯维加斯的别称）。"}, {"text": "府城", "is_correct": false, "explanation": "“府城”与“组成”声母不同，意思是旧时府一级行政机构所在的城市。"}, {"text": "煮成", "is_correct": false, "explanation": "“煮成”与“组成”声母不同（翘舌与平舌），意思是煮出来成为某种食物。"}], "explanations": {"组成": "组成：由部分结合成整体，正是这里要的词。", "赌城": "“赌城”与“组成”声母不同，意思是以赌博闻名的城市（拉斯维加斯的别称）。", "府城": "“府城”与“组成”声母不同，意思是旧时府一级行政机构所在的城市。", "煮成": "“煮成”与“组成”声母不同（翘舌与平舌），意思是煮出来成为某种食物。"}, "sentence_index": null, "correct_answer": "组成"}, "level_3": {"options": [{"text": "组成", "is_correct": true, "explanation": "组成：指果汁的构成成分，名词用法，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，与“苹果、梨和水”的列举不符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能用来列举果汁的原料。"}, {"text": "颜值", "is_correct": false, "explanation": "语域：“颜值”是口语网络词，与说明式的构成描述不搭。"}], "explanations": {"组成": "组成：指果汁的构成成分，名词用法，符合句意。", "颜色": "语义：“颜色”指色彩，与“苹果、梨和水”的列举不符。", "价格": "语义：“价格”指钱数，不能用来列举果汁的原料。", "颜值": "语域：“颜值”是口语网络词，与说明式的构成描述不搭。"}, "sentence_index": 6, "correct_answer": "组成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们组成了深厚的友谊。", "explanation": "这里应该用〈建立〉。“组成”指把部分拼成整体，友谊并非由部分拼成，要说“建立友谊”。"}, {"text": "这件事组成了他的善良。", "explanation": "这里应该用〈体现〉。“组成”不能表示表现出某种品质。"}, {"text": "这种药组成了止痛的作用。", "explanation": "这里应该用〈具有〉。“组成”说的是构成的部分，不能说药“组成”某种作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个学校三个部门组成。", "corrected_sentence": "这个学校由三个部门组成。", "error_description": "“组成”引出构成部分时前面要加“由”，正确说法是“由三个部门组成”；漏掉“由”，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑很多零件组成。", "corrected_sentence": "这台电脑由很多零件组成。", "error_description": "“组成”引出构成部分时要用“由”，正确说法是“由很多零件组成”。省略“由”后句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
