INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12943, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "物质中晶体所占的比例或程度，反映结晶的完善程度。", "primary_collocate": null, "pronunciation": "jié jīng dù", "ipa": "tɕjɛ˧˥ tɕiŋ˥ tu˥˩", "syllable_count": 3, "sentences": [{"text": "其效率高度依赖于材料的化学组成、结晶度、玻璃化转变温度以及环境的湿度、温度与微生物群落构成。", "target_word": "结晶度", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种塑料的结晶度越高，就越硬。", "target_word": "结晶度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冷却得慢，材料的结晶度会变高。", "target_word": "结晶度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室用仪器测出了样品的结晶度。", "target_word": "结晶度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结晶度低的塑料比较软，也比较透明。", "target_word": "结晶度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，结晶度是指晶体所占的比例。", "target_word": "结晶度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加热以后，这块材料的结晶度下降了。", "target_word": "结晶度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两种样品的结晶度差得很多。", "target_word": "结晶度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想提高结晶度，可以慢慢冷却材料。", "target_word": "结晶度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结晶度高的瓶子，不容易变形。", "target_word": "结晶度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "結晶度", "label": "繁体"}, {"form": "相对结晶度", "label": "复合"}], "register": "书面", "sense_fingerprint": "物质中晶体所占比例，材料科学术语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc05871b-dbfb-4323-99f2-f0bf55bd0d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12943, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结晶度", "is_correct": true, "explanation": "结晶度：指物质中晶体所占的比例，符合句意。"}, {"text": "国籍", "is_correct": false, "explanation": "语义：“国籍”指所属国家，与材料的化学组成、温度等性质并列不相干。"}, {"text": "颜值", "is_correct": false, "explanation": "语域：“颜值”是口语网络词，与科技文章中的术语语域不符。"}, {"text": "口味", "is_correct": false, "explanation": "语义：“口味”指味道偏好，用来描述材料的性质说不通。"}], "explanations": {"结晶度": "结晶度：指物质中晶体所占的比例，符合句意。", "国籍": "语义：“国籍”指所属国家，与材料的化学组成、温度等性质并列不相干。", "颜值": "语域：“颜值”是口语网络词，与科技文章中的术语语域不符。", "口味": "语义：“口味”指味道偏好，用来描述材料的性质说不通。"}, "sentence_index": 0, "correct_answer": "结晶度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "实验室用仪器测出了这杯糖水的结晶度。", "explanation": "这里应该用〈浓度〉。溶液中溶质的多少用浓度，结晶度只描述固体中晶体所占的比例。"}, {"text": "这套设备的结晶度很高。", "explanation": "这里应该用〈功率〉。结晶度说的是物质中晶体所占的比例，设备的强弱不能用它来表示。"}, {"text": "这道菜的结晶度太咸了。", "explanation": "这里应该用〈味道〉。结晶度只说明晶体所占的比例，不能说咸不咸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12943, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结晶度", "is_correct": true, "explanation": "结晶度：指晶体所占的比例，在“下降”的语境中符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指存在的时长，材料的性质不能说“年龄下降”。"}, {"text": "人气", "is_correct": false, "explanation": "语域：“人气”多指人或商品受欢迎的程度，用于材料的科学描述不合适。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高矮，用于材料说不通。"}], "explanations": {"结晶度": "结晶度：指晶体所占的比例，在“下降”的语境中符合句意。", "年龄": "语义：“年龄”指存在的时长，材料的性质不能说“年龄下降”。", "人气": "语域：“人气”多指人或商品受欢迎的程度，用于材料的科学描述不合适。", "身高": "语义：“身高”指人的高矮，用于材料说不通。"}, "sentence_index": 6, "correct_answer": "结晶度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种布的结晶度很便宜。", "explanation": "这里应该用〈价格〉。结晶度只说明晶体所占的比例，“便宜”修饰的应是价格，不能用来形容结晶度。"}, {"text": "这位老师的结晶度很高。", "explanation": "这里应该用〈水平〉。结晶度只说明物质中晶体所占的比例，不能用来评价人。"}, {"text": "这种糖浆的结晶度很高，很好喝。", "explanation": "这里应该用〈口味〉。结晶度只说明晶体所占的比例，不能用来评价好不好喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种纤维的结晶度的较低，弹性较好。", "corrected_sentence": "这种纤维的结晶度较低，弹性较好。", "error_description": "多了一个“的”：“结晶度”是主语，后面直接接谓语“较低”，不能在“结晶度”和“较低”之间加“的”，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两种材料的结晶度得差很远。", "corrected_sentence": "两种材料的结晶度差得很远。", "error_description": "补语“得”应放在“差”之后，说“差得很远”。把“得”放在“差”前面，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
