INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12944, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物质从液态或橡胶态转变为非晶态固体，具有玻璃的硬度和透明性。", "primary_collocate": null, "pronunciation": "bō lí huà", "ipa": "pwo˥ li˧˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "其效率高度依赖于材料的化学组成、结晶度，以及材料冷却后能否形成非晶态固体，即能否发生玻璃化。", "target_word": "玻璃化", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "玻璃化会让材料变得又硬又脆。", "target_word": "玻璃化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "温度降得太快，就会出现玻璃化。", "target_word": "玻璃化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玻璃化是物质变成非晶态固体的过程。", "target_word": "玻璃化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种塑料在低温下会发生玻璃化。", "target_word": "玻璃化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玻璃化以后，材料不再有弹性。", "target_word": "玻璃化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验结果表明，玻璃化出现得很早。", "target_word": "玻璃化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水分太少，会影响玻璃化的速度。", "target_word": "玻璃化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玻璃化让这块软胶变得像玻璃一样硬。", "target_word": "玻璃化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者正在观察样品的玻璃化。", "target_word": "玻璃化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "玻璃化转变", "label": "复合"}], "register": "书面", "sense_fingerprint": "物质转变为非晶态固体的过程，材料科学术语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc05871b-dbfb-4323-99f2-f0bf55bd0d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12944, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玻璃化", "is_correct": true, "explanation": "正确。“形成非晶态固体”即“玻璃化”的含义，与前文的化学组成、结晶度并列。"}, {"text": "液化", "is_correct": false, "explanation": "语义：液化指气体变为液体，与冷却后形成非晶态固体的过程不符。"}, {"text": "氧化", "is_correct": false, "explanation": "语义：氧化是物质与氧发生的化学反应，与形成非晶态固体无关。"}, {"text": "老化", "is_correct": false, "explanation": "搭配：“老化”多指材料随时间推移性能变差，不指形成非晶态固体的过程。"}], "explanations": {"玻璃化": "正确。“形成非晶态固体”即“玻璃化”的含义，与前文的化学组成、结晶度并列。", "液化": "语义：液化指气体变为液体，与冷却后形成非晶态固体的过程不符。", "氧化": "语义：氧化是物质与氧发生的化学反应，与形成非晶态固体无关。", "老化": "搭配：“老化”多指材料随时间推移性能变差，不指形成非晶态固体的过程。"}, "sentence_index": 0, "correct_answer": "玻璃化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "硅熔体慢慢冷却时会玻璃化，形成规则排列的晶体。", "explanation": "这里应该用〈结晶〉。玻璃化指物质变成没有规则结构的非晶态，形成规则排列的晶体要用结晶。"}, {"text": "水蒸气遇冷会玻璃化成水珠。", "explanation": "这里应该用〈凝结〉。水蒸气遇冷变成水珠是凝结；玻璃化指物质变成非晶态固体，与此不符。"}, {"text": "熔化的食盐冷却后会玻璃化。", "explanation": "这里应该用〈凝固〉。熔化的食盐冷却后变成固体要用凝固；玻璃化指物质变成非晶态固体、具有玻璃的硬度和透明性，食盐冷却后形成的是晶体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玻璃化", "is_correct": true, "explanation": "正确。“玻璃化”指物质转变为非晶态固体的过程，句中说它在实验中出现得很早。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，不是材料的变化过程，与“实验结果”所说的材料转变不符。"}, {"text": "月食", "is_correct": false, "explanation": "语义：月食是天文现象，与材料实验的结果无关，句子读起来不通。"}, {"text": "彩虹", "is_correct": false, "explanation": "搭配：“实验结果表明”后接的是研究对象的变化，“彩虹”不是实验对象，不能与此搭配。"}], "explanations": {"玻璃化": "正确。“玻璃化”指物质转变为非晶态固体的过程，句中说它在实验中出现得很早。", "地震": "语义：地震是自然灾害，不是材料的变化过程，与“实验结果”所说的材料转变不符。", "月食": "语义：月食是天文现象，与材料实验的结果无关，句子读起来不通。", "彩虹": "搭配：“实验结果表明”后接的是研究对象的变化，“彩虹”不是实验对象，不能与此搭配。"}, "sentence_index": 6, "correct_answer": "玻璃化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜里，空气中的水汽玻璃化成露水。", "explanation": "这里应该用〈凝结〉。水汽变成露水是凝结；玻璃化指物质变成非晶态固体，与此不符。"}, {"text": "冰块在阳光下玻璃化成水。", "explanation": "这里应该用〈融化〉。冰受热变成水是融化，玻璃化指物质变成非晶态固体，不指液化或融化。"}, {"text": "湖水在夏天玻璃化。", "explanation": "这里应该用〈蒸发〉。湖水在夏天变成水汽离开水面是蒸发；玻璃化指物质变成非晶态固体，与此不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种熔体冷却时玻璃化的很快。", "corrected_sentence": "这种熔体冷却时玻璃化得很快。", "error_description": "补语标记错误：表示程度的补语应用“得”，写成“玻璃化得很快”；“的”不能引出补语，“玻璃化的很快”不合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者很快这种材料玻璃化了。", "corrected_sentence": "研究者很快使这种材料玻璃化了。", "error_description": "缺少致使动词“使”：“玻璃化”表示材料自身发生的变化，要表示“使这种材料发生变化”须用“使…玻璃化”；句中“研究者很快”之后直接接名词，缺少“使”，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
