INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12945, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从一种形式、状态或特点变为另一种。", "primary_collocate": null, "pronunciation": "zhuǎn biàn", "ipa": "tʂwan˨˩˦ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这片沙漠慢慢转变成了绿洲。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气从下雨转变成了晴天。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水在零度以下会转变为冰。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座小城慢慢转变成了大城市。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块湿地的形态已经转变了很多。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过几年努力，农村的面貌转变了很多。", "target_word": "转变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，天气开始转变。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂正在转变成一家科技公司。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "由于下雨，比赛的形式转变了。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毛毛虫会转变成美丽的蝴蝶。", "target_word": "转变", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "转变了", "label": "完成体"}, {"form": "转变过", "label": "经历体"}, {"form": "转变着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "事物的形式、状态或特点由一种变成另一种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18b3f918-5c54-4472-be9f-e910ce51db7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12945, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转变", "is_correct": true, "explanation": "「转变」指事物由一种状态变成另一种，沙漠变成绿洲正是这种变化。"}, {"text": "转动", "is_correct": false, "explanation": "语义：「转动」指物体围绕轴旋转，不能表示沙漠变成绿洲。"}, {"text": "转播", "is_correct": false, "explanation": "语义：「转播」指转送广播或电视信号，与沙漠的变化无关。"}, {"text": "转向", "is_correct": false, "explanation": "语义：「转向」指改变方向，不能说「转向成了绿洲」。"}], "explanations": {"转变": "「转变」指事物由一种状态变成另一种，沙漠变成绿洲正是这种变化。", "转动": "语义：「转动」指物体围绕轴旋转，不能表示沙漠变成绿洲。", "转播": "语义：「转播」指转送广播或电视信号，与沙漠的变化无关。", "转向": "语义：「转向」指改变方向，不能说「转向成了绿洲」。"}, "sentence_index": 0, "correct_answer": "转变"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "司机转变了车速。", "explanation": "这里应该用〈改变〉。转变强调事物由一种形式、状态变成另一种，车速只是快慢的调整，用改变。"}, {"text": "请把电视转变到新闻频道。", "explanation": "这里应该用〈转换〉。转变指事物性质或状态的根本变化，切换频道是操作，应用转换。"}, {"text": "他转变了音量，房间安静了许多。", "explanation": "这里应该用〈调节〉。转变指事物由一种形式或状态变为另一种；音量只是高低的增减，应用调节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12945, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转变", "is_correct": true, "explanation": "天气由一种状态转为另一种状态，与「春天来了，天气开始」的语境相符。"}, {"text": "转身", "is_correct": false, "explanation": "搭配：「转身」是人身体的动作，不能说「天气转身」。"}, {"text": "转弯", "is_correct": false, "explanation": "语义：「转弯」指改变行进方向，天气不会转弯。"}, {"text": "转手", "is_correct": false, "explanation": "语义：「转手」指把东西卖给别人，与天气无关。"}], "explanations": {"转变": "天气由一种状态转为另一种状态，与「春天来了，天气开始」的语境相符。", "转身": "搭配：「转身」是人身体的动作，不能说「天气转身」。", "转弯": "语义：「转弯」指改变行进方向，天气不会转弯。", "转手": "语义：「转手」指把东西卖给别人，与天气无关。"}, "sentence_index": 6, "correct_answer": "转变"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月我的体重转变了三公斤。", "explanation": "这里应该用〈增加〉。转变说事物性质或形式的根本变化，体重的数量增减要用增加。"}, {"text": "这学期我的数学成绩转变了十分。", "explanation": "这里应该用〈提高〉。转变指性质或形式的变化，成绩分数的上升是数量变化，应用提高。"}, {"text": "他把书转变到了桌子上。", "explanation": "这里应该用〈放〉。转变指事物性质或形式的根本变化，把书搬到桌上是位置移动，应说放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12945, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子转变在现代化的小镇。", "corrected_sentence": "这个村子转变成了现代化的小镇。", "error_description": "「转变」带结果时要用「成」或「为」引出结果，这里误用「在」，应改为「成」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12945, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子的性格转变地很快。", "corrected_sentence": "孩子的性格转变得很快。", "error_description": "「转变」后的情态补语要用「得」，这里误用「地」，应改为「得」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12946, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12946, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12946, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "湿度指空气中水蒸气的含量，通常用百分比表示。", "primary_collocate": null, "pronunciation": "shī dù", "ipa": "ʂʅ˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "气象台预报说，受冷空气影响，明天的湿度将降到百分之三十以下，干燥天气要注意防火。", "target_word": "湿度", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "大棚内的湿度长期偏高时，霉菌和病害容易滋生，需要结合通风与加温加以调控。", "target_word": "湿度", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "其效率高度依赖于材料的化学组成、结晶度、玻璃化转变温度以及环境的湿度、温度与微生物群落构成。", "target_word": "湿度", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今天湿度很高，衣服不容易干。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天南方的湿度比北方大。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿度太低时，皮肤会觉得干。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小仪器可以测空气的湿度。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿度达到百分之八十，快要下雨了。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里的湿度太大，墙上长了霉。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用加湿器可以提高房间的湿度。", "target_word": "湿度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相对湿度", "label": "复合"}, {"form": "空气湿度", "label": "复合"}, {"form": "湿度计", "label": "复合"}, {"form": "濕度", "label": "繁体"}], "register": "中性", "sense_fingerprint": "空气中水蒸气含量的高低，用百分比表示", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfd7af12-1a73-462f-9399-277b88dbbcd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12946, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "湿度", "is_correct": true, "explanation": "正确答案：湿度（shī dù），指空气中水蒸气的含量。"}, {"text": "十度", "is_correct": false, "explanation": "shí dù（第二声）与 shī dù（第一声）声调不同，意思是十度。"}, {"text": "适度", "is_correct": false, "explanation": "shì dù（第四声）与 shī dù（第一声）声调不同，意思是适度。"}, {"text": "试读", "is_correct": false, "explanation": "shì dú（第四、第二声）与 shī dù（第一、第四声）声调不同，意思是试读。"}], "explanations": {"湿度": "正确答案：湿度（shī dù），指空气中水蒸气的含量。", "十度": "shí dù（第二声）与 shī dù（第一声）声调不同，意思是十度。", "适度": "shì dù（第四声）与 shī dù（第一声）声调不同，意思是适度。", "试读": "shì dú（第四、第二声）与 shī dù（第一、第四声）声调不同，意思是试读。"}, "sentence_index": null, "correct_answer": "湿度"}, "level_3": {"options": [{"text": "湿度", "is_correct": true, "explanation": "湿度：指空气中水蒸气的含量，预报中常用百分比表示，句意相符。"}, {"text": "湿气", "is_correct": false, "explanation": "语义：湿气指潮气，是笼统说法，不说“降到百分之三十”这类具体数值。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：亮度指光线明暗，与空气干燥、预报百分比的句意不符。"}, {"text": "湿地", "is_correct": false, "explanation": "语义：湿地指地表长期积水的地域，与空气中的水蒸气含量无关。"}], "explanations": {"湿度": "湿度：指空气中水蒸气的含量，预报中常用百分比表示，句意相符。", "湿气": "语义：湿气指潮气，是笼统说法，不说“降到百分之三十”这类具体数值。", "亮度": "语义：亮度指光线明暗，与空气干燥、预报百分比的句意不符。", "湿地": "语义：湿地指地表长期积水的地域，与空气中的水蒸气含量无关。"}, "sentence_index": 0, "correct_answer": "湿度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子湿度很重，墙上长了霉。", "explanation": "这里应该用〈湿气〉。“湿气重”说屋里的潮气；湿度是测得的数值，应说“高”或“大”，不说“重”。"}, {"text": "夏天的湿度很多，衣服总是潮的。", "explanation": "这里应该用〈水汽〉。“水汽多”指空气中水蒸气的量；湿度说的是含量高低，应说“高”，不说“多”。"}, {"text": "这块木头的湿度太高，不能拿来烧。", "explanation": "这里应该用〈含水量〉。湿度指空气中水蒸气的含量，木头里的水分要说含水量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湿度", "is_correct": true, "explanation": "湿度：指空气中水蒸气的含量，仪器可以测量它，句意相符。"}, {"text": "硬度", "is_correct": false, "explanation": "搭配：硬度是固体材料的属性，“测空气的硬度”搭配不当。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：空气本身没有可见的颜色，句意不合。"}, {"text": "形状", "is_correct": false, "explanation": "语义：空气没有固定形状，无从测起，句意不合。"}], "explanations": {"湿度": "湿度：指空气中水蒸气的含量，仪器可以测量它，句意相符。", "硬度": "搭配：硬度是固体材料的属性，“测空气的硬度”搭配不当。", "颜色": "语义：空气本身没有可见的颜色，句意不合。", "形状": "语义：空气没有固定形状，无从测起，句意不合。"}, "sentence_index": 6, "correct_answer": "湿度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的湿度是二十五摄氏度，很暖和。", "explanation": "这里应该用〈温度〉。摄氏度是冷热的单位；湿度说空气中水蒸气含量，用百分比表示。"}, {"text": "这杯水的湿度太高，小心烫嘴。", "explanation": "这里应该用〈温度〉。烫不烫说的是温度；湿度指空气中水蒸气的含量。"}, {"text": "这片湿度里住着很多水鸟。", "explanation": "这里应该用〈湿地〉。湿地是长期积水的地方；湿度是一个数值，不能住鸟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间的一只湿度是百分之六十。", "corrected_sentence": "这个房间的湿度是百分之六十。", "error_description": "量词错误：“湿度”是抽象数值，不能用“只”（只用于动物或成对物件中的一个）来修饰；正确说法是“这个房间的湿度是百分之六十”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏天的湿度很湿，出门一身汗。", "corrected_sentence": "夏天的湿度很高，出门一身汗。", "error_description": "词性误用：“湿”是形容词，“湿度”是表示数值的名词，不能说“湿度很湿”；应说“湿度很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
