INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12947, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "聚乳酸是一种由乳酸分子聚合而成的高分子材料，通常从玉米、木薯等可再生植物资源中提取，具有生物可降解性，常用于制造环保塑料制品。", "primary_collocate": null, "pronunciation": "jù rǔ suān", "ipa": "tɕy˥˩ ɻu˨˩˧ swan˥", "syllable_count": 3, "sentences": [{"text": "当前主流的可降解聚合物，如聚乳酸（PLA）、聚羟基脂肪酸酯（PHA）和聚己二酸/对苯二甲酸丁二酯（PBAT），均是通过精密的分子工程实现性能与降解性的平衡。", "target_word": "聚乳酸", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "聚乳酸是用玉米做成的材料。", "target_word": "聚乳酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "聚乳酸可以被微生物慢慢分解。", "target_word": "聚乳酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂用聚乳酸生产餐具。", "target_word": "聚乳酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "聚乳酸的原料来自可再生的植物。", "target_word": "聚乳酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "与普通塑料相比，聚乳酸更环保。", "target_word": "聚乳酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "聚乳酸在堆肥条件下会降解。", "target_word": "聚乳酸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究人员提高了聚乳酸的耐热性。", "target_word": "聚乳酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用聚乳酸做的吸管，遇热水会变软。", "target_word": "聚乳酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聚乳酸经过加工，可以制成薄膜。", "target_word": "聚乳酸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聚乳酸材料", "label": "复合"}, {"form": "聚乳酸塑料", "label": "复合"}], "register": "书面", "sense_fingerprint": "由乳酸聚合的可降解高分子材料，科技术语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc05871b-dbfb-4323-99f2-f0bf55bd0d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12947, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聚乳酸", "is_correct": true, "explanation": "正确。句中列举的是可降解聚合物，“聚乳酸（PLA）”是其中之一。"}, {"text": "聚乙烯", "is_correct": false, "explanation": "语义：聚乙烯不可降解，其缩写也不是PLA，不能列入可降解聚合物的例子。"}, {"text": "聚氯乙烯", "is_correct": false, "explanation": "语义：聚氯乙烯同样不可降解，与句中“可降解聚合物”的列举不符。"}, {"text": "乳酸", "is_correct": false, "explanation": "搭配：“如…（PLA）”列举的是聚合物名称，“乳酸”是单体，不能与其他聚合物并列。"}], "explanations": {"聚乳酸": "正确。句中列举的是可降解聚合物，“聚乳酸（PLA）”是其中之一。", "聚乙烯": "语义：聚乙烯不可降解，其缩写也不是PLA，不能列入可降解聚合物的例子。", "聚氯乙烯": "语义：聚氯乙烯同样不可降解，与句中“可降解聚合物”的列举不符。", "乳酸": "搭配：“如…（PLA）”列举的是聚合物名称，“乳酸”是单体，不能与其他聚合物并列。"}, "sentence_index": 0, "correct_answer": "聚乳酸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "聚乳酸可以用来勾芡，让汤汁变稠。", "explanation": "这里应该用〈淀粉〉。勾芡要用淀粉，让汤汁变稠；聚乳酸是高分子塑料材料，不能用来勾芡。"}, {"text": "聚乳酸是一种橡胶，常用来做轮胎。", "explanation": "这里应该用〈橡胶〉。橡胶富有弹性，常用来做轮胎；聚乳酸是高分子塑料材料，不是橡胶。"}, {"text": "聚乳酸是牛奶中的一种糖。", "explanation": "这里应该用〈乳糖〉。乳糖是牛奶中的一种糖；聚乳酸是高分子材料，不是糖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12947, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聚乳酸", "is_correct": true, "explanation": "正确。“聚乳酸”是可降解材料，句中说它在堆肥条件下会降解。"}, {"text": "聚苯乙烯", "is_correct": false, "explanation": "语义：聚苯乙烯不可降解，与句中“在堆肥条件下会降解”的说法不符。"}, {"text": "聚丙烯", "is_correct": false, "explanation": "语义：聚丙烯在堆肥条件下几乎不降解，句子读起来不通。"}, {"text": "水泥", "is_correct": false, "explanation": "搭配：“降解”多指有机物或可降解材料，“水泥”是无机材料，不与此搭配。"}], "explanations": {"聚乳酸": "正确。“聚乳酸”是可降解材料，句中说它在堆肥条件下会降解。", "聚苯乙烯": "语义：聚苯乙烯不可降解，与句中“在堆肥条件下会降解”的说法不符。", "聚丙烯": "语义：聚丙烯在堆肥条件下几乎不降解，句子读起来不通。", "水泥": "搭配：“降解”多指有机物或可降解材料，“水泥”是无机材料，不与此搭配。"}, "sentence_index": 6, "correct_answer": "聚乳酸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车需要加聚乳酸才能跑。", "explanation": "这里应该用〈汽油〉。汽车要加汽油才能跑；聚乳酸是高分子塑料材料，不能当燃料。"}, {"text": "医生用聚乳酸给伤口消毒。", "explanation": "这里应该用〈酒精〉。给伤口消毒用酒精；聚乳酸是高分子塑料材料，不能用来消毒。"}, {"text": "聚乳酸是用石油做的，价格很低。", "explanation": "这里应该用〈聚乙烯〉。聚乙烯是用石油做的塑料，价格低；聚乳酸是用玉米等植物原料制成的，不是石油产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究人员了用聚乳酸做实验样品。", "corrected_sentence": "研究人员用了聚乳酸做实验样品。", "error_description": "“了”的位置错误：动态助词“了”应放在动词“用”之后，写成“用了聚乳酸”；“了用”不合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种薄膜被聚乳酸制成。", "corrected_sentence": "这种薄膜用聚乳酸制成。", "error_description": "介词错误：说明制作材料时应用“用”，“被”表示被动，不能引入制作材料；应写作“用聚乳酸制成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '587b0649-6db5-45d5-835c-b6af418c7077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
