INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12948, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "会合、集中，把分散的合在一起。", "primary_collocate": null, "pronunciation": "jù", "ipa": "tɕy˥˩", "syllable_count": 1, "sentences": [{"text": "这些零散的资料最后被聚在一起，整理成了一本书。", "target_word": "聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览结束后，艺术家们又聚在一起合影留念。", "target_word": "聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我们一家人聚在一起吃饭。", "target_word": "聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好久不见，今晚大家聚一聚吧。", "target_word": "聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年的时候，亲戚都聚到奶奶家。", "target_word": "聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们聚在操场上看比赛。", "target_word": "聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们每个月聚一次。", "target_word": "聚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下课后，学生们聚在门口说话。", "target_word": "聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们聚着看街头表演。", "target_word": "聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友好不容易聚了一回。", "target_word": "聚", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "聚了", "label": "完成体"}, {"form": "聚着", "label": "持续体"}, {"form": "聚过", "label": "经历体"}, {"form": "聚一聚", "label": "重叠"}, {"form": "聚会", "label": "复合"}, {"form": "聚集", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或事物从分散处会合到一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18b3f918-5c54-4472-be9f-e910ce51db7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12948, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "聚", "is_correct": true, "explanation": "「聚 jù」意思是会合、集中。"}, {"text": "去", "is_correct": false, "explanation": "「qù」与「jù」声母不同（q/j），意思是前往。"}, {"text": "举", "is_correct": false, "explanation": "「jǔ」（第三声）与「jù」（第四声）声调不同，意思是抬起。"}, {"text": "居", "is_correct": false, "explanation": "「jū」（第一声）与「jù」（第四声）声调不同，意思是居住。"}], "explanations": {"聚": "「聚 jù」意思是会合、集中。", "去": "「qù」与「jù」声母不同（q/j），意思是前往。", "举": "「jǔ」（第三声）与「jù」（第四声）声调不同，意思是抬起。", "居": "「jū」（第一声）与「jù」（第四声）声调不同，意思是居住。"}, "sentence_index": null, "correct_answer": "聚"}, "level_3": {"options": [{"text": "聚", "is_correct": true, "explanation": "「聚」表示把分散的东西合到一起，与「零散的资料……在一起」相符。"}, {"text": "散", "is_correct": false, "explanation": "语义：「散」表示分开，与「被……在一起」的合并义相反。"}, {"text": "解", "is_correct": false, "explanation": "搭配：「解」指分开或解开，不能表示把资料合并在一起。"}, {"text": "离", "is_correct": false, "explanation": "语义：「离」表示分离，与「在一起」的合并义相反。"}], "explanations": {"聚": "「聚」表示把分散的东西合到一起，与「零散的资料……在一起」相符。", "散": "语义：「散」表示分开，与「被……在一起」的合并义相反。", "解": "搭配：「解」指分开或解开，不能表示把资料合并在一起。", "离": "语义：「离」表示分离，与「在一起」的合并义相反。"}, "sentence_index": 0, "correct_answer": "聚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人聚在教室里看书。", "explanation": "这里应该用〈待〉。聚指多人从各处会合到一起，一个人独自待着应说待。"}, {"text": "小猫独自聚在床底下。", "explanation": "这里应该用〈躲〉。聚指多个人或事物会合到一起，小猫独自藏起来应说躲。"}, {"text": "我们两家聚得很远。", "explanation": "这里应该用〈相隔〉。聚指会合到一起，两家之间距离遥远应说相隔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12948, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "聚", "is_correct": true, "explanation": "「聚 jù」意思是会合、集中。"}, {"text": "序", "is_correct": false, "explanation": "「xù」与「jù」声母不同（x/j），意思是次序。"}, {"text": "叙", "is_correct": false, "explanation": "「xù」与「jù」声母不同（x/j），意思是叙述。"}, {"text": "续", "is_correct": false, "explanation": "「xù」与「jù」声母不同（x/j），意思是继续。"}, {"text": "绪", "is_correct": false, "explanation": "「xù」与「jù」声母不同（x/j），意思是头绪或情绪。"}], "explanations": {"聚": "「聚 jù」意思是会合、集中。", "序": "「xù」与「jù」声母不同（x/j），意思是次序。", "叙": "「xù」与「jù」声母不同（x/j），意思是叙述。", "续": "「xù」与「jù」声母不同（x/j），意思是继续。", "绪": "「xù」与「jù」声母不同（x/j），意思是头绪或情绪。"}, "sentence_index": null, "correct_answer": "聚"}, "level_3": {"options": [{"text": "聚", "is_correct": true, "explanation": "「聚一次」指朋友或家人相聚一次，与「每个月」相符。"}, {"text": "摔", "is_correct": false, "explanation": "语义：「摔」指跌落、倒下，与「每个月……一次」的相聚义不符。"}, {"text": "分", "is_correct": false, "explanation": "语义：「分」指划分或分开，不能表示相聚一次。"}, {"text": "挨", "is_correct": false, "explanation": "语义：「挨」表示遭受，不能表示相聚一次。"}], "explanations": {"聚": "「聚一次」指朋友或家人相聚一次，与「每个月」相符。", "摔": "语义：「摔」指跌落、倒下，与「每个月……一次」的相聚义不符。", "分": "语义：「分」指划分或分开，不能表示相聚一次。", "挨": "语义：「挨」表示遭受，不能表示相聚一次。"}, "sentence_index": 6, "correct_answer": "聚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议结束后，大家纷纷聚了。", "explanation": "这里应该用〈散〉。聚指从各处会合到一起，会议结束后人群离开应说散。"}, {"text": "这次考试他聚了第一名。", "explanation": "这里应该用〈拿到〉。聚指人或事物从分散处会合到一起，获得名次应说拿到。"}, {"text": "老师把任务聚给了每个人。", "explanation": "这里应该用〈分配〉。聚指人或事物从分散处会合到一起，把任务派给每人应说分配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下班后，同事们常常聚门口聊天。", "corrected_sentence": "下班后，同事们常常聚在门口聊天。", "error_description": "「聚」后面表示地点时要用介词「在」，这里漏掉了「在」，应说「聚在门口」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年我们聚着两次。", "corrected_sentence": "去年我们聚过两次。", "error_description": "「过」表示曾经发生过的经历，应用「聚过」；「着」表示动作正在持续，不能用于已结束的聚会次数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
