INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12949, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "羟基是化学中的一种原子团，由一个氧原子和一个氢原子组成，常出现在醇类等有机物中。", "primary_collocate": null, "pronunciation": "qiǎng jī", "ipa": "tɕʰjaŋ˨˩˦ tɕi˥", "syllable_count": 2, "sentences": [{"text": "醇类分子的官能团是羟基。", "target_word": "羟基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "羟基由一个氧原子和一个氢原子组成。", "target_word": "羟基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒精分子里有一个羟基。", "target_word": "羟基", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乙醇分子中含有羟基。", "target_word": "羟基", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "含有羟基的有机物常常是醇类。", "target_word": "羟基", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "羟基是由氧和氢组成的原子团。", "target_word": "羟基", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在黑板上画出了羟基的结构。", "target_word": "羟基", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "羟基能让分子更容易溶于水。", "target_word": "羟基", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种物质没有羟基，所以不是醇。", "target_word": "羟基", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "糖分子上有很多羟基。", "target_word": "羟基", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个羟基", "label": "量词"}, {"form": "羟基酸", "label": "复合"}], "register": "书面", "sense_fingerprint": "由一个氧原子和一个氢原子组成的化学原子团", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18b3f918-5c54-4472-be9f-e910ce51db7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12949, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "羟基", "is_correct": true, "explanation": "羟基 qiǎng jī 是本词，指由一个氧原子和一个氢原子组成的原子团。"}, {"text": "枪击", "is_correct": false, "explanation": "qiāng（第一声）与 qiǎng（第三声）声调不同，“枪击”意思是开枪射击。"}, {"text": "枪机", "is_correct": false, "explanation": "qiāng（第一声）与 qiǎng（第三声）声调不同，“枪机”意思是枪的机械部件。"}, {"text": "墙基", "is_correct": false, "explanation": "qiáng（第二声）与 qiǎng（第三声）声调不同，“墙基”意思是墙的地基。"}], "explanations": {"羟基": "羟基 qiǎng jī 是本词，指由一个氧原子和一个氢原子组成的原子团。", "枪击": "qiāng（第一声）与 qiǎng（第三声）声调不同，“枪击”意思是开枪射击。", "枪机": "qiāng（第一声）与 qiǎng（第三声）声调不同，“枪机”意思是枪的机械部件。", "墙基": "qiáng（第二声）与 qiǎng（第三声）声调不同，“墙基”意思是墙的地基。"}, "sentence_index": null, "correct_answer": "羟基"}, "level_3": {"options": [{"text": "羟基", "is_correct": true, "explanation": "正确：醇类分子的官能团是羟基（-OH），与句意相符。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气是气体单质，不是醇类的官能团。"}, {"text": "氨基", "is_correct": false, "explanation": "语义：氨基含氮，是胺类的官能团，不是醇类的。"}, {"text": "醛基", "is_correct": false, "explanation": "语义：醛基是醛类的官能团，不是醇类的。"}], "explanations": {"羟基": "正确：醇类分子的官能团是羟基（-OH），与句意相符。", "氧气": "语义：氧气是气体单质，不是醇类的官能团。", "氨基": "语义：氨基含氮，是胺类的官能团，不是醇类的。", "醛基": "语义：醛基是醛类的官能团，不是醇类的。"}, "sentence_index": 0, "correct_answer": "羟基"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在实验室买了一瓶羟基。", "explanation": "这里应该用〈乙醇〉。羟基是原子团，不能单独装瓶出售；乙醇是可以装瓶的化合物。"}, {"text": "羟基是一种原子。", "explanation": "这里应该用〈原子团〉。羟基由一个氧原子和一个氢原子组成，是原子团，不是单个原子。"}, {"text": "羟基是一个分子式。", "explanation": "这里的“羟基”是原子团，不是“分子式”，说成“是一个分子式”不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12949, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "羟基", "is_correct": true, "explanation": "正确：羟基是化学原子团，可以在黑板上画出它的结构。"}, {"text": "冰淇淋", "is_correct": false, "explanation": "语义：冰淇淋是食品，不能在黑板上画出它的化学结构。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”没有可以画出的结构，“结构”不搭配“天气”。"}, {"text": "快乐", "is_correct": false, "explanation": "语义：「快乐」是一种感受，没有可以在黑板上画出的化学结构。"}], "explanations": {"羟基": "正确：羟基是化学原子团，可以在黑板上画出它的结构。", "冰淇淋": "语义：冰淇淋是食品，不能在黑板上画出它的化学结构。", "天气": "搭配：“天气”没有可以画出的结构，“结构”不搭配“天气”。", "快乐": "语义：「快乐」是一种感受，没有可以在黑板上画出的化学结构。"}, "sentence_index": 6, "correct_answer": "羟基"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乙醇是一种羟基。", "explanation": "这里应该用〈醇〉。乙醇属于醇类，羟基只是分子中的一个原子团，不是一类化合物。"}, {"text": "甲醛是一种羟基。", "explanation": "这里应该用〈醛〉。甲醛属于醛类，羟基不是一类化合物。"}, {"text": "醋酸是一种羟基。", "explanation": "这里应该用〈羧酸〉。醋酸属于羧酸，羟基不是一类化合物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12949, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "酒精分子里含有一只羟基。", "corrected_sentence": "酒精分子里含有一个羟基。", "error_description": "错误：羟基的量词用了“只”，“只”多用于动物等，这里应改为“个”。正确：“一个羟基”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12949, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种分子里有很羟基。", "corrected_sentence": "这种分子里有很多羟基。", "error_description": "错误：“很”不能直接修饰名词“羟基”，“多”不可省略。正确：“有很多羟基”，数量短语“很多”修饰宾语“羟基”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44a1f037-7793-4423-b2e9-2ec73afc657c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
