INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12952, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "己二酸是一种有机化合物，主要用于生产尼龙66、聚氨酯、增塑剂等工业产品。", "primary_collocate": null, "pronunciation": "jǐ èr suān", "ipa": "tɕi˨˩ ɑɻ˥˩ swan˥", "syllable_count": 3, "sentences": [{"text": "己二酸和丁二醇反应可以得到聚酯。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "己二酸是生产尼龙的重要原料。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用己二酸生产尼龙纤维。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "己二酸是一种白色的晶体。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每年生产很多己二酸。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "己二酸可以用来做塑料增塑剂。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学老师在课上介绍了己二酸。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "己二酸在水里不容易溶解。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用环己烷制造己二酸。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把己二酸装进了大袋子里。", "target_word": "己二酸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "己二酸：工业用有机化合物，用于生产尼龙等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4242725a-da6e-4fb3-b896-246ef3d081ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12952, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "己二酸", "is_correct": true, "explanation": "正确：己二酸是二元酸，与丁二醇反应可以得到聚酯，句意正确。"}, {"text": "丙酸", "is_correct": false, "explanation": "配价：丙酸只有一个羧基，不能作为二元酸参与这种缩聚反应。"}, {"text": "乙醇", "is_correct": false, "explanation": "语义：乙醇是醇类而不是酸，不能充当这种聚酯的酸性单体。"}, {"text": "尿素", "is_correct": false, "explanation": "语义：尿素是含氮化合物，不是二元酸，不能与丁二醇反应生成聚酯。"}], "explanations": {"己二酸": "正确：己二酸是二元酸，与丁二醇反应可以得到聚酯，句意正确。", "丙酸": "配价：丙酸只有一个羧基，不能作为二元酸参与这种缩聚反应。", "乙醇": "语义：乙醇是醇类而不是酸，不能充当这种聚酯的酸性单体。", "尿素": "语义：尿素是含氮化合物，不是二元酸，不能与丁二醇反应生成聚酯。"}, "sentence_index": 0, "correct_answer": "己二酸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈买了一只己二酸。", "explanation": "这里应该用〈公斤〉或〈袋〉。己二酸是化工原料，不用“只”，“只”指动物或独立的小物件。"}, {"text": "己二酸是一种蓝色的液体。", "explanation": "这里应该用〈白色的晶体〉。己二酸是白色的晶体，不是蓝色的液体。"}, {"text": "这个箱子里有一根己二酸。", "explanation": "这里应该用〈袋〉或〈公斤〉。〈根〉用于细长的条状物，己二酸是粉末或晶体，不能用“根”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12952, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "己二酸", "is_correct": true, "explanation": "正确：化学老师在课上讲的是化学物质，己二酸是化学课上可以介绍的工业化合物。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是体育用品，化学课上不会介绍它，与“化学老师在课上”的语境不符。"}, {"text": "红烧肉", "is_correct": false, "explanation": "语义：红烧肉是菜肴，不属于化学知识，化学老师一般不会在课上介绍它。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“化学老师在课上介绍了”后接乐器不合理，化学课的内容通常是化学物质或化学原理。"}], "explanations": {"己二酸": "正确：化学老师在课上讲的是化学物质，己二酸是化学课上可以介绍的工业化合物。", "篮球": "语义：篮球是体育用品，化学课上不会介绍它，与“化学老师在课上”的语境不符。", "红烧肉": "语义：红烧肉是菜肴，不属于化学知识，化学老师一般不会在课上介绍它。", "钢琴": "搭配：“化学老师在课上介绍了”后接乐器不合理，化学课的内容通常是化学物质或化学原理。"}, "sentence_index": 6, "correct_answer": "己二酸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早上他喝了一杯己二酸。", "explanation": "这里应该用〈牛奶〉等饮料。己二酸是工业化工原料，不是可以喝的饮料。"}, {"text": "汽车要加己二酸才能开。", "explanation": "这里应该用〈汽油〉。己二酸是生产尼龙的原料，不是汽车的燃料。"}, {"text": "实验室用己二酸制作标本。", "explanation": "这里应该用〈甲醛〉。甲醛溶液能防腐，常用于制作生物标本，己二酸没有这种作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12952, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人己二酸运到了仓库。", "corrected_sentence": "工人把己二酸运到了仓库。", "error_description": "处置式错误：“己二酸”是动词“运”的受事，需用“把”引出并放在动词前，不能省略“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12952, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一只己二酸倒进了桶里。", "corrected_sentence": "他把一袋己二酸倒进了桶里。", "error_description": "量词用错。“己二酸”是化工原料，计量应用“袋”或“公斤”；“只”用于动物或独立的小物件。错误形式是“一只己二酸”，正确形式是“一袋己二酸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
