INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12955, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物质中保持化学性质的最小单位", "primary_collocate": null, "pronunciation": "fēn zǐ", "ipa": "fən˥ tsɨ˨˩", "syllable_count": 2, "sentences": [{"text": "水分子由氢原子和氧原子组成。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分子比原子大，但是我们看不见。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热水里的分子动得更快。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个水分子里有两个氢原子。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用小球做了一个分子模型。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖放进水里，糖分子慢慢散开了。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气中有很多氧分子。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰里的水分子动得很慢。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分子太小了，用眼睛看不见。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在研究这种分子的结构。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "分子：物质中保持化学性质的最小粒子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4242725a-da6e-4fb3-b896-246ef3d081ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12955, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分子", "is_correct": true, "explanation": "正确：水分子是由氢原子和氧原子组成的，“分子”指保持物质化学性质的微粒。"}, {"text": "离子", "is_correct": false, "explanation": "语义：离子是带电的粒子，“水离子”与“由氢原子和氧原子组成”的化学含义不符。"}, {"text": "细胞", "is_correct": false, "explanation": "语义：细胞是生物的基本单位，不是一个水的微粒，“水细胞”不成立。"}, {"text": "盐", "is_correct": false, "explanation": "搭配：“水”与“盐”不构成可以这样组合的物质名称，“水盐”不能指由氢原子和氧原子组成的物质。"}], "explanations": {"分子": "正确：水分子是由氢原子和氧原子组成的，“分子”指保持物质化学性质的微粒。", "离子": "语义：离子是带电的粒子，“水离子”与“由氢原子和氧原子组成”的化学含义不符。", "细胞": "语义：细胞是生物的基本单位，不是一个水的微粒，“水细胞”不成立。", "盐": "搭配：“水”与“盐”不构成可以这样组合的物质名称，“水盐”不能指由氢原子和氧原子组成的物质。"}, "sentence_index": 0, "correct_answer": "分子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯水里有一只分子。", "explanation": "这里应该用〈个〉。〈只〉用于动物或独立的个体，分子是微粒，不用“只”。"}, {"text": "金属是由分子构成的。", "explanation": "这里应该用〈原子〉。金属由原子直接构成，不由分子组成。"}, {"text": "这瓶氧气里有一根分子。", "explanation": "这里应该用〈个〉。〈根〉用于细长的条状物，分子是肉眼看不见的微粒，不能用“根”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12955, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分子", "is_correct": true, "explanation": "正确：空气中含有的氧分子是保持化学性质的微粒。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是固体矿物，不是空气中的气体微粒，句子读起来不成立。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁是金属材料，不存在于空气中，与“空气中有”的语境不符。"}, {"text": "花瓣", "is_correct": false, "explanation": "搭配：“氧”与“花瓣”不搭配，“氧花瓣”不是一个可以在空气中存在的物质名称。"}], "explanations": {"分子": "正确：空气中含有的氧分子是保持化学性质的微粒。", "石头": "语义：石头是固体矿物，不是空气中的气体微粒，句子读起来不成立。", "钢铁": "语义：钢铁是金属材料，不存在于空气中，与“空气中有”的语境不符。", "花瓣": "搭配：“氧”与“花瓣”不搭配，“氧花瓣”不是一个可以在空气中存在的物质名称。"}, "sentence_index": 6, "correct_answer": "分子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "分子是生物体结构和功能的基本单位。", "explanation": "这里应该用〈细胞〉。细胞是生物体结构和功能的基本单位，分子指保持物质化学性质的微粒，不能这样说。"}, {"text": "钠分子带一个正电荷。", "explanation": "这里应该用〈离子〉。带电的是离子，分子是电中性的微粒，钠分子不带电。"}, {"text": "食盐是一种白色的分子。", "explanation": "这里应该用〈晶体〉。食盐是由离子排列而成的晶体，不是分子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家发现了一只新的分子。", "corrected_sentence": "科学家发现了一种新的分子。", "error_description": "量词错误：“分子”应用量词“种”或“个”，不能用“只”。“只”用于动物或独立的小东西，分子是微粒，不能用“只”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "科学家分子分成了两部分。", "corrected_sentence": "科学家把分子分成了两部分。", "error_description": "处置式错误：“分子”作“分成”的受事，需用“把”引出，省略“把”后句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
