INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12956, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "表示来源或出处", "primary_collocate": null, "pronunciation": "yuán zì", "ipa": "ɥɛn˧˥ tsɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这种塑料源自玉米淀粉。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事源自一个古老的传说。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个习俗源自古代的农村。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的灵感源自生活中的小事。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话源自一首唐诗。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多成语源自历史故事。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词源自英语。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中秋节的习俗源自古人对月亮的崇拜。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种想法源自他小时候的经历。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏源自一本有名的小说。", "target_word": "源自", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "习俗、词语、想法等的来源或出处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4242725a-da6e-4fb3-b896-246ef3d081ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12956, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "源自", "is_correct": true, "explanation": "源自表示来源或出处，读作 yuán zì，例如“这个词源自英语”。"}, {"text": "原子", "is_correct": false, "explanation": "zǐ（第三声）与 zì（第四声）声调不同，意思是原子。"}, {"text": "原罪", "is_correct": false, "explanation": "zuì（第四声）比 zì 多一个介音 u，意思是原罪。"}, {"text": "圆子", "is_correct": false, "explanation": "zi（轻声）与 zì（第四声）声调不同，意思是圆子，一种圆形的食物。"}], "explanations": {"源自": "源自表示来源或出处，读作 yuán zì，例如“这个词源自英语”。", "原子": "zǐ（第三声）与 zì（第四声）声调不同，意思是原子。", "原罪": "zuì（第四声）比 zì 多一个介音 u，意思是原罪。", "圆子": "zi（轻声）与 zì（第四声）声调不同，意思是圆子，一种圆形的食物。"}, "sentence_index": null, "correct_answer": "源自"}, "level_3": {"options": [{"text": "源自", "is_correct": true, "explanation": "正确：源自表示来源，“这种塑料源自玉米淀粉”说明塑料的来源。"}, {"text": "生产", "is_correct": false, "explanation": "语义：句中说塑料的来源是玉米淀粉，“生产”颠倒了来源关系。"}, {"text": "消耗", "is_correct": false, "explanation": "语义：句中说塑料来自玉米淀粉，“消耗”与来源的方向相反。"}, {"text": "保护", "is_correct": false, "explanation": "语义：句中说的是塑料的来源，“保护”与来源无关。"}], "explanations": {"源自": "正确：源自表示来源，“这种塑料源自玉米淀粉”说明塑料的来源。", "生产": "语义：句中说塑料的来源是玉米淀粉，“生产”颠倒了来源关系。", "消耗": "语义：句中说塑料来自玉米淀粉，“消耗”与来源的方向相反。", "保护": "语义：句中说的是塑料的来源，“保护”与来源无关。"}, "sentence_index": 0, "correct_answer": "源自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他源自北京。", "explanation": "这里应该用〈来自〉。“源自”指事物的起源或出处，说人的籍贯要用“来自”。"}, {"text": "这个学生源自农村。", "explanation": "这里应该用〈出身〉。说人的家庭背景用“出身”，“源自”不用于人。"}, {"text": "这份工作源自昨天。", "explanation": "这里应该用〈始于〉。“源自”表示事物的来源或出处，接事物或地点；说工作从哪天开始要用“始于”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12956, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "源自", "is_correct": true, "explanation": "源自表示来源或出处，读作 yuán zì。"}, {"text": "原址", "is_correct": false, "explanation": "zhǐ（第三声）与 zì（第四声）声母和声调都不同，“原址”指原来的地址。"}, {"text": "园子", "is_correct": false, "explanation": "zi（轻声）与 zì（第四声）声调不同，意思是园子，即小花园。"}, {"text": "原质", "is_correct": false, "explanation": "zhì（第四声）与 zì 声母不同（zh 与 z），“原质”指事物原本的性质或本质。"}], "explanations": {"源自": "源自表示来源或出处，读作 yuán zì。", "原址": "zhǐ（第三声）与 zì（第四声）声母和声调都不同，“原址”指原来的地址。", "园子": "zi（轻声）与 zì（第四声）声调不同，意思是园子，即小花园。", "原质": "zhì（第四声）与 zì 声母不同（zh 与 z），“原质”指事物原本的性质或本质。"}, "sentence_index": null, "correct_answer": "源自"}, "level_3": {"options": [{"text": "源自", "is_correct": true, "explanation": "源自表示来源，“这个词源自英语”说明词的来源，句意正确。"}, {"text": "包括", "is_correct": false, "explanation": "语义：“这个词包括英语”表示词里含有英语，与“源自英语”的来源义不符。"}, {"text": "学习", "is_correct": false, "explanation": "语义：“学习英语”指学习这门语言，句中主语是“这个词”，搭配不当。"}, {"text": "使用", "is_correct": false, "explanation": "语义：词不能“使用”英语，“这个词使用英语”与句意不符。"}], "explanations": {"源自": "源自表示来源，“这个词源自英语”说明词的来源，句意正确。", "包括": "语义：“这个词包括英语”表示词里含有英语，与“源自英语”的来源义不符。", "学习": "语义：“学习英语”指学习这门语言，句中主语是“这个词”，搭配不当。", "使用": "语义：词不能“使用”英语，“这个词使用英语”与句意不符。"}, "sentence_index": 6, "correct_answer": "源自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我源自家去学校。", "explanation": "这里应该用〈出发〉。“源自”只表示事物的来源，不能用来说人从某处动身去别的地方。"}, {"text": "这座房子源自很多砖。", "explanation": "这里应该用〈由……组成〉。“源自”表示来源，不表示事物由哪些部分构成。"}, {"text": "这辆车源自上海开往北京。", "explanation": "这里应该用〈从……开往〉。“源自”只表示来源，不表示车辆的出发和去向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个节日被源自古代的祭祀。", "corrected_sentence": "这个节日源自古代的祭祀。", "error_description": "“源自”表示来源，不用被动式，应说“这个节日源自古代的祭祀”，去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个习惯源自了很久以前的生活。", "corrected_sentence": "这个习惯源自很久以前的生活。", "error_description": "“源自”表示来源，不带“了”；应说“这个习惯源自很久以前的生活”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
