INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12957, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指可以回收并重新加工利用的物质和物品，如废纸、废塑料。", "primary_collocate": null, "pronunciation": "zài shēng zī yuán", "ipa": "tsaɪ˥˩ ʂɤŋ˥˥ tsɹ̩˥˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "工厂每天收集很多旧报纸，这些都是再生资源。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "废纸和旧瓶子都是再生资源。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要多用再生资源。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂用一种再生资源做新纸。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再生资源可以回收，再用一次。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，旧衣服也是再生资源。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回收再生资源，可以保护环境。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里有很多回收再生资源的公司。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "废塑料是一种重要的再生资源。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把这些再生资源送到回收站。", "target_word": "再生资源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "再生資源", "label": "繁体"}], "register": "书面", "sense_fingerprint": "可回收并重新加工利用的物质和物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4242725a-da6e-4fb3-b896-246ef3d081ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12957, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再生资源", "is_correct": true, "explanation": "再生资源指可回收并重新加工利用的物质，“旧报纸”正属于此类。"}, {"text": "再生能源", "is_correct": false, "explanation": "语义：“再生能源”指太阳能、风能等能源，旧报纸不是能源，与句意不符。"}, {"text": "矿产资源", "is_correct": false, "explanation": "语义：矿产资源指地下开采的矿物，旧报纸不是矿产，与句意不符。"}, {"text": "天然资源", "is_correct": false, "explanation": "语义：天然资源指自然界本有的资源，旧报纸是人造的废弃物，与句意不符。"}], "explanations": {"再生资源": "再生资源指可回收并重新加工利用的物质，“旧报纸”正属于此类。", "再生能源": "语义：“再生能源”指太阳能、风能等能源，旧报纸不是能源，与句意不符。", "矿产资源": "语义：矿产资源指地下开采的矿物，旧报纸不是矿产，与句意不符。", "天然资源": "语义：天然资源指自然界本有的资源，旧报纸是人造的废弃物，与句意不符。"}, "sentence_index": 0, "correct_answer": "再生资源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂用一只再生资源做新纸。", "explanation": "这里应该用〈种〉。“再生资源”的量词用“种”，“只”用于动物，不能计量资源。"}, {"text": "这家工厂用一头再生资源做新纸。", "explanation": "这里应该用〈种〉。“头”用于牲畜，不能计量再生资源，应说“一种”。"}, {"text": "这家工厂用一座再生资源做新纸。", "explanation": "这里应该用〈种〉。“座”用于山、桥等大型物体，不能计量再生资源，应说“一种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12957, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再生资源", "is_correct": true, "explanation": "再生资源指可回收并重新加工利用的物质，“回收再生资源，可以保护环境”句意正确。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“回收老师”不成立，句中回收的应是可重新利用的物质。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能被回收，与“保护环境”的回收对象不符。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是可回收再加工的物质，“回收歌曲”与句意不符。"}], "explanations": {"再生资源": "再生资源指可回收并重新加工利用的物质，“回收再生资源，可以保护环境”句意正确。", "老师": "语义：“回收老师”不成立，句中回收的应是可重新利用的物质。", "天空": "语义：天空不能被回收，与“保护环境”的回收对象不符。", "歌曲": "语义：歌曲不是可回收再加工的物质，“回收歌曲”与句意不符。"}, "sentence_index": 6, "correct_answer": "再生资源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天吃再生资源。", "explanation": "“吃”的对象要是食物，再生资源指可回收重新利用的废旧物质，不能吃。"}, {"text": "我们把再生资源种在花园里。", "explanation": "“种”用于植物或种子，再生资源不是植物，不能种。"}, {"text": "他把再生资源当成宠物养。", "explanation": "“养”用于动物等生命体，再生资源是物质，不能当宠物养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12957, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "废纸是一只再生资源。", "corrected_sentence": "废纸是一种再生资源。", "error_description": "“再生资源”的量词应为“种”，“只”用于动物，不能计量资源；应说“废纸是一种再生资源”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12957, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里有三座再生资源。", "corrected_sentence": "这里有三种再生资源。", "error_description": "“再生资源”的量词应为“种”；“座”用于山、桥等大型物体，不能计量资源，应说“这里有三种再生资源”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
