INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12958, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12958, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "淀粉是一种由葡萄糖分子聚合而成的多糖，广泛存在于植物中，常用于食品加工中作为增稠剂、稳定剂。", "primary_collocate": null, "pronunciation": "diàn fěn", "ipa": "tjɛn˥˩ fən˨˩˦", "syllable_count": 2, "sentences": [{"text": "例如，PLA源自可再生资源如玉米淀粉，其聚合过程通过催化缩聚完成，而其降解则需在高温高湿的堆肥环境中由嗜热菌群高效分解。", "target_word": "淀粉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "淀粉是由很多葡萄糖连成的多糖。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植物把光合作用制造的糖变成淀粉储存起来。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唾液中的酶能把淀粉分解成麦芽糖。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "碘液遇到淀粉会变成蓝色。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用淀粉生产可降解塑料。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小麦磨成粉后，里面最多的成分是淀粉。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "淀粉不溶于冷水，加热后才会变成糊状。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食品厂常把淀粉当作增稠剂。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "淀粉水解后可以得到葡萄糖。", "target_word": "淀粉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "玉米淀粉", "label": "复合"}, {"form": "淀粉酶", "label": "复合"}, {"form": "一勺淀粉", "label": "量词"}], "register": "科技", "sense_fingerprint": "由葡萄糖聚合成的多糖，存在于植物中，可作增稠剂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e12ecc-3ac0-4aa7-b224-954d9d880c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12958, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "淀粉", "is_correct": true, "explanation": "正确答案：淀粉（diàn fěn），指从植物中提取的白色多糖粉末。"}, {"text": "蛋粉", "is_correct": false, "explanation": "dàn 与 diàn 韵母不同（an 与 ian），意思是鸡蛋磨成的粉，不是淀粉。"}, {"text": "面粉", "is_correct": false, "explanation": "miàn 与 diàn 声母不同（m 与 d），意思是小麦磨成的面粉。"}, {"text": "电饭", "is_correct": false, "explanation": "fàn（第四声）与 fěn（第三声）韵母与声调都不同，意思是用电煮的饭。"}], "explanations": {"淀粉": "正确答案：淀粉（diàn fěn），指从植物中提取的白色多糖粉末。", "蛋粉": "dàn 与 diàn 韵母不同（an 与 ian），意思是鸡蛋磨成的粉，不是淀粉。", "面粉": "miàn 与 diàn 声母不同（m 与 d），意思是小麦磨成的面粉。", "电饭": "fàn（第四声）与 fěn（第三声）韵母与声调都不同，意思是用电煮的饭。"}, "sentence_index": null, "correct_answer": "淀粉"}, "level_3": {"options": [{"text": "淀粉", "is_correct": true, "explanation": "正确答案：淀粉。玉米淀粉是可再生资源，是 PLA 的原料，句中“玉米”指向它。"}, {"text": "石油", "is_correct": false, "explanation": "语义：石油是化石能源，不可再生，与“可再生资源”的说法相矛盾。"}, {"text": "煤炭", "is_correct": false, "explanation": "语义：煤炭同样是不可再生的化石燃料，不能作为句中的可再生原料。"}, {"text": "矿石", "is_correct": false, "explanation": "搭配：“玉米矿石”不成立，玉米不产出矿石，二者不能组合。"}], "explanations": {"淀粉": "正确答案：淀粉。玉米淀粉是可再生资源，是 PLA 的原料，句中“玉米”指向它。", "石油": "语义：石油是化石能源，不可再生，与“可再生资源”的说法相矛盾。", "煤炭": "语义：煤炭同样是不可再生的化石燃料，不能作为句中的可再生原料。", "矿石": "搭配：“玉米矿石”不成立，玉米不产出矿石，二者不能组合。"}, "sentence_index": 0, "correct_answer": "淀粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想让这杯咖啡更甜一点，就加了两勺淀粉。", "explanation": "这里应该用〈糖〉。淀粉没有甜味，让饮料变甜要用糖。"}, {"text": "天黑了，我打开淀粉看书。", "explanation": "这里应该用〈台灯〉。淀粉是粉末，不能照明，看书要开台灯。"}, {"text": "我用淀粉和了一大团面，准备做馒头。", "explanation": "这里应该用〈面粉〉。淀粉没有面筋，蒸不出松软的馒头，做馒头要用面粉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12958, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "淀粉", "is_correct": true, "explanation": "正确答案：淀粉（diàn fěn），指从植物中提取的白色多糖粉末。"}, {"text": "典范", "is_correct": false, "explanation": "diǎn（第三声）与 diàn（第四声）声调不同，fàn 与 fěn 韵母、声调也不同，意思是值得学习的榜样。"}, {"text": "垫付", "is_correct": false, "explanation": "fù 与 fěn 韵母与声调都不同，意思是先替别人付钱。"}, {"text": "电费", "is_correct": false, "explanation": "fèi（第四声）与 fěn（第三声）韵母不同（ei 与 en），意思是用电的费用。"}], "explanations": {"淀粉": "正确答案：淀粉（diàn fěn），指从植物中提取的白色多糖粉末。", "典范": "diǎn（第三声）与 diàn（第四声）声调不同，fàn 与 fěn 韵母、声调也不同，意思是值得学习的榜样。", "垫付": "fù 与 fěn 韵母与声调都不同，意思是先替别人付钱。", "电费": "fèi（第四声）与 fěn（第三声）韵母不同（ei 与 en），意思是用电的费用。"}, "sentence_index": null, "correct_answer": "淀粉"}, "level_3": {"options": [{"text": "淀粉", "is_correct": true, "explanation": "正确答案：淀粉。小麦粉中淀粉占大部分，是“最多”的成分。"}, {"text": "维生素", "is_correct": false, "explanation": "语义：小麦粉中维生素含量极少，不能说是“最多的成分”。"}, {"text": "矿物质", "is_correct": false, "explanation": "语义：小麦粉中矿物质含量很低，与“最多”的说法矛盾。"}, {"text": "脂肪", "is_correct": false, "explanation": "语义：小麦粉中脂肪含量很低，不是“最多的成分”。"}], "explanations": {"淀粉": "正确答案：淀粉。小麦粉中淀粉占大部分，是“最多”的成分。", "维生素": "语义：小麦粉中维生素含量极少，不能说是“最多的成分”。", "矿物质": "语义：小麦粉中矿物质含量很低，与“最多”的说法矛盾。", "脂肪": "语义：小麦粉中脂肪含量很低，不是“最多的成分”。"}, "sentence_index": 6, "correct_answer": "淀粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生用淀粉给伤口消毒。", "explanation": "这里应该用〈酒精〉。淀粉没有杀菌作用，给伤口消毒要用酒精。"}, {"text": "他一口气喝完了一杯淀粉。", "explanation": "这里应该用〈牛奶〉。淀粉是不溶于冷水的白色粉末，不能当饮料喝。"}, {"text": "他用钢笔蘸淀粉写字。", "explanation": "这里应该用〈墨水〉。淀粉不能用来写字，蘸钢笔要用墨水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们给实验室买了一只淀粉。", "corrected_sentence": "我们给实验室买了一袋淀粉。", "error_description": "量词用错：淀粉是粉末，应说“一袋淀粉”。“只”用于动物或成对物品中的一个，不能用来计量淀粉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厨房柜子里有三条淀粉。", "corrected_sentence": "厨房柜子里有三袋淀粉。", "error_description": "量词用错：“条”用于细长的物体，淀粉是粉末，应说“三袋淀粉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12959, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "正确答案：分散，与“聚合”是反义词，指把集中的事物分开。"}, {"text": "修理", "is_correct": false, "explanation": "修理与“聚合”没有反义关系，指把坏的东西修好。"}, {"text": "拒绝", "is_correct": false, "explanation": "拒绝与“聚合”没有反义关系，指不接受。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运与“聚合”没有反义关系，指把东西从一处移到另一处。"}], "correct_answer": "分散", "explanations": {"分散": "正确答案：分散，与“聚合”是反义词，指把集中的事物分开。", "修理": "修理与“聚合”没有反义关系，指把坏的东西修好。", "拒绝": "拒绝与“聚合”没有反义关系，指不接受。", "搬运": "搬运与“聚合”没有反义关系，指把东西从一处移到另一处。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12959, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "正确答案：分散，与“聚合”是反义词，指把集中的事物分开。"}, {"text": "游玩", "is_correct": false, "explanation": "游玩与“聚合”没有反义关系，指出去玩乐。"}, {"text": "寻找", "is_correct": false, "explanation": "寻找与“聚合”没有反义关系，指设法找到。"}, {"text": "批评", "is_correct": false, "explanation": "批评与“聚合”没有反义关系，指指出缺点或错误。"}], "correct_answer": "分散", "explanations": {"分散": "正确答案：分散，与“聚合”是反义词，指把集中的事物分开。", "游玩": "游玩与“聚合”没有反义关系，指出去玩乐。", "寻找": "寻找与“聚合”没有反义关系，指设法找到。", "批评": "批评与“聚合”没有反义关系，指指出缺点或错误。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12959, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指把分散的、不同的事物集中或组合在一起。", "primary_collocate": null, "pronunciation": "jù hé", "ipa": "tɕy˥˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这份报告把各部门的财务数据聚合在一起，形成了一套统一的指标体系。", "target_word": "聚合", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "网站把各地的新闻聚合在一起。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件能聚合不同平台的消息。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几家小店聚合成一个大市场。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想把分散的资源聚合起来。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家网店聚合了上百个品牌的商品。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多想法聚合在一起，才有了新的计划。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款软件把你的账号聚合到一个页面里。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个平台把不同领域的专家聚合在一起。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小公司后来聚合成了一家大企业。", "target_word": "聚合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聚合了", "label": "体标"}, {"form": "聚合着", "label": "体标"}, {"form": "聚合物", "label": "复合"}], "register": "中性", "sense_fingerprint": "把分散的、不同的事物集中或组合到一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e12ecc-3ac0-4aa7-b224-954d9d880c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12959, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "聚合", "is_correct": true, "explanation": "正确答案：聚合（jù hé），指把分散的事物集中或组合在一起。"}, {"text": "巨鹤", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）只差声调，意思是巨大的鹤。"}, {"text": "巨额", "is_correct": false, "explanation": "é 与 hé 只差声母 h，意思是数目非常大。"}, {"text": "聚会", "is_correct": false, "explanation": "huì（第四声）与 hé（第二声）韵母不同（ui 与 e），意思是人们聚在一起的活动。"}], "explanations": {"聚合": "正确答案：聚合（jù hé），指把分散的事物集中或组合在一起。", "巨鹤": "hè（第四声）与 hé（第二声）只差声调，意思是巨大的鹤。", "巨额": "é 与 hé 只差声母 h，意思是数目非常大。", "聚会": "huì（第四声）与 hé（第二声）韵母不同（ui 与 e），意思是人们聚在一起的活动。"}, "sentence_index": null, "correct_answer": "聚合"}, "level_3": {"options": [{"text": "聚合", "is_correct": true, "explanation": "正确答案：聚合，指把各部门的数据组合到一起，与“形成统一的指标体系”相符。"}, {"text": "分解", "is_correct": false, "explanation": "语义：分解是拆开，与“在一起”以及“形成统一体系”的结果相反。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：冷却是降温，与整理财务数据无关。"}, {"text": "溶解", "is_correct": false, "explanation": "搭配：“溶解”指物质溶于液体，数据不能“溶解在一起”。"}], "explanations": {"聚合": "正确答案：聚合，指把各部门的数据组合到一起，与“形成统一的指标体系”相符。", "分解": "语义：分解是拆开，与“在一起”以及“形成统一体系”的结果相反。", "冷却": "语义：冷却是降温，与整理财务数据无关。", "溶解": "搭配：“溶解”指物质溶于液体，数据不能“溶解在一起”。"}, "sentence_index": 0, "correct_answer": "聚合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把一个完整的苹果聚合成了四块。", "explanation": "这里应该用〈切〉。聚合是合在一起，把苹果切成四块要说切。"}, {"text": "他把一大袋糖聚合成了三小袋。", "explanation": "这里应该用〈分装〉。聚合是把多个合为一个，一大袋糖装成三小袋要说分装。"}, {"text": "他把一条长绳子聚合成了三段。", "explanation": "这里应该用〈剪〉。聚合是合在一起，把绳子剪成三段要说剪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聚合", "is_correct": true, "explanation": "正确答案：聚合。许多想法汇集在一起，才产生了新计划。"}, {"text": "分开", "is_correct": false, "explanation": "语义：“分开”与“在一起”相矛盾，想法不能分开在一起。"}, {"text": "遗忘", "is_correct": false, "explanation": "搭配：“遗忘在一起”不成立，“遗忘”是忘记，不能与“在一起”组合。"}, {"text": "拆散", "is_correct": false, "explanation": "语义：“拆散”表示拆开，与“在一起”以及“才有了新的计划”的意思相反。"}], "explanations": {"聚合": "正确答案：聚合。许多想法汇集在一起，才产生了新计划。", "分开": "语义：“分开”与“在一起”相矛盾，想法不能分开在一起。", "遗忘": "搭配：“遗忘在一起”不成立，“遗忘”是忘记，不能与“在一起”组合。", "拆散": "语义：“拆散”表示拆开，与“在一起”以及“才有了新的计划”的意思相反。"}, "sentence_index": 6, "correct_answer": "聚合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察把闹事的人群聚合开，维持了秩序。", "explanation": "这里应该用〈驱散〉。聚合是把分散的事物合在一起，把人群赶开要说驱散。"}, {"text": "这块大西瓜被他聚合成了八小块。", "explanation": "这里应该用〈切〉。聚合是合在一起，把西瓜切成小块要说切。"}, {"text": "他把一本厚书聚合成了三册。", "explanation": "这里应该用〈分册〉。聚合是合并，把一本书分成三册要说分册。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些零散的材料最后聚合了一个整体。", "corrected_sentence": "这些零散的材料最后聚合成了一个整体。", "error_description": "补语缺失：“聚合”后要用“成”引出结果，应说“聚合成了一个整体”，不能省去“成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把各组的数据聚合了成一张表。", "corrected_sentence": "他把各组的数据聚合成了一张表。", "error_description": "“了”位置错：“聚合”后要先接结果补语“成”，“了”放在“成”之后，应说“聚合成了一张表”，不能说“聚合了成一张表”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
