INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12960, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "单体通过多次缩合反应形成高分子，同时生成小分子副产物（如水、氨等）的聚合反应。", "primary_collocate": null, "pronunciation": "suō jù", "ipa": "swo˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "例如，PLA源自可再生资源如玉米淀粉，其聚合过程通过催化缩聚完成，而其降解则需在高温高湿的堆肥环境中由嗜热菌群高效分解。", "target_word": "缩聚", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这两种单体在高温下发生缩聚，生成尼龙。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "单体缩聚时会放出水。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对苯二甲酸和乙二醇缩聚后得到涤纶。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缩聚和加聚不一样，缩聚会产生小分子。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验中，小分子慢慢缩聚成了大分子。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师让原料在真空里缩聚，把水排走。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缩聚时要不断除去生成的水。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酚和甲醛缩聚后可以得到酚醛树脂。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度太低，单体很难缩聚。", "target_word": "缩聚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缩聚了", "label": "体标"}, {"form": "缩聚反应", "label": "复合"}, {"form": "缩聚物", "label": "复合"}], "register": "科技", "sense_fingerprint": "单体多次缩合成高分子并生成水、氨等小分子的聚合反应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e12ecc-3ac0-4aa7-b224-954d9d880c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12960, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缩聚", "is_correct": true, "explanation": "与“催化”搭配，指单体多次缩合生成高分子并放出小分子，和前文的“聚合过程”相符。"}, {"text": "缩短", "is_correct": false, "explanation": "语义：“缩短”指长度或时间变短，不是化学反应，不能被“催化”。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“催化”只用于化学反应，不能说“催化讨论”。"}, {"text": "登记", "is_correct": false, "explanation": "搭配：“登记”指备案记录，与“催化”及化学过程不相容。"}], "explanations": {"缩聚": "与“催化”搭配，指单体多次缩合生成高分子并放出小分子，和前文的“聚合过程”相符。", "缩短": "语义：“缩短”指长度或时间变短，不是化学反应，不能被“催化”。", "讨论": "搭配：“催化”只用于化学反应，不能说“催化讨论”。", "登记": "搭配：“登记”指备案记录，与“催化”及化学过程不相容。"}, "sentence_index": 0, "correct_answer": "缩聚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "乙烯在催化剂作用下缩聚，生成聚乙烯。", "explanation": "这里应该用〈加聚〉。乙烯加聚时不放出小分子，缩聚必须放出水、氨等小分子，所以这里不能用缩聚。"}, {"text": "乙醇和乙酸在浓硫酸作用下缩聚，生成乙酸乙酯。", "explanation": "这里应该用〈酯化〉。乙酸乙酯是简单的小分子，不是高分子，缩聚只用于生成高分子的反应。"}, {"text": "胶体粒子在溶液里缩聚成团。", "explanation": "这里应该用〈凝聚〉。胶粒聚集成团是物理过程，不是单体缩合成高分子的化学反应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缩聚", "is_correct": true, "explanation": "与“把水排走”呼应，缩聚时要放出水，所以工程师要把水排走。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：原料不能唱歌，“让原料在真空里唱歌”与化工操作的语境不搭。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：真空里缺少氧气，无法点燃，与“把水排走”的化工操作语境冲突。"}, {"text": "散步", "is_correct": false, "explanation": "语义：原料不能自己散步，“散步”只用于人或动物，与化工操作不符。"}], "explanations": {"缩聚": "与“把水排走”呼应，缩聚时要放出水，所以工程师要把水排走。", "唱歌": "搭配：原料不能唱歌，“让原料在真空里唱歌”与化工操作的语境不搭。", "点燃": "语义：真空里缺少氧气，无法点燃，与“把水排走”的化工操作语境冲突。", "散步": "语义：原料不能自己散步，“散步”只用于人或动物，与化工操作不符。"}, "sentence_index": 6, "correct_answer": "缩聚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "聚酯在高温高湿下缩聚，断成小分子。", "explanation": "这里应该用〈水解〉。水解使大分子断裂成小分子，缩聚则是小分子连成大分子，方向相反。"}, {"text": "浓硫酸能让蔗糖缩聚，变成黑色的炭。", "explanation": "这里应该用〈脱水〉。浓硫酸夺去蔗糖中的氢和氧，使其变成炭，并没有生成高分子，所以不能用缩聚。"}, {"text": "面团在温暖的地方缩聚，慢慢变大。", "explanation": "这里应该用〈发酵〉。面团变大靠酵母等微生物的发酵，不是化学缩聚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两种小分子在高温下缩聚一种大分子。", "corrected_sentence": "这两种小分子在高温下缩聚成一种大分子。", "error_description": "“缩聚”后缺少结果补语“成”。应说“缩聚成……”，表示生成的产物；直接接“一种大分子”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "实验员让单体在高温下了缩聚，生成了新的树脂。", "corrected_sentence": "实验员让单体在高温下缩聚，生成了新的树脂。", "error_description": "了的位置错误：“了”是动态助词，应放在动词后，不能插在“在高温下”和“缩聚”之间。应说“在高温下缩聚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12961, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低温", "is_correct": true, "explanation": "与“高温”构成反义，指气温低，与“高温”相对。"}, {"text": "湿度", "is_correct": false, "explanation": "“湿度”指空气湿润程度，与“高温”不构成反义。"}, {"text": "风力", "is_correct": false, "explanation": "“风力”指风的强弱，与“高温”不是反义关系。"}, {"text": "降水", "is_correct": false, "explanation": "“降水”指降落的雨雪等，与“高温”不构成反义。"}], "correct_answer": "低温", "explanations": {"低温": "与“高温”构成反义，指气温低，与“高温”相对。", "湿度": "“湿度”指空气湿润程度，与“高温”不构成反义。", "风力": "“风力”指风的强弱，与“高温”不是反义关系。", "降水": "“降水”指降落的雨雪等，与“高温”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12961, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低温", "is_correct": true, "explanation": "与“高温”构成反义，指气温低，与“高温”相对。"}, {"text": "气压", "is_correct": false, "explanation": "“气压”指大气的压力，与“高温”不构成反义。"}, {"text": "风速", "is_correct": false, "explanation": "“风速”指风的快慢，与“高温”不是反义关系。"}, {"text": "雾霾", "is_correct": false, "explanation": "“雾霾”指空气污染现象，与“高温”不构成反义。"}], "correct_answer": "低温", "explanations": {"低温": "与“高温”构成反义，指气温低，与“高温”相对。", "气压": "“气压”指大气的压力，与“高温”不构成反义。", "风速": "“风速”指风的快慢，与“高温”不是反义关系。", "雾霾": "“雾霾”指空气污染现象，与“高温”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12961, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "气温很高，指天气炎热，温度在摄氏35度以上。", "primary_collocate": null, "pronunciation": "gāo wēn", "ipa": "kaʊ˥ wən˥", "syllable_count": 2, "sentences": [{"text": "夏季在高温高湿的天气里长时间劳作，人体的散热效率会明显下降，中暑风险随之增加。", "target_word": "高温", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "今天的高温超过三十五度，大家都不想出门。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天高温的时候，我常常喝很多水。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市夏天经常有高温。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为高温，学校今天下午不上课。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高温天气里，老人最好待在家里。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报说明天有高温，出门要带水。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连续一周的高温让路边的花都枯了。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在高温下工作了一整天，累极了。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高温预警发布后，公园里的人少多了。", "target_word": "高温", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高温天气", "label": "复合"}, {"form": "高温预警", "label": "复合"}, {"form": "高溫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "气温很高、天气炎热，摄氏35度以上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e12ecc-3ac0-4aa7-b224-954d9d880c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12961, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高温", "is_correct": true, "explanation": "正确答案：高温。“高温高湿”是常见的天气组合，指气温高、湿度大。"}, {"text": "低温", "is_correct": false, "explanation": "语义：低温天气不会让散热效率下降，与句意矛盾。"}, {"text": "湿度", "is_correct": false, "explanation": "搭配：“湿度高湿”重复，不能与“高湿”并列修饰天气。"}, {"text": "雨量", "is_correct": false, "explanation": "搭配：“雨量”指降水多少，不能用“高湿”来修饰。"}], "explanations": {"高温": "正确答案：高温。“高温高湿”是常见的天气组合，指气温高、湿度大。", "低温": "语义：低温天气不会让散热效率下降，与句意矛盾。", "湿度": "搭配：“湿度高湿”重复，不能与“高湿”并列修饰天气。", "雨量": "搭配：“雨量”指降水多少，不能用“高湿”来修饰。"}, "sentence_index": 0, "correct_answer": "高温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影的高温部分特别精彩。", "explanation": "这里应该用〈高潮〉。“高潮”指情节最激烈、最精彩的部分，“高温”只指气温，不能用来说电影的情节。"}, {"text": "我明年要参加高温，压力很大。", "explanation": "这里应该用〈高考〉。“高考”是考试，“高温”只指天气，不能用来说参加考试。"}, {"text": "这份合同的高温条款写得很清楚。", "explanation": "这里应该用〈违约〉。“高温”只指天气炎热，合同条款要说“违约”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12961, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高温", "is_correct": true, "explanation": "与“出门要带水”相符，天气预报说明天天气炎热。"}, {"text": "寒潮", "is_correct": false, "explanation": "语义：寒潮是降温天气，与“出门要带水”的炎热情境矛盾。"}, {"text": "暴雪", "is_correct": false, "explanation": "语义：暴雪天气与“出门要带水”的炎热情境不符，句意冲突。"}, {"text": "冰雹", "is_correct": false, "explanation": "语义：冰雹是寒冷的强对流天气，与“出门要带水”的炎热情境不符。"}], "explanations": {"高温": "与“出门要带水”相符，天气预报说明天天气炎热。", "寒潮": "语义：寒潮是降温天气，与“出门要带水”的炎热情境矛盾。", "暴雪": "语义：暴雪天气与“出门要带水”的炎热情境不符，句意冲突。", "冰雹": "语义：冰雹是寒冷的强对流天气，与“出门要带水”的炎热情境不符。"}, "sentence_index": 6, "correct_answer": "高温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下班高温时，地铁里特别挤。", "explanation": "这里应该用〈高峰〉。“高峰”指人流最多的时段，地铁拥挤说“下班高峰”，“高温”指天气热。"}, {"text": "他是这家公司的高温经理。", "explanation": "这里应该用〈高级〉。“高级”说职位或等级，“高温”只说温度，不能修饰“经理”。"}, {"text": "他的考试成绩是全班的高温。", "explanation": "这里应该用〈最高分〉。“高温”只指气温，不能用来说成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12961, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只高温让我们都不敢出门。", "corrected_sentence": "这场高温让我们都不敢出门。", "error_description": "量词错误：天气现象用量词“场”，“只”一般用于动物，不能用来数“高温”。应说“这场高温”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12961, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "因为高温的，学校停了课。", "corrected_sentence": "因为高温，学校停了课。", "error_description": "多了“的”：“高温的”后缺少中心语，放在“因为”后不成立。应直接说“因为高温”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
