INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12962, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指空气中含有大量水蒸气，湿度很高的状态。", "primary_collocate": null, "pronunciation": "gāo shī", "ipa": "kaʊ˥ ʂɨ˥", "syllable_count": 2, "sentences": [{"text": "例如，PLA源自可再生资源如玉米淀粉，其聚合过程通过催化缩聚完成，而其降解则需在高温高湿的堆肥环境中由嗜热菌群高效分解。", "target_word": "高湿", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这里春天常常高湿，墙上会出水。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高湿的环境里，食物很容易坏。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下室一直高湿，毛巾总是不干。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高湿的天气让木头家具变形了。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在高湿的房间里，衣服几天都干不了。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器怕高湿，所以要放在干燥的地方。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高湿的季节，墙角容易长霉。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说高湿的空气对关节不好。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个仓库高湿，粮食要放在高处。", "target_word": "高湿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高湿度", "label": "复合"}, {"form": "高温高湿", "label": "复合"}, {"form": "高濕", "label": "繁体"}], "register": "中性", "sense_fingerprint": "空气中水蒸气多、湿度很高的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e12ecc-3ac0-4aa7-b224-954d9d880c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12962, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高湿", "is_correct": true, "explanation": "正确：高湿（gāo shī）指空气中水蒸气多，湿度很高。"}, {"text": "高士", "is_correct": false, "explanation": "gāo 不变，shì 与 shī 只差声调（第四声与第一声），意思是高尚的人。"}, {"text": "告示", "is_correct": false, "explanation": "gào 与 gāo 声调不同，shì 与 shī 声调不同，意思是告示。"}, {"text": "搞事", "is_correct": false, "explanation": "gǎo 与 gāo、shì 与 shī 只差声调，意思是故意惹麻烦。"}], "explanations": {"高湿": "正确：高湿（gāo shī）指空气中水蒸气多，湿度很高。", "高士": "gāo 不变，shì 与 shī 只差声调（第四声与第一声），意思是高尚的人。", "告示": "gào 与 gāo 声调不同，shì 与 shī 声调不同，意思是告示。", "搞事": "gǎo 与 gāo、shì 与 shī 只差声调，意思是故意惹麻烦。"}, "sentence_index": null, "correct_answer": "高湿"}, "level_3": {"options": [{"text": "高湿", "is_correct": true, "explanation": "正确：高湿描述空气湿度高，与同句的“高温”共同描述堆肥环境。"}, {"text": "清凉", "is_correct": false, "explanation": "语义：同句已说“高温”，清凉的环境与之矛盾。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：同句说“高温”，堆肥环境不会寒冷，与语境矛盾。"}, {"text": "稀薄", "is_correct": false, "explanation": "搭配：“稀薄”指空气稀少，不说堆肥环境稀薄，与“高温”的描述不合。"}], "explanations": {"高湿": "正确：高湿描述空气湿度高，与同句的“高温”共同描述堆肥环境。", "清凉": "语义：同句已说“高温”，清凉的环境与之矛盾。", "寒冷": "语义：同句说“高温”，堆肥环境不会寒冷，与语境矛盾。", "稀薄": "搭配：“稀薄”指空气稀少，不说堆肥环境稀薄，与“高温”的描述不合。"}, "sentence_index": 0, "correct_answer": "高湿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很高湿，晾了一天还没干。", "explanation": "这里应该用〈潮湿〉。高湿只描述空气的湿度，衣服沾了水要说〈潮湿〉。"}, {"text": "她哭了很久，眼睛很高湿。", "explanation": "这里应该用〈湿润〉。高湿不用来形容眼睛，眼睛里的水汽要说〈湿润〉。"}, {"text": "他的头发很高湿，还在滴水。", "explanation": "这里应该用〈湿漉漉〉。高湿指空气的湿度，头发沾水要说〈湿漉漉〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12962, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "高湿", "is_correct": true, "explanation": "正确：高湿（gāo shī）指空气中水蒸气多，湿度很高。"}, {"text": "干湿", "is_correct": false, "explanation": "gān 与 gāo 韵母不同（an 与 ao），shī 不变，意思是干和湿。"}, {"text": "高枝", "is_correct": false, "explanation": "zhī 与 shī 声母不同（zh 与 sh），gāo 不变，意思是高处的树枝。"}, {"text": "干事", "is_correct": false, "explanation": "gàn 与 gāo 韵母和声调不同，shì 与 shī 声调不同，意思是工作人员。"}], "explanations": {"高湿": "正确：高湿（gāo shī）指空气中水蒸气多，湿度很高。", "干湿": "gān 与 gāo 韵母不同（an 与 ao），shī 不变，意思是干和湿。", "高枝": "zhī 与 shī 声母不同（zh 与 sh），gāo 不变，意思是高处的树枝。", "干事": "gàn 与 gāo 韵母和声调不同，shì 与 shī 声调不同，意思是工作人员。"}, "sentence_index": null, "correct_answer": "高湿"}, "level_3": {"options": [{"text": "高湿", "is_correct": true, "explanation": "正确：机器怕高湿，所以要放在干燥的地方，前后语义一致。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：后句说“放在干燥的地方”，若说机器怕干燥，前后矛盾。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容表面质感，不说机器怕粗糙。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：机器怕明亮与前后语境都不相关，不合常理。"}], "explanations": {"高湿": "正确：机器怕高湿，所以要放在干燥的地方，前后语义一致。", "干燥": "语义：后句说“放在干燥的地方”，若说机器怕干燥，前后矛盾。", "粗糙": "搭配：“粗糙”形容表面质感，不说机器怕粗糙。", "明亮": "语义：机器怕明亮与前后语境都不相关，不合常理。"}, "sentence_index": 6, "correct_answer": "高湿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯咖啡很高湿，喝起来很甜。", "explanation": "这里应该用〈浓〉。高湿只描述空气或环境的湿度，不用来形容饮料的浓淡。"}, {"text": "他今天高湿得很，一句话也不说。", "explanation": "这里应该用〈闷〉。高湿只指空气或环境的湿度，形容人的情绪和状态要用〈闷〉。"}, {"text": "这座山很高湿，我们爬了很久。", "explanation": "这里应该用〈高大〉。高湿指湿度大，不指高度；说山很高要用〈高大〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天的仓库被高湿，要常开门通风。", "corrected_sentence": "夏天的仓库高湿，要常开门通风。", "error_description": "错误：“被高湿”。正确：“高湿”。“被”字句要求后面接动词，不能直接接形容词“高湿”；“高湿”作谓语时前面不加“被”，直接说“仓库高湿”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个仓库高湿度，粮食容易坏。", "corrected_sentence": "这个仓库高湿，粮食容易坏。", "error_description": "词类错误：“高湿度”是名词，不能直接作谓语。作谓语应说“仓库高湿”，不说“仓库高湿度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa4217b-4928-4b3d-b514-21ac69746120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12965, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "与“聚集”相对，指分开、散开，是“共聚”这一义项的反义词。"}, {"text": "出发", "is_correct": false, "explanation": "指动身离开，与“共聚”没有反义关系。"}, {"text": "阅读", "is_correct": false, "explanation": "指看书或文字，与“聚集”的意思无反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "指入睡休息，与“共聚”没有反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "与“聚集”相对，指分开、散开，是“共聚”这一义项的反义词。", "出发": "指动身离开，与“共聚”没有反义关系。", "阅读": "指看书或文字，与“聚集”的意思无反义关系。", "睡觉": "指入睡休息，与“共聚”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
