INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12965, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指许多人或事物聚集到一起，形成一个整体。", "primary_collocate": null, "pronunciation": "gòng jù", "ipa": "kʊŋ˥˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "这次学术会议吸引了来自各国的学者共聚一堂，共同探讨材料科学的最新突破。", "target_word": "共聚", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "来自各地的朋友都在北京共聚。", "target_word": "共聚", "complexity_tier": "T3", "furigana": "gòng jù", "sentence_source": "generated"}, {"text": "世界各国的运动员共聚一堂。", "target_word": "共聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大会期间，很多专家共聚在这座城市。", "target_word": "共聚", "complexity_tier": "T3", "furigana": "gòng jù", "sentence_source": "generated"}, {"text": "百年校庆，很多校友共聚一堂。", "target_word": "共聚", "complexity_tier": "T3", "furigana": "gòng jù", "sentence_source": "generated"}, {"text": "同学们十年后再次共聚一堂。", "target_word": "共聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们约好周末在公园共聚。", "target_word": "共聚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年夏天，大家在海边共聚过一次。", "target_word": "共聚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各地的代表昨天共聚在上海开会。", "target_word": "共聚", "complexity_tier": "T3", "furigana": "gòng jù", "sentence_source": "generated"}, {"text": "新年到了，全家人共聚一堂。", "target_word": "共聚", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "共聚了", "label": "完成体"}, {"form": "共聚过", "label": "经历体"}, {"form": "共聚一堂", "label": "固定短语"}], "register": "书面语", "sense_fingerprint": "许多人或事物聚集到一起形成整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29ae13fa-e2f6-4de8-a72a-3575f717bdf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12965, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "共聚", "is_correct": true, "explanation": "gòng jù（第四声）指许多人或事物聚集到一起。"}, {"text": "工具", "is_correct": false, "explanation": "gōng jù（第一声）与 gòng jù（第四声）声调不同，意思是工具。"}, {"text": "共居", "is_correct": false, "explanation": "gòng jū 与 gòng jù 第二音节声调不同（第一声与第四声），意思是住在一起。"}, {"text": "共计", "is_correct": false, "explanation": "gòng jì 与 gòng jù 韵母不同（i 与 ü），意思是总计。"}], "explanations": {"共聚": "gòng jù（第四声）指许多人或事物聚集到一起。", "工具": "gōng jù（第一声）与 gòng jù（第四声）声调不同，意思是工具。", "共居": "gòng jū 与 gòng jù 第二音节声调不同（第一声与第四声），意思是住在一起。", "共计": "gòng jì 与 gòng jù 韵母不同（i 与 ü），意思是总计。"}, "sentence_index": null, "correct_answer": "共聚"}, "level_3": {"options": [{"text": "共聚", "is_correct": true, "explanation": "正确。此处指许多学者聚到一起，与“来自各国的学者”的语境相合。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪与学术会议的语境不符，“学者烹饪一堂”说不通。"}, {"text": "收成", "is_correct": false, "explanation": "搭配：“收成”指农作物的产量，不能与“学者”搭配。"}, {"text": "园艺", "is_correct": false, "explanation": "语义：园艺指种植花木，与学术会议的语境冲突。"}], "explanations": {"共聚": "正确。此处指许多学者聚到一起，与“来自各国的学者”的语境相合。", "烹饪": "语义：烹饪与学术会议的语境不符，“学者烹饪一堂”说不通。", "收成": "搭配：“收成”指农作物的产量，不能与“学者”搭配。", "园艺": "语义：园艺指种植花木，与学术会议的语境冲突。"}, "sentence_index": 0, "correct_answer": "共聚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在会上共聚了很多经验。", "explanation": "这里应该用〈分享〉。“共聚”指许多人或事物聚到一起，不表示把经验交给别人，经验要说“分享”。"}, {"text": "他一个人共聚在房间里看书。", "explanation": "这里应该用〈独自〉。“共聚”要求多个人或事物聚在一起，单独一人不能说“共聚”。"}, {"text": "代表们共聚了各自的意见。", "explanation": "这里应该用〈交换〉。“共聚”只说人或事物聚到一处，不带“意见”这类抽象宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12965, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "共聚", "is_correct": true, "explanation": "gòng jù（第四声）指许多人或事物聚集到一起。"}, {"text": "工具", "is_correct": false, "explanation": "gōng jù（第一声）与 gòng jù（第四声）声调不同，意思是工具。"}, {"text": "功绩", "is_correct": false, "explanation": "gōng jì（第一声）与 gòng jù：第一音节声调不同，第二音节韵母不同，意思是功绩。"}, {"text": "供给", "is_correct": false, "explanation": "gōng jǐ（第三声）与 gòng jù：声调和韵母都有不同，意思是供给。"}], "explanations": {"共聚": "gòng jù（第四声）指许多人或事物聚集到一起。", "工具": "gōng jù（第一声）与 gòng jù（第四声）声调不同，意思是工具。", "功绩": "gōng jì（第一声）与 gòng jù：第一音节声调不同，第二音节韵母不同，意思是功绩。", "供给": "gōng jǐ（第三声）与 gòng jù：声调和韵母都有不同，意思是供给。"}, "sentence_index": null, "correct_answer": "共聚"}, "level_3": {"options": [{"text": "共聚", "is_correct": true, "explanation": "“共聚”表示许多人聚在一起，与“约好周末在公园”的语境相合。"}, {"text": "施工", "is_correct": false, "explanation": "语义：施工指建造或修建工程，与“约好周末在公园”的聚会语境冲突。"}, {"text": "分配", "is_correct": false, "explanation": "配价：“分配”需要带宾语，句中缺少“任务”之类的宾语，无法成立。"}, {"text": "结账", "is_correct": false, "explanation": "语义：结账需要店铺和账单，与“在公园”的语境不符。"}], "explanations": {"共聚": "“共聚”表示许多人聚在一起，与“约好周末在公园”的语境相合。", "施工": "语义：施工指建造或修建工程，与“约好周末在公园”的聚会语境冲突。", "分配": "配价：“分配”需要带宾语，句中缺少“任务”之类的宾语，无法成立。", "结账": "语义：结账需要店铺和账单，与“在公园”的语境不符。"}, "sentence_index": 6, "correct_answer": "共聚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场雨共聚了三天。", "explanation": "这里应该用〈持续〉。“共聚”指许多人或事物聚到一起，不能用来说时间的延续，表示雨一直下要用“持续”。"}, {"text": "我们共聚了一场比赛。", "explanation": "这里应该用〈举办〉。“共聚”不能带“比赛”作宾语。"}, {"text": "一个苹果共聚在桌上。", "explanation": "这里应该用〈放〉。“共聚”要求多个人或事物，单个物体不能说“共聚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12965, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天中午，老同学们在茶馆共聚了。", "corrected_sentence": "明天中午，老同学们在茶馆共聚。", "error_description": "“了”用错了。“明天中午”是还没发生的事，不能在“共聚”后用表示完成的“了”，应去掉“了”，说“在茶馆共聚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12965, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上个月，老师们在会议室共聚过一次过。", "corrected_sentence": "上个月，老师们在会议室共聚过一次。", "error_description": "“过”多用了一个。“过”紧跟动词“共聚”表示经历，句末再加“过”是重复，正确说法是“共聚过一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
