INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12967, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "纳米是长度单位，符号为nm，1纳米等于十亿分之一米，常用于描述微观世界的尺度。", "primary_collocate": null, "pronunciation": "nà mǐ", "ipa": "na˥˩ mi˨˩˦", "syllable_count": 2, "sentences": [{"text": "材料科学的突破不仅体现在单体选择与共聚技术上，更延伸至纳米复合改性、表面功能化与降解速率调控等深层维度。", "target_word": "纳米", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "一纳米等于十亿分之一米。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "纳米的符号是nm。", "target_word": "纳米", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "头发丝的宽度有几万纳米。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病毒的大小只有几十纳米。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家用纳米来量很小的东西。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这层膜只有一百纳米厚。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一米等于十亿纳米。", "target_word": "纳米", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们看不见纳米那么小的东西。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，纳米是长度单位。", "target_word": "纳米", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "纳米技术", "label": "复合词"}, {"form": "纳米材料", "label": "复合词"}, {"form": "纳米级", "label": "复合词"}, {"form": "納米", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长度单位，十亿分之一米，描述微观尺度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29ae13fa-e2f6-4de8-a72a-3575f717bdf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12967, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纳米", "is_correct": true, "explanation": "“纳米”作定语，修饰“复合改性”，表示纳米尺度的复合改性。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪与材料科学的语境不符，“烹饪复合改性”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不能修饰“复合改性”，两者搭配不当。"}, {"text": "园艺", "is_correct": false, "explanation": "语义：园艺指种植花木，与句中的材料改性语境冲突。"}], "explanations": {"纳米": "“纳米”作定语，修饰“复合改性”，表示纳米尺度的复合改性。", "烹饪": "语义：烹饪与材料科学的语境不符，“烹饪复合改性”说不通。", "体重": "搭配：“体重”不能修饰“复合改性”，两者搭配不当。", "园艺": "语义：园艺指种植花木，与句中的材料改性语境冲突。"}, "sentence_index": 0, "correct_answer": "纳米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根头发只有几万只纳米粗。", "explanation": "这里应该用〈直接放数量〉。“纳米”作长度单位，前面不用“只”，应说“几万纳米”。"}, {"text": "这袋米重三纳米。", "explanation": "这里应该用〈克〉或〈千克〉。“纳米”是长度单位，不能用来表示重量。"}, {"text": "我们等了三纳米才轮到我。", "explanation": "这里应该用〈分钟〉。“纳米”是长度单位，不能用来计时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12967, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纳米", "is_correct": true, "explanation": "“纳米”是长度单位，与“只有一百……厚”的数量搭配相合。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”不能用来表示厚度，与“厚”的语义冲突。"}, {"text": "高度", "is_correct": false, "explanation": "搭配：“一百高度厚”不成词组，“高度”不能直接接在数量后作厚度。"}, {"text": "体积", "is_correct": false, "explanation": "语义：“体积”指立体空间大小，不能表示薄膜的厚度。"}], "explanations": {"纳米": "“纳米”是长度单位，与“只有一百……厚”的数量搭配相合。", "重量": "语义：“重量”不能用来表示厚度，与“厚”的语义冲突。", "高度": "搭配：“一百高度厚”不成词组，“高度”不能直接接在数量后作厚度。", "体积": "语义：“体积”指立体空间大小，不能表示薄膜的厚度。"}, "sentence_index": 6, "correct_answer": "纳米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我买了三纳米的布。", "explanation": "这里应该用〈尺〉。“纳米”只用于极微小的长度，不能用来量布料。"}, {"text": "我们从北京到上海走了三纳米。", "explanation": "这里应该用〈公里〉。“纳米”只用于很小的长度，不能说路程。"}, {"text": "这个苹果有三百纳米重。", "explanation": "这里应该用〈克〉。“纳米”是长度单位，不能用来表示重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种膜只有几十只纳米厚。", "corrected_sentence": "这种膜只有几十纳米厚。", "error_description": "“纳米”前面不能加“只”。作长度单位时，数量直接放在前面，应为“几十纳米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12967, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根线只有几十个纳米粗。", "corrected_sentence": "这根线只有几十纳米粗。", "error_description": "“纳米”作长度单位，前面不能加量词“个”，数量词直接放在前面，应为“几十纳米粗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
