INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12968, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指两种或两种以上的材料结合起来形成一个整体。", "primary_collocate": null, "pronunciation": "fù hé", "ipa": "fu˥˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "材料科学的突破不仅体现在单体选择与共聚技术上，更延伸至纳米复合改性、表面功能化与降解速率调控等深层维度。", "target_word": "复合", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这块板由两层材料复合而成。", "target_word": "复合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两种金属复合在一起会更结实。", "target_word": "复合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把布和塑料复合起来。", "target_word": "复合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种纸是用三层纸复合的。", "target_word": "复合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玻璃和塑料复合后，不容易碎。", "target_word": "复合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "棉和丝复合后，衣服又软又暖。", "target_word": "复合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厂里正在试着复合两种新材料。", "target_word": "复合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个小零件复合成一个整体。", "target_word": "复合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几种材料复合以后，做成的板子又轻又薄。", "target_word": "复合", "complexity_tier": "T3", "furigana": "fù hé", "sentence_source": "generated"}], "morphological_forms": [{"form": "复合了", "label": "完成体"}, {"form": "复合过", "label": "经历体"}, {"form": "复合材料", "label": "复合词"}, {"form": "複合", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "两种或多种材料结合成一个整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29ae13fa-e2f6-4de8-a72a-3575f717bdf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12968, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "复合", "is_correct": true, "explanation": "正确答案。复合（fù hé）指把几个部分结合成一个整体。"}, {"text": "符合", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，意思是与标准或事实相合。"}, {"text": "附和", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）声调不同，意思是跟着别人说相同的话。"}, {"text": "不合", "is_correct": false, "explanation": "bù 与 fù 声母不同（b 与 f），意思是不相合、不合适。"}], "explanations": {"复合": "正确答案。复合（fù hé）指把几个部分结合成一个整体。", "符合": "fú（第二声）与 fù（第四声）声调不同，意思是与标准或事实相合。", "附和": "hè（第四声）与 hé（第二声）声调不同，意思是跟着别人说相同的话。", "不合": "bù 与 fù 声母不同（b 与 f），意思是不相合、不合适。"}, "sentence_index": null, "correct_answer": "复合"}, "level_3": {"options": [{"text": "复合", "is_correct": true, "explanation": "正确。纳米复合改性指把不同材料组合起来以改变其性质，符合句意。"}, {"text": "分离", "is_correct": false, "explanation": "语义：“分离”是使分开，与改性所需的组合方向相反，句意不通。"}, {"text": "分解", "is_correct": false, "explanation": "搭配：“分解”多指把物质拆成成分，不说“纳米分解改性”。"}, {"text": "拆分", "is_correct": false, "explanation": "语义：“拆分”是拆开，与深层改性的组合方向相反，句意不通。"}], "explanations": {"复合": "正确。纳米复合改性指把不同材料组合起来以改变其性质，符合句意。", "分离": "语义：“分离”是使分开，与改性所需的组合方向相反，句意不通。", "分解": "搭配：“分解”多指把物质拆成成分，不说“纳米分解改性”。", "拆分": "语义：“拆分”是拆开，与深层改性的组合方向相反，句意不通。"}, "sentence_index": 0, "correct_answer": "复合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司把两个部门复合了。", "explanation": "这里应该用〈合并〉。复合多指材料、物质的组合，公司部门的归并要用合并。"}, {"text": "这种方法把理论和实践复合起来。", "explanation": "这里应该用〈结合〉。复合多指材料、物质的组合，理论与实践这类抽象内容要用结合。"}, {"text": "这两种文化在这里复合了。", "explanation": "这里应该用〈融合〉。复合指把部件合成整体，文化之间的交汇要用融合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "复合", "is_correct": true, "explanation": "正确。棉和丝复合后，指两种纤维合成一体，句意通顺。"}, {"text": "分开", "is_correct": false, "explanation": "语义：“分开”表示分离，与纤维合成后衣服变暖的意思相反。"}, {"text": "切碎", "is_correct": false, "explanation": "搭配：“切碎”多用于食物或物料，不说“棉和丝切碎后”。"}, {"text": "剪断", "is_correct": false, "explanation": "搭配：“剪断”指剪开、切断，不能与“棉和丝”表示的合成结果搭配。"}], "explanations": {"复合": "正确。棉和丝复合后，指两种纤维合成一体，句意通顺。", "分开": "语义：“分开”表示分离，与纤维合成后衣服变暖的意思相反。", "切碎": "搭配：“切碎”多用于食物或物料，不说“棉和丝切碎后”。", "剪断": "搭配：“剪断”指剪开、切断，不能与“棉和丝”表示的合成结果搭配。"}, "sentence_index": 6, "correct_answer": "复合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两条河在这里复合了。", "explanation": "这里应该用〈汇合〉。复合指把几个部分合成一个整体，河流汇到一处要用汇合。"}, {"text": "这支球队复合得很好。", "explanation": "这里应该用〈配合〉。复合多指材料、物质的组合，球队成员协同做事要用配合。"}, {"text": "几个国家复合起来抗议了。", "explanation": "这里应该用〈联合〉。复合指部件组合成整体，团体之间的联合行动要用联合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两种纤维复合一起，布料更耐用。", "corrected_sentence": "这两种纤维复合在一起，布料更耐用。", "error_description": "“复合”表示把几部分合成整体，后面要接“在一起”。漏掉“在”会说成“复合一起”，应为“复合在一起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两种薄膜复合起去，包装更牢固。", "corrected_sentence": "这两种薄膜复合起来，包装更牢固。", "error_description": "“复合起来”中的“来”表示结果是合成一体，不能说“起去”，应为“复合起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
