INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12969, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "改变材料原有的性质或形态。", "primary_collocate": null, "pronunciation": "gǎi xìng", "ipa": "kai̯˨˩˦ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "材料科学的突破不仅体现在单体选择与共聚技术上，更延伸至纳米复合改性、表面功能化与降解速率调控等深层维度。", "target_word": "改性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种塑料经过改性，变得更结实了。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改性可以让橡胶更耐热。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂对这种材料做了改性处理。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门做塑料改性。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改性后的塑料不容易裂开。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料的改性方法很简单。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做过改性的纸，放在水里也不会烂。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室正在研究木材的改性。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改性的目的是让材料更耐用。", "target_word": "改性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改性剂", "label": "复合词"}, {"form": "改性塑料", "label": "复合词"}, {"form": "改性处理", "label": "复合词"}], "register": "科技书面语", "sense_fingerprint": "改变材料原有的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29ae13fa-e2f6-4de8-a72a-3575f717bdf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12969, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "改性", "is_correct": true, "explanation": "正确答案。改性（gǎi xìng）指改变材料原有的性质。"}, {"text": "改型", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，意思是改变型号或样式。"}, {"text": "改进", "is_correct": false, "explanation": "gǎi jìn 与 gǎi xìng 第二音节声母、韵母都不同（j/x，in/ing），意思是改良提高。"}, {"text": "改信", "is_correct": false, "explanation": "xìn 与 xìng 韵尾不同（n 与 ng），意思是改变信仰或信念。"}], "explanations": {"改性": "正确答案。改性（gǎi xìng）指改变材料原有的性质。", "改型": "xíng（第二声）与 xìng（第四声）声调不同，意思是改变型号或样式。", "改进": "gǎi jìn 与 gǎi xìng 第二音节声母、韵母都不同（j/x，in/ing），意思是改良提高。", "改信": "xìn 与 xìng 韵尾不同（n 与 ng），意思是改变信仰或信念。"}, "sentence_index": null, "correct_answer": "改性"}, "level_3": {"options": [{"text": "改性", "is_correct": true, "explanation": "正确。纳米复合改性指通过复合来改变材料的性质，符合句意。"}, {"text": "污染", "is_correct": false, "explanation": "语义：“污染”是负面状况，不能作为与“表面功能化”并列的研究方向，句意不通。"}, {"text": "礼仪", "is_correct": false, "explanation": "语义：礼仪属社会行为规范，与材料科学的研究维度不相干。"}, {"text": "腐蚀", "is_correct": false, "explanation": "搭配：“纳米复合腐蚀”搭配不当，腐蚀是材料受损，不是要进行的研究操作。"}], "explanations": {"改性": "正确。纳米复合改性指通过复合来改变材料的性质，符合句意。", "污染": "语义：“污染”是负面状况，不能作为与“表面功能化”并列的研究方向，句意不通。", "礼仪": "语义：礼仪属社会行为规范，与材料科学的研究维度不相干。", "腐蚀": "搭配：“纳米复合腐蚀”搭配不当，腐蚀是材料受损，不是要进行的研究操作。"}, "sentence_index": 0, "correct_answer": "改性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他经过改性，变得更开朗了。", "explanation": "这里应该用〈改造〉。改性用于改变材料等物质的性质，人的思想性格的转变要用改造。"}, {"text": "这家餐厅改性了服务质量。", "explanation": "这里应该用〈改善〉。改性指改变材料的性质，服务和质量的提升要用改善。"}, {"text": "这座老房子经过改性，变得更漂亮了。", "explanation": "这里应该用〈改建〉。改性用于材料的性质改变，房屋的翻修要用改建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12969, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改性", "is_correct": true, "explanation": "正确。这种材料的改性方法指改变材料性质的方法，句意通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是外观属性，不是加工方法，“颜色方法”句意不通。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”是属性，不是可以采用的方法，与“方法很简单”不搭。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能用来指加工方法，与“这种材料的……方法”不搭配。"}], "explanations": {"改性": "正确。这种材料的改性方法指改变材料性质的方法，句意通顺。", "颜色": "语义：“颜色”是外观属性，不是加工方法，“颜色方法”句意不通。", "重量": "语义：“重量”是属性，不是可以采用的方法，与“方法很简单”不搭。", "年龄": "搭配：“年龄”不能用来指加工方法，与“这种材料的……方法”不搭配。"}, "sentence_index": 6, "correct_answer": "改性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座公园经过改性，景色更好了。", "explanation": "这里应该用〈美化〉。改性指改变材料的性质，公园景观的装饰与提升要用美化。"}, {"text": "他改性了文章的结尾。", "explanation": "这里应该用〈修改〉。改性用于改变材料的性质，文章字句的调整要用修改。"}, {"text": "学校进行了改性，课程变了很多。", "explanation": "这里应该用〈改革〉。改性用于材料，学校制度和课程的变革要用改革。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12969, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂对这种木材做了改性过。", "corrected_sentence": "工厂对这种木材做了改性。", "error_description": "“过”多余。“做了改性”已经表示完成，句末不能再加“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12969, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种纸经过改性的，又软又韧。", "corrected_sentence": "这种纸经过改性，又软又韧。", "error_description": "“的”后面要有中心语，这里“经过改性的，又软又韧”不成句。应删去“的”，说“这种纸经过改性，又软又韧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
