INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12970, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "使某事物具备特定的功能或用途。", "primary_collocate": null, "pronunciation": "gōng néng huà", "ipa": "kʊŋ˥ nɤŋ˧˥ xu̯a˥˩", "syllable_count": 3, "sentences": [{"text": "材料科学的突破不仅体现在单体选择与共聚技术上，更延伸至纳米复合改性、表面功能化与降解速率调控等深层维度。", "target_word": "功能化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "表面功能化可以让材料有新的用处。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块玻璃经过功能化，能自己变色。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "功能化是这项研究的重点。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师在做布料的功能化。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸的功能化让它也能防水。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料的功能化设计很特别。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "功能化后的布，既防水又透气。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在课上讨论材料的功能化。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过表面功能化，这种塑料能吸附污水里的油。", "target_word": "功能化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "功能化材料", "label": "复合词"}, {"form": "功能化设计", "label": "复合词"}, {"form": "功能化处理", "label": "复合词"}], "register": "科技书面语", "sense_fingerprint": "使材料具备特定功能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29ae13fa-e2f6-4de8-a72a-3575f717bdf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12970, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "功能化", "is_correct": true, "explanation": "正确。句中指给表面增加特定用途，“表面功能化”即使材料具备新功能。"}, {"text": "口语化", "is_correct": false, "explanation": "语域：“口语化”指变得通俗、口语化，与“纳米复合改性、降解速率调控”这类科技书面语不搭。"}, {"text": "娱乐化", "is_correct": false, "explanation": "语义：“娱乐化”指变得有娱乐性，与材料表面改性无关，放在这里句子不通。"}, {"text": "戏剧化", "is_correct": false, "explanation": "语义：“戏剧化”指加入戏剧效果，不能用来描述材料表面的改性过程，句子意思说不通。"}], "explanations": {"功能化": "正确。句中指给表面增加特定用途，“表面功能化”即使材料具备新功能。", "口语化": "语域：“口语化”指变得通俗、口语化，与“纳米复合改性、降解速率调控”这类科技书面语不搭。", "娱乐化": "语义：“娱乐化”指变得有娱乐性，与材料表面改性无关，放在这里句子不通。", "戏剧化": "语义：“戏剧化”指加入戏剧效果，不能用来描述材料表面的改性过程，句子意思说不通。"}, "sentence_index": 0, "correct_answer": "功能化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要把资料功能化整理。", "explanation": "这里应该用〈系统化〉。系统化指使事物有条理、成体系，功能化指给事物增添特定用途，二者不能互换。"}, {"text": "这件事被他功能化了。", "explanation": "这里应该用〈复杂化〉。功能化指使事物具备某种用途，不能用来说把事情变得复杂。"}, {"text": "双方的合作正在功能化。", "explanation": "这里应该用〈深化〉。深化指使合作更加深入，功能化指给事物增加用途，合作不能“功能化”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12970, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "功能化", "is_correct": true, "explanation": "正确。“功能化设计”指赋予材料特定功能的设计，与“很特别”的语境一致。"}, {"text": "妖魔化", "is_correct": false, "explanation": "语义：“妖魔化”指把事物描绘成妖魔，不能用来说材料的设计，与“很特别”的评价也不符。"}, {"text": "病态化", "is_correct": false, "explanation": "语义：“病态化”指变得不正常，与“很特别”的正面评价冲突，材料设计不说病态化。"}, {"text": "粗俗化", "is_correct": false, "explanation": "语域：“粗俗化”指使变得庸俗，与科技书面语的语境不符，用在材料设计上很不自然。"}], "explanations": {"功能化": "正确。“功能化设计”指赋予材料特定功能的设计，与“很特别”的语境一致。", "妖魔化": "语义：“妖魔化”指把事物描绘成妖魔，不能用来说材料的设计，与“很特别”的评价也不符。", "病态化": "语义：“病态化”指变得不正常，与“很特别”的正面评价冲突，材料设计不说病态化。", "粗俗化": "语域：“粗俗化”指使变得庸俗，与科技书面语的语境不符，用在材料设计上很不自然。"}, "sentence_index": 6, "correct_answer": "功能化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "别把这个小问题功能化。", "explanation": "这里应该用〈简单化〉。简单化指使事情变简单，功能化指给事物增添用途，不能用来说把问题变简单。"}, {"text": "我的眼睛要功能化，别让它太累。", "explanation": "这里应该用〈保护〉。保护指照料使不受损害，功能化指给事物增添用途，眼睛不能说功能化。"}, {"text": "他每天早上都功能化半小时跑步。", "explanation": "这里应该用〈坚持〉。坚持指持续做某事，功能化指让材料具备特定功能，不能说人做运动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套家具功能化了过，既能坐又能放书。", "corrected_sentence": "这套家具功能化过，既能坐又能放书。", "error_description": "错误形式是“功能化了过”，“了”和“过”不能同时用在同一个动词后，应只用“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种纤维正在功能化了，以后能自己抗菌。", "corrected_sentence": "这种纤维正在功能化，以后能自己抗菌。", "error_description": "错误形式是“正在功能化了”，“正在”表示进行中，不能和表示完成的“了”同用，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '359c172d-3f8c-4869-8425-155c116d2b2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
