INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12975, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "基团是指分子中具有特定化学性质或结构特征的原子组合，是化合物中的基本组成部分。", "primary_collocate": null, "pronunciation": "jī tuán", "ipa": "tɕi˥ tʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "研究者通过引入纳米填料或光敏基团，使材料在紫外线或机械应力下预先产生微裂纹，从而扩大微生物附着的比表面积，加速降解进程。", "target_word": "基团", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种分子含有一个特殊的基团。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基团由几个原子组成。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学家研究了这个基团的结构。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机分子上的基团决定它的性质。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在分子上加了一个新基团。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的基团让化合物有不同的性质。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个分子的基团完全不同。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验中这个基团很容易发生反应。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画出了这个基团。", "target_word": "基团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个基团", "label": "量词"}, {"form": "这些基团", "label": "量词"}], "register": "科技", "sense_fingerprint": "化学：分子中具有特定性质或结构的原子组合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d11fcc8-d62b-4b13-af83-f4f5872bc024') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12975, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基团", "is_correct": true, "explanation": "正确。“光敏基团”是分子中对光有反应的原子组合，符合句中“引入”“产生微裂纹”的语境。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒是生物体，句中是为了改变材料性质而引入的化学结构，不能说引入病毒。"}, {"text": "乐曲", "is_correct": false, "explanation": "语义：乐曲不是化学结构，“引入乐曲”无法让材料产生微裂纹。"}, {"text": "大楼", "is_correct": false, "explanation": "搭配：“引入”不搭配“大楼”，也不能说“光敏大楼”。"}], "explanations": {"基团": "正确。“光敏基团”是分子中对光有反应的原子组合，符合句中“引入”“产生微裂纹”的语境。", "病毒": "语义：病毒是生物体，句中是为了改变材料性质而引入的化学结构，不能说引入病毒。", "乐曲": "语义：乐曲不是化学结构，“引入乐曲”无法让材料产生微裂纹。", "大楼": "搭配：“引入”不搭配“大楼”，也不能说“光敏大楼”。"}, "sentence_index": 0, "correct_answer": "基团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个基团有三十名成员。", "explanation": "这里应该用〈团体〉。基团是分子中的原子组合，不指一群人，不能说有多少名成员。"}, {"text": "这台机器的基团坏了。", "explanation": "这里应该用〈零件〉。基团是化学术语，指分子中的原子组合，不能指机器的零件。"}, {"text": "这个基团很可爱，孩子们都喜欢它。", "explanation": "这里应该用〈小动物〉。基团是化学术语，指分子中的原子组合，不是可爱的动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12975, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基团", "is_correct": true, "explanation": "正确。“不同的基团”让化合物有不同的性质，是化学中的组成部分，符合句意。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不是分子的组成部分，无法让化合物有不同的性质。"}, {"text": "旋律", "is_correct": false, "explanation": "语义：旋律是音乐的组成部分，与化合物的性质无关，句意不通。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不是化学结构，句中讲的是化合物的性质，没有这样的语境。"}], "explanations": {"基团": "正确。“不同的基团”让化合物有不同的性质，是化学中的组成部分，符合句意。", "老虎": "语义：老虎是动物，不是分子的组成部分，无法让化合物有不同的性质。", "旋律": "语义：旋律是音乐的组成部分，与化合物的性质无关，句意不通。", "花朵": "语义：花朵不是化学结构，句中讲的是化合物的性质，没有这样的语境。"}, "sentence_index": 6, "correct_answer": "基团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家基团有三万名员工。", "explanation": "这里应该用〈集团〉。基团是化学术语，指分子中的原子组合，不能指公司或企业。"}, {"text": "他的数学基团很扎实，考试没问题。", "explanation": "这里应该用〈基础〉。基团是化学术语，指分子中的原子组合，不能用来说数学的根基。"}, {"text": "他把这个基团送给了朋友。", "explanation": "这里应该用〈物件〉。基团是化学术语，指分子中的原子组合，不是可以拿来送人的实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12975, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个分子里有一条基团，决定了它的性质。", "corrected_sentence": "这个分子里有一个基团，决定了它的性质。", "error_description": "量词用错。“基团”应该用“个”，“条”用于细长的东西，不能用来数基团。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12975, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个分子上有三只基团。", "corrected_sentence": "这个分子上有三个基团。", "error_description": "错误在量词：「只」用于动物等，不能用于基团，应说「三个基团」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
