INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12976, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12976, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "紫外线是太阳光中波长比可见光短、能量较高的电磁辐射，过量照射会损伤皮肤和眼睛。", "primary_collocate": null, "pronunciation": "zǐ wài xiàn", "ipa": "tsɨ˨˩˦ waɪ˥˩ ɕjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "研究者通过引入纳米填料或光敏基团，使材料在紫外线或机械应力下预先产生微裂纹，从而扩大微生物附着的比表面积，加速降解进程。", "target_word": "紫外线", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "紫外线的波长比可见光短。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过量的紫外线会损伤皮肤和眼睛。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "臭氧层能挡住大部分紫外线。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院用紫外线给房间杀菌。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "紫外线的能量比可见光高。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的紫外线特别强，要涂防晒霜。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的眼睛看不见紫外线。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用仪器测量紫外线的强度。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种塑料遇到紫外线就会变脆。", "target_word": "紫外线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "束", "label": "量词"}, {"form": "紫外辐射", "label": "复合词"}], "register": "科技", "sense_fingerprint": "物理：波长比可见光短、能量较高的电磁辐射", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d11fcc8-d62b-4b13-af83-f4f5872bc024') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "紫外线", "is_correct": true, "explanation": "正确答案。句中“在紫外线或机械应力下”的紫外线是使材料产生微裂纹的光照条件之一。"}, {"text": "科学家", "is_correct": false, "explanation": "语义：科学家是人，不是能使材料受到作用的条件，与句中“材料在……下”不符。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“在……下”后接的是环境或作用条件，不能说“性格”。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡不是能使材料产生微裂纹的光或力，与句中光敏基团的语境不符。"}], "explanations": {"紫外线": "正确答案。句中“在紫外线或机械应力下”的紫外线是使材料产生微裂纹的光照条件之一。", "科学家": "语义：科学家是人，不是能使材料受到作用的条件，与句中“材料在……下”不符。", "性格": "搭配：“在……下”后接的是环境或作用条件，不能说“性格”。", "咖啡": "语义：咖啡不是能使材料产生微裂纹的光或力，与句中光敏基团的语境不符。"}, "sentence_index": 0, "correct_answer": "紫外线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台遥控器靠紫外线来控制电视。", "explanation": "这里应该用〈红外线〉。遥控器靠红外线传递信号；紫外线能量高，会伤害皮肤和眼睛，不用于遥控。"}, {"text": "这种紫外线是红色的，看起来很漂亮。", "explanation": "这里应该用〈红光〉。紫外线人眼看不见，没有颜色可言；红光才是看得见的红色光。"}, {"text": "夜里路灯的紫外线很亮，我们能看清路。", "explanation": "这里应该用〈可见光〉。可见光人眼能看见，能照明；紫外线人眼看不见，不能用来照亮道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "紫外线", "is_correct": true, "explanation": "正确答案。“夏天的紫外线特别强”指夏天的阳光中紫外线很强，所以要涂防晒霜。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音与后文“要涂防晒霜”的语境不符，防晒霜是针对光照的。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“强”不能修饰树叶，这里要表示光照的强弱。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：香蕉不能有“强”的光照，与夏天防晒的语境不符。"}], "explanations": {"紫外线": "正确答案。“夏天的紫外线特别强”指夏天的阳光中紫外线很强，所以要涂防晒霜。", "声音": "语义：声音与后文“要涂防晒霜”的语境不符，防晒霜是针对光照的。", "树叶": "搭配：“强”不能修饰树叶，这里要表示光照的强弱。", "香蕉": "语义：香蕉不能有“强”的光照，与夏天防晒的语境不符。"}, "sentence_index": 6, "correct_answer": "紫外线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋子里有一本紫外线。", "explanation": "这里应该用〈束〉。“本”用于书册，紫外线是光，计量光线要用“束”。"}, {"text": "实验室里有一块紫外线。", "explanation": "这里应该用〈束〉。“块”用于块状的固体，紫外线是光，计量光线要用“束”。"}, {"text": "墙角有一张紫外线。", "explanation": "这里应该用〈束〉。“张”用于纸、桌子等扁平的东西，紫外线是光，计量光线要用“束”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "紫外线地能量很高。", "corrected_sentence": "紫外线的能量很高。", "error_description": "结构助词用错。“紫外线”修饰名词“能量”，应用“的”，说“紫外线的能量”；“地”用于修饰动词，不能放在名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种塑料很快会紫外线下变脆。", "corrected_sentence": "这种塑料很快会在紫外线下变脆。", "error_description": "介词漏用：「紫外线下」前缺少“在”，应为「在紫外线下」，表示在紫外线照射的条件下。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
