INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12983, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体表面因黏性而连接在另一物体上，不易脱离。", "primary_collocate": null, "pronunciation": "fù zhuó", "ipa": "fu˥˩ ʈʂuo˧˥", "syllable_count": 2, "sentences": [{"text": "研究者通过引入纳米填料或光敏基团，使材料在紫外线或机械应力下预先产生微裂纹，从而扩大微生物附着的比表面积，加速降解进程。", "target_word": "附着", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "雨后，泥土附着在鞋底上。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灰尘附着在墙上，很难擦掉。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的石头上附着很多小贝壳。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种胶带很好，能牢牢附着在玻璃上。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牙齿上附着的细菌会让人生病。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船底附着了许多海草，船走得很慢。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油漆不能附着在湿墙上，要等墙干。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小虫子附着在叶子下面，不容易看见。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪花附着在窗户上，慢慢变成水。", "target_word": "附着", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "附着了", "label": "体标（了）"}, {"form": "附着力", "label": "复合词"}, {"form": "附着物", "label": "复合词"}], "register": "书面", "sense_fingerprint": "物体凭黏性贴在另一物体表面，不易脱落", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cec2e43-2775-454a-9511-b4b696244bdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12983, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "附着", "is_correct": true, "explanation": "微生物附着的比表面积指微生物粘在材料表面的面积，符合句意。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：逃跑指离开，与比表面积无关，句意是微生物粘在表面。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：游泳指在水中活动，不能修饰比表面积。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡指休息的状态，与微生物粘在表面的意思不相关。"}], "explanations": {"附着": "微生物附着的比表面积指微生物粘在材料表面的面积，符合句意。", "逃跑": "语义：逃跑指离开，与比表面积无关，句意是微生物粘在表面。", "游泳": "搭配：游泳指在水中活动，不能修饰比表面积。", "睡": "语义：睡指休息的状态，与微生物粘在表面的意思不相关。"}, "sentence_index": 0, "correct_answer": "附着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从不附着别人生活，凡事都自己做主。", "explanation": "这里应该用〈依附〉。附着指小东西粘在物体表面，靠他人生活要用依附。"}, {"text": "他附着在墙上打了个盹。", "explanation": "这里应该用〈靠〉。附着指小东西黏在物体表面，人倚着墙要说靠。"}, {"text": "工人们在河上附着了一座大桥。", "explanation": "这里应该用〈架设〉。附着指小东西粘在物体表面，大桥要用架设。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12983, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "附着", "is_correct": true, "explanation": "船底附着了许多海草，表示海草粘在船底，符合句意。"}, {"text": "切", "is_correct": false, "explanation": "语义：船底不能切海草，切的动作与粘在船底的意思不符。"}, {"text": "挑", "is_correct": false, "explanation": "配价：挑需要有施事拣选，船底不能挑海草。"}, {"text": "吞", "is_correct": false, "explanation": "语义：吞指吃下去，船底不能吞海草。"}], "explanations": {"附着": "船底附着了许多海草，表示海草粘在船底，符合句意。", "切": "语义：船底不能切海草，切的动作与粘在船底的意思不符。", "挑": "配价：挑需要有施事拣选，船底不能挑海草。", "吞": "语义：吞指吃下去，船底不能吞海草。"}, "sentence_index": 6, "correct_answer": "附着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在桌上附着了一个生日蛋糕，很好看。", "explanation": "这里应该用〈摆〉。附着指黏性粘连，蛋糕是放在桌上，不是粘上去的。"}, {"text": "他把毛巾附着在门后。", "explanation": "这里应该用〈挂〉。毛巾挂在门后靠挂钩，不是黏附。"}, {"text": "公司附着国家的政策，才能生存下去。", "explanation": "这里应该用〈依靠〉。附着指小东西粘在物体表面，靠政策生存要用依靠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这层薄膜不能附着玻璃上。", "corrected_sentence": "这层薄膜不能附着在玻璃上。", "error_description": "错误：“附着”后漏掉介词“在”。附着要引出处所，应说“不能附着在玻璃上”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "油漆刚涂上去，就慢慢附着了在木门上了。", "corrected_sentence": "油漆刚涂上去，就慢慢附着在木门上了。", "error_description": "错误：「附着」与处所补语「在木门上」之间不能插入「了」。应说「慢慢附着在木门上了」，把「了」放在补语后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8a17325-c333-4116-93cf-78505131cfb7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
