INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12987, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指含盐量很少的水，通常来自河流、湖泊，与海水相对。", "primary_collocate": null, "pronunciation": "dàn shuǐ", "ipa": "tan˥˩ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "从棉花种植阶段的大量灌溉，到印染、整理等后处理环节的高耗水作业，每一吨纺织品的诞生往往伴随着数万升淡水的消耗。", "target_word": "淡水", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个湖里的水是淡水，不是海水。", "target_word": "淡水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河里的淡水可以养很多鱼。", "target_word": "淡水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地球上的淡水很少，要节约用水。", "target_word": "淡水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种鱼只能生活在淡水里。", "target_word": "淡水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船上的人用完了带来的淡水。", "target_word": "淡水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的城市把海水变成淡水。", "target_word": "淡水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片湖里的淡水很干净，鱼也多。", "target_word": "淡水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪山融化后，给下游带来了淡水。", "target_word": "淡水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的河水是淡水，所以能种水稻。", "target_word": "淡水", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "淡水湖", "label": "复合"}, {"form": "淡水鱼", "label": "复合"}], "register": "中性", "sense_fingerprint": "含盐很少的水，河湖之水，相对海水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfd7af12-1a73-462f-9399-277b88dbbcd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12987, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "淡水", "is_correct": true, "explanation": "淡水：含盐很少的水，即河湖之水，与“数万升”的消耗相符。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：纺织过程耗费的是水，汽油不是这里消耗的对象，句意不符。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：句中讲的是用水量，纺织生产不耗牛奶，句意不合。"}, {"text": "盐", "is_correct": false, "explanation": "搭配：盐以克、公斤计量，不用“升”，“数万升盐”不搭配。"}], "explanations": {"淡水": "淡水：含盐很少的水，即河湖之水，与“数万升”的消耗相符。", "汽油": "语义：纺织过程耗费的是水，汽油不是这里消耗的对象，句意不符。", "牛奶": "语义：句中讲的是用水量，纺织生产不耗牛奶，句意不合。", "盐": "搭配：盐以克、公斤计量，不用“升”，“数万升盐”不搭配。"}, "sentence_index": 0, "correct_answer": "淡水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "船上带了一根淡水，供大家路上喝。", "explanation": "量词错误：“根”用于细长的东西，淡水是液体，应说“一瓶淡水”或“一桶淡水”。"}, {"text": "厨房里放着一只淡水，准备煮饭。", "explanation": "量词错误：“只”用于动物或成对物件中的一个，淡水应说“一桶淡水”。"}, {"text": "他买了一张淡水，带回家。", "explanation": "量词错误：“张”用于纸、桌子等平面的东西，淡水应说“一瓶淡水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12987, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "淡水", "is_correct": true, "explanation": "淡水：含盐很少的水，海水淡化后得到的就是淡水，句意相符。"}, {"text": "咸水", "is_correct": false, "explanation": "语义：咸水仍是含盐的水，与“变成”后的淡化结果相反。"}, {"text": "酒", "is_correct": false, "explanation": "语义：海水淡化得到的是淡水，不会变成酒。"}, {"text": "钢", "is_correct": false, "explanation": "搭配：液态的海水不能“变成”固体金属钢，二者不搭配。"}], "explanations": {"淡水": "淡水：含盐很少的水，海水淡化后得到的就是淡水，句意相符。", "咸水": "语义：咸水仍是含盐的水，与“变成”后的淡化结果相反。", "酒": "语义：海水淡化得到的是淡水，不会变成酒。", "钢": "搭配：液态的海水不能“变成”固体金属钢，二者不搭配。"}, "sentence_index": 6, "correct_answer": "淡水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "淡水的盐分很高，不能直接喝。", "explanation": "这里应该用〈海水〉。淡水指含盐很少的水，不能说“盐分很高”；盐分高的是海水。"}, {"text": "淡水很咸，常用来腌菜。", "explanation": "这里应该用〈盐水〉。淡水含盐很少，不能说“很咸”；腌菜用的盐水才咸。"}, {"text": "淡水煮出来的饭很咸，不能吃。", "explanation": "这里应该用〈咸水〉。淡水含盐少，煮出来的饭不会咸；咸水煮饭才会很咸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河里的一块淡水可以用来灌溉农田。", "corrected_sentence": "这条河里的淡水可以用来灌溉农田。", "error_description": "量词错误：“淡水”是液体，不能用“块”计量；应直接说“这条河里的淡水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把干净地淡水装进了桶里，够喝三天。", "corrected_sentence": "我们把干净的淡水装进了桶里，够喝三天。", "error_description": "结构助词错误：“干净”修饰“淡水”，二者之间应用“的”，此处误用“地”；“地”用于动词前作状语。应说“干净的淡水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a80b7b-6215-4605-be79-c8811bfd8ec2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
