INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12989, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指产品、设备等在规格或说明上标明的数值或参数。", "primary_collocate": null, "pronunciation": "biāo chēng", "ipa": "piɑʊ̯˥ ʈʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这台风扇的标称噪声是三十分贝。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个充电宝的标称容量是一万毫安时。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机电池的标称电压一般是三点七伏。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台空调的标称功率是一千五百瓦。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款手机的实际续航时间比标称的短。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买电器前，请先看一下说明书上的标称数值。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶药的标称含量是每片五十毫克。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个灯泡的标称寿命是一万个小时。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我测了一下，电压和标称差不多。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条数据线的标称长度是一米，其实短了一点。", "target_word": "标称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "標稱", "label": "繁体"}, {"form": "标称值", "label": "复合"}], "register": "书面", "sense_fingerprint": "标称：产品、设备在规格或说明上标明的数值或参数，如标称容量、标称电压", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d854d00-1f88-4c3f-9c27-9bef55911eec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12989, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标称", "is_correct": true, "explanation": "正确。标称噪声是产品规格上标明的数值。"}, {"text": "标价", "is_correct": false, "explanation": "语义：标价是商品的售价，与噪声的数值无关。"}, {"text": "烧毁", "is_correct": false, "explanation": "搭配：烧毁是毁坏物体，不能用来修饰噪声。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：生锈只用于金属等物体，不能用来修饰噪声。"}], "explanations": {"标称": "正确。标称噪声是产品规格上标明的数值。", "标价": "语义：标价是商品的售价，与噪声的数值无关。", "烧毁": "搭配：烧毁是毁坏物体，不能用来修饰噪声。", "生锈": "搭配：生锈只用于金属等物体，不能用来修饰噪声。"}, "sentence_index": 0, "correct_answer": "标称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人的标称年龄是三十岁。", "explanation": "这里应该用〈自报〉。标称只用于产品、设备规格或说明上的数值，人的年龄要说自报年龄。"}, {"text": "这次比赛他的标称名次是第一。", "explanation": "这里应该用〈名次〉。标称只用于产品、设备规格或说明上的数值，比赛名次是实际结果，要说名次。"}, {"text": "这款手机的标称销量是五百万台。", "explanation": "这里应该用〈销售数量〉。标称只用于产品、设备规格或说明上的数值，卖出多少台是实际的销售情况，要说销售数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12989, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标称", "is_correct": true, "explanation": "正确。标称含量是产品说明上标明的每片含量。"}, {"text": "口味", "is_correct": false, "explanation": "语义：口味不是能用含量衡量的数值，与“每片五十毫克”不搭。"}, {"text": "包装", "is_correct": false, "explanation": "语义：包装指外形和容器，不能用来修饰“含量”。"}, {"text": "保质期", "is_correct": false, "explanation": "搭配：保质期说的是时间，不说含量。"}], "explanations": {"标称": "正确。标称含量是产品说明上标明的每片含量。", "口味": "语义：口味不是能用含量衡量的数值，与“每片五十毫克”不搭。", "包装": "语义：包装指外形和容器，不能用来修饰“含量”。", "保质期": "搭配：保质期说的是时间，不说含量。"}, "sentence_index": 6, "correct_answer": "标称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次数学考试的标称成绩是九十分。", "explanation": "这里应该用〈分数〉。标称只用于产品、设备规格上标明的数值，考试得了多少分是实际结果，不能说标称。"}, {"text": "这棵老树的标称年龄是三百年。", "explanation": "这里应该用〈树龄〉。标称只用于产品、设备的规格或说明，树活了多少年要说树龄。"}, {"text": "这杯水的标称温度是六十度。", "explanation": "这里应该用〈实际〉。标称是规格或说明上标明的数值；这杯水此刻的冷热是随手测得的实际情况，不能说标称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12989, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款灯具的标称电压是十二瓦。", "corrected_sentence": "这款灯具的标称电压是十二伏。", "error_description": "错在单位：电压的单位是伏，应说“十二伏”；“瓦”是功率的单位，不能用来量电压。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12989, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台吸尘器的标称功率是七百安。", "corrected_sentence": "这台吸尘器的标称功率是七百瓦。", "error_description": "错在单位：功率的单位是瓦，应说“七百瓦”；“安”是电流的单位，不能用来量功率。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3077faca-1268-451b-bb11-eb7906611bf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
